    private void migrateAddressMenuNavigationPreference() {
        String value = preferences.getString(PREF_ADDRESS_MENU_BUTTONS, null);
        if (value == null || !value.contains(ADDRESS_MENU_NAV)) {
            return;
        }
        List<String> oldMenu = orderedButtonIds(value, "", new String[]{
                ADDRESS_MENU_WEBVIEW, ADDRESS_MENU_BOOKMARK, ADDRESS_MENU_FIND,
                ADDRESS_MENU_SYNC, ADDRESS_MENU_SETTINGS, ADDRESS_MENU_NAV, ADDRESS_NAV_BACK,
                ADDRESS_NAV_FORWARD, ADDRESS_NAV_SHARE, ADDRESS_NAV_RELOAD
        });
        List<String> nextMenu = new ArrayList<>();
        List<String> nextNav = new ArrayList<>();
        for (String id : oldMenu) {
            if (ADDRESS_NAV_BACK.equals(id) || ADDRESS_NAV_FORWARD.equals(id)
                    || ADDRESS_NAV_SHARE.equals(id) || ADDRESS_NAV_RELOAD.equals(id)) {
                nextNav.add(id);
            } else if (!ADDRESS_MENU_NAV.equals(id)) {
                nextMenu.add(id);
            }
        }
        if (nextNav.isEmpty()) {
            nextNav.addAll(orderedButtonIds(preferences.getString(PREF_ADDRESS_NAV_BUTTONS, DEFAULT_ADDRESS_NAV_BUTTONS),
                    DEFAULT_ADDRESS_NAV_BUTTONS, ADDRESS_NAV_BUTTON_IDS));
        }
        if (nextMenu.isEmpty()) {
            nextMenu.addAll(orderedButtonIds(DEFAULT_ADDRESS_MENU_BUTTONS, DEFAULT_ADDRESS_MENU_BUTTONS, ADDRESS_MENU_BUTTON_IDS));
        }
        preferences.edit()
                .putString(PREF_ADDRESS_MENU_BUTTONS, joinButtonIds(nextMenu))
                .putString(PREF_ADDRESS_NAV_BUTTONS, joinButtonIds(nextNav))
                .apply();
    }

    private void migratePopularButtonPreference() {
        if (preferences.getBoolean(PREF_POPULAR_BUTTON_MIGRATED, false)) {
            return;
        }
        String value = preferences.getString(PREF_THREAD_TITLE_MENU_BUTTONS, DEFAULT_THREAD_TITLE_MENU_BUTTONS);
        List<String> menu = orderedButtonIds(value, DEFAULT_THREAD_TITLE_MENU_BUTTONS, THREAD_TITLE_BUTTON_IDS);
        if (!menu.contains(THREAD_BUTTON_POPULAR)) {
            int linkIndex = menu.indexOf(THREAD_BUTTON_LINKS);
            if (linkIndex >= 0) {
                menu.add(linkIndex + 1, THREAD_BUTTON_POPULAR);
            } else {
                menu.add(THREAD_BUTTON_POPULAR);
            }
        }
        preferences.edit()
                .putString(PREF_THREAD_TITLE_MENU_BUTTONS, joinButtonIds(menu))
                .putBoolean(PREF_POPULAR_BUTTON_MIGRATED, true)
                .apply();
    }

    private void ensureDefaultCustomBbsLinks() {
        if (!preferences.getBoolean(PREF_DEFAULT_CUSTOM_BBS_ADDED, false)
                || preferences.getBoolean(PREF_DEFAULT_CUSTOM_BBS_REMOVED, false)) {
            return;
        }
        removeBbsLink(preferences, SHITARABA_BBSMENU_URL);
        removeBbsLink(preferences, FUTABA_BBSMENU_URL);
        preferences.edit().putBoolean(PREF_DEFAULT_CUSTOM_BBS_REMOVED, true).apply();
    }

    private List<String> addressBarButtonIds() {
        List<String> ids = orderedButtonIdsFromPreferences(PREF_ADDRESS_BAR_BUTTONS, DEFAULT_ADDRESS_BAR_BUTTONS, ADDRESS_BUTTON_IDS);
        if (inlineWebViewMode) {
            ids.remove(ADDRESS_BAR_NEW_TAB);
            ids.remove(ADDRESS_BAR_TABS);
            ids.remove(ADDRESS_MENU_BOOKMARK);
        }
        if (!ids.contains(ADDRESS_BAR_MENU)) {
            ids.add(ADDRESS_BAR_MENU);
        }
        return ids;
    }

    private List<String> addressMenuButtonIds() {
        List<String> ids = orderedButtonIdsFromPreferences(PREF_ADDRESS_MENU_BUTTONS,
                DEFAULT_ADDRESS_MENU_BUTTONS, ADDRESS_BUTTON_IDS);
        ids.remove(ADDRESS_MENU_NAV);
        ids.remove(ADDRESS_BAR_MENU);
        if (inlineWebViewMode) {
            ids.remove(ADDRESS_BAR_NEW_TAB);
            ids.remove(ADDRESS_BAR_TABS);
            ids.remove(ADDRESS_MENU_BOOKMARK);
            if (!addressButtonPlaced(ADDRESS_MENU_WEBVIEW) && !ids.contains(ADDRESS_MENU_WEBVIEW)) {
                ids.add(0, ADDRESS_MENU_WEBVIEW);
            }
        }
        if (!addressButtonPlaced(ADDRESS_MENU_SETTINGS) && !ids.contains(ADDRESS_MENU_SETTINGS)) {
            ids.add(ADDRESS_MENU_SETTINGS);
        }
        return ids;
    }

    private List<String> addressNavButtonIds() {
        List<String> ids = orderedButtonIdsFromPreferences(PREF_ADDRESS_NAV_BUTTONS, DEFAULT_ADDRESS_NAV_BUTTONS, ADDRESS_BUTTON_IDS);
        ids.remove(ADDRESS_BAR_MENU);
        return ids;
    }

    private boolean addressButtonPlaced(String id) {
        return addressButtonListContains(PREF_ADDRESS_BAR_BUTTONS, DEFAULT_ADDRESS_BAR_BUTTONS, id)
                || addressButtonListContains(PREF_ADDRESS_MENU_BUTTONS, DEFAULT_ADDRESS_MENU_BUTTONS, id)
                || addressButtonListContains(PREF_ADDRESS_NAV_BUTTONS, DEFAULT_ADDRESS_NAV_BUTTONS, id);
    }

    private boolean addressButtonListContains(String key, String fallback, String id) {
        return orderedButtonIds(preferences == null ? fallback : preferences.getString(key, fallback),
                fallback, ADDRESS_BUTTON_IDS).contains(id);
    }

    private List<String> orderedButtonIdsFromPreferences(String preferenceKey, String fallback, String[] allowed) {
        return orderedButtonIds(preferences == null ? fallback : preferences.getString(preferenceKey, fallback),
                fallback, allowed);
    }

    static List<String> orderedButtonIds(String value, String fallback, String[] allowed) {
        Set<String> allowedSet = new HashSet<>();
        Collections.addAll(allowedSet, allowed);
        List<String> result = new ArrayList<>();
        addButtonIds(result, value, allowedSet);
        if (result.isEmpty()) {
            addButtonIds(result, fallback, allowedSet);
        }
        return result;
    }

    private static void addButtonIds(List<String> result, String value, Set<String> allowedSet) {
        if (value == null) {
            return;
        }
        for (String raw : value.split(",")) {
            String id = raw.trim();
            if (!id.isEmpty() && allowedSet.contains(id) && !result.contains(id)) {
                result.add(id);
            }
        }
    }

    static String joinButtonIds(List<String> ids) {
        StringBuilder builder = new StringBuilder();
        for (String id : ids) {
            if (builder.length() > 0) {
                builder.append(',');
            }
            builder.append(id);
        }
        return builder.toString();
    }

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        preferences = getSharedPreferences(PREFS_NAME, MODE_PRIVATE);
        tabPayloadStore = new TabPayloadStore(this);
        migrateAddressMenuNavigationPreference();
        migratePopularButtonPreference();
        migrateFavoriteBoardsToBookmarks();
        ensureDefaultCustomBbsLinks();
        appliedThemeMode = themeMode();
        appliedSync2chUpdateAt = preferences.getLong(PREF_SYNC2CH_UPDATED_AT, 0L);
        appliedLocalBackupRestoreAt = preferences.getLong(PREF_LOCAL_BACKUP_RESTORED_AT, 0L);
        appliedButtonLayoutSignature = buttonLayoutSignature();
        buildLayout();
        contentFrame.addView(loadingView(""));
        scheduleTabUnload();

        contentFrame.postDelayed(this::openInitialContent, 32);
    }

    private void openInitialContent() {
        boolean restored = restoreTabs();
        if (handleViewIntent(getIntent())) {
            return;
        }
        if (!restored) {
            createBlankTab();
        }
    }

    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        setIntent(intent);
        handleViewIntent(intent);
    }

    private boolean handleViewIntent(Intent intent) {
        if (intent == null || !Intent.ACTION_VIEW.equals(intent.getAction()) || intent.getData() == null) {
            return false;
        }
        openIncomingLink(intent.getData().toString(), intent.getIntExtra(EXTRA_JUMP_POST_NUMBER, 0));
        return true;
    }

    private void openIncomingLink(String rawUrl) {
        openIncomingLink(rawUrl, 0);
    }

    private void openIncomingLink(String rawUrl, int postNumber) {
        String url = normalizeUrl(rawUrl);
        if (isSupportedBbsLink(url)) {
            if (postNumber > 0 && isThreadUrl(url)) {
                openThreadPost(url, postNumber, currentTab());
            } else {
                routeLink(url, currentTab());
            }
            if (tabs.isEmpty() && !pendingNewTab) {
                createBlankTab();
            }
            return;
        }
        openExternal(url);
        if (tabs.isEmpty() && !pendingNewTab) {
            createBlankTab();
        }
    }

    private boolean isSupportedBbsLink(String url) {
        return is5chUrl(url)
                || isRegisteredBbsUrl(url)
                || isKnownCustomBbsUrl(url)
                || isThreadUrl(url)
                || isBoardUrl(url)
                || isBbsDirectoryUrl(url)
                || isHissiCheckerUrl(url)
                || isFindSearchUrl(url)
                || isFindHomeUrl(url)
                || isFullTextSearchUrl(url);
    }

    @Override
    protected void onPause() {
        if (saveTabsTask != null) {
            mainHandler.removeCallbacks(saveTabsTask);
            saveTabsTask = null;
        }
        if (unloadTabsTask != null) {
            mainHandler.removeCallbacks(unloadTabsTask);
            unloadTabsTask = null;
        }
        saveTabs(true);
        super.onPause();
    }

    @Override
    protected void onResume() {
        super.onResume();
        String currentThemeMode = themeMode();
        boolean themeChanged = appliedThemeMode != null && !appliedThemeMode.equals(currentThemeMode);
        String currentButtonLayoutSignature = buttonLayoutSignature();
        boolean buttonLayoutChanged = appliedButtonLayoutSignature != null
                && !appliedButtonLayoutSignature.equals(currentButtonLayoutSignature);
        if (bottomToolbar != null && (addressBarTop != addressBarOnTop() || themeChanged || buttonLayoutChanged)) {
            CuspTab tab = currentTab();
            if (tab != null) {
                rememberTabScroll(tab);
            }
            appliedThemeMode = currentThemeMode;
            appliedButtonLayoutSignature = currentButtonLayoutSignature;
            buildLayout();
            if (pendingNewTab) {
                showPendingNewTabHistory(pendingHistoryAll);
            } else if (currentIndex >= 0 && currentIndex < tabs.size()) {
                switchToTab(currentIndex);
            }
        }
        long syncUpdatedAt = preferences.getLong(PREF_SYNC2CH_UPDATED_AT, 0L);
        if (syncUpdatedAt != appliedSync2chUpdateAt) {
            appliedSync2chUpdateAt = syncUpdatedAt;
            if (restoreTabs()) {
                if (currentIndex >= 0 && currentIndex < tabs.size()) {
                    switchToTab(currentIndex);
                } else {
                    renderTabs();
                }
            }
        }
        long backupRestoredAt = preferences.getLong(PREF_LOCAL_BACKUP_RESTORED_AT, 0L);
        if (backupRestoredAt != appliedLocalBackupRestoreAt) {
            appliedLocalBackupRestoreAt = backupRestoredAt;
            appliedThemeMode = themeMode();
            appliedButtonLayoutSignature = buttonLayoutSignature();
            buildLayout();
            if (restoreTabs() && currentIndex >= 0 && currentIndex < tabs.size()) {
                switchToTab(currentIndex);
            } else {
                showPendingNewTab();
            }
        }
        scheduleTabUnload();
    }

    @Override
    protected void onDestroy() {
        if (inlineWebView != null) {
            inlineWebView.stopLoading();
            inlineWebView.loadUrl("about:blank");
            inlineWebView.destroy();
            inlineWebView = null;
        }
        if (saveTabsTask != null) {
            mainHandler.removeCallbacks(saveTabsTask);
            saveTabsTask = null;
        }
        if (unloadTabsTask != null) {
            mainHandler.removeCallbacks(unloadTabsTask);
            unloadTabsTask = null;
        }
        saveTabs(true);
        ioExecutor.shutdownNow();
        boardLoadExecutor.shutdownNow();
        if (bookmarkOverviewLoadTask != null) {
            bookmarkOverviewLoadTask.cancel(true);
            bookmarkOverviewLoadTask = null;
        }
        tabOverviewExecutor.shutdownNow();
        tabReloadExecutor.shutdownNow();
        super.onDestroy();
    }

    @Override
    public void onBackPressed() {
        if (imageOverlay != null) {
            closeImageViewer();
            return;
        }
        if (tabOverviewVisible) {
            tabOverviewVisible = false;
            switchToTab(currentIndex, true);
            return;
        }
        if (pendingNewTab) {
            if (newTabNavigationIndex > 0) {
                navigateNewTabHistory(-1);
                return;
            }
            cancelPendingNewTab();
            return;
        }
        if (addressBar != null && addressBar.hasFocus()) {
            clearAddressFocus();
            return;
        }
        if (inlineWebViewMode) {
            if (inlineWebView != null && inlineWebView.canGoBack()) {
                inlineWebView.goBack();
            } else {
                closeInlineWebView();
            }
            return;
        }
        if (isPageSearchOpen()) {
            closeThreadSearch();
            return;
        }
        if (!replyPopups.isEmpty()) {
            dismissTopReplyPopup();
            return;
        }
        if (!animatedPopups.isEmpty()) {
            dismissTopAnimatedPopup();
            return;
        }
        CuspTab tab = currentTab();
        if (canGoBackInCurrentTab(tab)) {
            goBack();
            return;
        }
        if (tab != null && tab.backToNewTab && tab.navigationIndex <= 0) {
            closeCurrentTab();
            showPendingNewTab();
            return;
        }
        if (tabs.size() > 1) {
            closeCurrentTab();
            return;
        }
        super.onBackPressed();
    }

    @Override
    public boolean dispatchTouchEvent(MotionEvent event) {
        if (event.getAction() == MotionEvent.ACTION_DOWN) {
            if (dismissPopupOnOutsideTap(event)) return true;
            if (highlightedPostView != null) {
                clearJumpHighlight();
            }
            if (addressBar != null && addressBar.hasFocus()
                    && !isTouchInsideView(event, addressBar)
                    && (suggestionsPanel == null || suggestionsPanel.getVisibility() != View.VISIBLE
                    || !isTouchInsideView(event, suggestionsPanel))) {
                clearAddressFocus();
            }
        }
        boolean wasGestureIntercepting = gestureIntercepting;
        boolean consumeGesture = trackGestureEvent(event);
        if (consumeGesture) {
            if (!wasGestureIntercepting && gestureIntercepting) {
                cancelChildTouch(event);
            }
            return true;
        }
        return super.dispatchTouchEvent(event);
    }

    private boolean dismissPopupOnOutsideTap(MotionEvent event) {
        if (!animatedPopups.isEmpty() && !isTouchInsideAnimatedPopup(event)) {
            dismissTopAnimatedPopup();
            return true;
        }
        if (!replyPopups.isEmpty() && !isTouchInsideTopReplyPopup(event)) {
            dismissTopReplyPopup();
            return true;
        }
        return false;
    }

    private void cancelChildTouch(MotionEvent event) {
        MotionEvent cancel = MotionEvent.obtain(event);
        cancel.setAction(MotionEvent.ACTION_CANCEL);
        try {
            super.dispatchTouchEvent(cancel);
        } finally {
            cancel.recycle();
        }
    }

    private void buildLayout() {
        addressBarTop = addressBarOnTop();
        applySystemBarTheme();
        toolbarButtons.clear();
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setBackgroundColor(bgColor());
        root.setFocusableInTouchMode(true);
        root.requestFocus();
        setContentView(root);
        installKeyboardFocusWatcher(root);

        progressBar = new ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal);
        progressBar.setIndeterminate(true);
        progressBar.setVisibility(View.GONE);
        root.addView(progressBar, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(3)));

        contentFrame = new FrameLayout(this);
        contentFrame.setBackgroundColor(bgColor());
        contentFrame.setFocusableInTouchMode(true);
        overlayFrame = new FrameLayout(this);
        overlayFrame.addView(contentFrame, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        suggestionsPanel = new LinearLayout(this);
        suggestionsPanel.setOrientation(LinearLayout.VERTICAL);
        suggestionsPanel.setBackgroundColor(Color.TRANSPARENT);
        suggestionsPanel.setPadding(dp(12), dp(12), dp(12), dp(12));
        suggestionsPanel.setVisibility(View.GONE);
        FrameLayout.LayoutParams suggestionsParams = new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        suggestionsParams.gravity = addressBarTop ? Gravity.TOP : Gravity.BOTTOM;
        overlayFrame.addView(suggestionsPanel, suggestionsParams);

        threadSearchBar = new LinearLayout(this);
        threadSearchBar.setOrientation(LinearLayout.HORIZONTAL);
        threadSearchBar.setGravity(Gravity.CENTER_VERTICAL);
        threadSearchBar.setPadding(dp(8), dp(5), dp(6), dp(5));
        threadSearchBar.setBackground(bottomBarBackground());
        threadSearchBar.setVisibility(View.GONE);

        threadSearchInput = new EditText(this);
        threadSearchInput.setSingleLine(true);
        threadSearchInput.setTextSize(14);
        threadSearchInput.setTextColor(textColor());
        threadSearchInput.setHintTextColor(hintTextColor());
        threadSearchInput.setHint(text("\u30da\u30fc\u30b8\u5185\u691c\u7d22", "Find in page"));
        threadSearchInput.setImeOptions(EditorInfo.IME_ACTION_SEARCH);
        threadSearchInput.setBackground(addressBarBackground());
        threadSearchInput.setPadding(dp(12), 0, dp(12), 0);
        threadSearchInput.setOnEditorActionListener((v, actionId, event) -> {
            boolean enter = event != null && event.getKeyCode() == KeyEvent.KEYCODE_ENTER
                    && event.getAction() == KeyEvent.ACTION_UP;
            boolean enterDown = event != null && event.getKeyCode() == KeyEvent.KEYCODE_ENTER
                    && event.getAction() == KeyEvent.ACTION_DOWN;
            if (actionId == EditorInfo.IME_ACTION_SEARCH
                    || actionId == EditorInfo.IME_ACTION_DONE
                    || enter) {
                if (inlineWebViewMode && inlineWebView != null) {
                    inlineWebView.findNext(true);
                } else if (isThreadPageSearchActive()) {
                    CuspTab tab = currentTab();
                    if (tab != null && !tab.threadSearchMatches.isEmpty()) {
                        moveThreadSearch(1);
                    } else {
                        scheduleThreadSearch(threadSearchInput.getText().toString(), true);
                    }
                } else if (!pageSearchMatches.isEmpty()) {
                    movePageSearch(1);
                } else {
                    updatePageSearch(threadSearchInput.getText().toString(), true);
                }
                InputMethodManager manager = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
                if (manager != null) {
                    manager.hideSoftInputFromWindow(threadSearchInput.getWindowToken(), 0);
                }
                threadSearchInput.clearFocus();
                return true;
            }
            return enterDown;
        });
        threadSearchInput.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                if (!updatingThreadSearchInput) {
                    if (inlineWebViewMode && inlineWebView != null) {
                        pageSearchQuery = s.toString();
                        inlineWebView.findAllAsync(pageSearchQuery);
                    } else if (isThreadPageSearchActive()) {
                        scheduleThreadSearch(s.toString(), true);
                    } else {
                        updatePageSearch(s.toString(), true);
                    }
                }
            }

            @Override
            public void afterTextChanged(Editable s) {
            }
        });
        threadSearchBar.addView(threadSearchInput, new LinearLayout.LayoutParams(0, dp(40), 1));
        threadSearchCount = new TextView(this);
        threadSearchCount.setTextColor(mutedColor());
        threadSearchCount.setTextSize(12);
        threadSearchCount.setGravity(Gravity.CENTER);
        threadSearchBar.addView(threadSearchCount, new LinearLayout.LayoutParams(dp(42), dp(40)));
        threadSearchBar.addView(threadSearchButton(R.drawable.ic_arrow_up, text("\u524d\u3078", "Previous"), v -> moveActivePageSearch(-1)));
        threadSearchBar.addView(threadSearchButton(R.drawable.ic_arrow_down, text("\u6b21\u3078", "Next"), v -> moveActivePageSearch(1)));
        threadSearchBar.addView(threadSearchButton(R.drawable.ic_close, text("\u9589\u3058\u308b", "Close"), v -> closeThreadSearch()));

        bottomThreadBar = new LinearLayout(this);
        bottomThreadBar.setOrientation(LinearLayout.HORIZONTAL);
        bottomThreadBar.setGravity(Gravity.CENTER_VERTICAL);
        bottomThreadBar.setPadding(dp(10), dp(4), dp(6), dp(4));
        bottomThreadBar.setBackground(bottomBarBackground());

        bottomThreadTitle = new TextView(this);
        bottomThreadTitle.setTextColor(textColor());
        bottomThreadTitle.setTextSize(14);
        bottomThreadTitle.setSingleLine(false);
        bottomThreadTitle.setMaxLines(2);
        bottomThreadTitle.setEllipsize(TextUtils.TruncateAt.END);
        bottomThreadTitle.setIncludeFontPadding(false);
        bottomThreadTitle.setGravity(Gravity.CENTER_VERTICAL);
        attachTitleBarTabSwipe(bottomThreadTitle);
        bottomThreadBar.addView(bottomThreadTitle, new LinearLayout.LayoutParams(
                0, ViewGroup.LayoutParams.MATCH_PARENT, 1));
        attachTitleBarTabSwipe(bottomThreadBar);

        rebuildBottomThreadButtons();

        bottomToolbar = new LinearLayout(this);
        bottomToolbar.setOrientation(LinearLayout.HORIZONTAL);
        bottomToolbar.setGravity(Gravity.CENTER_VERTICAL);
        bottomToolbar.setPadding(dp(6), dp(5), dp(6), dp(5));
        bottomToolbar.setBackground(bottomBarBackground());

        addressBar = new EditText(this);
        addressBar.setSingleLine(true);
        addressBar.setMaxLines(1);
        addressBar.setMinLines(1);
        addressBar.setLines(1);
        addressBar.setHorizontallyScrolling(true);
        addressBar.setHorizontalScrollBarEnabled(false);
        addressBar.setEllipsize(TextUtils.TruncateAt.END);
        addressBar.setTextSize(15);
        addressBar.setIncludeFontPadding(false);
        addressBar.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
        addressBar.setTextColor(textColor());
        addressBar.setHintTextColor(hintTextColor());
        addressBar.setHint(text("\u691c\u7d22\u307e\u305f\u306fURL", "Search or URL"));
        addressBar.setSelectAllOnFocus(true);
        addressBar.setImeOptions(EditorInfo.IME_ACTION_SEARCH);
        addressBar.setInputType(android.text.InputType.TYPE_CLASS_TEXT
                | android.text.InputType.TYPE_TEXT_VARIATION_URI);
        addressBar.setSingleLine(true);
        addressBar.setMaxLines(1);
        addressBar.setMinLines(1);
        addressBar.setLines(1);
        addressBar.setHorizontallyScrolling(true);
        addressBar.setHorizontalScrollBarEnabled(false);
        addressBar.setEllipsize(TextUtils.TruncateAt.END);
        addressBar.setBackground(addressBarBackground());
        addressBar.setCompoundDrawablesWithIntrinsicBounds(R.drawable.ic_search, 0, 0, 0);
        addressBar.setCompoundDrawablePadding(dp(8));
        addressBar.setPadding(dp(12), 0, dp(12), 0);
        addressBar.setOnEditorActionListener((v, actionId, event) -> {
            boolean enter = event != null && event.getKeyCode() == KeyEvent.KEYCODE_ENTER
                    && event.getAction() == KeyEvent.ACTION_UP;
            boolean enterDown = event != null && event.getKeyCode() == KeyEvent.KEYCODE_ENTER
                    && event.getAction() == KeyEvent.ACTION_DOWN;
            if (actionId == EditorInfo.IME_ACTION_SEARCH
                    || actionId == EditorInfo.IME_ACTION_GO
                    || actionId == EditorInfo.IME_ACTION_DONE
                    || enter) {
                openFromAddressBar();
                return true;
            }
            return enterDown;
        });
        addressBar.setOnKeyListener((v, keyCode, event) -> {
            if (keyCode == KeyEvent.KEYCODE_ENTER && event.getAction() == KeyEvent.ACTION_UP) {
                openFromAddressBar();
                return true;
            }
            return false;
        });
        addressBar.setOnClickListener(v -> {
            if (suppressNextAddressClick) {
                suppressNextAddressClick = false;
                return;
            }
            addressBar.requestFocus();
            if (!addressFocusedOnDown) {
                focusAddressBarText();
            }
            showKeyboardSoon();
        });
        addressBar.setOnFocusChangeListener((v, hasFocus) -> {
            if (hasFocus) {
                focusAddressBarText();
                if (!addressTouchInProgress) {
                    showKeyboardSoon();
                }
            } else {
                updateAddressBarDisplay(false);
            }
            updateAddressFocusUi(hasFocus);
        });
        addressBar.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                if (addressBar.hasFocus()) {
                    updateSuggestions();
                }
            }

            @Override
            public void afterTextChanged(Editable s) {
            }
        });
        addressBar.setOnLongClickListener(v -> {
            if (addressBar.hasFocus()) {
                return false;
            }
            suppressNextAddressClick = true;
            mainHandler.postDelayed(() -> suppressNextAddressClick = false, 900);
            addressTouchInProgress = false;
            clearAddressFocus();
            showAddressEditMenu();
            return true;
        });
        addressBar.setOnTouchListener((v, event) -> {
            if (event.getActionMasked() == MotionEvent.ACTION_DOWN) {
                addressFocusedOnDown = addressBar.hasFocus();
                addressTouchInProgress = true;
                addressTouchStartedUnfocused = !addressFocusedOnDown;
                addressUnfocusedLongPressTriggered = false;
                if (addressTouchStartedUnfocused) {
                    scheduleAddressUnfocusedLongPress();
                    return true;
                }
            }
            if (suppressNextAddressClick
                    && (event.getActionMasked() == MotionEvent.ACTION_UP
                    || event.getActionMasked() == MotionEvent.ACTION_CANCEL)) {
                suppressNextAddressClick = false;
                addressTouchInProgress = false;
                addressTouchStartedUnfocused = false;
                addressUnfocusedLongPressTriggered = false;
                cancelAddressUnfocusedLongPress();
                if (!addressFocusedOnDown) {
                    clearAddressFocus();
                }
                return true;
            }
            if (addressTouchStartedUnfocused) {
                if (event.getActionMasked() == MotionEvent.ACTION_UP
                        || event.getActionMasked() == MotionEvent.ACTION_CANCEL) {
                    boolean shouldFocus = event.getActionMasked() == MotionEvent.ACTION_UP
                            && !addressUnfocusedLongPressTriggered;
                    addressTouchInProgress = false;
                    addressTouchStartedUnfocused = false;
                    cancelAddressUnfocusedLongPress();
                    if (shouldFocus) {
                        addressBar.requestFocus();
                        focusAddressBarText();
                        showKeyboardSoon();
                    }
                }
                return true;
            }
            if (event.getActionMasked() == MotionEvent.ACTION_UP
                    || event.getActionMasked() == MotionEvent.ACTION_CANCEL) {
                addressTouchInProgress = false;
                addressTouchStartedUnfocused = false;
                addressUnfocusedLongPressTriggered = false;
                cancelAddressUnfocusedLongPress();
            }
            return false;
        });
        addressBar.setOnScrollChangeListener((v, scrollX, scrollY, oldScrollX, oldScrollY) -> {
            if (!addressBar.hasFocus() && (scrollX != 0 || scrollY != 0)) {
                addressBar.scrollTo(0, 0);
            }
        });
        LinearLayout.LayoutParams addressParams = new LinearLayout.LayoutParams(0, dp(40), 1);
        bottomToolbar.addView(addressBar, addressParams);

        rebuildAddressBarButtons();

        bottomToolbarSlot = chromeBarSlot(bottomToolbar, dp(54));
        threadSearchBarSlot = chromeBarSlot(threadSearchBar, dp(50));
        bottomThreadBarSlot = chromeBarSlot(bottomThreadBar, dp(50));

        if (addressBarTop) {
            root.addView(bottomToolbarSlot, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(54)));
            root.addView(overlayFrame, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, 0, 1));
            root.addView(threadSearchBarSlot, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(50)));
            root.addView(bottomThreadBarSlot, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(50)));
        } else {
            root.addView(overlayFrame, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, 0, 1));
            root.addView(threadSearchBarSlot, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(50)));
            root.addView(bottomThreadBarSlot, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(50)));
            root.addView(bottomToolbarSlot, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(54)));
        }
        syncChromeBarSlots(false);
    }

    private FrameLayout chromeBarSlot(View bar, int height) {
        FrameLayout slot = new FrameLayout(this);
        slot.setClipChildren(true);
        slot.addView(bar, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, height));
        return slot;
    }

    private ImageButton iconButton(int iconRes, String description, View.OnClickListener listener) {
        ImageButton button = new ImageButton(this);
        button.setImageResource(iconRes);
        button.setContentDescription(description);
        button.setColorFilter(textColor());
        button.setBackground(iconButtonBackground());
        button.setPadding(dp(9), dp(9), dp(9), dp(9));
        button.setScaleType(ImageButton.ScaleType.CENTER);
        button.setOnClickListener(listener);
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(dp(34), dp(36));
        params.setMargins(dp(2), 0, dp(2), 0);
        button.setLayoutParams(params);
        return button;
    }

    private View tabCountButton() {
        FrameLayout view = new FrameLayout(this);
        tabCountLabel = tabCountIconSquare(tabOverviewVisible);
        view.addView(tabCountLabel, new FrameLayout.LayoutParams(dp(30), dp(30), Gravity.CENTER));
        view.setContentDescription(text("\u30bf\u30d6", "Tabs"));
        view.setOnClickListener(v -> showTabOverview());
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(dp(42), dp(40));
        view.setLayoutParams(params);
        return view;
    }

    private void scheduleAddressUnfocusedLongPress() {
        cancelAddressUnfocusedLongPress();
        addressUnfocusedLongPressTask = () -> {
            if (addressBar == null || !addressTouchStartedUnfocused || !addressTouchInProgress) {
                return;
            }
            addressUnfocusedLongPressTriggered = true;
            suppressNextAddressClick = true;
            mainHandler.postDelayed(() -> suppressNextAddressClick = false, 900);
            addressTouchInProgress = false;
            addressTouchStartedUnfocused = false;
            clearAddressFocus();
            showAddressEditMenu();
        };
        mainHandler.postDelayed(addressUnfocusedLongPressTask, ViewConfiguration.getLongPressTimeout());
    }

    private void cancelAddressUnfocusedLongPress() {
        if (addressUnfocusedLongPressTask != null) {
            mainHandler.removeCallbacks(addressUnfocusedLongPressTask);
            addressUnfocusedLongPressTask = null;
        }
    }

    private TextView tabCountIconSquare(boolean selected) {
        TextView view = new TextView(this);
        int count = tabCountForCurrentScope();
        view.setText(count > 99 ? "\u221e" : String.valueOf(count));
        view.setTextColor(textColor());
        view.setTextSize(13);
        view.setGravity(Gravity.CENTER);
        view.setSingleLine(true);
        view.setBackground(tabCountBackground(selected));
        view.setLayoutParams(new ViewGroup.LayoutParams(dp(30), dp(30)));
        return view;
    }

    private void updateTabCountButton() {
        if (tabCountLabel == null) {
            return;
        }
        int count = tabCountForCurrentScope();
        tabCountLabel.setText(count > 99 ? "\u221e" : String.valueOf(count));
        tabCountLabel.setBackground(tabCountBackground(tabOverviewVisible));
    }

    private int tabCountForCurrentScope() {
        boolean privateScope = tabOverviewVisible ? tabOverviewPrivateMode : currentTabIsPrivate();
        int count = 0;
        for (CuspTab tab : tabs) {
            if (tab != null && tab.privateBrowsing == privateScope && isNormalTabScope(tab)) {
                count++;
            }
        }
        return count;
    }

    private GradientDrawable tabCountBackground(boolean selected) {
        GradientDrawable drawable = new GradientDrawable();
        drawable.setColor(selected ? activeColor() : Color.TRANSPARENT);
        drawable.setStroke(dp(2), selected ? TEAL : textColor());
        drawable.setCornerRadius(dp(5));
        return drawable;
    }

    private void addToolbarButton(LinearLayout toolbar, int iconRes, String description, View.OnClickListener listener) {
        ImageButton button = iconButton(iconRes, description, listener);
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(dp(34), dp(36));
        params.setMargins(dp(7), 0, dp(7), 0);
        button.setLayoutParams(params);
        toolbarButtons.add(button);
        toolbar.addView(button);
    }

    private void updateAddressFocusUi(boolean focused) {
        for (View button : toolbarButtons) {
            button.setVisibility(focused ? View.GONE : View.VISIBLE);
        }
        if (bottomThreadBar != null) {
            if (focused) {
                bottomThreadBar.setVisibility(View.GONE);
            } else {
                updateBottomThreadBar(currentTab());
            }
        }
        syncChromeBarSlots(false);
        if (focused) {
            updateSuggestions();
        } else if (suggestionsPanel != null) {
            suggestionsPanel.setVisibility(View.GONE);
        }
    }

    private void prepareChromeForLoading() {
        if (addressBar != null && addressBar.hasFocus()) {
            clearAddressFocus();
        }
        if (suggestionsPanel != null) {
            suggestionsPanel.setVisibility(View.GONE);
        }
        for (View button : toolbarButtons) {
            button.setVisibility(View.VISIBLE);
            button.setEnabled(true);
        }
        if (bottomToolbar != null && !tabOverviewVisible) {
            bottomToolbar.setVisibility(View.VISIBLE);
        }
        setChromeBarsHidden(false);
        syncChromeBarSlots(false);
    }

    private boolean hideBarsOnScroll() {
        return preferences != null && preferences.getBoolean(PREF_HIDE_BARS_ON_SCROLL, false);
    }

    private void handleContentScrollForChrome(int scrollY, int oldScrollY) {
        if (!hideBarsOnScroll() || tabOverviewVisible || addressBar != null && addressBar.hasFocus()) {
            setChromeBarsHidden(false);
            return;
        }
        int delta = scrollY - oldScrollY;
        if (Math.abs(delta) < dp(3)) {
            return;
        }
        setChromeBarsHidden(delta > 0 && scrollY > dp(16));
    }

    private void setChromeBarsHidden(boolean hidden) {
        if (!hideBarsOnScroll()) {
            hidden = false;
        }
        if (chromeBarsHidden == hidden) {
            return;
        }
        chromeBarsHidden = hidden;
        syncChromeBarSlots(true);
    }

    private void syncChromeBarSlots(boolean animated) {
        syncChromeBarSlot(bottomToolbarSlot, bottomToolbar, dp(54), animated);
        syncChromeBarSlot(threadSearchBarSlot, threadSearchBar, dp(50), animated,
                addressBar != null && addressBar.hasFocus());
        syncChromeBarSlot(bottomThreadBarSlot, bottomThreadBar, dp(50), animated);
    }

    private void syncChromeBarSlot(FrameLayout slot, View bar, int fullHeight, boolean animated) {
        syncChromeBarSlot(slot, bar, fullHeight, animated, false);
    }

    private void syncChromeBarSlot(FrameLayout slot, View bar, int fullHeight, boolean animated, boolean forceHidden) {
        if (slot == null || bar == null || slot.getLayoutParams() == null) {
            return;
        }
        int targetHeight = forceHidden || chromeBarsHidden || bar.getVisibility() == View.GONE ? 0 : fullHeight;
        float targetTranslation = targetHeight == 0 && bar.getVisibility() != View.GONE ? fullHeight : 0;
        bar.animate().cancel();
        bar.animate().translationY(targetTranslation).setDuration(animated ? 160 : 0).start();
        ViewGroup.LayoutParams params = slot.getLayoutParams();
        if (params.height == targetHeight) {
            return;
        }
        if (!animated) {
            params.height = targetHeight;
            slot.setLayoutParams(params);
            return;
        }
        int startHeight = params.height;
        ValueAnimator animator = ValueAnimator.ofInt(startHeight, targetHeight);
        animator.setDuration(160);
        animator.addUpdateListener(animation -> {
            ViewGroup.LayoutParams next = slot.getLayoutParams();
            if (next == null) {
                return;
            }
            next.height = (int) animation.getAnimatedValue();
            slot.setLayoutParams(next);
        });
        animator.start();
    }

    private void updateSuggestions() {
        if (suggestionsPanel == null || !addressBar.hasFocus()) {
            return;
        }
        suggestionsPanel.removeAllViews();

        boolean allSelected = addressBar.hasSelection()
                && addressBar.getSelectionStart() == 0
                && addressBar.getSelectionEnd() == addressBar.getText().length();
        String query = allSelected ? "" : addressBar.getText().toString().trim().toLowerCase(Locale.ROOT);
        String clipboardLink = query.isEmpty() ? clipboardLink() : null;
        configureSuggestionsPanel(!query.isEmpty());
        if (!query.isEmpty()) {
            int bookmarkCount = 0;
            if (!showBookmarksInTabOverview()) {
                for (SavedItem bookmark : readSavedItems(PREF_THREAD_BOOKMARKS)) {
                    String title = bookmark.title == null ? "" : bookmark.title;
                    String url = bookmark.url == null ? "" : bookmark.url;
                    if (!title.toLowerCase(Locale.ROOT).contains(query)
                            && !url.toLowerCase(Locale.ROOT).contains(query)) {
                        continue;
                    }
                    TextView item = suggestionItem(text("\u30d6\u30c3\u30af\u30de\u30fc\u30af", "Bookmark"), title);
                    item.setOnClickListener(v -> {
                        addressBar.setText(url);
                        addressBar.setSelection(addressBar.getText().length());
                        openFromAddressBar();
                    });
                    if (suggestionsPanel.getChildCount() > 0) {
                        suggestionsPanel.addView(suggestionDivider());
                    }
                    suggestionsPanel.addView(item);
                    bookmarkCount++;
                    if (bookmarkCount >= 6) {
                        break;
                    }
                }
            }
            int tabCount = 0;
            for (int i = 0; i < tabs.size(); i++) {
                CuspTab tab = tabs.get(i);
                String title = tabSuggestionTitle(tab);
                String url = tab.url == null ? "" : tab.url;
                if (!title.toLowerCase(Locale.ROOT).contains(query)
                        && !url.toLowerCase(Locale.ROOT).contains(query)) {
                    continue;
                }
                int index = i;
                TextView item = suggestionItem(text("\u30bf\u30d6", "Tab"), title);
                item.setOnClickListener(v -> switchToTab(index));
                if (suggestionsPanel.getChildCount() > 0) {
                    suggestionsPanel.addView(suggestionDivider());
                }
                suggestionsPanel.addView(item);
                tabCount++;
                if (tabCount >= 6) {
                    break;
                }
            }
            int count = 0;
            for (ThreadHistoryItem history : threadHistory()) {
                if (history.title.toLowerCase(Locale.ROOT).contains(query)) {
                    TextView item = suggestionItem(text("\u95b2\u89a7\u5c65\u6b74", "Browsing history"), history.title);
                    item.setOnClickListener(v -> {
                        addressBar.setText(history.url);
                        addressBar.setSelection(addressBar.getText().length());
                        openFromAddressBar();
                    });
                    if (suggestionsPanel.getChildCount() > 0) {
                        suggestionsPanel.addView(suggestionDivider());
                    }
                    suggestionsPanel.addView(item);
                    count++;
                    if (count >= 6) {
                        break;
                    }
                }
            }
        }
        if (clipboardLink != null) {
            boolean hasRows = suggestionsPanel.getChildCount() > 0;
            if (!query.isEmpty() && !addressBarTop) {
                suggestionsPanel.addView(new View(this), new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, 0, 1));
            }
            if (hasRows) {
                suggestionsPanel.addView(suggestionDivider());
            }
            TextView item = suggestionItem(
                    text("\u30af\u30ea\u30c3\u30d7\u30dc\u30fc\u30c9\u304b\u3089\u30ea\u30f3\u30af\u3092\u5165\u529b", "Enter link from clipboard"),
                    clipboardLink,
                    R.drawable.ic_paste);
            item.setOnClickListener(v -> {
                addressBar.setText(clipboardLink);
                addressBar.setSelection(addressBar.getText().length());
            });
            suggestionsPanel.addView(item);
        }
        if (suggestionsPanel.getChildCount() == 0) {
            if (query.isEmpty()) {
                suggestionsPanel.setVisibility(View.GONE);
                return;
            }
            TextView empty = suggestionItem(text("\u5019\u88dc\u306a\u3057", "No suggestions"), text("\u691c\u7d22\u8a9e\u307e\u305f\u306fURL\u3092\u5165\u529b", "Enter a search term or URL"));
            suggestionsPanel.addView(empty);
        }
        suggestionsPanel.setVisibility(View.VISIBLE);
    }

    private String tabSuggestionTitle(CuspTab tab) {
        if (tab == null) {
            return text("\u65b0\u898f\u30bf\u30d6", "New tab");
        }
        if (tab.title != null && !tab.title.trim().isEmpty()) {
            return tab.title.trim();
        }
        if (tab.url != null && !tab.url.trim().isEmpty()) {
            return tab.url.trim();
        }
        return text("\u65b0\u898f\u30bf\u30d6", "New tab");
    }

    private void configureSuggestionsPanel(boolean fullScreen) {
        if (suggestionsPanel == null) {
            return;
        }
        ViewGroup.LayoutParams currentParams = suggestionsPanel.getLayoutParams();
        FrameLayout.LayoutParams params = currentParams instanceof FrameLayout.LayoutParams
                ? (FrameLayout.LayoutParams) currentParams
                : new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        params.width = ViewGroup.LayoutParams.MATCH_PARENT;
        params.height = fullScreen ? ViewGroup.LayoutParams.MATCH_PARENT : ViewGroup.LayoutParams.WRAP_CONTENT;
        params.gravity = addressBarTop ? Gravity.TOP : Gravity.BOTTOM;
        suggestionsPanel.setLayoutParams(params);
        suggestionsPanel.setPadding(fullScreen ? dp(12) : 0, fullScreen ? dp(12) : 0,
                fullScreen ? dp(12) : 0, fullScreen ? dp(12) : 0);
        suggestionsPanel.setBackground(fullScreen
                ? new ColorDrawable(menuColor())
                : compactSuggestionPanelBackground());
    }

    private GradientDrawable compactSuggestionPanelBackground() {
        GradientDrawable drawable = new GradientDrawable();
        drawable.setColor(menuColor());
        drawable.setStroke(dp(1), borderColor());
        drawable.setCornerRadius(0);
        return drawable;
    }

