    private void updatePrivateChrome() {
        int bg = bgColor();
        int bar = barColor();
        int stroke = borderColor();
        boolean privateActive = privateUiActive();
        boolean dark = Theme.dark(this);
        if (bg == appliedChromeBgColor
                && bar == appliedChromeBarColor
                && stroke == appliedChromeStrokeColor
                && privateActive == appliedChromePrivate
                && dark == appliedChromeDark) {
            return;
        }
        appliedChromeBgColor = bg;
        appliedChromeBarColor = bar;
        appliedChromeStrokeColor = stroke;
        appliedChromePrivate = privateActive;
        appliedChromeDark = dark;
        applySystemBarTheme();
        if (contentFrame != null) {
            contentFrame.setBackgroundColor(bg);
        }
        if (bottomToolbar != null) {
            bottomToolbar.setBackground(bottomBarBackground());
        }
        if (bottomThreadBar != null) {
            bottomThreadBar.setBackground(bottomBarBackground());
        }
        if (threadSearchBar != null) {
            threadSearchBar.setBackground(bottomBarBackground());
        }
        if (addressBar != null) {
            addressBar.setHintTextColor(hintTextColor());
            addressBar.setBackground(addressBarBackground());
        }
        if (threadSearchInput != null) {
            threadSearchInput.setBackground(addressBarBackground());
            threadSearchInput.setHintTextColor(hintTextColor());
        }
        tintChromeContents(bottomToolbar);
        tintChromeContents(bottomThreadBar);
        tintChromeContents(threadSearchBar);
        if (threadSearchCount != null) {
            threadSearchCount.setTextColor(mutedColor());
        }
        updateTabCountButton();
    }

    private void tintChromeContents(View view) {
        if (view == null) {
            return;
        }
        if (view instanceof TextView) {
            TextView textView = (TextView) view;
            textView.setTextColor(textColor());
            if (textView instanceof EditText) {
                textView.setHintTextColor(hintTextColor());
            }
            for (Drawable drawable : textView.getCompoundDrawables()) {
                if (drawable != null) {
                    drawable.setColorFilter(textColor(), PorterDuff.Mode.SRC_IN);
                }
            }
        } else if (view instanceof ImageView) {
            ((ImageView) view).setColorFilter(textColor());
        }
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) {
                tintChromeContents(group.getChildAt(i));
            }
        }
    }

    private void createTab(String url, boolean select) {
        createTab(url, select, -1, false, currentTabIsPrivate());
    }

    private void createTab(String url, boolean select, int returnToIndex) {
        createTab(url, select, returnToIndex, false, currentTabIsPrivate());
    }

    private void createTab(String url, boolean select, int returnToIndex, boolean backToNewTab) {
        createTab(url, select, returnToIndex, backToNewTab, currentTabIsPrivate());
    }

    private void createTab(String url, boolean select, int returnToIndex, boolean backToNewTab, boolean privateBrowsing) {
        CuspTab tab = new CuspTab();
        tab.title = text("\u65b0\u898f\u30bf\u30d6", "New tab");
        tab.url = "";
        tab.returnToIndex = returnToIndex;
        tab.backToNewTab = backToNewTab;
        tab.privateBrowsing = privateBrowsing;
        tab.lastActivatedAt = android.os.SystemClock.uptimeMillis();
        tabs.add(tab);
        if (select) {
            if (url != null && !url.trim().isEmpty()) {
                tab.readerView = loadingView("");
            }
            switchToTab(tabs.size() - 1);
            postOpenInSelectedTab(tab, url);
        } else {
            renderTabs();
        }
    }

    private void createBookmarkOverviewTab(SavedItem item) {
        String url = item == null ? "" : item.url;
        if (url == null || url.trim().isEmpty()) {
            return;
        }
        rememberTabOverviewScroll();
        int existing = bookmarkOverviewTabIndex(item);
        if (existing >= 0) {
            reopenExistingBookmarkOverviewTab(existing, item);
            return;
        }
        CuspTab tab = new CuspTab();
        tab.title = text("\u30d6\u30c3\u30af\u30de\u30fc\u30af", "Bookmark");
        tab.url = "";
        applyThreadTabScope(tab, TabScope.BOOKMARK, item == null ? "" : item.folder);
        tab.privateBrowsing = currentTabIsPrivate();
        tab.lastActivatedAt = android.os.SystemClock.uptimeMillis();
        tabs.add(tab);
        currentIndex = tabs.size() - 1;
        pendingNewTab = false;
        tabOverviewVisible = false;
        contentFrame.removeAllViews();
        contentFrame.addView(loadingView(""));
        openInCurrentTab(normalizeUrl(url), true, TabScope.BOOKMARK,
                item == null ? "" : item.folder, false);
        renderTabs();
    }

    private void reopenExistingBookmarkOverviewTab(int index, SavedItem item) {
        if (index < 0 || index >= tabs.size() || item == null || item.url == null
                || item.url.trim().isEmpty()) {
            return;
        }
        String folder = normalizeSavedFolder(item.folder);
        CuspTab tab = tabs.get(index);
        applyThreadTabScope(tab, TabScope.BOOKMARK, folder);
        tabOverviewVisible = false;
        pendingNewTab = false;
        pendingHistoryAll = false;
        switchToTab(index);
    }

    private int bookmarkOverviewTabIndex(SavedItem item) {
        if (item == null || item.url == null || item.url.trim().isEmpty()) {
            return -1;
        }
        String folder = normalizeSavedFolder(item.folder);
        for (int i = 0; i < tabs.size(); i++) {
            CuspTab tab = tabs.get(i);
            if (tab != null && isBookmarkTabScope(tab)
                    && sameSavedUrl(threadUrl(tab), item.url)
                    && bookmarkTabFolder(tab).equals(folder)) {
                return i;
            }
        }
        return -1;
    }

