    private void showPendingNewTab() {
        showPendingNewTab(false);
    }

    private void showPendingNewTab(boolean privateBrowsing) {
        showPendingNewTab(privateBrowsing, true);
    }

    private void showPendingNewTab(boolean privateBrowsing, boolean rememberCurrentTab) {
        rememberTabOverviewScroll();
        CuspTab previous = rememberCurrentTab ? currentTab() : null;
        if (previous != null) {
            rememberTabScroll(previous);
            requestSaveTabsSoon();
        }
        if (!replyPopups.isEmpty()) {
            dismissThreadPopups();
        }
        pendingNewTab = true;
        pendingPrivateNewTab = privateBrowsing;
        pendingHistoryAll = false;
        resetNewTabHistory();
        tabOverviewVisible = false;
        contentFrame.setBackgroundColor(bgColor());
        contentFrame.removeAllViews();
        visibleThreadPage = null;
        visibleThreadScroll = null;
        visiblePostViews.clear();
        progressBar.setVisibility(View.GONE);
        hideCenterSpinner();
        contentFrame.addView(buildSearchHomeView(false, true));
        addressBar.setText("");
        updateBottomThreadBar(null);
        clearAddressFocus();
        renderTabs();
    }

    private void showPendingNewTabHistory(boolean fullHistory) {
        if (!pendingNewTab) {
            showPendingNewTab();
            return;
        }
        rememberTabOverviewScroll();
        pendingHistoryAll = fullHistory;
        recordNewTabPage(fullHistory ? "history" : "home");
        tabOverviewVisible = false;
        contentFrame.setBackgroundColor(bgColor());
        contentFrame.removeAllViews();
        progressBar.setVisibility(View.GONE);
        hideCenterSpinner();
        contentFrame.addView(fullHistory ? buildHistoryView() : buildSearchHomeView(false));
        addressBar.setText("");
        clearAddressFocus();
        renderTabs();
    }

    private void cancelPendingNewTab() {
        pendingNewTab = false;
        pendingPrivateNewTab = false;
        if (tabs.isEmpty()) {
            showPendingNewTab();
            return;
        }
        pendingHistoryAll = false;
        switchToTab(Math.max(0, Math.min(currentIndex, tabs.size() - 1)));
    }

    private boolean restoreTabs() {
        String saved = preferences.getString(PREF_TABS, "");
        if (saved == null || saved.isEmpty()) {
            return false;
        }
        try {
            boolean legacySession = saved.trim().startsWith("{");
            JSONObject root = legacySession
                    ? new JSONObject(saved)
                    : preferenceJsonObject(PREF_TAB_SESSION_STATE);
            JSONArray array = legacySession ? root.optJSONArray("tabs") : new JSONArray(saved);
            if (array == null || array.length() == 0) {
                return false;
            }
            resetTabsForRestore();
            tabOverviewNormalScrollY = Math.max(0, root.optInt(TAB_OVERVIEW_NORMAL_SCROLL_KEY, 0));
            tabOverviewPrivateScrollY = Math.max(0, root.optInt(TAB_OVERVIEW_PRIVATE_SCROLL_KEY, 0));
            tabOverviewScrollY = currentTabIsPrivate() ? tabOverviewPrivateScrollY : tabOverviewNormalScrollY;
            restoredTabOverviewNormalOrder.clear();
            restoredTabOverviewNormalOrder.addAll(stringListFromJson(root.optJSONArray(TAB_OVERVIEW_NORMAL_ORDER_KEY)));
            restoredTabOverviewOrderSignature = root.optString(TAB_OVERVIEW_ORDER_SIGNATURE_KEY, "");
            lastTabOverviewNormalOrder.clear();
            lastTabOverviewNormalOrder.addAll(restoredTabOverviewNormalOrder);
            lastTabOverviewOrderSignature = restoredTabOverviewOrderSignature;
            int selected = Math.max(0, Math.min(root.optInt("current", 0), array.length() - 1));
            for (int i = 0; i < array.length(); i++) {
                JSONObject item = array.getJSONObject(i);
                String url = item.optString("url", "");
                CuspTab tab = new CuspTab();
                tab.sessionId = item.optString("sessionId", "");
                if (tab.sessionId.isEmpty()) {
                    tab.sessionId = UUID.randomUUID().toString();
                }
                tab.title = item.optString("title", text("\u65b0\u898f\u30bf\u30d6", "New tab"));
                tab.url = url;
                tab.privateBrowsing = item.optBoolean("privateBrowsing", false);
                applyThreadTabScope(tab,
                        tabScopeFromSavedItem(item),
                        item.optString("bookmarkOverviewFolder", ""));
                String nativeKind = item.optString("nativeKind", "");
                tab.nativeKind = nativeKind.isEmpty() || "null".equals(nativeKind) ? null : nativeKind;
                tab.threadScrollRatio = (float) item.optDouble("threadScrollRatio", 0);
                tab.threadBottomOffset = item.optInt("threadBottomOffset", 0);
                tab.threadScrollUrl = item.optString("threadScrollUrl", url);
                tab.hasSavedThreadScroll = item.optBoolean("hasSavedThreadScroll", false);
                tab.contentScrollRatio = (float) item.optDouble("contentScrollRatio", 0);
                tab.contentScrollY = item.optInt("contentScrollY", 0);
                tab.contentScrollUrl = item.optString("contentScrollUrl", url);
                tab.hasSavedContentScroll = item.optBoolean("hasSavedContentScroll", false);
                tab.knownMaxPostNumber = item.optInt("knownMaxPostNumber", 0);
                tab.knownPostCount = item.optInt("knownPostCount", 0);
                tab.knownBoardOrder = item.optInt("knownBoardOrder", 0);
                tab.cachedUnreadCount = item.optInt("cachedUnreadCount", 0);
                tab.hasThreadStats = item.optBoolean("hasThreadStats", tab.knownMaxPostNumber > 0);
                tab.knownThreadArchived = item.optBoolean("knownThreadArchived", false);
                tab.deferredThreadUpdatePostNumber = item.optInt("deferredThreadUpdatePostNumber", 0);
                tab.overviewBoardName = item.optString("overviewBoardName", "");
                tab.overviewTitle = item.optString("overviewTitle", "");
                restoreNavigationHistory(tab, item);
                tab.readerMode = tab.nativeKind != null || url.isEmpty();
                if (isThreadPageNativeKind(tab.nativeKind)) {
                    tab.savedThreadPageJson = item.optJSONObject("threadPage");
                } else if (NATIVE_SEARCH.equals(tab.nativeKind) || NATIVE_BOARD.equals(tab.nativeKind)) {
                    tab.savedSearchPageJson = item.optJSONObject("searchPage");
                }
                boolean hasPayloadKind = isThreadPageNativeKind(tab.nativeKind)
                        || NATIVE_SEARCH.equals(tab.nativeKind) || NATIVE_BOARD.equals(tab.nativeKind);
                tab.payloadLoaded = legacySession || tab.savedThreadPageJson != null
                        || tab.savedSearchPageJson != null || !hasPayloadKind;
                if (tab.navigationHistory.isEmpty() && url != null && !url.isEmpty()) {
                    tab.navigationHistory.add(url);
                    tab.navigationIndex = 0;
                }
                tab.returnToIndex = -1;
                tabs.add(tab);
                restoreSavedTabOverviewResult(tab);
            }
            switchToTab(selected);
            renderTabs();
            if (legacySession) {
                // Migrate the old monolithic JSON after the first upgraded launch.
                saveTabs(false);
            }
            return true;
        } catch (Exception error) {
            return false;
        }
    }

    private String themeMode() {
        return preferences.getString(PREF_THEME_MODE, Theme.MODE_SYSTEM);
    }

    private void openInTab(CuspTab tab, String url, boolean addHistory) {
        int oldIndex = currentIndex;
        int index = tabs.indexOf(tab);
        if (index < 0) {
            return;
        }
        TabScope scope = tab.tabScope;
        String bookmarkFolder = bookmarkTabFolder(tab);
        currentIndex = index;
        openInCurrentTab(url, addHistory, scope, bookmarkFolder, false);
        currentIndex = Math.max(0, Math.min(oldIndex, tabs.size() - 1));
        if (currentIndex != index && contentFrame.getChildCount() > 0 && currentTab() != null && currentTab().readerView != null) {
            switchToTab(currentIndex);
        }
    }

    private void resetTabsForRestore() {
        for (CuspTab tab : tabs) {
            unloadTabView(tab);
        }
        tabs.clear();
        currentIndex = -1;
        clearTabOverviewResultCache();
        tabOverviewNormalView = null;
        tabOverviewPrivateView = null;
        tabOverviewValueDirtyTabs.clear();
    }

    private void saveTabs() {
        saveTabs(false);
    }

    private void saveTabs(boolean synchronous) {
        try {
            CuspTab current = currentTab();
            if (current != null) {
                rememberTabScroll(current);
            }
            rememberTabOverviewScroll();
            JSONArray array = new JSONArray();
            Set<String> activeSessionIds = new LinkedHashSet<>();
            int savedCurrent = 0;
            int savedIndex = 0;
            for (CuspTab tab : tabs) {
                if (tab.privateBrowsing) {
                    continue;
                }
                if (tab.sessionId == null || tab.sessionId.isEmpty()) {
                    tab.sessionId = UUID.randomUUID().toString();
                }
                activeSessionIds.add(tab.sessionId);
                JSONObject item = new JSONObject();
                item.put("sessionId", tab.sessionId);
                item.put("url", tab.url == null ? "" : tab.url);
                item.put("title", tab.title == null ? "Tab" : tab.title);
                item.put("privateBrowsing", false);
                item.put("tabScope", tab.tabScope.name());
                item.put("bookmarkOverviewTab", isBookmarkTabScope(tab));
                item.put("bookmarkOverviewFolder", normalizeSavedFolder(tab.bookmarkOverviewFolder));
                item.put("nativeKind", tab.nativeKind == null ? JSONObject.NULL : tab.nativeKind);
                item.put("threadScrollRatio", tab.threadScrollRatio);
                item.put("threadBottomOffset", tab.threadBottomOffset);
                item.put("threadScrollUrl", tab.threadScrollUrl == null ? threadUrl(tab) : tab.threadScrollUrl);
                item.put("hasSavedThreadScroll", tab.hasSavedThreadScroll);
                item.put("contentScrollRatio", tab.contentScrollRatio);
                item.put("contentScrollY", tab.contentScrollY);
                item.put("contentScrollUrl", tab.contentScrollUrl == null ? tabUrlForScroll(tab) : tab.contentScrollUrl);
                item.put("hasSavedContentScroll", tab.hasSavedContentScroll);
                item.put("knownMaxPostNumber", tab.knownMaxPostNumber);
                item.put("knownPostCount", tab.knownPostCount);
                item.put("knownBoardOrder", tab.knownBoardOrder);
                item.put("cachedUnreadCount", tab.cachedUnreadCount);
                item.put("hasThreadStats", tab.hasThreadStats);
                item.put("knownThreadArchived", tab.knownThreadArchived);
                item.put("deferredThreadUpdatePostNumber", tab.deferredThreadUpdatePostNumber);
                item.put("overviewBoardName", overviewBoardNameForSave(tab));
                item.put("overviewTitle", overviewTitleForSave(tab));
                item.put("navigationIndex", tab.navigationIndex);
                JSONArray history = new JSONArray();
                for (String historyUrl : tab.navigationHistory) {
                    history.put(historyUrl);
                }
                item.put("navigationHistory", history);
                boolean currentTabForSave = tab == current;
                if (isThreadPageNativeKind(tab.nativeKind) && tab.threadPage != null && tab.threadPage.error == null) {
                    updateTabThreadStats(tab, tab.threadPage);
                }
                if (currentTabForSave) {
                    persistCurrentTabPayload(tab);
                }
                array.put(item);
                if (tab == current) {
                    savedCurrent = savedIndex;
                }
                savedIndex++;
            }
            JSONObject root = new JSONObject();
            root.put("current", Math.max(0, savedCurrent));
            root.put(TAB_OVERVIEW_NORMAL_SCROLL_KEY, tabOverviewNormalScrollY);
            root.put(TAB_OVERVIEW_PRIVATE_SCROLL_KEY, tabOverviewPrivateScrollY);
            writeTabOverviewOrderSnapshot(root);
            SharedPreferences.Editor editor = preferences.edit()
                    .putString(PREF_TABS, array.toString())
                    .putString(PREF_TAB_SESSION_STATE, root.toString());
            if (synchronous) {
                editor.commit();
            } else {
                editor.apply();
            }
            tabPayloadStore.removeStale(activeSessionIds);
        } catch (Exception ignored) {
        }
    }

    private void persistCurrentTabPayload(CuspTab tab) {
        if (tab == null || tab.sessionId == null || tab.sessionId.isEmpty()) {
            return;
        }
        try {
            JSONObject payload = new JSONObject();
            if (isThreadPageNativeKind(tab.nativeKind) && tab.threadPage != null && tab.threadPage.error == null) {
                payload.put("threadPage", threadPageToJson(tab.threadPage));
            } else if (isThreadPageNativeKind(tab.nativeKind) && tab.savedThreadPageJson != null) {
                payload.put("threadPage", tab.savedThreadPageJson);
            } else if ((NATIVE_SEARCH.equals(tab.nativeKind) || NATIVE_BOARD.equals(tab.nativeKind))
                    && tab.searchPage != null && tab.searchPage.error == null) {
                payload.put("searchPage", searchPageToJson(tab.searchPage));
            } else if ((NATIVE_SEARCH.equals(tab.nativeKind) || NATIVE_BOARD.equals(tab.nativeKind))
                    && tab.savedSearchPageJson != null) {
                payload.put("searchPage", tab.savedSearchPageJson);
            } else {
                return;
            }
            String raw = payload.toString();
            if (!raw.equals(tab.lastSavedPayloadJson) && tabPayloadStore.write(tab.sessionId, raw)) {
                tab.lastSavedPayloadJson = raw;
                tab.payloadLoaded = true;
            }
        } catch (Exception ignored) {
        }
    }

    private void requestSaveTabsSoon() {
        requestSaveTabsSoon(SAVE_TABS_DELAY_MS);
    }

    private void requestSaveTabsSoon(long delayMs) {
        if (saveTabsTask != null) {
            mainHandler.removeCallbacks(saveTabsTask);
        }
        saveTabsTask = () -> {
            saveTabsTask = null;
            saveTabs(false);
        };
        mainHandler.postDelayed(saveTabsTask, Math.max(0L, delayMs));
    }

    private List<String> stringListFromJson(JSONArray array) {
        List<String> result = new ArrayList<>();
        if (array == null) {
            return result;
        }
        for (int i = 0; i < array.length(); i++) {
            String value = array.optString(i, "");
            if (!value.isEmpty()) {
                result.add(value);
            }
        }
        return result;
    }

    private JSONArray stringListToJson(List<String> values) {
        JSONArray array = new JSONArray();
        if (values == null) {
            return array;
        }
        for (String value : values) {
            array.put(value == null ? "" : value);
        }
        return array;
    }

    private void writeTabOverviewOrderSnapshot(JSONObject root) {
        if (root == null || lastTabOverviewNormalOrder.isEmpty()
                || !tabOverviewSortSignature().equals(lastTabOverviewOrderSignature)
                || !tabOverviewOrderMatchesCurrent(lastTabOverviewNormalOrder, false)) {
            return;
        }
        try {
            root.put(TAB_OVERVIEW_NORMAL_ORDER_KEY, stringListToJson(lastTabOverviewNormalOrder));
            root.put(TAB_OVERVIEW_ORDER_SIGNATURE_KEY, lastTabOverviewOrderSignature);
        } catch (Exception ignored) {
        }
    }

    private void scheduleTabUnload() {
        if (unloadTabsTask != null) {
            return;
        }
        unloadTabsTask = () -> {
            unloadTabsTask = null;
            unloadIdleTabs();
            scheduleTabUnload();
        };
        mainHandler.postDelayed(unloadTabsTask, TAB_UNLOAD_INTERVAL_MS);
    }

    private void scheduleBackgroundTrim() {
        if (backgroundTrimTask != null) {
            return;
        }
        backgroundTrimTask = () -> {
            backgroundTrimTask = null;
            if (!tabs.isEmpty() && !pendingNewTab) {
                trimBackgroundTabViews();
                trimBackgroundPageData();
            }
        };
        mainHandler.postDelayed(backgroundTrimTask, BACKGROUND_TRIM_DELAY_MS);
    }

    private void unloadIdleTabs() {
        if (tabs.isEmpty() || pendingNewTab) {
            return;
        }
        long now = android.os.SystemClock.uptimeMillis();
        long unloadAfter = tabs.size() > 8 ? TAB_UNLOAD_AFTER_MANY_TABS_MS : TAB_UNLOAD_AFTER_MS;
        for (int i = 0; i < tabs.size(); i++) {
            if (i == currentIndex) {
                continue;
            }
            CuspTab tab = tabs.get(i);
            if (tab.readerView == null || now - tab.lastActivatedAt < unloadAfter) {
                continue;
            }
            unloadTabView(tab);
        }
        trimBackgroundTabViews();
        trimBackgroundPageData();
    }

    private void trimBackgroundTabViews() {
        while (backgroundTabViewCount() > maxBackgroundTabViews()) {
            CuspTab oldest = null;
            for (int i = 0; i < tabs.size(); i++) {
                if (i == currentIndex) {
                    continue;
                }
                CuspTab tab = tabs.get(i);
                if (tab.readerView == null) {
                    continue;
                }
                if (oldest == null || tab.lastActivatedAt < oldest.lastActivatedAt) {
                    oldest = tab;
                }
            }
            if (oldest == null) {
                return;
            }
            unloadTabView(oldest);
        }
    }

    private int maxBackgroundTabViews() {
        return tabs.size() > MANY_TABS_THRESHOLD
                ? MAX_BACKGROUND_TAB_VIEWS_MANY_TABS
                : MAX_BACKGROUND_TAB_VIEWS;
    }

    private int backgroundTabViewCount() {
        int count = 0;
        for (int i = 0; i < tabs.size(); i++) {
            if (i != currentIndex && tabs.get(i).readerView != null) {
                count++;
            }
        }
        return count;
    }

    private void trimBackgroundPageData() {
        while (backgroundPageDataCount() > maxBackgroundPageData()) {
            CuspTab oldest = null;
            for (int i = 0; i < tabs.size(); i++) {
                if (i == currentIndex) {
                    continue;
                }
                CuspTab tab = tabs.get(i);
                if (!hasUnloadablePageData(tab)) {
                    continue;
                }
                if (oldest == null || tab.lastActivatedAt < oldest.lastActivatedAt) {
                    oldest = tab;
                }
            }
            if (oldest == null) {
                return;
            }
            unloadTabPageData(oldest);
        }
    }

    private int maxBackgroundPageData() {
        return tabs.size() > MANY_TABS_THRESHOLD
                ? MAX_BACKGROUND_PAGE_DATA_MANY_TABS
                : MAX_BACKGROUND_PAGE_DATA;
    }

    private int backgroundPageDataCount() {
        int count = 0;
        for (int i = 0; i < tabs.size(); i++) {
            if (i != currentIndex && hasUnloadablePageData(tabs.get(i))) {
                count++;
            }
        }
        return count;
    }

    private boolean hasUnloadablePageData(CuspTab tab) {
        return tab != null && (tab.threadPage != null || tab.searchPage != null);
    }

    private void unloadTabView(CuspTab tab) {
        if (tab == null || tab.readerView == null) {
            return;
        }
        rememberTabScroll(tab);
        clearTabViewState(tab);
    }

    private void clearTabViewState(CuspTab tab) {
        if (tab == null) {
            return;
        }
        cancelThreadChunkRender(tab);
        if (tab.threadBottomLoader != null) {
            resetBottomRefreshLoader(tab.threadBottomLoader);
        }
        clearBoardTopRefreshState(tab);
        if (tab.readerView != null && tab.readerView.getParent() instanceof ViewGroup) {
            ((ViewGroup) tab.readerView.getParent()).removeView(tab.readerView);
        }
        tab.threadScrollChromeFrames = 0;
        tab.readerView = null;
        tab.threadScroll = null;
        tab.threadList = null;
        tab.threadBottomLoader = null;
        tab.scrollScrubber = null;
        tab.unreadMarkerLayer = null;
        tab.postViews = null;
        tab.postSlots = null;
        tab.renderedPostSlots = null;
    }

    private void unloadTabPageData(CuspTab tab) {
        if (tab == null) {
            return;
        }
        if (tab.threadPage != null) {
            updateTabThreadStats(tab, tab.threadPage);
            if (!isPrivateTab(tab)) {
                cacheThreadPage(tab.threadPage);
            }
            tab.threadPage = null;
        }
        tab.searchPage = null;
        tab.savedThreadPageJson = null;
        tab.savedSearchPageJson = null;
        tab.boardHistoryPages.clear();
    }

    private JSONObject threadPageToJson(ThreadPage page) throws Exception {
        JSONObject object = new JSONObject();
        object.put("url", page.url);
        object.put("title", page.title);
        object.put("archived", page.archived);
        object.put("datUrl", page.datUrl == null ? "" : page.datUrl);
        object.put("datByteLength", page.datByteLength);
        object.put("hissiSummary", page.hissiSummary == null ? "" : page.hissiSummary);
        JSONArray posts = new JSONArray();
        for (Post post : page.posts) {
            JSONObject item = new JSONObject();
            item.put("number", post.number);
            item.put("name", post.name);
            item.put("date", post.date);
            item.put("body", post.body);
            item.put("sourceTitle", post.sourceTitle == null ? "" : post.sourceTitle);
            item.put("sourceUrl", post.sourceUrl == null ? "" : post.sourceUrl);
            item.put("sourcePostNumber", post.sourcePostNumber);
            posts.put(item);
        }
        object.put("posts", posts);
        return object;
    }

    private ThreadPage threadPageFromJson(JSONObject object) {
        if (object == null) {
            return null;
        }
        ThreadPage page = new ThreadPage();
        page.url = object.optString("url", "");
        page.title = object.optString("title", hostTitle(page.url));
        page.archived = object.optBoolean("archived", false);
        page.datUrl = object.optString("datUrl", "");
        page.datByteLength = object.optLong("datByteLength", 0);
        page.hissiSummary = object.optString("hissiSummary", "");
        JSONArray posts = object.optJSONArray("posts");
        if (posts != null) {
            for (int i = 0; i < posts.length(); i++) {
                JSONObject item = posts.optJSONObject(i);
                if (item == null) {
                    continue;
                }
                Post post = new Post();
                post.number = item.optInt("number", i + 1);
                post.name = item.optString("name", "");
                post.date = item.optString("date", "");
                post.body = item.optString("body", "");
                post.sourceTitle = item.optString("sourceTitle", "");
                post.sourceUrl = item.optString("sourceUrl", "");
                post.sourcePostNumber = item.optInt("sourcePostNumber", 0);
                post.cachedLikelyAa = likelyAaPost(post.body);
                page.posts.add(post);
                page.postsByNumber.put(post.number, post);
            }
        }
        return page;
    }

    private void cacheThreadPage(ThreadPage page) {
        if (Looper.myLooper() == Looper.getMainLooper()) {
            ioExecutor.execute(() -> writeThreadPageCache(page));
        } else {
            writeThreadPageCache(page);
        }
    }

    private void writeThreadPageCache(ThreadPage page) {
        if (page == null || page.url == null || page.url.isEmpty() || page.error != null || page.posts.isEmpty()) {
            return;
        }
        if (!AppCache.enabled(preferences)) {
            return;
        }
        try {
            File dir = threadCacheDir();
            if (!dir.exists() && !dir.mkdirs()) {
                return;
            }
            byte[] bytes = threadPageToJson(page).toString().getBytes(Charset.forName("UTF-8"));
            if (!AppCache.canWrite(this, preferences, bytes.length)) {
                return;
            }
            try (FileOutputStream out = new FileOutputStream(threadCacheFile(page.url))) {
                out.write(bytes);
            }
        } catch (Exception ignored) {
        }
    }

    private ThreadPage readCachedThreadPage(String url) {
        if (url == null || url.isEmpty() || !AppCache.enabled(preferences)) {
            return null;
        }
        try {
            File file = threadCacheFile(url);
            if (!file.exists() || file.length() <= 0) {
                return null;
            }
            file.setLastModified(System.currentTimeMillis());
            return threadPageFromJson(new JSONObject(new String(readFileBytes(file), Charset.forName("UTF-8"))));
        } catch (Exception ignored) {
            return null;
        }
    }

    private File threadCacheDir() {
        return new File(getCacheDir(), "threads");
    }

    private File threadCacheFile(String url) throws Exception {
        return new File(threadCacheDir(), cacheKey(url) + ".json");
    }

    private JSONObject searchPageToJson(SearchPage page) throws Exception {
        JSONObject object = new JSONObject();
        object.put("url", page.url);
        object.put("title", page.title);
        JSONArray results = new JSONArray();
        for (SearchResult result : page.results) {
            JSONObject item = new JSONObject();
            item.put("title", result.title);
            item.put("url", result.url);
            item.put("meta", result.meta);
            item.put("category", result.category == null ? "" : result.category);
            item.put("responses", result.responses);
            item.put("velocity", result.velocity);
            item.put("boardOrder", result.boardOrder);
            item.put("createdAt", result.createdAt);
            item.put("unread", result.unread);
            item.put("hasReadHistory", result.hasReadHistory);
            item.put("boardName", result.boardName == null ? "" : result.boardName);
            if (result.priorityMatch != null) {
                JSONObject priority = new JSONObject();
                priority.put("value", result.priorityMatch.value);
                priority.put("regex", result.priorityMatch.regex);
                item.put("priorityMatch", priority);
            }
            results.put(item);
        }
        object.put("results", results);
        if (page.categoryCounts != null && !page.categoryCounts.isEmpty()) {
            JSONObject counts = new JSONObject();
            for (Map.Entry<String, Integer> entry : page.categoryCounts.entrySet()) {
                counts.put(entry.getKey(), entry.getValue());
            }
            object.put("categoryCounts", counts);
        }
        object.put("fullTextPage", page.fullTextPage);
        object.put("fullTextHasMore", page.fullTextHasMore);
        object.put("fullTextReachedEnd", page.fullTextReachedEnd);
        return object;
    }

    private SearchPage searchPageFromJson(JSONObject object) {
        return searchPageFromJson(object, true);
    }

    private SearchPage searchPageFromJson(JSONObject object, boolean refreshReadState) {
        if (object == null) {
            return null;
        }
        SearchPage page = new SearchPage();
        page.url = object.optString("url", "");
        page.title = object.optString("title", searchTitle(page.url));
        page.fullTextPage = Math.max(1, object.optInt("fullTextPage", 1));
        page.fullTextHasMore = object.optBoolean("fullTextHasMore", false);
        page.fullTextReachedEnd = object.optBoolean("fullTextReachedEnd", false);
        JSONObject readPosts = null;
        List<ThreadHistoryItem> historyItems = null;
        Set<String> historyUrls = null;
        if (refreshReadState) {
            readPosts = readHistoryEnabled() ? preferenceJsonObject(PREF_READ_POSTS) : new JSONObject();
            historyItems = threadHistory();
            historyUrls = threadHistoryUrlSnapshot(historyItems);
        }
        JSONArray results = object.optJSONArray("results");
        if (results != null) {
            for (int i = 0; i < results.length(); i++) {
                JSONObject item = results.optJSONObject(i);
                if (item == null) {
                    continue;
                }
                SearchResult result = new SearchResult();
                result.title = item.optString("title", "");
                result.url = item.optString("url", "");
                result.meta = item.optString("meta", "");
                result.category = item.optString("category", "");
                result.responses = item.optInt("responses", 0);
                result.velocity = item.optDouble("velocity", 0d);
                result.boardOrder = item.optInt("boardOrder", i);
                result.createdAt = item.optLong("createdAt", 0L);
                result.unread = item.optInt("unread", 0);
                result.hasReadHistory = item.optBoolean("hasReadHistory", result.unread > 0);
                result.boardName = item.optString("boardName", "");
                if (refreshReadState && result.responses > 0 && datAddress(result.url) != null) {
                    result.hasReadHistory = threadHistoryContains(historyUrls, historyItems, result.url);
                    int readNumber = result.hasReadHistory ? boardThreadReadNumber(readPosts, result.url) : 0;
                    result.unread = result.hasReadHistory ? Math.max(0, result.responses - readNumber) : 0;
                }
                Object priority = item.opt("priorityMatch");
                if (priority instanceof JSONObject) {
                    JSONObject priorityObject = (JSONObject) priority;
                    String value = priorityObject.optString("value", "").trim();
                    if (!value.isEmpty()) {
                        result.priorityMatch = new BoardPriorityMatch(value, priorityObject.optBoolean("regex", false));
                    }
                } else if (priority instanceof String) {
                    String value = ((String) priority).trim();
                    if (!value.isEmpty()) {
                        result.priorityMatch = new BoardPriorityMatch(value, false);
                    }
                }
                page.results.add(result);
            }
        }
        JSONObject counts = object.optJSONObject("categoryCounts");
        if (counts != null) {
            page.categoryCounts = new LinkedHashMap<>();
            Iterator<String> keys = counts.keys();
            while (keys.hasNext()) {
                String key = keys.next();
                page.categoryCounts.put(key, counts.optInt(key, 0));
            }
        }
        return page;
    }

    private SearchPage parseShitarabaBbsMenuJson(String menuUrl, String json) throws Exception {
        JSONObject root = new JSONObject(json);
        SearchPage page = new SearchPage();
        page.url = menuUrl;
        page.title = "\u3057\u305f\u3089\u3070\u63b2\u793a\u677f";
        Map<String, Integer> categoryCounts = new LinkedHashMap<>();
        Map<String, String> boardNames = new LinkedHashMap<>();
        Set<String> seen = new LinkedHashSet<>();
        JSONArray menus = root.optJSONArray("menu_list");
        if (menus != null) {
            for (int i = 0; i < menus.length(); i++) {
                JSONObject category = menus.optJSONObject(i);
                if (category == null) {
                    continue;
                }
                String categoryName = cleanText(category.optString("category_name", ""));
                JSONArray boards = category.optJSONArray("category_content");
                if (boards == null) {
                    continue;
                }
                for (int j = 0; j < boards.length(); j++) {
                    JSONObject board = boards.optJSONObject(j);
                    if (board == null) {
                        continue;
                    }
                    String url = normalizeUrl(board.optString("url", ""));
                    if (url.isEmpty() || !seen.add(url)) {
                        continue;
                    }
                    String title = cleanText(board.optString("board_name", ""));
                    if (title.isEmpty()) {
                        title = boardNameFromUrl(url);
                    }
                    SearchResult result = new SearchResult();
                    result.title = title == null || title.isEmpty() ? hostTitle(url) : title;
                    result.url = url;
                    result.meta = Uri.parse(url).getHost();
                    result.category = categoryName;
                    page.results.add(result);
                    boardNames.put(url, result.title);
                    categoryCounts.put(categoryName, categoryCounts.containsKey(categoryName)
                            ? categoryCounts.get(categoryName) + 1 : 1);
                }
            }
        }
        page.categoryCounts = categoryCounts;
        saveBoardDisplayNames(boardNames);
        if (page.results.isEmpty()) {
            throw new IllegalStateException(text("\u677f\u30ea\u30f3\u30af\u304c\u898b\u3064\u304b\u308a\u307e\u305b\u3093", "No board links found."));
        }
        return page;
    }

    private SearchPage parseFutabaBoard(String boardUrl, String html) {
        SearchPage page = new SearchPage();
        page.url = boardUrl;
        page.title = boardTitle(boardUrl);
        JSONObject readPosts = readHistoryEnabled() ? preferenceJsonObject(PREF_READ_POSTS) : new JSONObject();
        List<ThreadHistoryItem> historyItems = threadHistory();
        Set<String> historyUrls = threadHistoryUrlSnapshot(historyItems);
        String boardDisplay = displayBoardTitle(boardUrl);
        Pattern pattern = Pattern.compile(
                "<div[^>]+class=[\"'][^\"']*(?<![A-Za-z0-9_-])thre(?![A-Za-z0-9_-])[^\"']*[\"'][^>]*data-res=[\"']?(\\d+)[\"']?[^>]*>(.*?)(?=<div[^>]+class=[\"'][^\"']*(?<![A-Za-z0-9_-])thre(?![A-Za-z0-9_-])|<table[^>]+align=left|</body>)",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = pattern.matcher(html == null ? "" : html);
        int order = 1;
        while (matcher.find()) {
            String key = matcher.group(1);
            String block = matcher.group(2);
            String rawTitle = firstMatch(block, "<blockquote[^>]*>(.*?)</blockquote>");
            String title = rawTitle == null ? "" : cleanText(rawTitle);
            if (title.isEmpty()) {
                title = "No." + key;
            }
            int responses = futabaResponseCount(block);
            SearchResult result = new SearchResult();
            result.title = title;
            result.url = futabaThreadUrl(boardUrl, key);
            result.responses = responses;
            result.velocity = threadVelocity(key, responses);
            result.boardOrder = order;
            result.createdAt = threadCreatedAtMillis(key);
            result.hasReadHistory = threadHistoryContains(historyUrls, historyItems, result.url);
            int readNumber = result.hasReadHistory ? boardThreadReadNumber(readPosts, result.url) : 0;
            result.unread = result.hasReadHistory ? Math.max(0, responses - readNumber) : 0;
            result.boardName = boardDisplay;
            result.priorityMatch = matchingBoardPriorityWord(title, boardUrl);
            result.meta = boardThreadMeta(result);
            page.results.add(result);
            order++;
        }
        sortBoardResults(page.results);
        return page;
    }

    private int futabaResponseCount(String block) {
        int replies = 0;
        Matcher matcher = Pattern.compile("class=[\"']rsc[\"']", Pattern.CASE_INSENSITIVE).matcher(block == null ? "" : block);
        while (matcher.find()) {
            replies++;
        }
        return replies + 1;
    }

    private String futabaThreadUrl(String boardUrl, String key) {
        try {
            Uri uri = Uri.parse(normalizeUrl(boardUrl));
            String scheme = uri.getScheme() == null ? "https" : uri.getScheme();
            String host = uri.getHost();
            List<String> parts = pathParts(uri.getPath());
            if (host == null || parts.isEmpty()) {
                return trimSlash(boardUrl) + "/res/" + key + ".htm";
            }
            String board = parts.get(0);
            return scheme + "://" + host + "/" + board + "/res/" + key + ".htm";
        } catch (Exception ignored) {
            return trimSlash(boardUrl) + "/res/" + key + ".htm";
        }
    }

    private SearchPage cachedBbsDirectoryPage(String directoryUrl) {
        CachedBbsMenu cached = readBbsMenuCache(directoryUrl);
        return cached == null ? null : cached.page;
    }

    private CachedBbsMenu readBbsMenuCache(String directoryUrl) {
        String key = bbsMenuCacheKey(directoryUrl);
        if (key.isEmpty() || !isCacheableBbsMenuUrl(directoryUrl)) {
            return null;
        }
        CachedBbsMenu memory = bbsMenuCache.get(key);
        if (memory != null && memory.page != null && !memory.page.results.isEmpty()) {
            memory.page.title = bbsMenuTitle(directoryUrl, memory.page.title);
            bbsMenuCache.remove(key);
            bbsMenuCache.put(key, memory);
            return memory;
        }
        try {
            JSONObject item = preferenceJsonObject(PREF_BBSMENU_CACHE).optJSONObject(key);
            if (item == null && isFiveChBbsMenuUrl(directoryUrl)) {
                item = legacyFiveChBbsMenuCache();
            }
            if (item == null) {
                return null;
            }
            SearchPage page = searchPageFromJson(item.optJSONObject("page"), false);
            if (page == null || page.results.isEmpty()) {
                return null;
            }
            page.title = bbsMenuTitle(directoryUrl, page.title);
            if (page.url == null || page.url.trim().isEmpty()) {
                page.url = directoryUrl;
            }
            CachedBbsMenu cached = new CachedBbsMenu(page, Math.max(0L, item.optLong("cachedAt", 0L)));
            bbsMenuCache.put(key, cached);
            trimMemoryBbsMenuCache();
            return cached;
        } catch (Exception ignored) {
            return null;
        }
    }

    private JSONObject legacyFiveChBbsMenuCache() {
        try {
            String saved = preferences.getString(PREF_FIVE_CH_BBSMENU_CACHE, "");
            return saved == null || saved.isEmpty() ? null : new JSONObject(saved);
        } catch (Exception ignored) {
            return null;
        }
    }

    private boolean isBbsMenuCacheFresh(String directoryUrl) {
        CachedBbsMenu cached = readBbsMenuCache(directoryUrl);
        return cached != null
                && cached.cachedAt > 0L
                && System.currentTimeMillis() - cached.cachedAt < FIVE_CH_BBSMENU_CACHE_REFRESH_MS;
    }

    private SearchPage downloadBbsDirectoryWithCache(String directoryUrl) throws Exception {
        SearchPage page = downloadBbsDirectory(directoryUrl);
        cacheBbsMenu(directoryUrl, page);
        return page;
    }

    private void cacheBbsMenu(String directoryUrl, SearchPage page) {
        if (page == null || page.error != null || page.results.isEmpty()
                || (!isCacheableBbsMenuUrl(directoryUrl) && !isCacheableBbsMenuUrl(page.url))) {
            return;
        }
        try {
            page.title = bbsMenuTitle(directoryUrl, page.title);
            long now = System.currentTimeMillis();
            JSONObject root = preferenceJsonObject(PREF_BBSMENU_CACHE);
            JSONObject item = new JSONObject();
            item.put("cachedAt", now);
            item.put("page", searchPageToJson(page));
            for (String key : bbsMenuCacheKeys(directoryUrl, page.url)) {
                root.put(key, item);
                bbsMenuCache.remove(key);
                bbsMenuCache.put(key, new CachedBbsMenu(page, now));
            }
            trimStoredBbsMenuCache(root);
            preferences.edit().putString(PREF_BBSMENU_CACHE, root.toString()).apply();
            if (isFiveChBbsMenuUrl(directoryUrl) || isFiveChBbsMenuUrl(page.url)) {
                preferences.edit().putString(PREF_FIVE_CH_BBSMENU_CACHE, item.toString()).apply();
            }
            trimMemoryBbsMenuCache();
        } catch (Exception ignored) {
        }
    }

    private void refreshBbsMenuCacheIfStale(String directoryUrl) {
        String key = bbsMenuCacheKey(directoryUrl);
        if (key.isEmpty() || !isCacheableBbsMenuUrl(directoryUrl)
                || bbsMenuRefreshInFlight.contains(key) || isBbsMenuCacheFresh(directoryUrl)) {
            return;
        }
        bbsMenuRefreshInFlight.add(key);
        ioExecutor.execute(() -> {
            try {
                SearchPage page = downloadBbsDirectory(directoryUrl);
                cacheBbsMenu(directoryUrl, page);
            } catch (Exception ignored) {
            }
            runOnUiThread(() -> bbsMenuRefreshInFlight.remove(key));
        });
    }

    private void preloadBbsMenuCache(String directoryUrl) {
        String key = bbsMenuCacheKey(directoryUrl);
        if (key.isEmpty() || !isCacheableBbsMenuUrl(directoryUrl)
                || bbsMenuCache.containsKey(key) || bbsMenuPreloadInFlight.contains(key)) {
            return;
        }
        bbsMenuPreloadInFlight.add(key);
        ioExecutor.execute(() -> {
            try {
                CachedBbsMenu cached = readBbsMenuCache(directoryUrl);
                if (cached == null || cached.cachedAt <= 0L
                        || System.currentTimeMillis() - cached.cachedAt >= FIVE_CH_BBSMENU_CACHE_REFRESH_MS) {
                    downloadBbsDirectoryWithCache(directoryUrl);
                }
            } catch (Exception ignored) {
            }
            runOnUiThread(() -> bbsMenuPreloadInFlight.remove(key));
        });
    }

    private String bbsMenuCacheKey(String url) {
        if (url == null || url.trim().isEmpty()) {
            return "";
        }
        return boardHistoryKey(url);
    }

    private List<String> bbsMenuCacheKeys(String originalUrl, String pageUrl) {
        List<String> keys = new ArrayList<>();
        if (isCacheableBbsMenuUrl(originalUrl)) {
            addUnique(keys, bbsMenuCacheKey(originalUrl));
        }
        if (isCacheableBbsMenuUrl(pageUrl)) {
            addUnique(keys, bbsMenuCacheKey(pageUrl));
        }
        return keys;
    }

    private void trimMemoryBbsMenuCache() {
        while (bbsMenuCache.size() > MAX_BBSMENU_CACHE_ENTRIES) {
            String oldest = bbsMenuCache.keySet().iterator().next();
            bbsMenuCache.remove(oldest);
        }
    }

    private void trimStoredBbsMenuCache(JSONObject root) {
        if (root == null || root.length() <= MAX_BBSMENU_CACHE_ENTRIES) {
            return;
        }
        List<String> keys = new ArrayList<>();
        Iterator<String> iterator = root.keys();
        while (iterator.hasNext()) {
            keys.add(iterator.next());
        }
        Collections.sort(keys, (left, right) -> {
            JSONObject leftItem = root.optJSONObject(left);
            JSONObject rightItem = root.optJSONObject(right);
            long leftTime = leftItem == null ? 0L : leftItem.optLong("cachedAt", 0L);
            long rightTime = rightItem == null ? 0L : rightItem.optLong("cachedAt", 0L);
            return Long.compare(leftTime, rightTime);
        });
        for (String key : keys) {
            if (root.length() <= MAX_BBSMENU_CACHE_ENTRIES) {
                break;
            }
            root.remove(key);
        }
    }

    private boolean isCacheableBbsMenuUrl(String url) {
        return url != null && isBbsMenuUrl(url) && (is5chUrl(url) || isRegisteredBbsUrl(url));
    }

    private boolean isFiveChBbsMenuUrl(String url) {
        return url != null && isBbsMenuUrl(url) && is5chUrl(url);
    }

    private void restoreNavigationHistory(CuspTab tab, JSONObject item) {
        JSONArray history = item.optJSONArray("navigationHistory");
        if (history != null) {
            for (int j = 0; j < history.length(); j++) {
                String url = history.optString(j, "");
                if (!url.isEmpty()) {
                    tab.navigationHistory.add(url);
                }
            }
        }
        if (tab.navigationHistory.isEmpty()) {
            tab.navigationIndex = -1;
        } else {
            tab.navigationIndex = Math.max(0, Math.min(item.optInt("navigationIndex", tab.navigationHistory.size() - 1),
                    tab.navigationHistory.size() - 1));
        }
    }

    private void switchToTab(int index) {
        switchToTab(index, false);
    }

    private void switchToTab(int index, boolean deferViewLoad) {
        if (index < 0 || index >= tabs.size()) {
            return;
        }
        rememberTabOverviewScroll();
        tabOverviewVisible = false;
        pendingNewTab = false;
        pendingHistoryAll = false;
        CuspTab previous = currentTab();
        CuspTab target = tabs.get(index);
        if (previous != null && previous != target) {
            rememberTabScroll(previous);
        }
        if (highlightedPostView != null) {
            clearJumpHighlight();
        }
        clearAddressFocus();
        setChromeBarsHidden(false);
        if (index != currentIndex && !replyPopups.isEmpty()) {
            dismissThreadPopups();
        }
        currentIndex = index;
        CuspTab tab = target;
        tab.lastActivatedAt = android.os.SystemClock.uptimeMillis();
        if (deferViewLoad && tab.readerView == null) {
            tab.readerView = loadingView("");
            scheduleDeferredTabViewLoad(tab);
        } else {
            ensureTabViewLoaded(tab);
        }
        if (NATIVE_THREAD.equals(tab.nativeKind)) {
            adoptSharedThreadScroll(tab);
            if (deferViewLoad) {
                scheduleDeferredThreadReadStateRefresh(tab);
            } else {
                refreshThreadReadStateOnOpen(tab);
            }
        }
        contentFrame.setBackgroundColor(bgColor());
        contentFrame.removeAllViews();
        visibleThreadPage = null;
        visibleThreadScroll = null;
        visiblePostViews.clear();
        if (tab.readerView != null) {
            ViewGroup oldParent = (ViewGroup) tab.readerView.getParent();
            if (oldParent != null) {
                oldParent.removeView(tab.readerView);
            }
            boolean delayThreadReveal = shouldDelayThreadRevealForScroll(tab);
            boolean restoreContentScroll = !delayThreadReveal && shouldRestoreContentScroll(tab);
            tab.restoringScroll = delayThreadReveal || restoreContentScroll;
            if (!isLoadingReaderView(tab.readerView)) {
                tab.readerView.setVisibility(delayThreadReveal || restoreContentScroll
                        ? View.INVISIBLE : View.VISIBLE);
            }
            contentFrame.addView(tab.readerView);
            if (isThreadPageNativeKind(tab.nativeKind)) {
                visibleThreadPage = tab.threadPage;
                visibleThreadScroll = tab.threadScroll;
            }
            if (isThreadPageNativeKind(tab.nativeKind) && tab.postViews != null) {
                visiblePostViews.putAll(tab.postViews);
            }
            if (isThreadPageNativeKind(tab.nativeKind) && tab.threadPage != null && !tab.threadPage.posts.isEmpty()) {
                if (deferViewLoad) {
                    scheduleDeferredThreadActivation(tab);
                } else {
                    refreshUnreadColors(tab);
                    restoreThreadScroll(tab);
                }
            } else if (restoreContentScroll) {
                restoreContentScroll(tab);
            } else {
                tab.restoringScroll = false;
                tab.readerView.setVisibility(View.VISIBLE);
            }
        }
        syncLoadingUiWithCurrentSurface();
        updateAddressBarDisplay(false);
        updateBottomThreadBar(tab);
        updateThreadSearchBar(tab);
        renderTabs();
        scheduleDeferredThreadUpdate(tab);
        scheduleThreadScrollChromeRefresh(tab, 5);
        scheduleTabUnload();
        scheduleBackgroundTrim();
    }

    private void scheduleDeferredTabViewLoad(CuspTab tab) {
        mainHandler.post(() -> {
            if (tab == null || tab != currentTab() || !tabs.contains(tab) || tabOverviewVisible) {
                return;
            }
            if (isLoadingReaderView(tab.readerView)) {
                tab.readerView = null;
            }
            ensureTabViewLoaded(tab);
            if (tab == currentTab() && !tabOverviewVisible && !isLoadingReaderView(tab.readerView)) {
                switchToTab(tabs.indexOf(tab));
            }
        });
    }

    private void scheduleDeferredThreadReadStateRefresh(CuspTab tab) {
        mainHandler.post(() -> {
            if (tab != null && tab == currentTab() && tabs.contains(tab) && !tabOverviewVisible) {
                refreshThreadReadStateOnOpen(tab);
            }
        });
    }

    private void scheduleDeferredThreadActivation(CuspTab tab) {
        mainHandler.post(() -> {
            if (tab == null || tab != currentTab() || !tabs.contains(tab) || tabOverviewVisible
                    || tab.threadPage == null || tab.threadPage.posts.isEmpty()) {
                return;
            }
            refreshUnreadColors(tab);
            if (shouldRestoreThreadScroll(tab)) {
                restoreThreadScroll(tab);
            }
        });
    }

    private void scheduleDeferredThreadUpdate(CuspTab tab) {
        if (tab == null || tab.deferredThreadUpdateLoading
                || tab.deferredThreadUpdatePostNumber <= 0
                || !NATIVE_THREAD.equals(tab.nativeKind)) {
            return;
        }
        tab.deferredThreadUpdateLoading = true;
        mainHandler.post(() -> {
            if (tab != currentTab() || !tabs.contains(tab) || tabOverviewVisible
                    || tab.url == null || tab.url.isEmpty()) {
                tab.deferredThreadUpdateLoading = false;
                return;
            }
            loadThread(tab, tab.url, false);
        });
    }

    private void ensureTabViewLoaded(CuspTab tab) {
        if (tab == null || tab.readerView != null) {
            return;
        }
        if (!tab.payloadLoaded && tab.sessionId != null && !tab.sessionId.isEmpty()) {
            tab.readerView = loadingView("");
            loadTabPayload(tab);
            return;
        }
        View view = buildAvailableTabReaderView(tab, true);
        if (view != null) {
            tab.readerView = view;
            return;
        }
        tab.readerView = loadingView("");
        if (tab.url != null && !tab.url.isEmpty()) {
            mainHandler.post(() -> openInTab(tab, tab.url, false));
        }
    }

    private boolean isLoadingReaderView(View view) {
        return view != null && LOADING_VIEW_TAG.equals(view.getTag());
    }

    private void showCurrentReaderView(CuspTab tab) {
        if (tab == null || tab.readerView == null || contentFrame == null) {
            return;
        }
        ViewGroup oldParent = (ViewGroup) tab.readerView.getParent();
        if (oldParent != null) {
            oldParent.removeView(tab.readerView);
        }
        boolean delayThreadReveal = shouldDelayThreadRevealForScroll(tab);
        boolean restoreContentScroll = !delayThreadReveal && shouldRestoreContentScroll(tab);
        tab.restoringScroll = delayThreadReveal || restoreContentScroll;
        if (!isLoadingReaderView(tab.readerView)) {
            tab.readerView.setVisibility(delayThreadReveal || restoreContentScroll
                    ? View.INVISIBLE : View.VISIBLE);
        }
        contentFrame.removeAllViews();
        contentFrame.addView(tab.readerView);
        if (delayThreadReveal) {
            restoreThreadScroll(tab);
        } else if (restoreContentScroll) {
            restoreContentScroll(tab);
        } else {
            tab.restoringScroll = false;
        }
    }

    private void loadTabPayload(CuspTab tab) {
        if (tab == null || tab.payloadLoading || tab.payloadLoaded || tabPayloadStore == null) {
            return;
        }
        tab.payloadLoading = true;
        String sessionId = tab.sessionId;
        ioExecutor.execute(() -> {
            String raw = tabPayloadStore.read(sessionId);
            JSONObject payload = null;
            if (!raw.isEmpty()) {
                try {
                    payload = new JSONObject(raw);
                } catch (Exception ignored) {
                }
            }
            JSONObject loadedPayload = payload;
            mainHandler.post(() -> finishTabPayloadLoad(tab, sessionId, raw, loadedPayload));
        });
    }

    private void finishTabPayloadLoad(CuspTab tab, String sessionId, String raw, JSONObject payload) {
        if (tab == null || !tabs.contains(tab) || !sessionId.equals(tab.sessionId)) {
            return;
        }
        tab.payloadLoading = false;
        tab.payloadLoaded = true;
        tab.lastSavedPayloadJson = raw;
        if (payload != null) {
            if (isThreadPageNativeKind(tab.nativeKind)) {
                tab.savedThreadPageJson = payload.optJSONObject("threadPage");
            } else if (NATIVE_SEARCH.equals(tab.nativeKind) || NATIVE_BOARD.equals(tab.nativeKind)) {
                tab.savedSearchPageJson = payload.optJSONObject("searchPage");
            }
        }
        if (tab != currentTab() || tabOverviewVisible) {
            return;
        }
        if (isLoadingReaderView(tab.readerView)) {
            tab.readerView = null;
        }
        ensureTabViewLoaded(tab);
        if (tab.readerView != null && !isLoadingReaderView(tab.readerView)) {
            switchToTab(tabs.indexOf(tab));
        }
    }

    private boolean shouldDelayThreadRevealForScroll(CuspTab tab) {
        return tab != null
                && tab.readerView != null
                && !isLoadingReaderView(tab.readerView)
                && isThreadPageNativeKind(tab.nativeKind)
                && tab.threadPage != null
                && tab.threadPage.posts != null
                && !tab.threadPage.posts.isEmpty()
                && (tab.restoreFromBottom || shouldRestoreThreadScroll(tab));
    }

    private void syncLoadingUiWithCurrentSurface() {
        CuspTab tab = currentTab();
        boolean loading = !pendingNewTab && !tabOverviewVisible
                && tab != null && isLoadingReaderView(tab.readerView);
        if (loading) {
            progressBar.setVisibility(View.VISIBLE);
            showCenterSpinner();
        } else {
            progressBar.setVisibility(View.GONE);
            hideCenterSpinner();
        }
    }

    private View previewTabReaderViewForSwipe(CuspTab tab) {
        if (tab == null) {
            return null;
        }
        if (tab.readerView != null && !useLightweightTitleSwipePreview(tab)) {
            return tab.readerView;
        }
        return titleTabSwipeContentPreview(tab);
    }

    private boolean useLightweightTitleSwipePreview(CuspTab tab) {
        if (tab == null) {
            return true;
        }
        if (tabs.size() > MANY_TABS_THRESHOLD) {
            return true;
        }
        if (!NATIVE_THREAD.equals(tab.nativeKind) || tab.threadPage == null) {
            return false;
        }
        if (tab.threadPage.posts.size() > 80) {
            return true;
        }
        int checked = 0;
        for (Post post : tab.threadPage.posts) {
            if (post == null) {
                continue;
            }
            if (post.aaMode || Boolean.TRUE.equals(post.cachedLikelyAa) || maybeHeavyAaBody(post.body)) {
                return true;
            }
            if (++checked >= 40) {
                break;
            }
        }
        return false;
    }

    private View titleTabSwipeContentPreview(CuspTab tab) {
        FrameLayout box = new FrameLayout(this);
        box.setBackgroundColor(bgColor());
        ProgressBar spinner = new ProgressBar(this);
        spinner.setIndeterminate(true);
        box.addView(spinner, new FrameLayout.LayoutParams(dp(48), dp(48), Gravity.CENTER));
        return box;
    }

    private View buildAvailableTabReaderView(CuspTab tab, boolean interactiveHome) {
        if (tab == null) {
            return null;
        }
        if (isThreadPageNativeKind(tab.nativeKind)) {
            if (tab.savedThreadPageJson != null) {
                tab.threadPage = threadPageFromJson(tab.savedThreadPageJson);
                tab.savedThreadPageJson = null;
            }
            if (NATIVE_THREAD.equals(tab.nativeKind)
                    && (tab.threadPage == null || tab.threadPage.posts.isEmpty())
                    && tab.url != null && !tab.url.isEmpty()) {
                ThreadPage cached = readCachedThreadPage(tab.url);
                if (cached != null && cached.error == null && !cached.posts.isEmpty()) {
                    tab.threadPage = cached;
                }
            }
            if (tab.threadPage != null && !tab.threadPage.posts.isEmpty()) {
                tab.readerMode = true;
                if (NATIVE_THREAD.equals(tab.nativeKind)) {
                    tab.readPostNumber = readPostNumberForTab(tab, tab.threadPage.url);
                    updateTabThreadStats(tab, tab.threadPage);
                } else {
                    tab.readPostNumber = 0;
                }
                tab.postViews = new LinkedHashMap<>();
                return buildThreadView(tab.threadPage, tab);
            }
        } else if (NATIVE_SEARCH.equals(tab.nativeKind) || NATIVE_BOARD.equals(tab.nativeKind)) {
            if (tab.savedSearchPageJson != null) {
                tab.searchPage = searchPageFromJson(tab.savedSearchPageJson, !isBbsMenuUrl(tab.url));
                tab.savedSearchPageJson = null;
            }
            if (tab.searchPage != null) {
                tab.readerMode = true;
                if (NATIVE_BOARD.equals(tab.nativeKind) && isBbsCategoryInternalUrl(tab.url)
                        && isBbsMenuUrl(tab.searchPage.url)) {
                    tab.searchPage.url = tab.url;
                    requestSaveTabsSoon();
                }
                if (NATIVE_BOARD.equals(tab.nativeKind) && isBbsMenuUrl(tab.searchPage.url)) {
                    return buildBbsCategoryIndexView(tab.searchPage, tab);
                }
                return buildSearchView(tab.searchPage, !NATIVE_BOARD.equals(tab.nativeKind), tab);
            }
        } else if (NATIVE_SAVED.equals(tab.nativeKind)
                && tab.url != null && tab.url.startsWith(INTERNAL_URL_PREFIX + "saved/")) {
            SavedPage savedPage = savedPageFromToken(
                    decodeNewTabToken(tab.url.substring((INTERNAL_URL_PREFIX + "saved/").length())));
            tab.readerMode = true;
            return withTopPullRefreshIfPossible(buildSavedItemsView(savedPage.key, savedPage.folder), tab);
        } else if (NATIVE_HISTORY.equals(tab.nativeKind)) {
            tab.readerMode = true;
            return withTopPullRefreshIfPossible(buildHistoryView(), tab);
        } else if (NATIVE_SEARCH_HOME.equals(tab.nativeKind) || tab.url == null || tab.url.isEmpty()) {
            tab.readerMode = true;
            tab.nativeKind = NATIVE_SEARCH_HOME;
            return withTopPullRefreshIfPossible(buildSearchHomeView(interactiveHome), tab);
        }
        return null;
    }

    private void updateBottomThreadBar(CuspTab tab) {
        if (bottomThreadBar == null || bottomThreadTitle == null) {
            return;
        }
        if (inlineWebViewMode) {
            bottomThreadBar.setVisibility(View.GONE);
        } else if (tabOverviewVisible) {
            bottomThreadBar.setVisibility(View.GONE);
        } else if (isAddressEditing()) {
            bottomThreadBar.setVisibility(View.GONE);
        } else if (pendingNewTab) {
            bottomThreadTitle.setText(pendingNewTabTitle());
            bottomThreadTitle.setOnClickListener(null);
            bottomThreadTitle.setOnLongClickListener(v -> {
                copyVisibleTitle();
                return true;
            });
            bottomThreadTitle.setClickable(false);
            setBottomThreadActionButtonsVisible(false);
            bottomThreadBar.setVisibility(View.VISIBLE);
        } else if (tab != null) {
            String title = tab.threadPage != null && tab.threadPage.title != null ? tab.threadPage.title : displayTitleForTab(tab);
            if (tab.threadPage != null) {
                setThreadTitleText(bottomThreadTitle, tab.threadPage, title);
            } else {
                bottomThreadTitle.setText(title == null || title.trim().isEmpty() ? text("\u30bf\u30d6", "Tab") : title);
            }
            boolean isThread = NATIVE_THREAD.equals(tab.nativeKind);
            boolean threadLoading = isThread && (tab.threadPage == null || isLoadingReaderView(tab.readerView));
            boolean canWrite = isThread && tab.threadPage != null && tab.threadPage.error == null;
            boolean canManageBoard = NATIVE_BOARD.equals(tab.nativeKind) && tab.url != null
                    && isBoardUrl(tab.url) && !isBbsDirectoryUrl(tab.url);
            bottomThreadTitle.setOnClickListener(canWrite ? v -> scrollCurrentThreadToBottom() : null);
            bottomThreadTitle.setOnLongClickListener(v -> {
                if (canWrite) {
                    showThreadTitleMenu(v);
                } else if (canManageBoard) {
                    showBoardTitleMenu(v);
                } else {
                    copyVisibleTitle();
                }
                return true;
            });
            bottomThreadTitle.setClickable(canWrite || canManageBoard);
            setBottomThreadActionButtonsVisible(canWrite || threadLoading);
            setBottomThreadActionButtonsEnabled(canWrite);
            if (bottomBookmarkButton != null) {
                bottomBookmarkButton.setImageResource(R.drawable.ic_more_vert);
                bottomBookmarkButton.setContentDescription(canManageBoard
                        ? text("\u677f\u30e1\u30cb\u30e5\u30fc", "Board menu")
                        : text("\u30b9\u30ec\u30e1\u30cb\u30e5\u30fc", "Thread menu"));
                bottomBookmarkButton.setVisibility(canWrite || canManageBoard || threadLoading ? View.VISIBLE : View.GONE);
                bottomBookmarkButton.setEnabled(canWrite || canManageBoard);
                bottomBookmarkButton.setAlpha(canWrite || canManageBoard ? 1f : 0.38f);
                bottomBookmarkButton.setOnClickListener(canWrite ? v -> showThreadTitleMenu(v)
                        : canManageBoard ? v -> showBoardTitleMenu(v) : null);
            }
            bottomThreadBar.setVisibility(View.VISIBLE);
        } else {
            bottomThreadBar.setVisibility(View.GONE);
        }
        syncChromeBarSlots(false);
    }

    private void setBottomThreadActionButtonsVisible(boolean visible) {
        for (ImageButton button : bottomThreadButtons.values()) {
            button.setVisibility(visible ? View.VISIBLE : View.GONE);
        }
    }

    private void setBottomThreadActionButtonsEnabled(boolean enabled) {
        for (ImageButton button : bottomThreadButtons.values()) {
            button.setEnabled(enabled);
            button.setAlpha(enabled ? 1f : 0.38f);
        }
    }

    private boolean isAddressEditing() {
        return addressBar != null && addressBar.hasFocus();
    }

    private void attachTitleBarTabSwipe(View view) {
        if (view == null) {
            return;
        }
        view.setOnTouchListener(this::handleTitleBarTabSwipeTouch);
    }

    private boolean handleTitleBarTabSwipeTouch(View view, MotionEvent event) {
        if (event == null || view == null) {
            return false;
        }
        int action = event.getActionMasked();
        if (action == MotionEvent.ACTION_DOWN) {
            if (titleTabSwipeAnimating) {
                return true;
            }
            titleTabSwipeDownX = event.getRawX();
            titleTabSwipeDownY = event.getRawY();
            titleTabSwipeDragging = false;
            titleTabSwipeTargetIndex = -1;
            return false;
        }
        if (action == MotionEvent.ACTION_MOVE) {
            float dx = event.getRawX() - titleTabSwipeDownX;
            float dy = event.getRawY() - titleTabSwipeDownY;
            if (!titleTabSwipeDragging) {
                if (!canStartTitleTabSwipe()) {
                    return false;
                }
                if (Math.abs(dy) > dp(10) && Math.abs(dy) > Math.abs(dx) * 1.2f) {
                    return false;
                }
                if (Math.abs(dx) <= dp(12) || Math.abs(dx) <= Math.abs(dy) * 1.2f) {
                    return false;
                }
                int target = titleSwipeTargetIndex(dx < 0 ? 1 : -1);
                if (target < 0 || !beginTitleTabSwipe(target, dx)) {
                    return false;
                }
                titleTabSwipeDragging = true;
                view.cancelLongPress();
                requestDisallowInterceptDeep(view, true);
            }
            updateTitleTabSwipe(dx);
            return true;
        }
        if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
            if (!titleTabSwipeDragging) {
                resetTitleTabSwipeState();
                return false;
            }
            float dx = event.getRawX() - titleTabSwipeDownX;
            boolean commit = action == MotionEvent.ACTION_UP && shouldCommitTitleTabSwipe(dx);
            finishTitleTabSwipe(commit);
            requestDisallowInterceptDeep(view, false);
            return true;
        }
        return titleTabSwipeDragging;
    }

    private boolean canStartTitleTabSwipe() {
        return titleBarTabSwipeEnabled()
                && !titleTabSwipeAnimating
                && !pendingNewTab
                && !tabOverviewVisible
                && contentFrame != null
                && contentFrame.getWidth() > 0
                && currentIndex >= 0
                && currentIndex < tabs.size()
                && titleSwipeTargetIndex(1) >= 0
                && imageOverlay == null
                && animatedPopups.isEmpty()
                && replyPopups.isEmpty();
    }

    private boolean titleBarTabSwipeEnabled() {
        return preferences == null || preferences.getBoolean(PREF_TITLE_BAR_TAB_SWIPE, true);
    }

    private int titleSwipeTargetIndex(int delta) {
        if (tabs.isEmpty() || currentIndex < 0 || currentIndex >= tabs.size() || delta == 0) {
            return -1;
        }
        CuspTab current = tabs.get(currentIndex);
        List<Integer> candidates = new ArrayList<>();
        if (isBookmarkTabScope(current)) {
            String folder = bookmarkTabFolder(current);
            for (int i = 0; i < tabs.size(); i++) {
                CuspTab tab = tabs.get(i);
                if (isBookmarkTabScope(tab)
                        && tab.privateBrowsing == current.privateBrowsing
                        && bookmarkTabFolder(tab).equals(folder)) {
                    candidates.add(i);
                }
            }
        } else {
            for (int i = 0; i < tabs.size(); i++) {
                CuspTab tab = tabs.get(i);
                if (isNormalTabScope(tab) && tab.privateBrowsing == current.privateBrowsing) {
                    candidates.add(i);
                }
            }
        }
        if (candidates.size() <= 1) {
            return -1;
        }
        int position = candidates.indexOf(currentIndex);
        if (position < 0) {
            return -1;
        }
        int next = (position + (delta > 0 ? 1 : -1) + candidates.size()) % candidates.size();
        int target = candidates.get(next);
        return target == currentIndex ? -1 : target;
    }

    private boolean beginTitleTabSwipe(int targetIndex, float dx) {
        CuspTab current = currentTab();
        if (current == null || current.readerView == null || targetIndex < 0 || targetIndex >= tabs.size()) {
            return false;
        }
        View targetView = previewTabReaderViewForSwipe(tabs.get(targetIndex));
        if (targetView == null) {
            return false;
        }
        int width = contentFrame.getWidth();
        if (width <= 0) {
            return false;
        }
        titleTabSwipeTargetIndex = targetIndex;
        titleTabSwipeCurrentView = current.readerView;
        titleTabSwipeTargetView = targetView;
        titleTabSwipeEdge = dx < 0 ? 1 : -1;
        ViewParent targetParent = targetView.getParent();
        if (targetParent instanceof ViewGroup) {
            ((ViewGroup) targetParent).removeView(targetView);
        }
        titleTabSwipeTargetBar = createTitleTabSwipeTargetBar(tabs.get(targetIndex), titleTabSwipeEdge);
        if (bottomThreadBar != null) {
            bottomThreadBar.setLayerType(View.LAYER_TYPE_HARDWARE, null);
        }
        targetView.setLayerType(View.LAYER_TYPE_HARDWARE, null);
        titleTabSwipeCurrentView.setLayerType(View.LAYER_TYPE_HARDWARE, null);
        targetView.setVisibility(View.VISIBLE);
        targetView.setTranslationX(titleTabSwipeEdge * width);
        contentFrame.addView(targetView, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        updateTitleTabSwipe(dx);
        return true;
    }

    private void updateTitleTabSwipe(float dx) {
        if (titleTabSwipeCurrentView == null || titleTabSwipeTargetView == null || contentFrame == null) {
            return;
        }
        int width = Math.max(1, contentFrame.getWidth());
        float movement = titleTabSwipeMovement(dx, width);
        titleTabSwipeCurrentView.setTranslationX(movement);
        titleTabSwipeTargetView.setTranslationX(titleTabSwipeEdge * width + movement);
        updateTitleTabSwipeBar(movement, width);
    }

    private View createTitleTabSwipeTargetBar(CuspTab tab, int edge) {
        if (bottomThreadBarSlot == null || bottomThreadBar == null) {
            return null;
        }
        LinearLayout bar = new LinearLayout(this);
        bar.setOrientation(LinearLayout.HORIZONTAL);
        bar.setGravity(Gravity.CENTER_VERTICAL);
        bar.setPadding(dp(10), dp(4), dp(6), dp(4));
        bar.setBackground(bottomBarBackground());
        TextView target = new TextView(this);
        target.setTextColor(textColor());
        target.setTextSize(14);
        target.setSingleLine(false);
        target.setMaxLines(2);
        target.setEllipsize(TextUtils.TruncateAt.END);
        target.setIncludeFontPadding(false);
        target.setGravity(Gravity.CENTER_VERTICAL);
        String title = tab == null || tab.threadPage == null || tab.threadPage.title == null
                ? displayTitleForTab(tab)
                : tab.threadPage.title;
        if (tab != null && tab.threadPage != null) {
            setThreadTitleText(target, tab.threadPage, title);
        } else {
            target.setText(title == null || title.trim().isEmpty() ? text("\u30bf\u30d6", "Tab") : title);
        }
        bar.addView(target, new LinearLayout.LayoutParams(
                0, ViewGroup.LayoutParams.MATCH_PARENT, 1));
        addTitleTabSwipePreviewButtons(bar, tab);
        FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, bottomThreadBar.getHeight() > 0
                        ? bottomThreadBar.getHeight() : dp(50));
        bottomThreadBarSlot.addView(bar, params);
        bar.setTranslationX(edge * Math.max(1, bottomThreadBarSlot.getWidth()));
        bar.setLayerType(View.LAYER_TYPE_HARDWARE, null);
        return bar;
    }

    private void addTitleTabSwipePreviewButtons(LinearLayout bar, CuspTab tab) {
        boolean canWrite = tab != null && NATIVE_THREAD.equals(tab.nativeKind)
                && tab.threadPage != null && tab.threadPage.error == null;
        boolean canManageBoard = tab != null && NATIVE_BOARD.equals(tab.nativeKind)
                && tab.url != null && isBoardUrl(tab.url) && !isBbsDirectoryUrl(tab.url);
        if (canWrite) {
            for (String id : orderedButtonIdsFromPreferences(PREF_THREAD_TITLE_BAR_BUTTONS,
                    DEFAULT_THREAD_TITLE_BAR_BUTTONS, THREAD_TITLE_BUTTON_IDS)) {
                ImageView icon = titleTabSwipePreviewIcon(threadActionIcon(id), buttonLabel(id));
                bar.addView(icon, new LinearLayout.LayoutParams(dp(42), dp(40)));
            }
        } else if (canManageBoard) {
            ImageView icon = titleTabSwipePreviewIcon(R.drawable.ic_more_vert,
                    text("\u677f\u30e1\u30cb\u30e5\u30fc", "Board menu"));
            bar.addView(icon, new LinearLayout.LayoutParams(dp(42), dp(40)));
        }
    }

    private ImageView titleTabSwipePreviewIcon(int iconRes, String description) {
        ImageView icon = new ImageView(this);
        icon.setImageResource(iconRes);
        icon.setContentDescription(description);
        icon.setColorFilter(textColor());
        icon.setPadding(dp(9), dp(9), dp(9), dp(9));
        icon.setScaleType(ImageView.ScaleType.CENTER);
        return icon;
    }

    private void updateTitleTabSwipeBar(float contentMovement, int contentWidth) {
        if (bottomThreadBar == null || titleTabSwipeTargetBar == null || bottomThreadBarSlot == null) {
            return;
        }
        int titleWidth = Math.max(1, bottomThreadBarSlot.getWidth());
        float progress = contentWidth <= 0 ? 0f : contentMovement / contentWidth;
        float titleMovement = progress * titleWidth;
        bottomThreadBar.setTranslationX(titleMovement);
        titleTabSwipeTargetBar.setTranslationX(titleTabSwipeEdge * titleWidth + titleMovement);
    }

    private float titleTabSwipeMovement(float dx, int width) {
        if (titleTabSwipeEdge > 0) {
            return Math.max(-width, Math.min(0f, dx));
        }
        return Math.max(0f, Math.min(width, dx));
    }

    private boolean shouldCommitTitleTabSwipe(float dx) {
        if (contentFrame == null) {
            return false;
        }
        int width = Math.max(1, contentFrame.getWidth());
        float movement = Math.abs(titleTabSwipeMovement(dx, width));
        float threshold = Math.max(dp(28), Math.min(width * 0.12f, dp(56)));
        return movement >= threshold;
    }

    private void animateTitleTabSwipeBar(boolean commit, int edge, long durationMs) {
        if (bottomThreadBar == null || titleTabSwipeTargetBar == null || bottomThreadBarSlot == null) {
            return;
        }
        int titleWidth = Math.max(1, bottomThreadBarSlot.getWidth());
        float currentEnd = commit ? -edge * titleWidth : 0f;
        float targetEnd = commit ? 0f : edge * titleWidth;
        bottomThreadBar.animate().cancel();
        titleTabSwipeTargetBar.animate().cancel();
        titleTabSwipeTargetBar.animate().translationX(targetEnd).setDuration(durationMs).start();
        bottomThreadBar.animate().translationX(currentEnd).setDuration(durationMs).start();
    }

    private void finishTitleTabSwipe(boolean commit) {
        View currentView = titleTabSwipeCurrentView;
        View targetView = titleTabSwipeTargetView;
        int targetIndex = titleTabSwipeTargetIndex;
        int edge = titleTabSwipeEdge;
        int width = contentFrame == null ? 0 : Math.max(1, contentFrame.getWidth());
        titleTabSwipeDragging = false;
        titleTabSwipeAnimating = true;
        if (currentView == null || targetView == null || width <= 0) {
            completeTitleTabSwipe(commit, targetIndex, currentView, targetView);
            return;
        }
        currentView.animate().cancel();
        targetView.animate().cancel();
        float currentEnd = commit ? -edge * width : 0f;
        float targetEnd = commit ? 0f : edge * width;
        long duration = 110L;
        animateTitleTabSwipeBar(commit, edge, duration);
        targetView.animate().translationX(targetEnd).setDuration(duration).start();
        currentView.animate()
                .translationX(currentEnd)
                .setDuration(duration)
                .withEndAction(() -> completeTitleTabSwipe(commit, targetIndex, currentView, targetView))
                .start();
    }

    private void completeTitleTabSwipe(boolean commit, int targetIndex, View currentView, View targetView) {
        if (currentView != null) {
            currentView.animate().cancel();
            currentView.setTranslationX(0f);
        }
        if (targetView != null) {
            targetView.animate().cancel();
            targetView.setTranslationX(0f);
            targetView.setLayerType(View.LAYER_TYPE_NONE, null);
        }
        if (currentView != null) {
            currentView.setLayerType(View.LAYER_TYPE_NONE, null);
        }
        if (bottomThreadBar != null) {
            bottomThreadBar.animate().cancel();
            bottomThreadBar.setTranslationX(0f);
            bottomThreadBar.setLayerType(View.LAYER_TYPE_NONE, null);
        }
        if (titleTabSwipeTargetBar != null) {
            titleTabSwipeTargetBar.animate().cancel();
            titleTabSwipeTargetBar.setTranslationX(0f);
            titleTabSwipeTargetBar.setLayerType(View.LAYER_TYPE_NONE, null);
            if (titleTabSwipeTargetBar.getParent() instanceof ViewGroup) {
                ((ViewGroup) titleTabSwipeTargetBar.getParent()).removeView(titleTabSwipeTargetBar);
            }
        }
        if (commit && targetIndex >= 0 && targetIndex < tabs.size()) {
            resetTitleTabSwipeState();
            switchToTab(targetIndex);
            return;
        }
        if (targetView != null && targetView.getParent() == contentFrame) {
            contentFrame.removeView(targetView);
        }
        resetTitleTabSwipeState();
    }

    private void resetTitleTabSwipeState() {
        titleTabSwipeDragging = false;
        titleTabSwipeAnimating = false;
        titleTabSwipeTargetIndex = -1;
        titleTabSwipeEdge = 0;
        titleTabSwipeCurrentView = null;
        titleTabSwipeTargetView = null;
        titleTabSwipeTargetBar = null;
    }

    private void copyVisibleTitle() {
        CharSequence title = bottomThreadTitle == null ? null : bottomThreadTitle.getText();
        String value = title == null ? "" : title.toString().replace(text(" DAT\u843d\u3061", " DAT dropped"), "").trim();
        if (value.isEmpty()) {
            CuspTab tab = currentTab();
            value = tab == null ? "" : displayTitleForTab(tab);
        }
        copyTextToClipboard("CuspiDroid title", value, text("\u30bf\u30a4\u30c8\u30eb\u3092\u30b3\u30d4\u30fc\u3057\u307e\u3057\u305f", "Title copied."));
    }

    private void copyTextToClipboard(String label, String value, String toast) {
        if (value == null || value.trim().isEmpty()) {
            return;
        }
        ClipboardManager manager = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
        if (manager != null) {
            manager.setPrimaryClip(ClipData.newPlainText(label, value.trim()));
            Toast.makeText(this, toast, Toast.LENGTH_SHORT).show();
        }
    }

    private String displayTitleForTab(CuspTab tab) {
        if (tab == null) {
            return text("\u30bf\u30d6", "Tab");
        }
        if (NATIVE_BOARD.equals(tab.nativeKind) && tab.url != null && !tab.url.trim().isEmpty()) {
            if (isBbsInternalPageUrl(tab.url)) {
                return internalPageTitle(tab.url);
            }
            String title = tab.overviewTitle != null && !tab.overviewTitle.trim().isEmpty()
                    && tab.readerView == null ? tab.overviewTitle.trim() : displayBoardTitle(tab.url);
            return isBoardUrl(tab.url) && !isBbsDirectoryUrl(tab.url) ? boardTitleWithPrefix(title) : title;
        }
        if (tab.overviewTitle != null && !tab.overviewTitle.trim().isEmpty()
                && tab.readerView == null) {
            return tab.overviewTitle.trim();
        }
        String title = tab.title;
        return title == null || title.trim().isEmpty() ? text("\u30bf\u30d6", "Tab") : title;
    }

    private String boardTitleWithPrefix(String title) {
        String value = title == null ? "" : title.trim();
        value = stripBoardTitlePrefix(value);
        if (value.isEmpty()) {
            value = text("\u677f", "Board");
        }
        return text("\u677f: ", "Board: ") + value;
    }

    private String stripBoardTitlePrefix(String title) {
        if (title == null) {
            return "";
        }
        String value = title.trim();
        if (value.startsWith("\u677f: ")) {
            return value.substring(3).trim();
        }
        if (value.startsWith("Board: ")) {
            return value.substring(7).trim();
        }
        return value;
    }

    private String pendingNewTabTitle() {
        String page = newTabNavigationIndex >= 0 && newTabNavigationIndex < newTabNavigationHistory.size()
                ? newTabNavigationHistory.get(newTabNavigationIndex) : "";
        return pendingNewTabPageTitle(page);
    }

    private String pendingNewTabPageTitle(String page) {
        if ("5ch".equals(page)) {
            return text("\u677f\u4e00\u89a7", "Boards");
        }
        if ("history".equals(page)) {
            return text("\u5c65\u6b74", "History");
        }
        if ("fulltext-search".equals(page)) {
            return text("\u5168\u6587\u691c\u7d22", "Full-text Search");
        }
        if (page != null && page.startsWith("bbs:")) {
            return bbsMenuTitle(decodeNewTabToken(page.substring("bbs:".length())), "");
        }
        if (page != null && page.startsWith("saved:")) {
            SavedPage savedPage = savedPageFromToken(page.substring("saved:".length()));
            return savedListTitle(savedPage.key, savedPage.folder);
        }
        if (page != null && page.startsWith("bbs-category:")) {
            BbsCategoryRequest request = decodeBbsCategoryToken(page.substring("bbs-category:".length()));
            if (request.category != null && !request.category.trim().isEmpty()
                    && !looksLikeUrlFragmentTitle(request.category)) {
                return request.category.trim();
            }
            return bbsMenuTitle(request.menuUrl, "");
        }
        if (page != null && page.startsWith("5ch-category:")) {
            String category = decodeNewTabToken(page.substring("5ch-category:".length()));
            if (!category.trim().isEmpty()) {
                return category;
            }
        }
        return text("\u65b0\u898f\u30bf\u30d6", "New tab");
    }

    private String bbsMenuTitle(String menuUrl, String fallback) {
        if (isFiveChBbsMenuUrl(menuUrl)) {
            return text("\u677f\u4e00\u89a7", "Boards");
        }
        String normalized = bbsMenuCacheKey(menuUrl);
        for (BbsLink link : readBbsLinks(preferences)) {
            if (normalized.equals(bbsMenuCacheKey(link.url))) {
                return link.name == null || link.name.trim().isEmpty()
                        ? hostTitle(menuUrl) : link.name.trim();
            }
        }
        if (fallback != null && !fallback.trim().isEmpty() && !looksLikeUrlFragmentTitle(fallback)) {
            return fallback.trim();
        }
        return hostTitle(menuUrl);
    }

    private void setThreadTitleText(TextView view, ThreadPage page, String fallback) {
        String title = page != null && page.title != null && !page.title.trim().isEmpty()
                ? page.title : (fallback == null || fallback.trim().isEmpty() ? text("\u30bf\u30d6", "Tab") : fallback);
        setThreadTitleText(view, title, page != null && page.archived);
    }

    private void setThreadTitleText(TextView view, String title, boolean archived) {
        title = title == null || title.trim().isEmpty() ? text("\u30bf\u30d6", "Tab") : title.trim();
        if (!archived) {
            view.setText(title);
            return;
        }
        String badge = "  " + text("DAT\u843d\u3061", "Archived");
        SpannableStringBuilder builder = new SpannableStringBuilder(title).append(badge);
        int start = builder.length() - badge.trim().length();
        int end = builder.length();
        builder.setSpan(new BackgroundColorSpan(linkHighlightColor()), start, end, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
        builder.setSpan(new ForegroundColorSpan(Color.rgb(29, 78, 216)), start, end, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
        view.setText(builder);
    }

    private void renderTabs() {
        updatePrivateChrome();
        if (bottomToolbar != null) {
            bottomToolbar.setVisibility(tabOverviewVisible ? View.GONE : View.VISIBLE);
        }
        syncChromeBarSlots(false);
        if (tabCountButton != null) {
            updateTabCountButton();
        }
        CuspTab tab = pendingNewTab ? null : currentTab();
        updateAddressBarButtons(tab);
        updateBottomThreadBar(tab);
    }

    private void updateAddressBarDisplay(boolean focusText) {
        if (addressBar == null || addressBar.hasFocus() && !focusText) {
            return;
        }
        addressBar.setText(inlineWebViewMode ? inlineWebViewUrl : addressBarTextForTab(currentTab()));
        if (focusText) {
            focusAddressBarText();
        } else {
            resetAddressBarScrollToStart();
        }
    }

    private String addressBarTextForTab(CuspTab tab) {
        if (tab == null || tab.url == null) {
            return "";
        }
        return addressBarTextForUrl(tab.nativeKind, tab.url);
    }

    private String addressBarTextForUrl(String nativeKind, String url) {
        if (url == null) {
            return "";
        }
        if (isBbsInternalPageUrl(url)) {
            String externalUrl = externalUrlFromBbsInternalPage(url);
            if (externalUrl != null && !externalUrl.trim().isEmpty()) {
                return externalUrl;
            }
        }
        if (shouldDisplaySearchQueryInAddress(nativeKind, url)) {
            String query = searchQueryFromUrl(url);
            if (query != null && !query.trim().isEmpty()) {
                return query.trim();
            }
        }
        return url;
    }

    private boolean shouldDisplaySearchQueryInAddress(CuspTab tab) {
        return tab != null && shouldDisplaySearchQueryInAddress(tab.nativeKind, tab.url);
    }

    private boolean shouldDisplaySearchQueryInAddress(String nativeKind, String url) {
        return NATIVE_SEARCH.equals(nativeKind) && isDefaultSearchUrl(url);
    }

    private void focusAddressBarText() {
        if (addressBar == null) {
            return;
        }
        addressBar.setEllipsize(null);
        addressBar.setHorizontallyScrolling(true);
        addressBar.selectAll();
        scrollAddressBarToEndSoon();
    }

    private void resetAddressBarScrollToStart() {
        if (addressBar == null) {
            return;
        }
        addressBar.setEllipsize(TextUtils.TruncateAt.END);
        addressBar.setHorizontallyScrolling(true);
        addressBar.setSelection(0);
        addressBar.scrollTo(0, 0);
        addressBar.post(() -> {
            if (addressBar != null && !addressBar.hasFocus()) {
                addressBar.scrollTo(0, 0);
            }
        });
    }

    private void scrollAddressBarToEndSoon() {
        if (addressBar == null) {
            return;
        }
        addressBar.post(() -> scrollAddressBarToEnd());
        addressBar.postDelayed(() -> scrollAddressBarToEnd(), 80);
    }

    private void scrollAddressBarToEnd() {
        if (addressBar == null || !addressBar.hasFocus()) {
            return;
        }
        android.text.Layout layout = addressBar.getLayout();
        int contentWidth = layout == null ? 0 : (int) Math.ceil(layout.getLineWidth(0));
        int viewportWidth = Math.max(0, addressBar.getWidth()
                - addressBar.getTotalPaddingLeft() - addressBar.getTotalPaddingRight());
        int maxScroll = Math.max(0, contentWidth - viewportWidth);
        addressBar.scrollTo(maxScroll, 0);
    }

    private void openFromAddressBar() {
        String input = addressBar.getText().toString().trim();
        if (input.isEmpty()) {
            return;
        }
        boolean urlLike = looksLikeUrl(input);
        String url = urlLike ? normalizeUrl(input) : searchUrl(input);
        if (inlineWebViewMode && inlineWebView != null) {
            clearAddressFocus();
            inlineWebView.loadUrl(url);
            return;
        }
        if (pendingNewTab) {
            clearAddressFocus();
            openPendingNewTabUrl(url);
            return;
        }
        CuspTab tab = currentTab();
        if (urlLike && shouldPreviewNativeBbsLoading(url) && showImmediateNavigationLoading(tab)) {
            clearAddressFocus();
            postOpenInSelectedTab(tab, url);
            return;
        }
        clearAddressFocus();
        openInCurrentTab(url);
    }

    private void openInCurrentTab(String url) {
        openInCurrentTab(url, true);
    }

    private void postOpenInSelectedTab(CuspTab tab, String url) {
        mainHandler.post(() -> {
            if (tab == null || !tabs.contains(tab) || tab != currentTab() || tabOverviewVisible) {
                return;
            }
            openInCurrentTab(url);
        });
    }

    private boolean showImmediateNavigationLoading(CuspTab tab) {
        if (tab == null || !tabs.contains(tab)) {
            return false;
        }
        prepareChromeForLoading();
        tab.readerView = loadingView("");
        tab.searchPage = null;
        tab.threadPage = null;
        tab.threadScroll = null;
        tab.postViews = null;
        clearBoardTopRefreshState(tab);
        if (tab == currentTab() && !tabOverviewVisible) {
            showCurrentReaderView(tab);
            visibleThreadPage = null;
            visibleThreadScroll = null;
            visiblePostViews.clear();
        }
        syncLoadingUiWithCurrentSurface();
        renderTabs();
        return true;
    }

    private boolean shouldPreviewNativeBbsLoading(String url) {
        if (url == null || isInternalPageUrl(url)) {
            return false;
        }
        try {
            Uri uri = Uri.parse(normalizeUrl(url));
            String scheme = uri.getScheme();
            if (!"http".equalsIgnoreCase(scheme) && !"https".equalsIgnoreCase(scheme)) {
                return false;
            }
        } catch (Exception ignored) {
            return false;
        }
        return is5chUrl(url) || isBbsMenuUrl(url) || isRegisteredBbsUrl(url);
    }

    private void openInCurrentTab(String url, boolean addHistory) {
        openInCurrentTab(url, addHistory, false);
    }

    private void openInCurrentTab(String url, boolean addHistory, boolean bookmarkOverviewTab) {
        CuspTab tab = currentTab();
        openInCurrentTab(url, addHistory,
                bookmarkOverviewTab ? TabScope.BOOKMARK : TabScope.NORMAL,
                bookmarkTabFolder(tab),
                false);
    }

    private void openInCurrentTab(String url, boolean addHistory, boolean bookmarkOverviewTab,
                                  boolean redirectResolved) {
        CuspTab tab = currentTab();
        openInCurrentTab(url, addHistory,
                bookmarkOverviewTab ? TabScope.BOOKMARK : TabScope.NORMAL,
                bookmarkTabFolder(tab),
                redirectResolved);
    }

    private void openInCurrentTab(String url, boolean addHistory, TabScope scope, String bookmarkFolder,
                                  boolean redirectResolved) {
        if (pendingNewTab) {
            openPendingNewTabUrl(url);
            return;
        }
        CuspTab tab = currentTab();
        if (tab == null) {
            createTab(url, true);
            return;
        }
        applyThreadTabScope(tab, scope, bookmarkFolder);
        if (!redirectResolved) {
            int redirectGeneration = ++tab.redirectGeneration;
            String normalizedUrl = isInternalPageUrl(url) ? url : normalizeUrl(url);
            if (shouldResolveBbsRedirectBeforeOpening(normalizedUrl)) {
                ioExecutor.execute(() -> {
                    String resolvedUrl = normalizedUrl;
                    try {
                        resolvedUrl = resolveRedirectedUrl(
                                normalizedUrl,
                                "Mozilla/5.0 (Linux; Android) CuspiDroid/0.1");
                    } catch (Exception ignored) {
                    }
                    String resultUrl = resolvedUrl;
                    runOnUiThread(() -> {
                        if (tab.redirectGeneration != redirectGeneration
                                || tab != currentTab() || !tabs.contains(tab)) {
                            return;
                        }
                        openInCurrentTab(resultUrl, addHistory, scope, bookmarkFolder, true);
                    });
                });
                return;
            }
        }
        if (isBbsInternalPageUrl(url)) {
            beginBbsInternalPageLoad(tab, url, addHistory);
            return;
        }
        if (isInternalPageUrl(url)) {
            if (addHistory) {
                recordNavigation(tab, url);
            }
            loadInternalPage(tab, url);
            return;
        }
        url = normalizeUrl(url);
        if (isBbsMenuUrl(url) && isBbsDirectoryUrl(url)) {
            openInCurrentTab(bbsRootPageUrl(url), addHistory, scope, bookmarkFolder, true);
            return;
        }
        if (isThreadUrl(url)) {
            if (addHistory) {
                recordNavigation(tab, url);
            }
            loadThread(tab, url);
            return;
        }
        if (isFullTextSearchUrl(url)) {
            if (addHistory) {
                recordNavigation(tab, url);
            }
            loadFullTextSearchResults(tab, url);
            return;
        }
        if (isHissiCheckerUrl(url)) {
            if (addHistory) {
                recordNavigation(tab, url);
            }
            loadHissiChecker(tab, url);
            return;
        }
        if (isFindSearchUrl(url)) {
            if (addHistory) {
                recordNavigation(tab, url);
            }
            loadSearchResults(tab, url);
            return;
        }
        if (isFindHomeUrl(url)) {
            if (addHistory) {
                recordNavigation(tab, url);
            }
            loadSearchHome(tab, url);
            return;
        }
        if (isBbsDirectoryUrl(url)) {
            if (addHistory) {
                recordNavigation(tab, url);
            }
            loadBbsDirectory(tab, url);
            return;
        }
        if (isBoardUrl(url)) {
            if (addHistory) {
                recordNavigation(tab, url);
            }
            loadBoard(tab, url);
            return;
        }
        openExternal(url);
    }

    private void applyThreadTabScope(CuspTab tab, TabScope scope, String bookmarkFolder) {
        if (tab == null) {
            return;
        }
        tab.tabScope = scope == null ? TabScope.NORMAL : scope;
        if (tab.tabScope == TabScope.BOOKMARK) {
            tab.bookmarkOverviewTab = true;
            tab.bookmarkOverviewFolder = normalizeSavedFolder(bookmarkFolder);
        } else {
            tab.bookmarkOverviewTab = false;
            tab.bookmarkOverviewFolder = "";
        }
    }

    private TabScope tabScopeFromSavedItem(JSONObject item) {
        if (item != null) {
            String value = item.optString("tabScope", "");
            if (!value.isEmpty()) {
                try {
                    return TabScope.valueOf(value);
                } catch (Exception ignored) {
                }
            }
            if (item.optBoolean("bookmarkOverviewTab", false)) {
                return TabScope.BOOKMARK;
            }
        }
        return TabScope.NORMAL;
    }

    private boolean isBookmarkTabScope(CuspTab tab) {
        return tab != null && tab.tabScope == TabScope.BOOKMARK;
    }

    private boolean isNormalTabScope(CuspTab tab) {
        return tab != null && tab.tabScope != TabScope.BOOKMARK;
    }

    private boolean isThreadPageNativeKind(String nativeKind) {
        return NATIVE_THREAD.equals(nativeKind) || NATIVE_HISSI.equals(nativeKind);
    }

    private String bookmarkTabFolder(CuspTab tab) {
        return normalizeSavedFolder(tab == null ? "" : tab.bookmarkOverviewFolder);
    }

    private boolean shouldResolveBbsRedirectBeforeOpening(String url) {
        if (url == null || url.isEmpty() || is5chUrl(url) || !isRegisteredBbsUrl(url)) {
            return false;
        }
        if (isBbsMenuUrl(url) || isBbsDirectoryUrl(url) || isBoardUrl(url) || isThreadUrl(url)) {
            return false;
        }
        try {
            String scheme = Uri.parse(url).getScheme();
            return "http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme);
        } catch (Exception ignored) {
            return false;
        }
    }

    private boolean isInternalPageUrl(String url) {
        return url != null && url.startsWith(INTERNAL_URL_PREFIX);
    }

    private boolean isBbsInternalPageUrl(String url) {
        return url != null && (url.startsWith(INTERNAL_URL_PREFIX + "bbs/")
                || url.startsWith(INTERNAL_URL_PREFIX + "bbs-category/"));
    }

    private boolean isBbsCategoryInternalUrl(String url) {
        return url != null && url.startsWith(INTERNAL_URL_PREFIX + "bbs-category/");
    }

    private String externalUrlFromBbsInternalPage(String url) {
        if (url == null) {
            return "";
        }
        if (url.startsWith(INTERNAL_URL_PREFIX + "bbs/")) {
            return decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "bbs/").length()));
        }
        if (url.startsWith(INTERNAL_URL_PREFIX + "bbs-category/")) {
            BbsCategoryRequest request = decodeBbsCategoryToken(
                    decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "bbs-category/").length())));
            return request.menuUrl == null ? "" : request.menuUrl;
        }
        return "";
    }

    private boolean isHissiCheckerUrl(String url) {
        try {
            Uri uri = Uri.parse(normalizeUrl(url));
            String host = uri.getHost();
            String path = uri.getPath();
            if (host == null || path == null) {
                return false;
            }
            String lowerHost = host.toLowerCase(Locale.ROOT);
            return (lowerHost.equals("hissi.org") || lowerHost.equals("www.hissi.org"))
                    && path.matches("/read\\.php/[^/]+/\\d{8}/[^/]+\\.html");
        } catch (Exception ignored) {
            return false;
        }
    }

    private String savedPageUrl(String key) {
        return savedPageUrl(key, "");
    }

    private String savedPageUrl(String key, String folder) {
        return INTERNAL_URL_PREFIX + "saved/" + encodeNewTabToken(savedPageToken(key, folder));
    }

    private String bbsRootPageKey(String menuUrl) {
        return "bbs:" + encodeNewTabToken(menuUrl);
    }

    private String bbsRootPageUrl(String menuUrl) {
        return INTERNAL_URL_PREFIX + "bbs/" + encodeNewTabToken(menuUrl);
    }

    private String bbsCategoryPageUrl(String menuUrl, String category) {
        return INTERNAL_URL_PREFIX + "bbs-category/" + encodeNewTabToken(bbsCategoryToken(menuUrl, category));
    }

    private String historyPageUrl() {
        return INTERNAL_URL_PREFIX + "history";
    }

    private String fullTextSearchPageUrl() {
        return INTERNAL_URL_PREFIX + "fulltext-search";
    }

    private String newTabReturnPageUrl() {
        if (!pendingNewTab || newTabNavigationIndex < 0 || newTabNavigationIndex >= newTabNavigationHistory.size()) {
            return null;
        }
        if (newTabNavigationIndex > 0) {
            return INTERNAL_URL_PREFIX + "newtab-history/" + encodeNewTabToken(newTabHistorySnapshot());
        }
        return null;
    }

    private String newTabHistorySnapshot() {
        try {
            JSONObject root = new JSONObject();
            JSONArray pages = new JSONArray();
            for (String page : newTabNavigationHistory) {
                pages.put(page == null ? "" : page);
            }
            root.put("pages", pages);
            root.put("index", newTabNavigationIndex);
            return root.toString();
        } catch (Exception error) {
            return "";
        }
    }

    private String internalPageTitle(String url) {
        if (url == null) {
            return text("\u30bf\u30d6", "Tab");
        }
        if (url.startsWith(INTERNAL_URL_PREFIX + "saved/")) {
            SavedPage savedPage = savedPageFromToken(decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "saved/").length())));
            return savedListTitle(savedPage.key, savedPage.folder);
        }
        if (url.equals(historyPageUrl())) {
            return text("\u5c65\u6b74", "History");
        }
        if (url.equals(fullTextSearchPageUrl())) {
            return text("\u5168\u6587\u691c\u7d22", "Full-text Search");
        }
        if (url.startsWith(INTERNAL_URL_PREFIX + "bbs/")) {
            String menuUrl = decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "bbs/").length()));
            return bbsMenuTitle(menuUrl, "");
        }
        if (url.startsWith(INTERNAL_URL_PREFIX + "bbs-category/")) {
            BbsCategoryRequest request = decodeBbsCategoryToken(
                    decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "bbs-category/").length())));
            if (request.category != null && !request.category.trim().isEmpty()
                    && !looksLikeUrlFragmentTitle(request.category)) {
                return request.category.trim();
            }
            return bbsMenuTitle(request.menuUrl, "");
        }
        if (url.startsWith(INTERNAL_URL_PREFIX + "newtab-history/")) {
            List<String> pages = decodeNewTabHistoryPages(url);
            int index = decodeNewTabHistoryIndex(url, pages);
            return pendingNewTabPageTitle(pages.isEmpty() ? "home" : pages.get(Math.max(0, Math.min(index, pages.size() - 1))));
        }
        return text("\u30bf\u30d6", "Tab");
    }

    private void loadInternalPage(CuspTab tab, String url) {
        if (tab == null || url == null) {
            return;
        }
        tab.readerMode = true;
        tab.url = url;
        tab.title = internalPageTitle(url);
        tab.threadPage = null;
        tab.searchPage = null;
        tab.threadScroll = null;
        tab.postViews = null;
        if (url.startsWith(INTERNAL_URL_PREFIX + "saved/")) {
            tab.nativeKind = NATIVE_SAVED;
            SavedPage savedPage = savedPageFromToken(decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "saved/").length())));
            tab.readerView = withTopPullRefreshIfPossible(buildSavedItemsView(savedPage.key, savedPage.folder), tab);
        } else if (url.equals(historyPageUrl())) {
            tab.nativeKind = NATIVE_HISTORY;
            tab.readerView = withTopPullRefreshIfPossible(buildHistoryView(), tab);
        } else if (url.equals(fullTextSearchPageUrl())) {
            tab.nativeKind = NATIVE_SEARCH_HOME;
            tab.readerView = withTopPullRefreshIfPossible(buildFullTextSearchHomeView(true), tab);
        } else if (url.startsWith(INTERNAL_URL_PREFIX + "bbs/")) {
            String menuUrl = decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "bbs/").length()));
            showBbsDirectoryIndexView(menuUrl, bbsRootPageKey(menuUrl), false);
            return;
        } else if (url.startsWith(INTERNAL_URL_PREFIX + "bbs-category/")) {
            String token = decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "bbs-category/").length()));
            showBbsCategoryView(token, false);
            return;
        } else {
            tab.nativeKind = NATIVE_SEARCH_HOME;
            tab.readerView = withTopPullRefreshIfPossible(buildSearchHomeView(true), tab);
        }
        if (tab == currentTab() && !tabOverviewVisible) {
            showCurrentReaderView(tab);
            hideCenterSpinner();
        }
        renderTabs();
    }

    private void recordNavigation(CuspTab tab, String url) {
        if (url == null || url.isEmpty()) {
            return;
        }
        if (tab != null && tab.url != null && !sameSavedUrl(tab.url, url)) {
            rememberBoardHistoryScroll(tab);
        }
        ensureCurrentPageNavigationBase(tab, url);
        if (tab.navigationIndex >= 0
                && tab.navigationIndex < tab.navigationHistory.size()
                && url.equals(tab.navigationHistory.get(tab.navigationIndex))) {
            return;
        }
        while (tab.navigationHistory.size() > tab.navigationIndex + 1) {
            tab.navigationHistory.remove(tab.navigationHistory.size() - 1);
        }
        tab.navigationHistory.add(url);
        tab.navigationIndex = tab.navigationHistory.size() - 1;
        requestSaveTabsSoon();
    }

    private void ensureCurrentPageNavigationBase(CuspTab tab, String nextUrl) {
        if (tab == null || tab.url == null || tab.url.trim().isEmpty()
                || nextUrl == null || nextUrl.trim().isEmpty()
                || sameSavedUrl(tab.url, nextUrl)) {
            return;
        }
        if (tab.navigationIndex >= 0 && tab.navigationIndex < tab.navigationHistory.size()) {
            return;
        }
        tab.navigationHistory.clear();
        tab.navigationHistory.add(tab.url);
        tab.navigationIndex = 0;
    }

    private void openPendingNewTabUrl(String url) {
        boolean privateBrowsing = pendingPrivateNewTab;
        String returnUrl = newTabReturnPageUrl();
        pendingNewTab = false;
        pendingPrivateNewTab = false;
        if (returnUrl == null) {
            createTab(url, true, -1, true, privateBrowsing);
            return;
        }
        CuspTab tab = new CuspTab();
        tab.title = text("\u65b0\u898f\u30bf\u30d6", "New tab");
        tab.url = "";
        tab.privateBrowsing = privateBrowsing;
        tab.backToNewTab = false;
        tab.lastActivatedAt = android.os.SystemClock.uptimeMillis();
        tab.readerView = loadingView("");
        tab.navigationHistory.add(returnUrl);
        tab.navigationIndex = 0;
        tabs.add(tab);
        switchToTab(tabs.size() - 1);
        postOpenInSelectedTab(tab, url);
    }

    private void loadThread(CuspTab tab, String url) {
        loadThread(tab, url, true);
    }

    private void loadThread(CuspTab tab, String url, boolean showFullLoading) {
        final String loadUrl = url;
        if (tab.url != null && !tab.url.isEmpty() && !sameSavedUrl(tab.url, loadUrl)) {
            tab.deferredThreadUpdatePostNumber = 0;
            tab.deferredThreadUpdateLoading = false;
        }
        rememberThreadScroll(tab);
        if (showFullLoading) {
            prepareChromeForLoading();
        }
        if (showFullLoading) {
            clearBoardTopRefreshState(tab);
        }
        tab.readerMode = true;
        tab.nativeKind = NATIVE_THREAD;
        tab.url = loadUrl;
        adoptSharedThreadScroll(tab, loadUrl);
        boolean keepExistingScroll = tab.hasSavedThreadScroll && sameSavedUrl(loadUrl, tab.threadScrollUrl);
        tab.title = hostTitle(loadUrl);
        applyPendingThreadMetadata(tab, loadUrl);
        tab.searchPage = null;
        if (showFullLoading || tab.readerView == null) {
            tab.readerView = loadingView("");
            switchToTab(tabs.indexOf(tab));
        }
        progressBar.setVisibility(View.VISIBLE);
        mainHandler.post(() -> loadThreadAfterLoading(tab, loadUrl, keepExistingScroll, showFullLoading));
    }

    private void loadThreadAfterLoading(CuspTab tab, String loadUrl, boolean keepExistingScroll,
                                        boolean showFullLoading) {
        if (tab == null || !tabs.contains(tab) || !loadUrl.equals(tab.url)) {
            if (tab != null) {
                tab.deferredThreadUpdateLoading = false;
            }
            return;
        }
        ThreadPage cached = readCachedThreadPage(loadUrl);
        if (cached != null && cached.error == null && !cached.posts.isEmpty()) {
            tab.title = cached.title;
            tab.threadPage = cached;
            tab.readPostNumber = readPostNumberForTab(tab, cached.url);
            updateTabThreadStats(tab, cached);
            refreshTabOverviewValuesForTab(tab);
            tab.postViews = new LinkedHashMap<>();
            tab.readerView = buildThreadView(cached, tab);
            if (!tabOverviewVisible && (showFullLoading || tab == currentTab())) {
                switchToTab(tabs.indexOf(tab));
                restoreThreadScroll(tab);
                runPendingPostJump(tab);
            }
        }

        ioExecutor.execute(() -> {
            ThreadPage page;
            try {
                page = null;
                if (cached != null && cached.error == null && !cached.posts.isEmpty()) {
                    try {
                        page = downloadNewDatPosts(loadUrl, cached);
                    } catch (Exception ignored) {
                    }
                }
                if (page == null) {
                    page = downloadThreadPage(loadUrl);
                }
            } catch (Exception error) {
                page = ThreadPage.error(loadUrl, error.getMessage());
            }
                ThreadPage result = page;
            runOnUiThread(() -> {
                resetTopRefreshLoader(tab.boardTopLoader);
                if (!tabs.contains(tab) || !loadUrl.equals(tab.url)) {
                    tab.deferredThreadUpdateLoading = false;
                    if (tab == currentTab()) {
                        progressBar.setVisibility(View.GONE);
                    }
                    return;
                }
                finishDeferredThreadUpdate(tab, result);
                if (result.error == null && result.url != null && !result.url.trim().isEmpty()) {
                    replaceCurrentNavigationUrl(tab, loadUrl, result.url);
                    tab.url = result.url;
                }
                if (cached != null && cached.error == null && result.error == null
                        && sameRenderedThread(cached, result)
                        && tab.readerView != null && tab.threadPage == cached) {
                    tab.title = result.title;
                    applyThreadPageMetadata(cached, result);
                    cached.url = result.url;
                    tab.threadPage = cached;
                    tab.readPostNumber = readPostNumberForTab(tab, result.url);
                    updateTabThreadStats(tab, cached);
                    refreshTabOverviewValuesForTab(tab);
                    cacheThreadPage(result);
                    addThreadHistory(tab, result.url, result.title);
                    if (!tab.threadRendering) {
                        progressBar.setVisibility(View.GONE);
                    }
                    if (tab == currentTab()) {
                        restoreThreadScroll(tab);
                        runPendingPostJump(tab);
                    }
                    renderTabs();
                    return;
                }
                if (cached != null && cached.error == null && result.error == null
                        && result.newPostCount > 0
                        && tab.readerView != null && tab.threadPage == cached
                        && tab.threadList != null && tab.postViews != null && tab.postSlots != null
                        && !tab.threadRendering) {
                    int oldCount = Math.max(0, result.posts.size() - result.newPostCount);
                    tab.title = result.title;
                    tab.threadPage = result;
                    tab.readPostNumber = Math.max(tab.readPostNumber, readPostNumberForTab(tab, result.url));
                    updateThreadTitleHeader(tab, result);
                    updateTabThreadStats(tab, result);
                    refreshTabOverviewValuesForTab(tab);
                    cacheThreadPage(result);
                    addThreadHistory(tab, result.url, result.title);
                    renderAdditionalPostCardsIncrementally(tab.threadList, result, tab, oldCount, () -> {
                        if (tab == currentTab()) {
                            progressBar.setVisibility(View.GONE);
                            restoreThreadScroll(tab);
                            runPendingPostJump(tab);
                        }
                        renderTabs();
                    });
                    return;
                }
                if (result.error != null) {
                    Toast.makeText(this, friendlyThreadLoadError(result.error), Toast.LENGTH_SHORT).show();
                    if (cached != null && cached.error == null && !cached.posts.isEmpty()) {
                        tab.title = cached.title;
                        tab.threadPage = cached;
                        updateTabThreadStats(tab, cached);
                        refreshTabOverviewValuesForTab(tab);
                        if (!tab.threadRendering) {
                            progressBar.setVisibility(View.GONE);
                        }
                        renderTabs();
                        return;
                    }
                    if (tab.threadPage != null && tab.threadPage.error == null && !tab.threadPage.posts.isEmpty()) {
                        if (!tab.threadRendering) {
                            progressBar.setVisibility(View.GONE);
                        }
                        renderTabs();
                        return;
                    }
                    result.error = text("\u30ad\u30e3\u30c3\u30b7\u30e5\u304c\u306a\u304f\u3001\u30b9\u30ec\u3092\u8aad\u307f\u8fbc\u3081\u307e\u305b\u3093\u3067\u3057\u305f\u3002", "Could not load the thread and no cache is available.");
                }
                tab.title = result.title;
                tab.threadPage = result;
                tab.readPostNumber = readPostNumberForTab(tab, result.url);
                updateTabThreadStats(tab, result);
                refreshTabOverviewValuesForTab(tab);
                tab.postViews = new LinkedHashMap<>();
                tab.readerView = buildThreadView(result, tab);
                tab.hasSavedThreadScroll = keepExistingScroll;
                if (result.error == null && !result.posts.isEmpty()) {
                    cacheThreadPage(result);
                    addThreadHistory(tab, result.url, result.title);
                }
                if (result.error != null || result.posts.isEmpty()) {
                    progressBar.setVisibility(View.GONE);
                }
                if (tab == currentTab() && !tabOverviewVisible) {
                    switchToTab(currentIndex);
                    if (tab.threadSearchOpen && tab.threadSearchQuery != null && !tab.threadSearchQuery.trim().isEmpty()) {
                        updateThreadSearch(tab.threadSearchQuery, false);
                    }
                    restoreThreadScroll(tab);
                }
                renderTabs();
            });
        });
    }

    private void loadHissiChecker(CuspTab tab, String url) {
        if (tab == null) {
            return;
        }
        final String loadUrl = normalizeUrl(url);
        rememberThreadScroll(tab);
        prepareChromeForLoading();
        tab.readerMode = true;
        tab.nativeKind = NATIVE_HISSI;
        tab.url = loadUrl;
        tab.title = text("\u5fc5\u6b7b\u30c1\u30a7\u30c3\u30ab\u30fc", "Hissi Checker");
        tab.searchPage = null;
        tab.threadPage = null;
        tab.postViews = null;
        tab.readerView = loadingView("");
        switchToTab(tabs.indexOf(tab));
        progressBar.setVisibility(View.VISIBLE);
        ioExecutor.execute(() -> {
            ThreadPage page;
            try {
                page = parseHissiCheckerPage(loadUrl, download(loadUrl));
            } catch (Exception error) {
                page = ThreadPage.error(loadUrl, error.getMessage());
            }
            ThreadPage result = page;
            runOnUiThread(() -> {
                resetTopRefreshLoader(tab.boardTopLoader);
                if (!tabs.contains(tab) || !loadUrl.equals(tab.url) || !NATIVE_HISSI.equals(tab.nativeKind)) {
                    if (tab == currentTab()) {
                        progressBar.setVisibility(View.GONE);
                    }
                    return;
                }
                tab.title = result.title;
                tab.threadPage = result;
                tab.readPostNumber = 0;
                tab.postViews = new LinkedHashMap<>();
                tab.readerView = buildThreadView(result, tab);
                if (result.error != null || result.posts.isEmpty()) {
                    progressBar.setVisibility(View.GONE);
                }
                if (tab == currentTab() && !tabOverviewVisible) {
                    switchToTab(currentIndex);
                    restoreThreadScroll(tab);
                    runPendingPostJump(tab);
                }
                renderTabs();
            });
        });
    }

    private ThreadPage parseHissiCheckerPage(String url, String html) {
        ThreadPage page = new ThreadPage();
        page.url = url;
        page.title = cleanText(valueOr(firstMatch(html == null ? "" : html, "<title[^>]*>(.*?)</title>"),
                text("\u5fc5\u6b7b\u30c1\u30a7\u30c3\u30ab\u30fc", "Hissi Checker")));
        page.hissiSummary = hissiSummary(html);
        Matcher matcher = HISSI_POST_PATTERN.matcher(html == null ? "" : html);
        while (matcher.find()) {
            String header = matcher.group(1);
            String bodyHtml = matcher.group(2);
            String threadTitle = cleanText(valueOr(firstMatch(header, "<a[^>]*>(.*?)</a>"), ""));
            String sourceUrl = absolutizeUrl(url, firstHref(header));
            String plainHeader = cleanText(header);
            if (!threadTitle.isEmpty()) {
                plainHeader = plainHeader.replace(threadTitle, "").trim();
            }
            String sourceNumber = valueOr(firstMatch(plainHeader, "^(\\d+)\\s*[\\uFF1A:]"), "");
            String name = valueOr(firstMatch(header, "<b[^>]*>(.*?)</b>"), "anonymous");
            String meta = plainHeader.replaceFirst("^\\d+\\s*[\\uFF1A:]\\s*", "").trim();
            if (!name.isEmpty()) {
                meta = meta.replaceFirst(Pattern.quote(name), "").trim();
            }
            String body = cleanText(bodyHtml);
            Post post = new Post();
            post.number = page.posts.size() + 1;
            post.name = name;
            post.date = meta;
            post.body = body;
            post.sourceTitle = threadTitle;
            post.sourcePostNumber = parsePositiveInt(sourceNumber, 0);
            post.sourceUrl = sourceThreadUrl(sourceUrl, post.sourcePostNumber);
            post.cachedLikelyAa = likelyAaPost(post.body);
            page.posts.add(post);
            page.postsByNumber.put(post.number, post);
        }
        return page;
    }

    private String hissiSummary(String html) {
        String source = html == null ? "" : html;
        String title = cleanText(valueOr(firstMatch(source, "<title[^>]*>(.*?)</title>"), ""));
        if (title.startsWith("\u5fc5\u6b7b\u30c1\u30a7\u30c3\u30ab\u30fc\u3082\u3069\u304d")) {
            title = title.substring("\u5fc5\u6b7b\u30c1\u30a7\u30c3\u30ab\u30fc\u3082\u3069\u304d".length()).trim();
        }
        StringBuilder summary = new StringBuilder();
        String[] titleParts = title.split("\\s*>\\s*");
        if (titleParts.length > 1) {
            appendSummaryLine(summary, text("ID", "ID"), titleParts[titleParts.length - 1]);
            StringBuilder context = new StringBuilder();
            for (int i = 0; i < titleParts.length - 1; i++) {
                if (titleParts[i].trim().isEmpty()) {
                    continue;
                }
                if (context.length() > 0) {
                    context.append(" > ");
                }
                context.append(titleParts[i].trim());
            }
            appendSummaryLine(summary, text("\u677f/\u65e5\u4ed8", "Board/date"), context.toString());
        } else {
            appendSummaryLine(summary, text("ID", "ID"), title);
        }

        String rank = firstMatch(source, "<td[^>]*rowspan\\s*=\\s*2[^>]*>(.*?)</td>");
        if (rank == null || cleanText(rank).isEmpty()) {
            rank = firstMatch(source, "(<font[^>]*>.*?</font>\\s*/\\s*[^<]*ID[^<]*)");
        }
        appendSummaryLine(summary, text("\u9806\u4f4d", "Rank"), rank);

        String writeCountRow = firstMatch(source, "<tr[^>]*>\\s*<td[^>]*>\u66f8\u304d\u8fbc\u307f\u6570</td>(.*?)</tr>");
        String total = lastTableCellText(writeCountRow);
        if (total == null || total.isEmpty()) {
            total = firstMatch(source, ">Total</td>.*?<td[^>]*bgcolor\\s*=\\s*red[^>]*>(.*?)</td>");
        }
        appendSummaryLine(summary, text("\u66f8\u304d\u8fbc\u307f\u6570", "Posts"), total);

        Matcher names = Pattern.compile(
                "\u4f7f\u7528\u3057\u305f\u540d\u524d\u4e00\u89a7.*?\u66f8\u304d\u8fbc\u3093\u3060\u30b9\u30ec\u30c3\u30c9\u4e00\u89a7.*?</tr>\\s*<tr[^>]*>\\s*<td[^>]*>(.*?)</td>\\s*<td[^>]*>(.*?)</td>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL).matcher(source);
        if (names.find()) {
            appendSummaryLine(summary, text("\u540d\u524d", "Names"), compactSummaryText(names.group(1)));
            appendSummaryLine(summary, text("\u30b9\u30ec", "Threads"), hissiThreadSummary(names.group(2)));
        }
        return summary.toString();
    }

    private String lastTableCellText(String html) {
        if (html == null || html.isEmpty()) {
            return "";
        }
        Matcher cells = Pattern.compile("<td[^>]*>(.*?)</td>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL).matcher(html);
        String last = "";
        while (cells.find()) {
            last = cleanText(cells.group(1));
        }
        return last;
    }

    private String hissiThreadSummary(String html) {
        String source = html == null ? "" : html;
        List<String> titles = new ArrayList<>();
        Matcher links = Pattern.compile("<a\\b([^>]*)>(.*?)</a>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL).matcher(source);
        while (links.find()) {
            String attributes = links.group(1) == null ? "" : links.group(1).toLowerCase(Locale.ROOT);
            if (!attributes.contains("read.cgi")) {
                continue;
            }
            String title = cleanText(links.group(2));
            if (!title.isEmpty()) {
                titles.add(title);
            }
        }
        int omitted = parsePositiveInt(firstMatch(source,
                "\u305d\u306e\u4ed6\\s*(\\d+)\\s*\u30b9\u30ec\u30c3\u30c9"), 0);
        int total = titles.size() + omitted;
        if (total <= 0) {
            return compactSummaryText(source);
        }
        StringBuilder builder = new StringBuilder();
        builder.append(total).append(text("\u30b9\u30ec\u30c3\u30c9", " threads"));
        int shown = Math.min(3, titles.size());
        for (int i = 0; i < shown; i++) {
            builder.append(i == 0 ? ": " : " / ").append(titles.get(i));
        }
        if (omitted > 0) {
            builder.append(" / ").append(text("\u305d\u306e\u4ed6", "other "))
                    .append(omitted).append(text("\u30b9\u30ec\u30c3\u30c9", " threads"));
        } else if (titles.size() > shown) {
            builder.append(" / ...");
        }
        return builder.toString();
    }

    private void appendSummaryLine(StringBuilder builder, String label, String value) {
        String clean = cleanText(value == null ? "" : value);
        if (clean.isEmpty()) {
            return;
        }
        if (builder.length() > 0) {
            builder.append('\n');
        }
        builder.append(label).append(": ").append(clean);
    }

    private String compactSummaryText(String html) {
        String value = cleanText(html == null ? "" : html).replace('\r', '\n');
        String[] lines = value.split("\\n+");
        StringBuilder builder = new StringBuilder();
        for (String line : lines) {
            String item = line.trim();
            if (item.isEmpty()) {
                continue;
            }
            if (builder.length() > 0) {
                builder.append(" / ");
            }
            builder.append(item);
        }
        return builder.toString();
    }

    private String sourceThreadUrl(String url, int postNumber) {
        if (url == null || url.trim().isEmpty()) {
            return "";
        }
        String normalized = normalizeUrl(url);
        if (postNumber <= 0 || normalized.isEmpty()) {
            return normalized;
        }
        try {
            Uri uri = Uri.parse(normalized);
            List<String> segments = uri.getPathSegments();
            int readIndex = segments.indexOf("read.cgi");
            if (readIndex >= 0 && readIndex + 2 < segments.size()) {
                StringBuilder path = new StringBuilder();
                for (int i = 0; i <= readIndex + 2; i++) {
                    path.append('/').append(segments.get(i));
                }
                path.append('/');
                Uri.Builder builder = uri.buildUpon();
                builder.path(path.toString());
                builder.encodedQuery(null);
                builder.fragment(null);
                return builder.build().toString();
            }
        } catch (Exception ignored) {
        }
        String suffix = "/" + postNumber;
        return normalized.endsWith(suffix) ? normalized.substring(0, normalized.length() - suffix.length()) + "/" : normalized;
    }

    private String firstHref(String html) {
        Matcher matcher = HREF_PATTERN.matcher(html == null ? "" : html);
        if (!matcher.find()) {
            return "";
        }
        for (int i = 1; i <= 3; i++) {
            String value = matcher.group(i);
            if (value != null && !value.trim().isEmpty()) {
                return cleanText(value);
            }
        }
        return "";
    }

    private String absolutizeUrl(String base, String href) {
        if (href == null || href.trim().isEmpty()) {
            return "";
        }
        try {
            return new URL(new URL(base), href.trim()).toString();
        } catch (Exception ignored) {
            return normalizeUrl(href);
        }
    }

    private boolean sameRenderedThread(ThreadPage a, ThreadPage b) {
        if (a == null || b == null || a.posts.size() != b.posts.size()) {
            return false;
        }
        if (!TextUtils.equals(a.title, b.title)) {
            return false;
        }
        if (a.archived != b.archived) {
            return false;
        }
        if (a.posts.isEmpty()) {
            return true;
        }
        Post lastA = a.posts.get(a.posts.size() - 1);
        Post lastB = b.posts.get(b.posts.size() - 1);
        return lastA.number == lastB.number
                && TextUtils.equals(lastA.body, lastB.body)
                && TextUtils.equals(lastA.date, lastB.date)
                && TextUtils.equals(lastA.id(), lastB.id());
    }

    private void updateThreadTitleHeader(CuspTab tab, ThreadPage page) {
        if (tab == null || page == null || tab.threadList == null || tab.threadList.getChildCount() == 0) {
            return;
        }
        View title = tab.threadList.getChildAt(0);
        if (title instanceof TextView) {
            setThreadTitleText((TextView) title, page, page.title);
        }
    }

