    private void loadFullTextSearchResultsPage(CuspTab tab, String loadUrl, int pageNumber, boolean append) {
        if (tab == null || loadUrl == null) {
            return;
        }
        ioExecutor.execute(() -> {
            SearchPage page;
            try {
                page = downloadFullTextSearchPage(loadUrl, pageNumber);
            } catch (Exception error) {
                page = SearchPage.error(loadUrl, error.getMessage());
            }
            SearchPage result = page;
            runOnUiThread(() -> finishFullTextSearchResult(tab, loadUrl, result, append));
        });
    }

    private SearchPage downloadFullTextSearchPage(String loadUrl, int pageNumber) throws Exception {
        String query = searchQueryFromUrl(loadUrl);
        if (query.isEmpty()) {
            SearchPage page = new SearchPage();
            page.url = loadUrl;
            page.title = searchTitle(loadUrl);
            page.fullTextReachedEnd = true;
            return page;
        }
        String cseScript = downloadFullTextSearchText(
                "https://cse.google.com/cse.js?cx=" + URLEncoder.encode(SEARCH2CH_CSE_CX, "UTF-8"));
        String token = cseConfigString(cseScript, "cse_token");
        String libraryVersion = cseConfigString(cseScript, "cselibVersion");
        if (token.isEmpty() || libraryVersion.isEmpty()) {
            throw new IllegalStateException(text(
                    "\u5168\u6587\u691c\u7d22\u306e\u8a2d\u5b9a\u3092\u8aad\u307f\u8fbc\u3081\u307e\u305b\u3093\u3067\u3057\u305f\u3002",
                    "Could not load full-text search settings."));
        }
        int safePage = Math.max(1, pageNumber);
        StringBuilder url = new StringBuilder("https://cse.google.com/cse/element/v1");
        url.append("?rsz=filtered_cse");
        url.append("&num=10");
        url.append("&hl=ja");
        url.append("&source=gcsc");
        url.append("&cselibv=").append(URLEncoder.encode(libraryVersion, "UTF-8"));
        url.append("&cx=").append(URLEncoder.encode(SEARCH2CH_CSE_CX, "UTF-8"));
        url.append("&q=").append(URLEncoder.encode(query, "UTF-8"));
        url.append("&safe=off");
        url.append("&cse_tok=").append(URLEncoder.encode(token, "UTF-8"));
        url.append("&lr=&cr=&gl=");
        url.append("&filter=0");
        url.append("&sort=");
        url.append("&as_oq=");
        url.append("&as_sitesearch=");
        String exp = cseConfigArrayParameter(cseScript, "exp");
        if (!exp.isEmpty()) {
            url.append("&exp=").append(exp);
        }
        String fexp = cseConfigArrayParameter(cseScript, "fexp");
        if (!fexp.isEmpty()) {
            url.append("&fexp=").append(fexp);
        }
        url.append("&callback=__cuspidroidCseCallback");
        url.append("&rurl=").append(URLEncoder.encode(fullTextSearchUrl(query, safePage), "UTF-8"));
        if (safePage > 1) {
            url.append("&start=").append((safePage - 1) * 10);
        }
        String jsonp = downloadFullTextSearchText(url.toString());
        return parseFullTextSearchJsonp(loadUrl, jsonp, safePage);
    }

    private String downloadFullTextSearchText(String url) throws Exception {
        HttpURLConnection connection = null;
        try {
            Map<String, String> headers = new LinkedHashMap<>();
            headers.put("Accept", "application/javascript, text/javascript, */*");
            connection = openConnectionFollowingRedirects(url, FULL_TEXT_SEARCH_USER_AGENT, headers);
            int code = connection.getResponseCode();
            InputStream stream = code >= 400 ? connection.getErrorStream() : connection.getInputStream();
            if (stream == null) {
                throw new IllegalStateException("HTTP " + code);
            }
            String body = readText(stream, Charset.forName("UTF-8"));
            if (code >= 400) {
                throw new IllegalStateException("HTTP " + code + ": " + body);
            }
            return body;
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private String cseConfigString(String script, String key) {
        if (script == null || key == null) {
            return "";
        }
        Matcher matcher = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"([^\"]*)\"")
                .matcher(script);
        return matcher.find() ? matcher.group(1).replace("\\u003d", "=").trim() : "";
    }

    private String cseConfigArrayParameter(String script, String key) throws Exception {
        if (script == null || key == null) {
            return "";
        }
        Matcher matcher = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\\[(.*?)\\]",
                Pattern.DOTALL).matcher(script);
        if (!matcher.find()) {
            return "";
        }
        String[] values = matcher.group(1).split(",");
        List<String> encoded = new ArrayList<>();
        for (String value : values) {
            String item = value.trim();
            if (item.startsWith("\"") && item.endsWith("\"") && item.length() >= 2) {
                item = item.substring(1, item.length() - 1);
            }
            item = item.trim();
            if (!item.isEmpty()) {
                encoded.add(URLEncoder.encode(item, "UTF-8"));
            }
        }
        return String.join("%2C", encoded);
    }

    private SearchPage parseFullTextSearchJsonp(String loadUrl, String jsonp, int pageNumber) throws Exception {
        String body = jsonp == null ? "" : jsonp.trim();
        int start = body.indexOf('(');
        int end = body.lastIndexOf(')');
        if (start < 0 || end <= start) {
            throw new IllegalStateException(text(
                    "\u5168\u6587\u691c\u7d22\u306e\u5fdc\u7b54\u3092\u8aad\u307f\u53d6\u308c\u307e\u305b\u3093\u3067\u3057\u305f\u3002",
                    "Could not read full-text search response."));
        }
        JSONObject object = new JSONObject(body.substring(start + 1, end));
        JSONObject error = object.optJSONObject("error");
        if (error != null) {
            String message = error.optString("message", "").trim();
            if (message.isEmpty()) {
                message = "HTTP " + error.optInt("code", 0);
            }
            return SearchPage.error(loadUrl, message);
        }
        SearchPage page = new SearchPage();
        page.url = loadUrl;
        page.title = searchTitle(loadUrl);
        JSONArray results = object.optJSONArray("results");
        if (results != null) {
            for (int i = 0; i < results.length(); i++) {
                JSONObject item = results.optJSONObject(i);
                if (item == null) {
                    continue;
                }
                String title = plainHtmlText(item.optString("titleNoFormatting",
                        item.optString("title", ""))).trim();
                String resultUrl = item.optString("unescapedUrl", item.optString("url", "")).trim();
                if ((resultUrl.isEmpty() || resultUrl.contains("google.com/url"))
                        && !item.optString("clicktrackUrl", "").isEmpty()) {
                    resultUrl = searchQueryFromUrl(item.optString("clicktrackUrl", ""));
                }
                if (title.isEmpty() || resultUrl.isEmpty()) {
                    continue;
                }
                SearchResult result = new SearchResult();
                result.title = title;
                result.url = normalizeSearch2chResultUrl(resultUrl);
                result.meta = plainHtmlText(item.optString("contentNoFormatting",
                        item.optString("content", ""))).trim();
                page.results.add(result);
            }
        }
        JSONObject cursor = object.optJSONObject("cursor");
        page.fullTextPage = Math.max(1, pageNumber);
        page.fullTextHasMore = false;
        if (cursor != null) {
            int estimated = parsePositiveInt(cursor.optString("estimatedResultCount", ""), 0);
            page.fullTextHasMore = estimated > page.fullTextPage * 10;
            JSONArray pages = cursor.optJSONArray("pages");
            if (pages != null) {
                for (int i = 0; i < pages.length(); i++) {
                    JSONObject cursorPage = pages.optJSONObject(i);
                    if (cursorPage != null && parsePositiveInt(cursorPage.optString("label", ""), 0) > page.fullTextPage) {
                        page.fullTextHasMore = true;
                    }
                }
            }
        }
        page.fullTextReachedEnd = !page.fullTextHasMore;
        return page;
    }

    private String plainHtmlText(String value) {
        if (value == null || value.isEmpty()) {
            return "";
        }
        try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
                return Html.fromHtml(value, Html.FROM_HTML_MODE_LEGACY).toString();
            }
            return Html.fromHtml(value).toString();
        } catch (Exception error) {
            return value;
        }
    }

    private void extractFullTextSearchResults(CuspTab tab, String loadUrl, WebView webView,
                                              int attempt, int pageNumber, boolean append,
                                              boolean pageClicked) {
        if (tab == null || webView == null || !tabs.contains(tab) || !loadUrl.equals(tab.url)) {
            cleanupHiddenSearchWebView(webView);
            return;
        }
        String script = "(function(){"
                + "var target=" + Math.max(1, pageNumber) + ";"
                + "var attempt=" + Math.max(0, attempt) + ";"
                + "var query=" + JSONObject.quote(searchQueryFromUrl(loadUrl)) + ";"
                + "var clickedBefore=" + (pageClicked ? "true" : "false") + ";"
                + "function pageNumber(text,fallback){"
                + "var m=String(text||'').match(/\\d+/);"
                + "var n=m?parseInt(m[0],10):fallback;"
                + "return n&&n>0?n:fallback;"
                + "}"
                + "function visible(e){return !!(e&&(e.offsetWidth||e.offsetHeight||e.getClientRects().length));}"
                + "function nextControl(){"
                + "var nodes=document.querySelectorAll('.gsc-cursor-container-next[role=\"link\"],.gsc-cursor-next-page[role=\"link\"],.gsc-cursor-container-next,.gsc-cursor-next-page');"
                + "var fallback=null;"
                + "for(var i=0;i<nodes.length;i++){"
                + "var n=nodes[i];"
                + "if(!visible(n))continue;"
                + "if(!fallback)fallback=n;"
                + "if(n.getAttribute('tabindex')!=='-1')return n;"
                + "}"
                + "return fallback;"
                + "}"
                + "function submitSearch(){"
                + "if(!query||clickedBefore)return false;"
                + "var input=document.querySelector('input.gsc-input,.gsc-input-box input,input[name=\"search\"],input[type=\"text\"]');"
                + "if(!input)return false;"
                + "input.focus();"
                + "input.value=query;"
                + "input.dispatchEvent(new Event('input',{bubbles:true}));"
                + "input.dispatchEvent(new Event('change',{bubbles:true}));"
                + "var button=document.querySelector('.gsc-search-button-v2,input.gsc-search-button,button.gsc-search-button,button[type=\"submit\"],input[type=\"submit\"]');"
                + "if(button){button.click();return true;}"
                + "input.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,which:13,bubbles:true}));"
                + "input.dispatchEvent(new KeyboardEvent('keyup',{key:'Enter',keyCode:13,which:13,bubbles:true}));"
                + "return true;"
                + "}"
                + "function decodeHtml(text){"
                + "var e=document.createElement('textarea');"
                + "e.innerHTML=String(text||'');"
                + "return e.value;"
                + "}"
                + "function apiSnapshot(){"
                + "var state=window.__cuspidroidCseState;"
                + "if(!state||state.query!==query||state.page!==target||!state.data)return null;"
                + "var data=state.data;"
                + "var apiResults=data.results||[];"
                + "var rows=[];var seen={};"
                + "for(var i=0;i<apiResults.length;i++){"
                + "var item=apiResults[i]||{};"
                + "var title=decodeHtml(item.titleNoFormatting||item.title||'').trim();"
                + "var url=String(item.unescapedUrl||item.url||'').trim();"
                + "if((!url||url.indexOf('google.com/url')>=0)&&item.clicktrackUrl){"
                + "var m=String(item.clicktrackUrl).match(/[?&]q=([^&]+)/);"
                + "if(m){try{url=decodeURIComponent(m[1].replace(/\\+/g,' '));}catch(ex){url=m[1];}}"
                + "}"
                + "if(!title||!url||seen[url])continue;"
                + "seen[url]=true;"
                + "rows.push({title:title,url:url,meta:decodeHtml(item.contentNoFormatting||item.content||'').trim()});"
                + "}"
                + "var cursor=data.cursor||{};"
                + "var current=(parseInt(cursor.currentPageIndex,10)||0)+1;"
                + "var estimated=parseInt(String(cursor.estimatedResultCount||'0').replace(/\\D/g,''),10)||0;"
                + "var hasMore=estimated>Math.max(current,target)*10;"
                + "if(cursor.pages&&cursor.pages.length){"
                + "for(var p=0;p<cursor.pages.length;p++){"
                + "var label=parseInt(cursor.pages[p].label,10);"
                + "if(label>current)hasMore=true;"
                + "}"
                + "}"
                + "return {ready:true,results:rows,currentPage:Math.max(current,target),maxPage:Math.max(current,target),hasMore:hasMore};"
                + "}"
                + "function startApiFetch(){"
                + "if(!query||window.__cuspidroidCseLoading)return false;"
                + "var entries=(performance&&performance.getEntriesByType)?performance.getEntriesByType('resource'):[];"
                + "var base='';"
                + "for(var i=entries.length-1;i>=0;i--){"
                + "var name=entries[i].name||'';"
                + "if(name.indexOf('cse.google.com/cse/element/v1')>=0){base=name;break;}"
                + "}"
                + "if(!base)return false;"
                + "try{"
                + "var u=new URL(base,location.href);"
                + "u.searchParams.set('q',query);"
                + "u.searchParams.set('num','10');"
                + "u.searchParams.set('callback','__cuspidroidCseCallback');"
                + "if(target>1)u.searchParams.set('start',String((target-1)*10));"
                + "else u.searchParams.delete('start');"
                + "u.searchParams.set('rurl',location.href);"
                + "window.__cuspidroidCseLoading=true;"
                + "window.__cuspidroidCseState={query:query,page:target,data:null};"
                + "window.__cuspidroidCseCallback=function(data){"
                + "window.__cuspidroidCseLoading=false;"
                + "window.__cuspidroidCseState={query:query,page:target,data:data||{}};"
                + "};"
                + "var script=document.createElement('script');"
                + "script.src=u.toString();"
                + "script.onerror=function(){window.__cuspidroidCseLoading=false;};"
                + "document.documentElement.appendChild(script);"
                + "return true;"
                + "}catch(ex){window.__cuspidroidCseLoading=false;return false;}"
                + "}"
                + "var currentNode=document.querySelector('.gsc-cursor-current-page,.gsc-cursor-numbered-page');"
                + "var current=currentNode?pageNumber((currentNode.innerText||currentNode.textContent||'1').trim(),1):1;"
                + "var nodes=document.querySelectorAll('.gsc-webResult.gsc-result,.gsc-results .gsc-result');"
                + "var pages=document.querySelectorAll('.gsc-cursor-page');"
                + "var nextNodeControl=nextControl();"
                + "var maxPage=current;"
                + "for(var p=0;p<pages.length;p++){"
                + "var pn=pageNumber((pages[p].innerText||pages[p].textContent||'').trim(),0);"
                + "if(pn&&pn>maxPage)maxPage=pn;"
                + "}"
                + "if(target>1&&current!==target&&nodes.length>0){"
                + "if(pages.length>0&&target>maxPage&&!nextNodeControl){"
                + "return JSON.stringify({ready:true,results:[],currentPage:maxPage,maxPage:maxPage,hasMore:false});"
                + "}"
                + "var nextNode=null;var nextPage=999999;"
                + "for(var p=0;p<pages.length;p++){"
                + "var n=pageNumber((pages[p].innerText||pages[p].textContent||'').trim(),0);"
                + "if(n===target){pages[p].click();return JSON.stringify({ready:false,clicked:true});}"
                + "if(n>current&&n<nextPage){nextPage=n;nextNode=pages[p];}"
                + "}"
                + "if(nextNode){nextNode.click();return JSON.stringify({ready:false,clicked:true});}"
                + "if(nextNodeControl){nextNodeControl.click();return JSON.stringify({ready:false,clicked:true});}"
                + "return JSON.stringify({ready:true,results:[],currentPage:maxPage,maxPage:maxPage,hasMore:false});"
                + "}"
                + "var rows=[];"
                + "var seen={};"
                + "var anchors=document.querySelectorAll('a.gs-title,.gs-title a[href],.gsc-webResult a[href][data-ctorig],.gsc-results a[href][data-ctorig],.gsc-webResult a[href][data-cturl],.gsc-results a[href][data-cturl]');"
                + "for(var i=0;i<anchors.length;i++){"
                + "var a=anchors[i];"
                + "var e=a.closest?a.closest('.gsc-result'):null;"
                + "if(!e)e=a.parentNode;"
                + "if(e&&e.className&&(e.className.indexOf('gs-no-results-result')>=0||e.className.indexOf('gs-error-result')>=0))continue;"
                + "var title=a?(a.innerText||a.textContent||'').trim():'';"
                + "if(!title&&a.parentNode)title=(a.parentNode.innerText||a.parentNode.textContent||'').trim();"
                + "var url=a?(a.getAttribute('data-ctorig')||a.href||'').trim():'';"
                + "if((!url||url.indexOf('google.com/url')>=0)&&a){"
                + "var ct=a.getAttribute('data-cturl')||a.href||'';"
                + "var m=ct.match(/[?&]q=([^&]+)/);"
                + "if(m){try{url=decodeURIComponent(m[1].replace(/\\+/g,' '));}catch(ex){url=m[1];}}"
                + "}"
                + "if(url&&url.indexOf('google.com/search')>=0)continue;"
                + "if(!url||seen[url])continue;"
                + "seen[url]=true;"
                + "var vis=e&&e.querySelector?e.querySelector('.gs-visibleUrl-long,.gs-visibleUrl'):null;"
                + "var snip=e&&e.querySelector?e.querySelector('.gs-snippet'):null;"
                + "var meta=[];"
                + "if(vis&&(vis.innerText||vis.textContent))meta.push((vis.innerText||vis.textContent).trim());"
                + "if(snip&&(snip.innerText||snip.textContent))meta.push((snip.innerText||snip.textContent).trim());"
                + "if(title&&url)rows.push({title:title,url:url,meta:meta.join('\\n')});"
                + "}"
                + "var noResults=document.querySelector('.gs-no-results-result');"
                + "var errorResult=document.querySelector('.gs-error-result');"
                + "var empty=noResults||errorResult;"
                + "var errorText=errorResult?(errorResult.innerText||errorResult.textContent||'').trim():'';"
                + "var hasMore=pages.length>0?maxPage>current:!!nextNodeControl;"
                + "var api=rows.length===0?apiSnapshot():null;"
                + "if(api&&api.results&&api.results.length>0)return JSON.stringify(api);"
                + "if(target<=1&&rows.length===0&&!noResults&&attempt>=2&&submitSearch()){"
                + "return JSON.stringify({ready:false,clicked:true});"
                + "}"
                + "if(rows.length===0&&!noResults&&attempt>=3&&startApiFetch()){"
                + "return JSON.stringify({ready:false,results:[],currentPage:current,maxPage:maxPage,hasMore:false});"
                + "}"
                + "if(rows.length>=10&&!hasMore&&!document.querySelector('.gsc-cursor-box')&&attempt<5){"
                + "return JSON.stringify({ready:false,results:[],currentPage:current,maxPage:maxPage,hasMore:false});"
                + "}"
                + "return JSON.stringify({ready:rows.length>0||!!empty,results:rows,currentPage:current,maxPage:maxPage,hasMore:hasMore,error:errorText});"
                + "})()";
        webView.evaluateJavascript(script, value -> {
            if (value != null && value.contains("\\\"clicked\\\":true")) {
                mainHandler.postDelayed(() -> extractFullTextSearchResults(tab, loadUrl, webView,
                        attempt + 1, pageNumber, append, true), 1100);
                return;
            }
            SearchPage page = parseFullTextSearchSnapshot(loadUrl, value);
            if (append && pageNumber > 1 && page != null && page.results.isEmpty()
                    && !page.fullTextHasMore) {
                finishFullTextSearchIfPending(tab, loadUrl, webView, page, true);
                return;
            }
            if (append && pageNumber > 1 && page != null && !page.results.isEmpty()
                    && page.fullTextPage < pageNumber) {
                int newCount = countNewSearchResults(tab == null ? null : tab.searchPage, page);
                if (newCount > 0 && fullTextSearchPageReady(page, newCount, attempt)) {
                    page.fullTextPage = pageNumber;
                    finishFullTextSearchIfPending(tab, loadUrl, webView, page, true);
                    return;
                }
                if (attempt < 18) {
                    mainHandler.postDelayed(() -> extractFullTextSearchResults(tab, loadUrl, webView,
                            attempt + 1, pageNumber, true, pageClicked), 800);
                    return;
                }
                finishFullTextSearchIfPending(tab, loadUrl, webView,
                        SearchPage.error(loadUrl, text("\u8ffd\u52a0\u306e\u691c\u7d22\u7d50\u679c\u3092\u8aad\u307f\u8fbc\u3081\u307e\u305b\u3093\u3067\u3057\u305f", "Could not load more search results.")),
                        true);
                return;
            }
            if (append && pageNumber > 1 && page != null && !page.results.isEmpty()) {
                int newCount = countNewSearchResults(tab == null ? null : tab.searchPage, page);
                if (newCount <= 0) {
                    if (!page.fullTextHasMore) {
                        finishFullTextSearchIfPending(tab, loadUrl, webView, page, true);
                        return;
                    }
                    if (attempt < 18) {
                        mainHandler.postDelayed(() -> extractFullTextSearchResults(tab, loadUrl, webView,
                                attempt + 1, pageNumber, true, pageClicked), 800);
                        return;
                    }
                    finishFullTextSearchIfPending(tab, loadUrl, webView,
                            SearchPage.error(loadUrl, text("\u8ffd\u52a0\u306e\u691c\u7d22\u7d50\u679c\u3092\u8aad\u307f\u8fbc\u3081\u307e\u305b\u3093\u3067\u3057\u305f", "Could not load more search results.")),
                            true);
                    return;
                }
                if (newCount > 0 && !fullTextSearchPageReady(page, newCount, attempt) && attempt < 18) {
                    mainHandler.postDelayed(() -> extractFullTextSearchResults(tab, loadUrl, webView,
                            attempt + 1, pageNumber, true, pageClicked), 800);
                    return;
                }
            }
            if (page != null && ((page.error != null && attempt >= 6) || !page.results.isEmpty() || attempt >= 18)) {
                finishFullTextSearchIfPending(tab, loadUrl, webView, page, append);
                return;
            }
            if (attempt >= 18) {
                SearchPage empty = append
                        ? SearchPage.error(loadUrl, text("\u8ffd\u52a0\u306e\u691c\u7d22\u7d50\u679c\u3092\u8aad\u307f\u8fbc\u3081\u307e\u305b\u3093\u3067\u3057\u305f", "Could not load more search results."))
                        : new SearchPage();
                if (!append) {
                    empty.url = loadUrl;
                    empty.title = searchTitle(loadUrl);
                }
                finishFullTextSearchIfPending(tab, loadUrl, webView, empty, append);
                return;
            }
            mainHandler.postDelayed(() -> extractFullTextSearchResults(tab, loadUrl, webView,
                    attempt + 1, pageNumber, append, pageClicked), 700);
        });
    }

    private boolean fullTextSearchPageReady(SearchPage page, int newCount, int attempt) {
        int resultCount = page == null || page.results == null ? 0 : page.results.size();
        return resultCount >= 8 || newCount >= 6 || attempt >= 8;
    }

    private int countNewSearchResults(SearchPage existingPage, SearchPage candidatePage) {
        if (candidatePage == null || candidatePage.results == null || candidatePage.results.isEmpty()) {
            return 0;
        }
        Set<String> existing = new LinkedHashSet<>();
        if (existingPage != null && existingPage.results != null) {
            for (SearchResult result : existingPage.results) {
                if (result.url != null) {
                    existing.add(searchResultDedupeKey(result.url));
                }
            }
        }
        int count = 0;
        for (SearchResult result : candidatePage.results) {
            if (result.url == null || !existing.contains(searchResultDedupeKey(result.url))) {
                count++;
            }
        }
        return count;
    }

    private String searchResultDedupeKey(String url) {
        return normalizeSearch2chResultUrl(url == null ? "" : url).trim();
    }

    private SearchPage parseFullTextSearchSnapshot(String url, String rawValue) {
        try {
            String json = rawValue == null ? "" : rawValue;
            if (json.startsWith("\"") && json.endsWith("\"")) {
                json = new JSONArray("[" + json + "]").optString(0, "");
            }
            if (json.trim().isEmpty() || "null".equals(json)) {
                return null;
            }
            JSONObject object = new JSONObject(json);
            SearchPage page = new SearchPage();
            page.url = url;
            page.title = searchTitle(url);
            JSONArray results = object.optJSONArray("results");
            if (results != null) {
                for (int i = 0; i < results.length(); i++) {
                    JSONObject item = results.optJSONObject(i);
                    if (item == null) {
                        continue;
                    }
                    String resultUrl = item.optString("url", "").trim();
                    String title = item.optString("title", "").trim();
                    if (resultUrl.isEmpty() || title.isEmpty()) {
                        continue;
                    }
                    SearchResult result = new SearchResult();
                    result.url = normalizeSearch2chResultUrl(resultUrl);
                    result.title = title;
                    result.meta = item.optString("meta", "").trim();
                    page.results.add(result);
                }
            }
            String error = object.optString("error", "").trim();
            if (!error.isEmpty() && page.results.isEmpty()) {
                page.error = error;
                page.title = text("\u691c\u7d22\u5931\u6557", "Search failed");
            }
            page.fullTextPage = Math.max(1, object.optInt("currentPage", 1));
            page.fullTextHasMore = object.optBoolean("hasMore", false);
            page.fullTextReachedEnd = !page.fullTextHasMore;
            return object.optBoolean("ready", false) || !page.results.isEmpty() ? page : null;
        } catch (Exception ignored) {
            return null;
        }
    }

    private String normalizeSearch2chResultUrl(String url) {
        if (url == null) {
            return "";
        }
        String value = url.trim();
        try {
            Uri uri = Uri.parse(value);
            String q = uri.getQueryParameter("q");
            if (q != null && looksLikeUrl(q)) {
                return normalizeUrl(q);
            }
            String target = uri.getQueryParameter("url");
            if (target != null && looksLikeUrl(target)) {
                return normalizeUrl(target);
            }
        } catch (Exception ignored) {
        }
        return value;
    }

    private void finishFullTextSearchIfPending(CuspTab tab, String loadUrl, WebView webView, SearchPage page) {
        finishFullTextSearchIfPending(tab, loadUrl, webView, page, false);
    }

    private void finishFullTextSearchIfPending(CuspTab tab, String loadUrl, WebView webView, SearchPage page, boolean append) {
        if (webView.getTag() != null) {
            return;
        }
        webView.setTag(Boolean.TRUE);
        cleanupHiddenSearchWebView(webView);
        finishFullTextSearchResult(tab, loadUrl, page, append);
    }

    private void finishFullTextSearchResult(CuspTab tab, String loadUrl, SearchPage page, boolean append) {
        if (page == null) {
            page = SearchPage.error(loadUrl, text("\u5168\u6587\u691c\u7d22\u306e\u53d6\u5f97\u306b\u5931\u6557\u3057\u307e\u3057\u305f\u3002", "Could not load full-text search."));
        }
        if (tab == null || !tabs.contains(tab) || !loadUrl.equals(tab.url)) {
            if (tab == currentTab()) {
                progressBar.setVisibility(View.GONE);
            }
            return;
        }
        int restoreScrollY = 0;
        int previousResultCount = -1;
        int addedResultCount = 0;
        boolean appendedResults = false;
        ScrollView currentScroll = append ? findScrollView(contentFrame) : null;
        if (currentScroll != null) {
            restoreScrollY = currentScroll.getScrollY();
        }
        if (append && tab.searchPage != null && tab.searchPage.error == null && page.error == null) {
            previousResultCount = tab.searchPage.results.size();
            addedResultCount = appendSearchPageResults(tab.searchPage, page);
            page = tab.searchPage;
            appendedResults = true;
        } else if (append && tab.searchPage != null) {
            tab.searchPage.fullTextLoadingMore = false;
            updateFullTextLoadMoreFooter(findScrollView(contentFrame), tab.searchPage);
            Toast.makeText(this, text("\u8ffd\u52a0\u306e\u691c\u7d22\u7d50\u679c\u3092\u8aad\u307f\u8fbc\u3081\u307e\u305b\u3093\u3067\u3057\u305f", "Could not load more search results."), Toast.LENGTH_SHORT).show();
            progressBar.setVisibility(View.GONE);
            return;
        } else {
            tab.title = page.title;
            tab.searchPage = page;
        }
        page.fullTextLoadingMore = false;
        if (appendedResults && tab == currentTab() && !tabOverviewVisible
                && appendSearchResultsInPlace(currentScroll, page, previousResultCount, addedResultCount)) {
            progressBar.setVisibility(View.GONE);
            renderTabs();
            return;
        }
        resetTopRefreshLoader(tab.boardTopLoader);
        tab.readerView = buildSearchView(page, true, tab);
        progressBar.setVisibility(View.GONE);
        if (tab == currentTab() && !tabOverviewVisible) {
            switchToTab(currentIndex);
            if (append && restoreScrollY > 0) {
                int finalRestoreScrollY = restoreScrollY;
                ScrollView nextScroll = findScrollView(contentFrame);
                if (nextScroll != null) {
                    nextScroll.post(() -> nextScroll.scrollTo(0, finalRestoreScrollY));
                }
            }
        }
        renderTabs();
    }

    private int appendSearchPageResults(SearchPage target, SearchPage source) {
        Set<String> existing = new LinkedHashSet<>();
        for (SearchResult result : target.results) {
            if (result.url != null) {
                existing.add(searchResultDedupeKey(result.url));
            }
        }
        int previousPage = Math.max(1, target.fullTextPage);
        int added = 0;
        for (SearchResult result : source.results) {
            if (result.url == null || existing.add(searchResultDedupeKey(result.url))) {
                target.results.add(result);
                added++;
            }
        }
        target.fullTextPage = added > 0 && source.fullTextPage <= previousPage
                ? previousPage + 1
                : Math.max(previousPage, source.fullTextPage);
        target.fullTextHasMore = source.fullTextHasMore;
        target.fullTextReachedEnd = !source.fullTextHasMore;
        target.error = null;
        return added;
    }

    private boolean appendSearchResultsInPlace(ScrollView scroll, SearchPage page,
                                               int previousResultCount, int addedResultCount) {
        if (scroll == null || page == null || previousResultCount < 0
                || scroll.getChildCount() == 0 || !(scroll.getChildAt(0) instanceof LinearLayout)) {
            return false;
        }
        LinearLayout list = (LinearLayout) scroll.getChildAt(0);
        if (!(list.getTag() instanceof VirtualSearchState)) {
            return false;
        }
        LinearLayout footer = findFullTextLoadMoreFooter(scroll);
        if (footer != null && footer.getParent() == list) {
            list.removeView(footer);
        }
        int end = Math.max(previousResultCount, page.results.size());
        for (int i = previousResultCount; i < end; i++) {
            SearchResult result = page.results.get(i);
            if (!shouldHideNgThreadTitle(result.title)) {
                addVirtualSearchSlot(list, new VirtualSearchSlot(null, result, false));
            }
        }
        boolean showFooter = isFullTextSearchUrl(page.url) && !page.results.isEmpty()
                && (page.fullTextHasMore || !page.fullTextReachedEnd);
        if (showFooter) {
            if (footer == null) {
                footer = (LinearLayout) fullTextLoadMoreFooter(page, scroll);
            } else {
                updateFullTextLoadMoreFooterContent(footer, page, scroll);
            }
            list.addView(footer, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        }
        if (addedResultCount > 0) {
            ensureSearchSlotRefresh(scroll, list);
            scheduleSearchSlotRefresh(list);
        }
        return true;
    }

    private void cleanupHiddenSearchWebView(WebView webView) {
        try {
            ViewParent parent = webView.getParent();
            if (parent instanceof ViewGroup) {
                ((ViewGroup) parent).removeView(webView);
            }
            webView.stopLoading();
            webView.loadUrl("about:blank");
            webView.destroy();
        } catch (Exception ignored) {
        }
    }

    private String friendlyThreadLoadError(String detail) {
        String raw = detail == null ? "" : detail.trim();
        String lower = raw.toLowerCase(Locale.ROOT);
        if (lower.contains("unable to resolve host")
                || lower.contains("no address associated with hostname")
                || lower.contains("failed to connect")
                || lower.contains("timeout")
                || lower.contains("timed out")
                || lower.contains("network is unreachable")
                || lower.contains("connection reset")) {
            return text("\u901a\u4fe1\u3067\u304d\u306a\u3044\u305f\u3081\u3001\u6700\u65b0\u306e\u30b9\u30ec\u3092\u8aad\u307f\u8fbc\u3081\u307e\u305b\u3093\u3067\u3057\u305f\u3002",
                    "Could not load the latest thread because the network is unavailable.");
        }
        return raw.isEmpty()
                ? text("\u30b9\u30ec\u3092\u8aad\u307f\u8fbc\u3081\u307e\u305b\u3093\u3067\u3057\u305f\u3002", "Could not load the thread.")
                : text("\u30b9\u30ec\u3092\u8aad\u307f\u8fbc\u3081\u307e\u305b\u3093\u3067\u3057\u305f\u3002", "Could not load the thread.");
    }

    private ThreadPage downloadThreadPage(String url) throws Exception {
        ThreadPage datPage = downloadDatThread(url);
        if (datPage != null && !datPage.posts.isEmpty()) {
            return datPage;
        }
        String redirectedUrl = url;
        if (datAddress(url) == null) {
            redirectedUrl = resolveRedirectedUrl(
                    url,
                    "Mozilla/5.0 (Linux; Android) CuspiDroid/0.1");
            datPage = downloadDatThread(redirectedUrl);
            if (datPage != null && !datPage.posts.isEmpty()) {
                return datPage;
            }
        }
        ThreadPage htmlPage = null;
        Exception htmlError = null;
        try {
            String html = download(threadHtmlUrl(redirectedUrl), "Mozilla/5.0 CuspiDroid/0.1");
            htmlPage = parseThread(redirectedUrl, html);
            if (!htmlPage.posts.isEmpty()) {
                return htmlPage;
            }
        } catch (Exception error) {
            htmlError = error;
        }
        if (htmlPage != null) {
            return htmlPage;
        }
        throw htmlError == null ? new IllegalStateException("No posts were parsed.") : htmlError;
    }

