    private void loadBbsDirectory(CuspTab tab, String url) {
        loadBbsDirectory(tab, url, true);
    }

    private void loadBbsDirectory(CuspTab tab, String url, boolean foreground) {
        final String loadUrl = url;
        if (foreground) {
            prepareChromeForLoading();
        }
        if (foreground) {
            clearBoardTopRefreshState(tab);
        }
        tab.readerMode = true;
        tab.nativeKind = NATIVE_BOARD;
        tab.url = loadUrl;
        tab.title = hostTitle(loadUrl);
        if (foreground || tab.readerView == null) {
            tab.readerView = loadingView("");
        }
        tab.threadPage = null;
        tab.searchPage = null;
        tab.threadScroll = null;
        tab.postViews = null;
        if (foreground) {
            switchToTab(tabs.indexOf(tab));
            progressBar.setVisibility(View.VISIBLE);
        }

        ioExecutor.execute(() -> {
            SearchPage page;
            boolean usedCached = false;
            try {
                page = cachedBbsDirectoryPage(loadUrl);
                if (page != null) {
                    usedCached = true;
                } else {
                    page = downloadBbsDirectoryWithCache(loadUrl);
                }
                page.title = bbsMenuTitle(loadUrl, page.title);
                bbsCategoryCounts(page);
            } catch (Exception error) {
                page = SearchPage.error(loadUrl, error.getMessage());
            }
            SearchPage result = page;
            boolean refresh = usedCached;
            runOnUiThread(() -> {
                if (!tabs.contains(tab) || !loadUrl.equals(tab.url)) {
                    resetTopRefreshLoader(tab.boardTopLoader);
                    if ((foreground || tab == currentTab()) && !tabOverviewVisible) {
                        progressBar.setVisibility(View.GONE);
                    }
                    return;
                }
                if (result.error == null && result.url != null && !result.url.trim().isEmpty()) {
                    replaceCurrentNavigationUrl(tab, loadUrl, result.url);
                    tab.url = result.url;
                }
                tab.title = result.title;
                tab.searchPage = result;
                resetTopRefreshLoader(tab.boardTopLoader);
                tab.readerView = isBbsMenuUrl(result.url) ? buildBbsCategoryIndexView(result, tab) : buildSearchView(result, false, tab);
                cacheBoardHistoryPage(tab, result, tab.readerView);
                if ((foreground || tab == currentTab()) && !tabOverviewVisible) {
                    progressBar.setVisibility(View.GONE);
                }
                if (tab == currentTab() && !tabOverviewVisible) {
                    switchToTab(currentIndex);
                }
                requestSaveTabsSoon();
                renderTabs();
                if (refresh) {
                    refreshBbsMenuCacheIfStale(loadUrl);
                }
            });
        });
    }

    private View loadingView(String message) {
        LinearLayout box = new LinearLayout(this);
        box.setTag(LOADING_VIEW_TAG);
        box.setGravity(Gravity.CENTER);
        box.setOrientation(LinearLayout.VERTICAL);
        ProgressBar spinner = new ProgressBar(this);
        spinner.setIndeterminate(true);
        box.addView(spinner, new LinearLayout.LayoutParams(dp(48), dp(48)));
        TextView text = new TextView(this);
        text.setText(message);
        text.setTextColor(textColor());
        text.setTextSize(16);
        text.setPadding(0, dp(10), 0, 0);
        if (message != null && !message.isEmpty()) {
            box.addView(text);
        }
        return box;
    }

    private View buildThreadView(ThreadPage page, CuspTab tab) {
        cancelThreadChunkRender(tab);
        ScrollView scroll = new ThreadScrollView(this);
        tab.threadScroll = scroll;
        scroll.setFillViewport(true);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.getViewTreeObserver().addOnScrollChangedListener(this::scheduleThreadMediaLoads);
        scroll.setOnClickListener(v -> dismissTopReplyPopup());
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setPadding(dp(POST_OUTER_GAP_DP), dp(POST_OUTER_GAP_DP),
                dp(POST_OUTER_GAP_DP), dp(POST_OUTER_GAP_DP));
        tab.threadList = list;
        scroll.addView(list, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        TextView title = new TextView(this);
        setThreadTitleText(title, page, page.title);
        title.setTextColor(textColor());
        title.setTextSize(20);
        title.setGravity(Gravity.START);
        title.setPadding(0, 0, 0, dp(10));
        list.addView(title);

        if (tab != null && NATIVE_HISSI.equals(tab.nativeKind)
                && page.hissiSummary != null && !page.hissiSummary.trim().isEmpty()) {
            LinearLayout.LayoutParams summaryParams = new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            summaryParams.setMargins(0, 0, 0, dp(10));
            list.addView(hissiSummaryView(page.hissiSummary), summaryParams);
        }

        if (page.error != null) {
            TextView error = postText(page.error, page);
            error.setTextColor(Color.rgb(185, 28, 28));
            list.addView(error);
            return scroll;
        }

        if (matchesNgThread(page.title)) {
            list.addView(postText(text("NGThread\u306b\u3088\u308a\u975e\u8868\u793a", "Hidden by NGThread."), page));
            return withScrollScrubber(scroll, tab);
        }

        renderPostCardsIncrementally(list, page, tab);

        if (page.posts.isEmpty()) {
            list.addView(postText(text("\u66f8\u304d\u8fbc\u307f\u3092\u89e3\u6790\u3067\u304d\u307e\u305b\u3093", "No posts were parsed. Use reload or open another URL."), page));
        }
        FrameLayout bottomLoader = null;
        FrameLayout topLoader = null;
        if (tab != null && NATIVE_THREAD.equals(tab.nativeKind)) {
            bottomLoader = bottomRefreshLoader();
            bottomLoader.setVisibility(View.GONE);
            bottomLoader.setTranslationY(dp(58));
            tab.threadBottomLoader = bottomLoader;
        } else if (tab != null) {
            tab.threadBottomLoader = null;
        }
        if (tab != null && (NATIVE_THREAD.equals(tab.nativeKind) || NATIVE_HISSI.equals(tab.nativeKind))) {
            topLoader = bottomRefreshLoader();
            topLoader.setVisibility(View.GONE);
            topLoader.setTranslationY(-dp(58));
            tab.boardTopLoader = topLoader;
            if (bottomLoader != null) {
                enableThreadPullRefresh(scroll, topLoader, bottomLoader, tab);
            } else {
                enableTopPullRefresh(scroll, topLoader, () -> refreshTabFromTop(tab));
            }
        }
        FrameLayout frame = new FrameLayout(this);
        frame.setTag(R.id.tag_top_pull_refresh, true);
        frame.addView(withScrollScrubber(scroll, tab), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        if (topLoader != null) {
            FrameLayout.LayoutParams topParams = new FrameLayout.LayoutParams(dp(66), dp(66),
                    Gravity.TOP | Gravity.CENTER_HORIZONTAL);
            topParams.setMargins(0, dp(2), 0, 0);
            frame.addView(topLoader, topParams);
        }
        if (bottomLoader != null) {
            FrameLayout.LayoutParams loaderParams = new FrameLayout.LayoutParams(dp(66), dp(66),
                    Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL);
            loaderParams.setMargins(0, 0, 0, dp(2));
            frame.addView(bottomLoader, loaderParams);
        }
        return frame;
    }

