        TextView view = helperLine(text("\u8fd4\u4fe1 ", "Replies ") + replyCount);
        view.setTextColor(TEAL);
        view.setTypeface(Typeface.DEFAULT_BOLD);
        view.setGravity(Gravity.END | Gravity.CENTER_VERTICAL);
