    private boolean matchesNgPost(Post post) {
        return ngMatchCategory(post) != null;
    }

    private boolean shouldRenderPost(Post post) {
        NgMatch match = ngMatch(post);
        return match == null || !match.hide;
    }

    private String ngMatchCategory(Post post) {
        NgMatch match = ngMatch(post);
        return match == null ? null : match.category;
    }

    private NgMatch ngMatch(Post post) {
        if (post == null) {
            return null;
        }
        NgRules rules = ngRules();
        String targetUrl = currentNgThreadUrl();
        String cacheKey = cachedNgRulesKey + "\n" + targetUrl;
        if (post.cachedNgRulesKey != null && post.cachedNgRulesKey.equals(cacheKey)) {
            return post.cachedNgMatch ? new NgMatch(post.cachedNgCategory, post.cachedNgHide) : null;
        }
        NgMatch match = rules.match("NGWord", post.body, targetUrl);
        if (match == null) {
            match = rules.match("NGName", post.name, targetUrl);
        }
        if (match == null) {
            match = rules.match("NGID", post.id(), targetUrl);
        }
        if (match == null) {
            match = rules.match("NGBe", post.be(), targetUrl);
        }
        post.cachedNgRulesKey = cacheKey;
        post.cachedNgCategory = match == null ? "" : match.category;
        post.cachedNgHide = match != null && match.hide;
        post.cachedNgMatch = match != null;
        return match;
    }

    private boolean matchesNgThread(String title) {
        return ngThreadMatch(title) != null;
    }

    private boolean shouldHideNgThreadTitle(String title) {
        NgMatch match = ngThreadMatch(title);
        return match != null && match.hide;
    }

    private NgMatch ngThreadMatch(String title) {
        return ngRules().match("NGThread", title, currentNgThreadUrl());
    }

    private String currentNgThreadUrl() {
        CuspTab tab = currentTab();
        if (tab == null) {
            return "";
        }
        if (NATIVE_THREAD.equals(tab.nativeKind)) {
            String boardUrl = currentThreadBoardUrl(tab);
            return normalizeNgTargetUrl(boardUrl == null ? tab.url : boardUrl);
        }
        if (NATIVE_BOARD.equals(tab.nativeKind)) {
            return normalizeNgTargetUrl(tab.url);
        }
        return "";
    }

    private NgRules ngRules() {
        String rulesJson = preferences.getString(PREF_NG_RULES, "{}");
        String legacyWords = preferences.getString(PREF_NG_WORDS, "");
        String key = rulesJson + "\n" + legacyWords;
        if (cachedNgRules != null && key.equals(cachedNgRulesKey)) {
            return cachedNgRules;
        }
        NgRules rules = new NgRules();
        for (ScopedNgRule rule : readNgRules(preferences)) {
            rules.add(rule);
        }
        cachedNgRulesKey = key;
        cachedNgRules = rules;
        return rules;
    }

    private static class NgRules {
        static final String[] CATEGORIES = {"NGWord", "NGName", "NGID", "NGBe", "NGThread"};
        final List<CompiledNgRule> rules = new ArrayList<>();

        void add(ScopedNgRule rule) {
            try {
                rules.add(new CompiledNgRule(rule,
                        rule.regex ? Pattern.compile(rule.value, Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE) : null));
            } catch (Exception ignored) {
            }
        }

        NgMatch match(String category, String value, String targetUrl) {
            if (value == null || value.isEmpty()) {
                return null;
            }
            String lower = value.toLowerCase(Locale.ROOT);
            String target = normalizeNgTargetUrl(targetUrl);
            for (CompiledNgRule compiled : rules) {
                ScopedNgRule rule = compiled.rule;
                if (!category.equals(rule.category)
                        || (!rule.targetUrl.isEmpty() && !rule.targetUrl.equals(target))) {
                    continue;
                }
                if (compiled.pattern != null ? compiled.pattern.matcher(value).find()
                        : lower.contains(rule.value.toLowerCase(Locale.ROOT))) {
                    return new NgMatch(rule.category, NG_DISPLAY_HIDE.equals(rule.mode));
                }
            }
            return null;
        }
    }

    private static class NgMatch {
        final String category;
        final boolean hide;

        NgMatch(String category, boolean hide) {
            this.category = category == null ? "NGWord" : category;
            this.hide = hide;
        }
    }

    private static class CompiledNgRule {
        final ScopedNgRule rule;
        final Pattern pattern;

        CompiledNgRule(ScopedNgRule rule, Pattern pattern) {
            this.rule = rule;
            this.pattern = pattern;
        }
    }

    private View buildSearchView(SearchPage page) {
        return buildSearchView(page, true, null);
    }

    private View buildSearchView(SearchPage page, boolean showSearchControls) {
        return buildSearchView(page, showSearchControls, null);
    }

    private View buildSearchView(SearchPage page, boolean showSearchControls, CuspTab tab) {
        ScrollView scroll = new ScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.setOnScrollChangeListener((v, scrollX, scrollY, oldScrollX, oldScrollY) ->
                handleContentScrollForChrome(scrollY, oldScrollY));
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setPadding(dp(12), dp(12), dp(12), dp(24));
        scroll.addView(list, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        if (showSearchControls) {
            EditText query = new EditText(this);
            query.setSingleLine(true);
            query.setText(searchQueryFromUrl(page.url));
            query.setHint(text("\u691c\u7d22\u8a9e", "Search query"));
            query.setTextColor(textColor());
            query.setHintTextColor(mutedColor());
            query.setTextSize(18);
            query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);
            query.setInputType(android.text.InputType.TYPE_CLASS_TEXT);
            query.setBackground(addressBarBackground());
            query.setPadding(dp(12), 0, dp(12), 0);
            query.setOnEditorActionListener((v, actionId, event) -> {
                boolean enter = event != null && event.getAction() == KeyEvent.ACTION_UP
                        && event.getKeyCode() == KeyEvent.KEYCODE_ENTER;
                if (actionId == EditorInfo.IME_ACTION_SEARCH || enter) {
                    String value = query.getText().toString().trim();
                    if (!value.isEmpty()) {
                        try {
                            InputMethodManager manager = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
                            manager.hideSoftInputFromWindow(query.getWindowToken(), 0);
                        } catch (Exception ignored) {
                        }
                        openInCurrentTab(isFullTextSearchUrl(page.url) ? fullTextSearchUrl(value) : searchUrl(value));
                    }
                    return true;
                }
                return false;
            });
            LinearLayout.LayoutParams queryParams = new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(48));
            queryParams.setMargins(0, 0, 0, dp(8));
            list.addView(query, queryParams);

            TextView switchSearch = actionRow(isFullTextSearchUrl(page.url)
                    ? text("\u30b9\u30ec\u30bf\u30a4\u691c\u7d22", "Thread-title search")
                    : text("\u5168\u6587\u691c\u7d22", "Full-text search"));
            switchSearch.setOnClickListener(v -> {
                String value = query.getText().toString().trim();
                if (value.isEmpty()) {
                    return;
                }
                try {
                    InputMethodManager manager = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
                    manager.hideSoftInputFromWindow(query.getWindowToken(), 0);
                } catch (Exception ignored) {
                }
                openInCurrentTab(isFullTextSearchUrl(page.url) ? searchUrl(value) : fullTextSearchUrl(value));
            });
            LinearLayout.LayoutParams switchParams = new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
            switchParams.setMargins(0, 0, 0, dp(10));
            list.addView(switchSearch, switchParams);
        }

        if (page.error != null) {
            TextView error = postText(page.error, null);
            error.setTextColor(Color.rgb(185, 28, 28));
            list.addView(error);
            View wrapped = withScrollScrubber(scroll, tab);
            return tab == null ? wrapped : withTopPullRefresh(wrapped, scroll, tab, () -> refreshTabFromTop(tab));
        }

        renderSearchSlots(scroll, list, page);

        if (page.results.isEmpty()) {
            list.addView(postText(text("\u691c\u7d22\u7d50\u679c\u306a\u3057", "No search results."), null));
        }
        boolean fullTextSearch = isFullTextSearchUrl(page.url);
        if (fullTextSearch) {
            if (!page.results.isEmpty() && (page.fullTextHasMore || !page.fullTextReachedEnd)) {
                list.addView(fullTextLoadMoreFooter(page, scroll), new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
            }
        }
        View wrapped = withScrollScrubber(scroll, tab);
        if (tab != null) {
            return withTopPullRefresh(wrapped, scroll, tab, () -> refreshTabFromTop(tab),
                    fullTextSearch ? page : null);
        }
        if (fullTextSearch) {
            attachFullTextLoadMoreSwipe(scroll, page);
        }
        return wrapped;
    }

    private boolean shouldEnableBoardTopRefresh(SearchPage page, boolean showSearchControls, CuspTab tab) {
        return tab != null
                && !showSearchControls
                && NATIVE_BOARD.equals(tab.nativeKind)
                && page != null
                && page.error == null
                && page.url != null
                && isBoardUrl(page.url);
    }

    private View withTopPullRefresh(View content, ScrollView scroll, CuspTab tab, Runnable refresh) {
        return withTopPullRefresh(content, scroll, tab, refresh, null);
    }

    private View withTopPullRefresh(View content, ScrollView scroll, CuspTab tab, Runnable refresh,
                                    SearchPage fullTextLoadMorePage) {
        if (content == null || scroll == null || Boolean.TRUE.equals(content.getTag(R.id.tag_top_pull_refresh))) {
            return content;
        }
        if (tab != null) {
            scroll.setTag(R.id.tag_scroll_tab, tab);
        }
        FrameLayout frame = new FrameLayout(this);
        frame.setTag(R.id.tag_top_pull_refresh, true);
        frame.setBackgroundColor(bgColor());
        frame.addView(content, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        FrameLayout loader = bottomRefreshLoader();
        loader.setVisibility(View.GONE);
        loader.setTranslationY(-dp(58));
        if (tab != null) {
            tab.boardTopLoader = loader;
        }
        FrameLayout.LayoutParams loaderParams = new FrameLayout.LayoutParams(dp(66), dp(66),
                Gravity.TOP | Gravity.CENTER_HORIZONTAL);
        loaderParams.setMargins(0, dp(2), 0, 0);
        frame.addView(loader, loaderParams);
        Runnable refreshAction = refresh == null ? () -> resetTopRefreshLoader(loader) : refresh;
        if (fullTextLoadMorePage != null && isFullTextSearchUrl(fullTextLoadMorePage.url)) {
            enableSearchPullRefresh(scroll, loader, refreshAction, fullTextLoadMorePage);
        } else {
            enableTopPullRefresh(scroll, loader, refreshAction);
        }
        return frame;
    }

    private View withTopPullRefreshIfPossible(View content, CuspTab tab) {
        if (tab == null || content == null || Boolean.TRUE.equals(content.getTag(R.id.tag_top_pull_refresh))) {
            return content;
        }
        ScrollView scroll = findScrollView(content);
        if (scroll == null) {
            return content;
        }
        return withTopPullRefresh(content, scroll, tab, () -> refreshTabFromTop(tab));
    }

    private void maybeLoadMoreFullTextResults(SearchPage page, ScrollView scroll) {
        if (page == null || scroll == null || !isFullTextSearchUrl(page.url)
                || page.fullTextReachedEnd || page.fullTextLoadingMore) {
            return;
        }
        CuspTab tab = currentTab();
        if (tab == null || tab.searchPage != page || !page.url.equals(tab.url)) {
            return;
        }
        page.fullTextLoadingMore = true;
        updateFullTextLoadMoreFooter(scroll, page);
        progressBar.setVisibility(View.VISIBLE);
        loadFullTextSearchResultsPage(tab, page.url, Math.max(2, page.fullTextPage + 1), true);
    }

    private void attachFullTextLoadMoreSwipe(ScrollView scroll, SearchPage page) {
        final float[] downY = new float[1];
        final boolean[] armed = new boolean[1];
        scroll.setOnTouchListener((v, event) -> {
            if (event.getAction() == MotionEvent.ACTION_DOWN) {
                downY[0] = event.getY();
                armed[0] = isScrollAtBottom(scroll);
            } else if (event.getAction() == MotionEvent.ACTION_MOVE) {
                if (armed[0] && downY[0] - event.getY() > dp(54)) {
                    armed[0] = false;
                    maybeLoadMoreFullTextResults(page, scroll);
                }
            } else if (event.getAction() == MotionEvent.ACTION_UP || event.getAction() == MotionEvent.ACTION_CANCEL) {
                armed[0] = false;
            }
            return false;
        });
    }

    private void enableSearchPullRefresh(ScrollView scroll, View loader, Runnable refresh,
                                         SearchPage fullTextLoadMorePage) {
        final float[] downY = new float[1];
        final float[] pullDistance = new float[1];
        final boolean[] startedAtTop = new boolean[1];
        final boolean[] draggingTop = new boolean[1];
        final boolean[] refreshingTop = new boolean[1];
        final boolean[] loadMoreArmed = new boolean[1];
        final boolean[] ignoreUntilUp = new boolean[1];
        scroll.setOnTouchListener((v, event) -> {
            int hiddenOffset = -dp(58);
            int maxOffset = dp(86);
            int maxPull = dp(164);
            int triggerPull = maxPull / 2;
            int triggerOffset = hiddenOffset + (maxOffset - hiddenOffset) / 2;
            if (event.getAction() == MotionEvent.ACTION_DOWN) {
                ignoreUntilUp[0] = false;
                downY[0] = event.getY();
                pullDistance[0] = 0;
                startedAtTop[0] = !scroll.canScrollVertically(-1);
                draggingTop[0] = false;
                loadMoreArmed[0] = isScrollAtBottom(scroll);
                if (refreshingTop[0] && loader.getVisibility() != View.GONE) {
                    ignoreUntilUp[0] = true;
                    return false;
                }
                if (!refreshingTop[0]) {
                    resetTopRefreshLoader(loader);
                }
            }
            if (ignoreUntilUp[0]) {
                if (event.getAction() == MotionEvent.ACTION_UP
                        || event.getAction() == MotionEvent.ACTION_CANCEL) {
                    ignoreUntilUp[0] = false;
                }
                return false;
            }
            if (refreshingTop[0]) {
                if (loader.getVisibility() == View.GONE) {
                    refreshingTop[0] = false;
                } else {
                    return false;
                }
            }
            if (event.getAction() == MotionEvent.ACTION_MOVE) {
                if (!draggingTop[0] && loadMoreArmed[0] && downY[0] - event.getY() > dp(54)) {
                    loadMoreArmed[0] = false;
                    maybeLoadMoreFullTextResults(fullTextLoadMorePage, scroll);
                }
                if (!startedAtTop[0] && !draggingTop[0] && !refreshingTop[0]
                        && !scroll.canScrollVertically(-1)) {
                    startedAtTop[0] = true;
                    downY[0] = event.getY();
                    pullDistance[0] = 0;
                }
                if (!startedAtTop[0] || refreshingTop[0]) {
                    return false;
                }
                if (scroll.canScrollVertically(-1)) {
                    draggingTop[0] = false;
                    pullDistance[0] = 0;
                    resetTopRefreshLoader(loader);
                    return false;
                }
                float pull = Math.max(0, event.getY() - downY[0]);
                pullDistance[0] = pull;
                if (pull <= dp(4) && loader.getVisibility() == View.VISIBLE) {
                    startedAtTop[0] = false;
                    draggingTop[0] = false;
                    pullDistance[0] = 0;
                    animateTopRefreshLoaderClosed(loader);
                    return false;
                }
                if (pull > dp(4)) {
                    draggingTop[0] = true;
                    loadMoreArmed[0] = false;
                    loader.animate().cancel();
                    loader.clearAnimation();
                    loader.setVisibility(View.VISIBLE);
                    float progress = Math.min(pull, maxPull) / maxPull;
                    setBottomRefreshSpinning(loader, false);
                    loader.setTranslationY(hiddenOffset + (maxOffset - hiddenOffset) * progress);
                    loader.setRotation(progress * 270f);
                    return false;
                }
                if (draggingTop[0]) {
                    loader.setTranslationY(hiddenOffset);
                    loader.setRotation(0f);
                    return false;
                }
            } else if (event.getAction() == MotionEvent.ACTION_UP
                    || event.getAction() == MotionEvent.ACTION_CANCEL) {
                loadMoreArmed[0] = false;
                if (draggingTop[0] && event.getAction() == MotionEvent.ACTION_UP
                        && pullDistance[0] >= triggerPull) {
                    refreshingTop[0] = true;
                    draggingTop[0] = false;
                    pullDistance[0] = 0;
                    loader.setVisibility(View.VISIBLE);
                    loader.setRotation(0f);
                    setBottomRefreshSpinning(loader, true);
                    loader.animate().cancel();
                    loader.clearAnimation();
                    loader.animate().translationY(triggerOffset).setDuration(110)
                            .withEndAction(refresh).start();
                    return false;
                }
                if (draggingTop[0] || loader.getVisibility() == View.VISIBLE) {
                    startedAtTop[0] = false;
                    draggingTop[0] = false;
                    pullDistance[0] = 0;
                    resetTopRefreshLoader(loader);
                    return false;
                }
            }
            return false;
        });
    }

    private boolean isPostSwipeText(View view) {
        return view instanceof TextView && Boolean.TRUE.equals(view.getTag(R.id.tag_post_swipe_text));
    }

    private boolean isScrollAtBottom(ScrollView scroll) {
        if (scroll == null || scroll.getChildCount() == 0) {
            return false;
        }
        int range = scroll.getChildAt(0).getHeight() - scroll.getHeight();
        return range <= 0 || scroll.getScrollY() >= range - dp(4);
    }

    private View fullTextLoadMoreFooter(SearchPage page, ScrollView scroll) {
        LinearLayout footer = new LinearLayout(this);
        footer.setTag(FULL_TEXT_LOAD_MORE_FOOTER_TAG);
        footer.setGravity(Gravity.CENTER);
        footer.setOrientation(LinearLayout.VERTICAL);
        footer.setPadding(0, dp(10), 0, dp(10));
        footer.setBackground(roundedDrawable(postColor(), borderColor(), dp(8)));
        updateFullTextLoadMoreFooterContent(footer, page, scroll);
        return footer;
    }

    private void updateFullTextLoadMoreFooter(ScrollView scroll, SearchPage page) {
        LinearLayout footer = findFullTextLoadMoreFooter(scroll);
        if (footer != null) {
            updateFullTextLoadMoreFooterContent(footer, page, scroll);
        }
    }

    private LinearLayout findFullTextLoadMoreFooter(ScrollView scroll) {
        if (scroll == null || scroll.getChildCount() == 0 || !(scroll.getChildAt(0) instanceof ViewGroup)) {
            return null;
        }
        ViewGroup group = (ViewGroup) scroll.getChildAt(0);
        for (int i = 0; i < group.getChildCount(); i++) {
            View child = group.getChildAt(i);
            if (child instanceof LinearLayout && FULL_TEXT_LOAD_MORE_FOOTER_TAG.equals(child.getTag())) {
                return (LinearLayout) child;
            }
        }
        return null;
    }

    private void updateFullTextLoadMoreFooterContent(LinearLayout footer, SearchPage page, ScrollView scroll) {
        footer.removeAllViews();
        footer.setOnClickListener(null);
        if (page.fullTextLoadingMore) {
            ProgressBar spinner = new ProgressBar(this);
            spinner.setIndeterminate(true);
            footer.addView(spinner, new LinearLayout.LayoutParams(dp(34), dp(34)));
            return;
        }
        TextView label = new TextView(this);
        label.setText(text("\u3055\u3089\u306b\u8aad\u307f\u8fbc\u3080", "Load more"));
        label.setTextColor(TEAL);
        label.setTextSize(15);
        label.setTypeface(Typeface.DEFAULT_BOLD);
        label.setGravity(Gravity.CENTER);
        footer.addView(label, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        footer.setOnClickListener(v -> maybeLoadMoreFullTextResults(page, scroll));
    }

    private void renderSearchSlots(ScrollView scroll, LinearLayout list, SearchPage page) {
        List<VirtualSearchSlot> slots = new ArrayList<>();
        String renderedCategory = null;
        int count = 0;
        for (SearchResult result : page.results) {
            if (shouldHideNgThreadTitle(result.title)) {
                continue;
            }
            if (result.category != null && !result.category.trim().isEmpty()
                    && !result.category.equals(renderedCategory)) {
                renderedCategory = result.category;
                slots.add(new VirtualSearchSlot(renderedCategory, null, true));
            }
            slots.add(new VirtualSearchSlot(null, result, false));
            count++;
        }
        if (count > 0) {
            boolean customBoard = page != null && page.url != null
                    && isBoardUrl(page.url) && !is5chUrl(page.url)
                    && (isRegisteredBbsUrl(page.url) || isKnownCustomBbsUrl(page.url));
            renderVirtualSearchSlots(scroll, list, slots, true, customBoard);
        }
    }

    private void renderVirtualSearchSlots(ScrollView scroll, LinearLayout list, List<VirtualSearchSlot> slots,
                                          boolean deferSlots) {
        renderVirtualSearchSlots(scroll, list, slots, deferSlots, false);
    }

    private void renderVirtualSearchSlots(ScrollView scroll, LinearLayout list, List<VirtualSearchSlot> slots,
                                          boolean deferSlots, boolean incrementalCustomBoard) {
        VirtualSearchState state = new VirtualSearchState();
        list.setTag(state);
        if (slots == null || slots.isEmpty()) {
            return;
        }
        int initialBatch = incrementalCustomBoard
                ? CUSTOM_BOARD_INITIAL_SLOT_BATCH : SEARCH_INITIAL_SLOT_BATCH;
        int deferredBatch = incrementalCustomBoard
                ? CUSTOM_BOARD_DEFERRED_SLOT_BATCH : SEARCH_DEFERRED_SLOT_BATCH;
        long deferredDelay = incrementalCustomBoard
                ? CUSTOM_BOARD_DEFERRED_SLOT_DELAY_MS : SEARCH_DEFERRED_SLOT_DELAY_MS;
        int initialCount = deferSlots
                ? Math.min(slots.size(), initialBatch)
                : slots.size();
        appendVirtualSearchSlots(list, slots, 0, initialCount);
        ensureSearchSlotRefresh(scroll, list);
        scheduleSearchSlotRefresh(list);
        if (initialCount < slots.size()) {
            list.post(() -> appendDeferredVirtualSearchSlots(
                    scroll, list, slots, state, initialCount, deferredBatch, deferredDelay));
        }
    }

    private void appendDeferredVirtualSearchSlots(ScrollView scroll, LinearLayout list,
                                                  List<VirtualSearchSlot> slots,
                                                  VirtualSearchState state, int start,
                                                  int batchSize, long delayMs) {
        if (list == null || slots == null || list.getTag() != state) {
            return;
        }
        int end = Math.min(slots.size(), start + Math.max(1, batchSize));
        appendVirtualSearchSlots(list, slots, start, end);
        scheduleSearchSlotRefresh(list);
        if (end < slots.size()) {
            list.postDelayed(() -> appendDeferredVirtualSearchSlots(
                    scroll, list, slots, state, end, batchSize, delayMs), Math.max(0L, delayMs));
        }
    }

    private void appendVirtualSearchSlots(LinearLayout list, List<VirtualSearchSlot> slots, int start, int end) {
        if (list == null || slots == null) {
            return;
        }
        for (int i = Math.max(0, start); i < end && i < slots.size(); i++) {
            addVirtualSearchSlot(list, slots.get(i));
        }
    }

    private void ensureSearchSlotRefresh(ScrollView scroll, LinearLayout list) {
        if (scroll == null || list == null || !(list.getTag() instanceof VirtualSearchState)) {
            return;
        }
        VirtualSearchState state = (VirtualSearchState) list.getTag();
        if (state.refreshTask != null) {
            return;
        }
        state.refreshTask = () -> {
            state.refreshPending = false;
            refreshSearchSlots(scroll, list);
        };
        scroll.getViewTreeObserver().addOnScrollChangedListener(() -> {
            if (list.getTag() instanceof VirtualSearchState) {
                ((VirtualSearchState) list.getTag()).lastScrollAt = android.os.SystemClock.uptimeMillis();
            }
            scheduleSearchSlotRefresh(list);
        });
    }

    private void scheduleSearchSlotRefresh(LinearLayout list) {
        if (list == null || !(list.getTag() instanceof VirtualSearchState)) {
            return;
        }
        VirtualSearchState state = (VirtualSearchState) list.getTag();
        if (state.refreshTask == null || state.refreshPending) {
            return;
        }
        state.refreshPending = true;
        list.post(state.refreshTask);
    }

    private void addVirtualSearchSlot(LinearLayout list, VirtualSearchSlot slot) {
        FrameLayout holder = new FrameLayout(this);
        holder.setTag(slot);
        holder.addView(searchSlotSpacer(slot.height), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, slot.height));
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        if (slot.categoryHeader) {
            params.setMargins(0, dp(8), 0, dp(8));
        } else {
            params.setMargins(0, 0, 0, dp(8));
        }
        int footerIndex = fullTextLoadMoreFooterIndex(list);
        if (footerIndex >= 0) {
            list.addView(holder, footerIndex, params);
        } else {
            list.addView(holder, params);
        }
    }

    private int fullTextLoadMoreFooterIndex(LinearLayout list) {
        if (list == null) {
            return -1;
        }
        int last = list.getChildCount() - 1;
        if (last < 0) {
            return -1;
        }
        View child = list.getChildAt(last);
        return child instanceof LinearLayout && FULL_TEXT_LOAD_MORE_FOOTER_TAG.equals(child.getTag()) ? last : -1;
    }

    private void refreshSearchSlots(ScrollView scroll, LinearLayout list) {
        if (scroll == null || list == null) {
            return;
        }
        int scrollY = scroll.getScrollY();
        int height = scroll.getHeight();
        if (height <= 0) {
            return;
        }
        VirtualSearchState state = list.getTag() instanceof VirtualSearchState
                ? (VirtualSearchState) list.getTag() : null;
        boolean scrolling = state != null
                && android.os.SystemClock.uptimeMillis() - state.lastScrollAt < 180;
        int keepTop = Math.max(0, scrollY - (scrolling ? height * 3 : height * 2));
        int keepBottom = scrollY + (scrolling ? height * 7 : height * 5);
        int top = Math.max(0, scrollY - (scrolling ? height : height * 2));
        int bottom = scrollY + (scrolling ? height * 5 : height * 4);
        int visibleStart = firstChildWithBottomAtLeast(list, scrollY);
        int visibleEnd = lastChildWithTopAtMost(list, scrollY + height);
        int start = firstChildWithBottomAtLeast(list, top);
        int end = lastChildWithTopAtMost(list, bottom);
        int keepStart = firstChildWithBottomAtLeast(list, keepTop);
        int keepEnd = lastChildWithTopAtMost(list, keepBottom);
        Set<FrameLayout> keep = new LinkedHashSet<>();
        collectSearchSlotsInRange(list, keepStart, keepEnd, keep);
        int[] rendered = {0};
        boolean[] budgetReached = {false};
        renderSearchSlotsInRange(scroll, list, visibleStart, visibleEnd, SEARCH_VISIBLE_RENDER_BUDGET,
                rendered, budgetReached, keep);
        int budget = scrolling ? SEARCH_SCROLL_RENDER_BUDGET : SEARCH_IDLE_RENDER_BUDGET;
        renderSearchSlotsInRange(scroll, list, start, end, budget, rendered, budgetReached, keep);
        if (budgetReached[0]) {
            scheduleSearchSlotRefresh(list);
        }
        if (!scrolling && state != null && !state.renderedSlots.isEmpty()) {
            for (FrameLayout holder : new ArrayList<>(state.renderedSlots)) {
                if (keep.contains(holder)) {
                    continue;
                }
                Object tag = holder.getTag();
                if (tag instanceof VirtualSearchSlot) {
                    recycleSearchSlot(holder, (VirtualSearchSlot) tag);
                }
            }
        }
    }

    private void collectSearchSlotsInRange(ViewGroup list, int start, int end, Set<FrameLayout> keep) {
        if (list == null || keep == null || start > end || end < 0) {
            return;
        }
        int childCount = list.getChildCount();
        for (int i = Math.max(0, start); i <= end && i < childCount; i++) {
            View child = list.getChildAt(i);
            Object tag = child.getTag();
            if (child instanceof FrameLayout && tag instanceof VirtualSearchSlot) {
                keep.add((FrameLayout) child);
            }
        }
    }

    private void renderSearchSlotsInRange(ScrollView scroll, ViewGroup list, int start, int end, int budget,
                                          int[] rendered, boolean[] budgetReached, Set<FrameLayout> keep) {
        if (list == null || start > end || end < 0) {
            return;
        }
        int childCount = list.getChildCount();
        for (int i = Math.max(0, start); i <= end && i < childCount; i++) {
            View child = list.getChildAt(i);
            Object tag = child.getTag();
            if (!(child instanceof FrameLayout) || !(tag instanceof VirtualSearchSlot)) {
                continue;
            }
            FrameLayout holder = (FrameLayout) child;
            if (keep != null) {
                keep.add(holder);
            }
            VirtualSearchSlot slot = (VirtualSearchSlot) tag;
            if (slot.rendered) {
                continue;
            }
            if (scroll != null && holder.getBottom() <= scroll.getScrollY()) {
                continue;
            }
            if (rendered[0] >= budget) {
                budgetReached[0] = true;
                return;
            }
            renderSearchSlot(holder, slot);
            rendered[0]++;
        }
    }

    private void renderSearchSlot(FrameLayout holder, VirtualSearchSlot slot) {
        if (holder == null || slot == null || slot.rendered) {
            return;
        }
        View view = slot.bbsCategoryRow != null
                ? bbsCategoryRow(slot.bbsCategoryRow)
                : slot.categoryHeader ? categoryHeader(slot.category) : searchResultRow(slot.result);
        holder.removeAllViews();
        holder.addView(view, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        slot.rendered = true;
        if (holder.getParent() instanceof View) {
            View parent = (View) holder.getParent();
            if (parent instanceof LinearLayout && parent.getTag() instanceof VirtualSearchState) {
                ((VirtualSearchState) parent.getTag()).renderedSlots.add(holder);
            }
        }
    }

    private void recycleSearchSlot(FrameLayout holder, VirtualSearchSlot slot) {
        if (holder == null || slot == null || !slot.rendered) {
            return;
        }
        int measured = holder.getHeight();
        if (measured > 0) {
            slot.height = Math.max(slot.height, measured);
        }
        holder.removeAllViews();
        holder.addView(searchSlotSpacer(slot.height), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, slot.height));
        slot.rendered = false;
        if (holder.getParent() instanceof View) {
            View parent = (View) holder.getParent();
            if (parent instanceof LinearLayout && parent.getTag() instanceof VirtualSearchState) {
                ((VirtualSearchState) parent.getTag()).renderedSlots.remove(holder);
            }
        }
    }

    private View searchSlotSpacer(int height) {
        View spacer = new View(this);
        spacer.setMinimumHeight(Math.max(dp(44), height));
        return spacer;
    }

    private int estimateSearchResultHeight(SearchResult result) {
        String title = result == null || result.title == null ? "" : result.title;
        String meta = result == null || result.meta == null ? "" : result.meta;
        int titleLines = Math.max(1, title.length() / 24 + 1);
        int metaLines = meta.isEmpty() ? 0 : Math.max(1, meta.length() / 42 + 1);
        return dp(26 + Math.min(3, titleLines) * 20 + Math.min(2, metaLines) * 16);
    }

    private int firstChildWithBottomAtLeast(ViewGroup group, int y) {
        int low = 0;
        int high = group == null ? -1 : group.getChildCount() - 1;
        int answer = high + 1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            View child = group.getChildAt(mid);
            if (child.getBottom() >= y) {
                answer = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return Math.max(0, answer);
    }

    private int lastChildWithTopAtMost(ViewGroup group, int y) {
        int low = 0;
        int high = group == null ? -1 : group.getChildCount() - 1;
        int answer = -1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            View child = group.getChildAt(mid);
            if (child.getTop() <= y) {
                answer = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return answer;
    }

    private View searchResultRow(SearchResult result) {
        return searchResultRow(result, null);
    }

    private View searchResultRow(SearchResult result, Runnable beforeOpen) {
        LinearLayout shell = new LinearLayout(this);
        shell.setOrientation(LinearLayout.HORIZONTAL);
        shell.setGravity(Gravity.CENTER_VERTICAL);
        shell.setBackgroundColor(postColor());
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.VERTICAL);
        row.setPadding(dp(10), dp(9), dp(10), dp(9));
        row.setOnClickListener(v -> {
            if (beforeOpen != null) {
                beforeOpen.run();
            }
            routeSearchResult(result);
        });

        TextView resultTitle = new TextView(this);
        resultTitle.setText(styledResultTitle(result));
        resultTitle.setTextColor(textColor());
        resultTitle.setTextSize(16);
        resultTitle.setPadding(0, 0, 0, dp(4));
        row.addView(resultTitle);

        if (result != null && result.boardName != null && !result.boardName.isEmpty()) {
            row.addView(boardThreadMetaView(result, false));
        } else {
            TextView meta = new TextView(this);
            meta.setText(styledResultMeta(result == null ? "" : result.meta));
            meta.setTextColor(mutedColor());
            meta.setTextSize(12);
            row.addView(meta);
        }
        shell.addView(row, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        ImageButton save = saveToggleButtonForResult(result);
        if (save != null) {
            shell.addView(save, new LinearLayout.LayoutParams(dp(44), dp(44)));
        }
        return shell;
    }

    private View boardThreadMetaView(SearchResult result) {
        return boardThreadMetaView(result, false);
    }

    private View boardThreadMetaView(SearchResult result, boolean tabOverview) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.BOTTOM | Gravity.END);
        row.setPadding(0, dp(1), 0, 0);

        boolean showBoardName = showMetaField(PREF_BOARD_SHOW_BOARD_NAME, PREF_TAB_SHOW_BOARD_NAME, tabOverview);
        boolean showCreated = showMetaField(PREF_BOARD_SHOW_CREATED, PREF_TAB_SHOW_CREATED, tabOverview);
        if (showBoardName || showCreated) {
            row.addView(boardThreadLeftMetaItem(
                            showBoardName ? result.boardName : "",
                            showCreated ? boardCreatedText(result.createdAt) : ""),
                    new LinearLayout.LayoutParams(0, dp(30), 1));
        } else {
            View spacer = new View(this);
            row.addView(spacer, new LinearLayout.LayoutParams(0, dp(30), 1));
        }
        int unread = result.hasReadHistory ? Math.max(0, result.unread) : -1;
        if (showMetaField(PREF_BOARD_SHOW_UNREAD, PREF_TAB_SHOW_UNREAD, tabOverview) && unread > 0) {
            row.addView(boardThreadUnreadMetaItem(unread), boardThreadMetaItemParams(dp(30)));
        }
        if (showMetaField(PREF_BOARD_SHOW_ORDER, PREF_TAB_SHOW_ORDER, tabOverview)) {
            row.addView(boardThreadMetaItem(text("\u9806\u4f4d", "Rank"),
                    result.boardOrder > 0 ? String.valueOf(result.boardOrder) : "-", Gravity.END,
                    metaRankBlue(result.boardOrder), true),
                    boardThreadMetaItemParams(dp(31)));
        }
        if (showMetaField(PREF_BOARD_SHOW_VELOCITY, PREF_TAB_SHOW_VELOCITY, tabOverview)) {
            row.addView(boardThreadMetaItem(text("\u52e2\u3044", "Speed"),
                    result.velocity > 0 ? String.format(Locale.ROOT, "%.1f", result.velocity) : "-", Gravity.END,
                    metaBlue(Math.max(0d, result.velocity), true), true),
                    boardThreadMetaItemParams(dp(42)));
        }
        if (showMetaField(PREF_BOARD_SHOW_RESPONSES, PREF_TAB_SHOW_RESPONSES, tabOverview)) {
            row.addView(boardThreadMetaItem(text("\u30ec\u30b9", "Posts"),
                    result.responses > 0 ? String.valueOf(result.responses) : "-", Gravity.END,
                    metaBlue(Math.max(0, result.responses), false), true),
                    boardThreadMetaItemParams(dp(36)));
        }
        return row;
    }

    private boolean showMetaField(String boardPref, String tabPref, boolean tabOverview) {
        String key = tabOverview ? tabPref : boardPref;
        return preferences.getBoolean(key, defaultMetaFieldVisible(key));
    }

    private boolean defaultMetaFieldVisible(String key) {
        if (PREF_BOARD_SHOW_BOARD_NAME.equals(key)) {
            return false;
        }
        if (PREF_TAB_SHOW_ORDER.equals(key) || PREF_TAB_SHOW_CREATED.equals(key)) {
            return false;
        }
        return true;
    }

    private LinearLayout.LayoutParams boardThreadMetaItemParams(int width) {
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                width, dp(30));
        params.setMargins(dp(1), 0, 0, 0);
        return params;
    }

    private View boardThreadLeftMetaItem(String boardName, String createdText) {
        LinearLayout column = new LinearLayout(this);
        column.setOrientation(LinearLayout.VERTICAL);
        column.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
        boolean hasBoard = boardName != null && !boardName.trim().isEmpty();
        boolean hasCreated = createdText != null && !createdText.trim().isEmpty();
        if (hasBoard && hasCreated) {
            column.addView(leftMetaText(boardName, mutedColor(), 12), new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(15)));
            column.addView(leftMetaText(createdText, mutedColor(), 11), new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(15)));
        } else {
            String value = hasBoard ? boardName : createdText;
            int color = mutedColor();
            column.addView(leftMetaText(value, color, 12), new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(30)));
        }
        return column;
    }

