    private View buildBbsCategoryIndexView(SearchPage page, CuspTab tab) {
        ScrollView scroll = new ScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setPadding(dp(12), dp(12), dp(12), dp(24));
        scroll.addView(list, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        TextView title = new TextView(this);
        title.setText(page.title);
        title.setTextColor(textColor());
        title.setTextSize(20);
        title.setPadding(0, 0, 0, dp(10));
        list.addView(title);

        if (page.error != null) {
            TextView error = postText(page.error, null);
            error.setTextColor(Color.rgb(185, 28, 28));
            list.addView(error);
            View wrapped = withScrollScrubber(scroll, tab);
            return tab == null ? wrapped : withTopPullRefresh(wrapped, scroll, tab, () -> refreshTabFromTop(tab));
        }

        Map<String, Integer> counts = bbsCategoryCounts(page);
        List<VirtualSearchSlot> slots = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : counts.entrySet()) {
            String category = entry.getKey();
            String label = category.isEmpty() ? text("\u305d\u306e\u4ed6", "Other") : category;
            slots.add(new VirtualSearchSlot(new BbsCategoryRow(page.url, category, label, entry.getValue())));
        }
        renderVirtualSearchSlots(scroll, list, slots, true);
        View wrapped = withScrollScrubber(scroll, tab);
        return tab == null ? wrapped : withTopPullRefresh(wrapped, scroll, tab, () -> refreshTabFromTop(tab));
    }

    private Map<String, Integer> bbsCategoryCounts(SearchPage page) {
        if (page == null) {
            return new LinkedHashMap<>();
        }
        if (page.categoryCounts != null) {
            return page.categoryCounts;
        }
        Map<String, Integer> counts = new LinkedHashMap<>();
        for (SearchResult result : page.results) {
            String category = result.category == null ? "" : result.category.trim();
            counts.put(category, counts.containsKey(category) ? counts.get(category) + 1 : 1);
        }
        page.categoryCounts = counts;
        return counts;
    }

