    private View buildFullTextSearchHomeView(boolean forTab) {
        FrameLayout root = new FrameLayout(this);
        root.setBackgroundColor(bgColor());
        ScrollView scroll = new ScrollView(this);
        scroll.setBackgroundColor(bgColor());
        scroll.setVerticalScrollBarEnabled(false);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setPadding(dp(12), dp(12), dp(12), dp(24));
        scroll.addView(list, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        TextView title = sectionTitleView(text("\u5168\u6587\u691c\u7d22", "Full-text Search"));
        list.addView(title);

        TextView caption = postText("search2ch.info", null);
        caption.setTextColor(mutedColor());
        caption.setTextSize(13);
        LinearLayout.LayoutParams captionParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        captionParams.setMargins(0, 0, 0, dp(10));
        list.addView(caption, captionParams);

        EditText query = new EditText(this);
        query.setSingleLine(true);
        query.setHint(text("\u5168\u6587\u691c\u7d22\u8a9e", "Full-text search query"));
        query.setTextColor(textColor());
        query.setHintTextColor(mutedColor());
        query.setTextSize(18);
        query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);
        query.setInputType(android.text.InputType.TYPE_CLASS_TEXT);
        query.setBackground(addressBarBackground());
        query.setPadding(dp(12), 0, dp(12), 0);
        Runnable submit = () -> {
            String value = query.getText().toString().trim();
            if (value.isEmpty()) {
                return;
            }
            try {
                InputMethodManager manager = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
                manager.hideSoftInputFromWindow(query.getWindowToken(), 0);
            } catch (Exception ignored) {
            }
            openFullTextSearch(value);
        };
        query.setOnEditorActionListener((v, actionId, event) -> {
            boolean enter = event != null && event.getAction() == KeyEvent.ACTION_UP
                    && event.getKeyCode() == KeyEvent.KEYCODE_ENTER;
            if (actionId == EditorInfo.IME_ACTION_SEARCH || enter) {
                submit.run();
                return true;
            }
            return false;
        });
        LinearLayout.LayoutParams queryParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(48));
        queryParams.setMargins(0, 0, 0, dp(8));
        list.addView(query, queryParams);

        TextView titleSearch = actionRow(text("\u30b9\u30ec\u30bf\u30a4\u691c\u7d22", "Thread-title search"));
        titleSearch.setOnClickListener(v -> {
            String value = query.getText().toString().trim();
            if (value.isEmpty()) {
                return;
            }
            try {
                InputMethodManager manager = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
                manager.hideSoftInputFromWindow(query.getWindowToken(), 0);
            } catch (Exception ignored) {
            }
            openInCurrentTab(searchUrl(value));
        });
        list.addView(titleSearch);

        root.addView(scroll, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        addPrivateModeOverlay(root, currentTabIsPrivate(), v -> togglePendingPrivateNewTab());
        query.postDelayed(() -> {
            if (!forTab && pendingNewTab || forTab) {
                query.requestFocus();
                InputMethodManager manager = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
                if (manager != null) {
                    manager.showSoftInput(query, InputMethodManager.SHOW_IMPLICIT);
                }
            }
        }, 120);
        return root;
    }

    private void updateScrollThumb(ScrollView scroll, View scrubber, View thumb) {
        if (scroll == null || scrubber == null || thumb == null) {
            return;
        }
        int range = scroll.getChildCount() == 0 ? 0 : scroll.getChildAt(0).getHeight() - scroll.getHeight();
        FrameLayout.LayoutParams params = (FrameLayout.LayoutParams) thumb.getLayoutParams();
        if (range <= 0) {
            thumb.setVisibility(View.GONE);
            return;
        }
        thumb.setVisibility(View.VISIBLE);
        int frameHeight = Math.max(1, scrubber.getHeight());
        int thumbHeight = Math.max(dp(42), frameHeight * scroll.getHeight() / Math.max(scroll.getChildAt(0).getHeight(), 1));
        int maxTop = Math.max(0, frameHeight - thumbHeight);
        int top = maxTop * scroll.getScrollY() / range;
        if (params.height != thumbHeight || params.topMargin != top) {
            params.height = thumbHeight;
            params.topMargin = top;
            thumb.setLayoutParams(params);
        }
    }

    private void refreshThreadScrollChrome(CuspTab tab) {
        if (tab == null || tab.threadScroll == null || tab.scrollScrubber == null) {
            return;
        }
        View thumb = tab.scrollScrubber.getChildCount() >= 3 ? tab.scrollScrubber.getChildAt(2) : null;
        tab.scrollScrubber.post(() -> {
            tab.scrollScrubber.setAlpha(1f);
            updateScrollThumb(tab.threadScroll, tab.scrollScrubber, thumb);
            if (tab.threadRendering) {
                if (tab.unreadMarkerLayer != null) {
                    tab.unreadMarkerLayer.removeAllViews();
                }
                return;
            }
            if (recentlyScrolled(tab)) {
                return;
            }
            updateUnreadScrollMarkers(tab);
        });
    }

    private void scheduleThreadScrollChromeRefresh(CuspTab tab, int frames) {
        if (tab == null || tab.threadScroll == null || tab.scrollScrubber == null) {
            return;
        }
        tab.threadScrollChromeFrames = Math.max(tab.threadScrollChromeFrames, Math.max(1, frames));
        if (tab.threadScrollChromeTask != null) {
            return;
        }
        tab.threadScrollChromeTask = () -> {
            tab.threadScrollChromeTask = null;
            tab.threadScrollChromeFrames = Math.max(0, tab.threadScrollChromeFrames - 1);
            refreshThreadScrollChrome(tab);
            if (tab.threadScrollChromeFrames > 0 && tab.threadScroll != null && tab.scrollScrubber != null) {
                scheduleThreadScrollChromeRefresh(tab, tab.threadScrollChromeFrames);
            }
        };
        long delay = tab.threadRendering ? 160L : recentlyScrolled(tab) ? 120L : 16L;
        mainHandler.postDelayed(tab.threadScrollChromeTask, delay);
    }

    private void showFiveChBoardsView() {
        showFiveChBoardsView(true);
    }

    private void showFiveChBoardsView(boolean recordHistory) {
        if (recordHistory && openBbsDirectoryPage(FIVE_CH_BBSMENU_URL)) {
            return;
        }
        showBbsDirectoryIndexView(FIVE_CH_BBSMENU_URL, "5ch", recordHistory);
    }

    private void showBbsDirectoryIndexView(String menuUrl, String pageKey, boolean recordHistory) {
        if (menuUrl == null || menuUrl.trim().isEmpty()) {
            menuUrl = FIVE_CH_BBSMENU_URL;
        }
        if (pageKey == null || pageKey.trim().isEmpty()) {
            pageKey = isFiveChBbsMenuUrl(menuUrl) ? "5ch" : bbsRootPageKey(menuUrl);
        }
        if (recordHistory) {
            if (pendingNewTab) {
                recordNewTabPage(pageKey);
            } else {
                CuspTab tab = currentTab();
                if (tab != null) {
                    recordNavigation(tab, isFiveChBbsMenuUrl(menuUrl)
                            ? menuUrl : bbsRootPageUrl(menuUrl));
                }
            }
        }
        final boolean forNewTab = pendingNewTab;
        final CuspTab targetTab = forNewTab ? null : currentTab();
        if (forNewTab && restoreNewTabHistoryPage(pageKey)) {
            updateBottomThreadBar(null);
            renderTabs();
            return;
        }
        final String loadUrl = menuUrl;
        final String targetPageKey = pageKey;
        showBbsDirectoryLoading(forNewTab, targetTab);
        ioExecutor.execute(() -> {
            SearchPage page;
            boolean usedCached = false;
            try {
                page = cachedBbsDirectoryPage(loadUrl);
                if (page != null) {
                    usedCached = true;
                } else {
                    page = downloadBbsDirectoryWithCache(loadUrl);
                }
                page.title = bbsMenuTitle(loadUrl, page.title);
                bbsCategoryCounts(page);
            } catch (Exception error) {
                page = SearchPage.error(loadUrl, error.getMessage());
            }
            SearchPage result = page;
            boolean refresh = usedCached;
            runOnUiThread(() -> {
                applyBbsDirectoryResult(targetPageKey, forNewTab, targetTab, result, true);
                if (refresh) {
                    refreshBbsMenuCacheIfStale(loadUrl);
                }
            });
        });
    }

    private void showFiveChCategoryView(String encodedCategory, boolean record) {
        showBbsCategoryView(bbsCategoryToken(FIVE_CH_BBSMENU_URL, decodeNewTabToken(encodedCategory)), record);
    }

    private void showBbsCategoryView(String token, boolean record) {
        BbsCategoryRequest request = decodeBbsCategoryToken(token);
        String menuUrl = request.menuUrl == null || request.menuUrl.isEmpty() ? FIVE_CH_BBSMENU_URL : request.menuUrl;
        String category = request.category;
        String pageKey = "bbs-category:" + bbsCategoryToken(menuUrl, category);
        if (record) {
            if (pendingNewTab) {
                recordNewTabPage(pageKey);
            } else {
                CuspTab tab = currentTab();
                if (tab != null) {
                    recordNavigation(tab, bbsCategoryPageUrl(menuUrl, category));
                }
            }
        }
        final boolean forNewTab = pendingNewTab;
        final CuspTab targetTab = forNewTab ? null : currentTab();
        if (forNewTab && restoreNewTabHistoryPage(pageKey)) {
            updateBottomThreadBar(null);
            renderTabs();
            return;
        }
        final String loadUrl = menuUrl;
        final String targetCategory = category;
        final String targetPageKey = pageKey;
        showBbsDirectoryLoading(forNewTab, targetTab);
        ioExecutor.execute(() -> {
            SearchPage page;
            boolean usedCached = false;
            try {
                SearchPage all = cachedBbsDirectoryPage(loadUrl);
                if (all != null) {
                    usedCached = true;
                } else {
                    all = downloadBbsDirectoryWithCache(loadUrl);
                }
                page = filterBbsCategory(all, targetCategory);
                page.title = targetCategory == null || targetCategory.isEmpty()
                        ? all.title
                        : targetCategory;
            } catch (Exception error) {
                page = SearchPage.error(loadUrl, error.getMessage());
            }
            SearchPage result = page;
            boolean refresh = usedCached;
            runOnUiThread(() -> {
                applyBbsDirectoryResult(targetPageKey, forNewTab, targetTab, result, false);
                if (refresh) {
                    refreshBbsMenuCacheIfStale(loadUrl);
                }
            });
        });
    }

    private void showBbsDirectoryLoading(boolean forNewTab, CuspTab targetTab) {
        prepareChromeForLoading();
        View view = loadingView("");
        if (forNewTab) {
            contentFrame.removeAllViews();
            contentFrame.addView(view);
        } else if (targetTab != null) {
            targetTab.readerView = view;
            if (targetTab == currentTab()) {
                showCurrentReaderView(targetTab);
            }
        }
        progressBar.setVisibility(View.VISIBLE);
        showCenterSpinner();
    }

    private void applyBbsDirectoryResult(String pageKey, boolean forNewTab, CuspTab targetTab,
                                         SearchPage result, boolean categoryIndex) {
        if (forNewTab && !isCurrentNewTabPage(pageKey)) {
            if (!tabOverviewVisible) {
                progressBar.setVisibility(View.GONE);
                hideCenterSpinner();
            }
            return;
        }
        if (!forNewTab && (targetTab == null || !tabs.contains(targetTab))) {
            if (!tabOverviewVisible) {
                progressBar.setVisibility(View.GONE);
                hideCenterSpinner();
            }
            return;
        }
        result.title = bbsPageTitleFromPageKey(pageKey, result.title);
        if (!categoryIndex) {
            result.url = bbsInternalUrlFromPageKey(pageKey);
        }
        View resultView = categoryIndex ? buildBbsCategoryIndexView(result, targetTab) : buildSearchView(result, false, targetTab);
        if (forNewTab && result.error == null) {
            cacheNewTabHistoryPage(pageKey, resultView);
        }
        if (forNewTab) {
            progressBar.setVisibility(View.GONE);
            hideCenterSpinner();
            contentFrame.removeAllViews();
            contentFrame.addView(resultView);
        } else if (targetTab != null && tabs.contains(targetTab)) {
            targetTab.readerMode = true;
            targetTab.nativeKind = NATIVE_BOARD;
            targetTab.url = bbsInternalUrlFromPageKey(pageKey);
            targetTab.title = result.title;
            targetTab.searchPage = result;
            targetTab.readerView = resultView;
            targetTab.threadPage = null;
            targetTab.threadScroll = null;
            targetTab.postViews = null;
            cacheBoardHistoryPage(targetTab, result, resultView);
            if (targetTab == currentTab() && !tabOverviewVisible) {
                progressBar.setVisibility(View.GONE);
                hideCenterSpinner();
                showCurrentReaderView(targetTab);
            } else {
                progressBar.setVisibility(View.GONE);
                hideCenterSpinner();
            }
        }
        updateBottomThreadBar(forNewTab ? null : currentTab());
        renderTabs();
    }

    private String bbsPageTitleFromPageKey(String pageKey, String fallback) {
        if ("5ch".equals(pageKey)) {
            return text("\u677f\u4e00\u89a7", "Boards");
        }
        if (pageKey != null && pageKey.startsWith("bbs:")) {
            String menuUrl = decodeNewTabToken(pageKey.substring("bbs:".length()));
            return bbsMenuTitle(menuUrl, fallback);
        }
        if (pageKey != null && pageKey.startsWith("bbs-category:")) {
            BbsCategoryRequest request = decodeBbsCategoryToken(pageKey.substring("bbs-category:".length()));
            if (request.category != null && !request.category.trim().isEmpty()
                    && !looksLikeUrlFragmentTitle(request.category)) {
                return request.category.trim();
            }
            return bbsMenuTitle(request.menuUrl, fallback);
        }
        if (fallback != null && !fallback.trim().isEmpty() && !looksLikeUrlFragmentTitle(fallback)) {
            return fallback.trim();
        }
        return text("\u677f\u4e00\u89a7", "Boards");
    }

    private boolean looksLikeUrlFragmentTitle(String value) {
        if (value == null) {
            return false;
        }
        String trimmed = value.trim().toLowerCase(Locale.ROOT);
        return "http:".equals(trimmed) || "https:".equals(trimmed)
                || trimmed.startsWith("http://") || trimmed.startsWith("https://");
    }

    private String bbsMenuUrlFromPageKey(String pageKey) {
        if ("5ch".equals(pageKey) || pageKey != null && pageKey.startsWith("5ch-category:")) {
            return FIVE_CH_BBSMENU_URL;
        }
        if (pageKey != null && pageKey.startsWith("bbs:")) {
            String value = decodeNewTabToken(pageKey.substring("bbs:".length()));
            return value.isEmpty() ? FIVE_CH_BBSMENU_URL : value;
        }
        if (pageKey != null && pageKey.startsWith("bbs-category:")) {
            BbsCategoryRequest request = decodeBbsCategoryToken(pageKey.substring("bbs-category:".length()));
            return request.menuUrl == null || request.menuUrl.isEmpty() ? FIVE_CH_BBSMENU_URL : request.menuUrl;
        }
        return FIVE_CH_BBSMENU_URL;
    }

    private String bbsInternalUrlFromPageKey(String pageKey) {
        if ("5ch".equals(pageKey)) {
            return bbsRootPageUrl(FIVE_CH_BBSMENU_URL);
        }
        if (pageKey != null && pageKey.startsWith("bbs:")) {
            String value = decodeNewTabToken(pageKey.substring("bbs:".length()));
            return bbsRootPageUrl(value.isEmpty() ? FIVE_CH_BBSMENU_URL : value);
        }
        if (pageKey != null && pageKey.startsWith("bbs-category:")) {
            BbsCategoryRequest request = decodeBbsCategoryToken(pageKey.substring("bbs-category:".length()));
            return bbsCategoryPageUrl(
                    request.menuUrl == null || request.menuUrl.isEmpty() ? FIVE_CH_BBSMENU_URL : request.menuUrl,
                    request.category);
        }
        return bbsRootPageUrl(bbsMenuUrlFromPageKey(pageKey));
    }

    private boolean restoreNewTabHistoryPage(String pageKey) {
        NewTabHistoryPage cached = newTabHistoryPages.remove(pageKey);
        if (cached == null || cached.view == null) {
            return false;
        }
        newTabHistoryPages.put(pageKey, cached);
        if (cached.view.getParent() instanceof ViewGroup) {
            ((ViewGroup) cached.view.getParent()).removeView(cached.view);
        }
        progressBar.setVisibility(View.GONE);
        contentFrame.removeAllViews();
        contentFrame.addView(cached.view);
        return true;
    }

    private void cacheNewTabHistoryPage(String pageKey, View view) {
        if (pageKey == null || pageKey.isEmpty() || view == null) {
            return;
        }
        newTabHistoryPages.remove(pageKey);
        newTabHistoryPages.put(pageKey, new NewTabHistoryPage(view));
        while (newTabHistoryPages.size() > MAX_NEW_TAB_HISTORY_PAGES) {
            String oldest = newTabHistoryPages.keySet().iterator().next();
            newTabHistoryPages.remove(oldest);
        }
    }

    private boolean isCurrentNewTabPage(String pageKey) {
        return pendingNewTab
                && newTabNavigationIndex >= 0
                && newTabNavigationIndex < newTabNavigationHistory.size()
                && pageKey.equals(newTabNavigationHistory.get(newTabNavigationIndex));
    }

    private String bbsCategoryToken(String menuUrl, String category) {
        return encodeNewTabToken(menuUrl) + "::" + encodeNewTabToken(category);
    }

    private BbsCategoryRequest decodeBbsCategoryToken(String token) {
        String value = token == null ? "" : token;
        int split = value.indexOf("::");
        if (split < 0) {
            return new BbsCategoryRequest(FIVE_CH_BBSMENU_URL, decodeNewTabToken(value));
        }
        return new BbsCategoryRequest(
                decodeNewTabToken(value.substring(0, split)),
                decodeNewTabToken(value.substring(split + 2)));
    }

    private SearchPage filterBbsCategory(SearchPage source, String category) {
        SearchPage page = new SearchPage();
        page.url = source.url;
        page.title = category;
        page.error = source.error;
        for (SearchResult result : source.results) {
            if (TextUtils.equals(category, result.category)) {
                SearchResult copy = new SearchResult();
                copy.title = result.title;
                copy.url = result.url;
                copy.meta = result.meta;
                copy.responses = result.responses;
                copy.velocity = result.velocity;
                copy.boardOrder = result.boardOrder;
                copy.createdAt = result.createdAt;
                copy.unread = result.unread;
                copy.hasReadHistory = result.hasReadHistory;
                copy.boardName = result.boardName;
                copy.priorityMatch = result.priorityMatch;
                copy.category = "";
                page.results.add(copy);
            }
        }
        return page;
    }

    private void addHistorySection(LinearLayout list, boolean fullHistory) {
        list.addView(sectionTitleView(text("\u5c65\u6b74", "History")));
        List<ThreadHistoryItem> history = threadHistory();
        int limit = fullHistory ? history.size() : Math.min(history.size(), 8);
        if (history.isEmpty()) {
            list.addView(helperLine(text("\u95b2\u89a7\u5c65\u6b74\u306a\u3057", "No browsing history.")));
            return;
        }
        for (int i = 0; i < limit; i++) {
            list.addView(historyRow(history.get(i), fullHistory));
        }
        if (!fullHistory && history.size() > limit) {
            TextView more = actionRow(text("\u5c65\u6b74\u3092\u3082\u3063\u3068\u898b\u308b", "More history"));
            more.setOnClickListener(v -> {
                if (pendingNewTab) {
                    renderNewTabPage("history", true);
                } else {
                    CuspTab tab = currentTab();
                    if (tab != null) {
                        tab.readerView = buildHistoryView();
                        showCurrentReaderView(tab);
                    }
                }
            });
            list.addView(more);
        }
    }

    private View buildHistoryView() {
        ScrollView scroll = new ScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setPadding(dp(12), dp(12), dp(12), dp(24));
        scroll.addView(list, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        list.addView(sectionTitleView(text("\u5c65\u6b74", "History")));
        List<ThreadHistoryItem> history = threadHistory();
        if (history.isEmpty()) {
            list.addView(helperLine(text("\u95b2\u89a7\u5c65\u6b74\u306a\u3057", "No browsing history.")));
        } else {
            for (ThreadHistoryItem item : history) {
                list.addView(historyRow(item, true));
            }
        }
        return withScrollScrubber(scroll);
    }

    private void showTabOverview() {
        CuspTab current = currentTab();
        boolean targetPrivateMode = pendingNewTab ? pendingPrivateNewTab : currentTabIsPrivate();
        tabOverviewPrivateMode = targetPrivateMode;
        pendingNewTab = false;
        pendingHistoryAll = false;
        tabOverviewVisible = true;
        contentFrame.removeAllViews();
        contentFrame.addView(loadingView(""));
        visibleThreadPage = null;
        visibleThreadScroll = null;
        visiblePostViews.clear();
        syncLoadingUiWithCurrentSurface();
        updateBottomThreadBar(currentTab());
        renderTabs();
        mainHandler.post(() -> {
            if (!tabOverviewVisible || tabOverviewPrivateMode != targetPrivateMode) {
                return;
            }
            if (current != null) {
                rememberTabScroll(current);
            }
            clearAddressFocus();
            closeThreadSearch();
            if (!replyPopups.isEmpty()) {
                dismissThreadPopups();
            }
            contentFrame.removeAllViews();
            attachTabOverviewView();
            updateBottomThreadBar(currentTab());
            renderTabs();
            mainHandler.postDelayed(() -> {
                if (tabOverviewVisible) {
                    trimBackgroundTabViews();
                    trimBackgroundPageData();
                }
            }, 250);
        });
    }

    private void attachTabOverviewView() {
        View view = cachedTabOverviewView();
        boolean newlyBuilt = view == null;
        if (newlyBuilt) {
            view = buildTabOverviewView();
            setCachedTabOverviewView(view);
        } else if (view.getParent() instanceof ViewGroup) {
            ((ViewGroup) view.getParent()).removeView(view);
        }
        restoringTabOverviewScroll = currentTabOverviewScrollY() > 0;
        contentFrame.addView(view);
        View attachedView = view;
        if (!newlyBuilt) {
            boolean updatedTabs = refreshTabOverviewTabSlotsOnly();
            boolean updatedBookmarks = !tabOverviewPrivateMode && showBookmarksInTabOverview()
                    && bookmarkOverviewDirty
                    && refreshTabOverviewBookmarkSectionOnly(attachedView);
            boolean updatedBookmarkSelection = !tabOverviewPrivateMode && showBookmarksInTabOverview()
                    && !updatedBookmarks
                    && !bookmarkOverviewDirty
                    && refreshBookmarkOverviewSelectionInPlace(attachedView);
            if (!updatedTabs && !updatedBookmarks && !updatedBookmarkSelection) {
                refreshTabOverviewListOnly();
            }
        }
        restoreCachedTabOverviewScroll(view);
        syncClosedTabUndoBar();
    }

    private View cachedTabOverviewView() {
        return tabOverviewPrivateMode ? tabOverviewPrivateView : tabOverviewNormalView;
    }

    private void setCachedTabOverviewView(View view) {
        if (tabOverviewPrivateMode) {
            tabOverviewPrivateView = view;
        } else {
            tabOverviewNormalView = view;
        }
    }

    private int currentTabOverviewScrollY() {
        return tabOverviewPrivateMode ? tabOverviewPrivateScrollY : tabOverviewNormalScrollY;
    }

    private void setCurrentTabOverviewScrollY(int scrollY) {
        int value = Math.max(0, scrollY);
        if (value == tabOverviewScrollY
                && value == (tabOverviewPrivateMode ? tabOverviewPrivateScrollY : tabOverviewNormalScrollY)) {
            return;
        }
        tabOverviewScrollY = value;
        if (tabOverviewPrivateMode) {
            tabOverviewPrivateScrollY = value;
        } else {
            tabOverviewNormalScrollY = value;
        }
        requestSaveTabsSoon();
    }

    private void replaceCurrentNavigationUrl(CuspTab tab, String expectedUrl, String redirectedUrl) {
        if (tab == null || redirectedUrl == null || redirectedUrl.trim().isEmpty()
                || redirectedUrl.equals(expectedUrl)) {
            return;
        }
        if (tab.navigationIndex >= 0 && tab.navigationIndex < tab.navigationHistory.size()
                && expectedUrl.equals(tab.navigationHistory.get(tab.navigationIndex))) {
            tab.navigationHistory.set(tab.navigationIndex, redirectedUrl);
        }
        if (tab == currentTab() && addressBar != null) {
            addressBar.setText(addressBarTextForUrl(tab.nativeKind, redirectedUrl));
            resetAddressBarScrollToStart();
        }
        requestSaveTabsSoon();
    }

    private void rememberTabOverviewScroll() {
        if (!tabOverviewVisible || contentFrame == null) {
            return;
        }
        ScrollView scroll = findScrollView(contentFrame);
        if (scroll != null) {
            setCurrentTabOverviewScrollY(scroll.getScrollY());
        }
    }

    private void restoreCachedTabOverviewScroll(View view) {
        ScrollView scroll = findScrollView(view);
        if (scroll == null) {
            restoringTabOverviewScroll = false;
            return;
        }
        int restoreY = currentTabOverviewScrollY();
        if (restoreY <= 0) {
            finishTabOverviewScrollRestore(scroll);
            return;
        }
        boolean restoredImmediately = applyTabOverviewScrollRestore(scroll, restoreY);
        if (restoredImmediately) {
            restoringTabOverviewScroll = true;
        }
        scroll.getViewTreeObserver().addOnPreDrawListener(new ViewTreeObserver.OnPreDrawListener() {
            @Override
            public boolean onPreDraw() {
                if (scroll.getViewTreeObserver().isAlive()) {
                    scroll.getViewTreeObserver().removeOnPreDrawListener(this);
                }
                if (applyTabOverviewScrollRestore(scroll, restoreY)) {
                    finishTabOverviewScrollRestore(scroll);
                }
                return true;
            }
        });
        if (!restoredImmediately) {
            scroll.post(() -> {
                if (applyTabOverviewScrollRestore(scroll, restoreY)) {
                    finishTabOverviewScrollRestore(scroll);
                }
            });
        }
    }

    private boolean applyTabOverviewScrollRestore(ScrollView scroll, int restoreY) {
        if (scroll == null || restoreY <= 0) {
            return true;
        }
        if (scroll.getChildCount() == 0 || scroll.getHeight() <= 0) {
            return false;
        }
        int range = Math.max(0, scroll.getChildAt(0).getHeight() - scroll.getHeight());
        if (range <= 0) {
            scroll.scrollTo(0, 0);
            return true;
        }
        scroll.scrollTo(0, Math.min(restoreY, range));
        return true;
    }

    private void finishTabOverviewScrollRestore(ScrollView scroll) {
        restoringTabOverviewScroll = false;
        View child = scroll == null || scroll.getChildCount() == 0 ? null : scroll.getChildAt(0);
        if (child instanceof LinearLayout) {
            scheduleTabOverviewSlotRefresh((LinearLayout) child);
        }
    }

    private View buildTabOverviewView() {
        FrameLayout root = new FrameLayout(this);
        root.setBackgroundColor(bgColor());

        ScrollView scroll = new ScrollView(this);
        scroll.setBackgroundColor(bgColor());
        scroll.setVerticalScrollBarEnabled(false);
        scroll.setOnScrollChangeListener((v, scrollX, scrollY, oldScrollX, oldScrollY) -> {
            handleContentScrollForChrome(scrollY, oldScrollY);
            if (!restoringTabOverviewScroll) {
                setCurrentTabOverviewScrollY(scrollY);
            }
        });
        scroll.setOnDragListener((v, event) -> {
            autoScrollDuringDrag(scroll, event);
            return true;
        });
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        setTabOverviewListPadding(list);
        scroll.addView(list, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        root.addView(scroll, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        populateTabOverviewList(scroll, list, true, false);
        scheduleDeferredTabOverviewSort(list, tabOverviewPrivateMode);

        FrameLayout loader = bottomRefreshLoader();
        loader.setVisibility(View.GONE);
        loader.setTranslationY(-dp(58));
        FrameLayout.LayoutParams loaderParams = new FrameLayout.LayoutParams(dp(66), dp(66),
                Gravity.TOP | Gravity.CENTER_HORIZONTAL);
        loaderParams.setMargins(0, dp(2), 0, 0);
        root.addView(loader, loaderParams);
        enableTopPullRefresh(scroll, loader, () -> refreshTabOverviewFromTop(loader));

        addPrivateModeOverlay(root, tabOverviewPrivateMode, v -> toggleTabOverviewPrivateMode());
        ImageButton reloadAll = iconButton(R.drawable.ic_refresh, text("\u3059\u3079\u3066\u66f4\u65b0", "Reload all"), v -> reloadAllTabs(true));
        reloadAll.setBackground(roundedDrawable(menuColor(), borderColor(), dp(22)));
        FrameLayout.LayoutParams reloadParams = new FrameLayout.LayoutParams(dp(54), dp(54), Gravity.BOTTOM | Gravity.RIGHT);
        reloadParams.setMargins(0, 0, dp(84), dp(18));
        root.addView(reloadAll, reloadParams);

        ImageButton add = iconButton(R.drawable.ic_add, text("\u65b0\u898f\u30bf\u30d6", "New tab"), v -> {
            showPendingNewTab(tabOverviewPrivateMode);
            focusPendingNewTabSearch();
        });
        add.setBackground(roundedDrawable(TEAL, TEAL, dp(22)));
        add.setColorFilter(Color.WHITE);
        FrameLayout.LayoutParams addParams = new FrameLayout.LayoutParams(dp(54), dp(54), Gravity.BOTTOM | Gravity.RIGHT);
        addParams.setMargins(0, 0, dp(18), dp(18));
        root.addView(add, addParams);
        if (recentlyClosedTab != null) {
            root.addView(closedTabUndoBar(), closedTabUndoParams());
        }
        return root;
    }

    private void populateTabOverviewList(ScrollView scroll, LinearLayout list) {
        populateTabOverviewList(scroll, list, true);
    }

    private void populateTabOverviewList(ScrollView scroll, LinearLayout list, boolean includeBookmarks) {
        populateTabOverviewList(scroll, list, includeBookmarks, true);
    }

    private void populateTabOverviewList(ScrollView scroll, LinearLayout list,
                                         boolean includeBookmarks, boolean allowSort) {
        list.removeAllViews();
        setTabOverviewListPadding(list);
        LinearLayout header = new LinearLayout(this);
        header.setOrientation(LinearLayout.HORIZONTAL);
        header.setGravity(Gravity.CENTER_VERTICAL);
        TextView title = sectionTitleView(tabOverviewPrivateMode
                ? text("\u30d7\u30e9\u30a4\u30d9\u30fc\u30c8\u30bf\u30d6", "Private tabs")
                : text("\u901a\u5e38\u30bf\u30d6", "Normal tabs"));
        header.addView(title, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        header.addView(new View(this), new LinearLayout.LayoutParams(dp(38), dp(38)));
        list.addView(header);
        addTabOverviewSection(scroll, list, tabOverviewPrivateMode, allowSort);
        if (includeBookmarks && !tabOverviewPrivateMode && showBookmarksInTabOverview()) {
            scheduleInitialBookmarkOverviewSection(scroll, list);
        }
    }

    private void scheduleInitialBookmarkOverviewSection(ScrollView scroll, LinearLayout list) {
        if (scroll == null || list == null) {
            return;
        }
        boolean privateMode = tabOverviewPrivateMode;
        int generation = ++bookmarkOverviewRenderGeneration;
        Map<String, CuspTab> openTabs = bookmarkOverviewOpenThreadTabs();
        if (bookmarkOverviewLoadTask != null) {
            bookmarkOverviewLoadTask.cancel(true);
        }
        bookmarkOverviewLoadTask = tabOverviewExecutor.submit(() -> {
            BookmarkOverviewSnapshot snapshot = bookmarkOverviewSnapshot(openTabs, generation);
            mainHandler.post(() -> {
                if (!tabOverviewVisible || tabOverviewPrivateMode != privateMode
                        || list.getParent() != scroll || generation != bookmarkOverviewRenderGeneration) {
                    return;
                }
                bookmarkOverviewLoadTask = null;
                addBookmarkOverviewSection(list, true, snapshot);
                scheduleTabOverviewSlotRefresh(list);
            });
        });
    }

    private void setTabOverviewListPadding(LinearLayout list) {
        if (list == null) {
            return;
        }
        int bottom = dp(84) + (recentlyClosedTab == null ? 0 : dp(48));
        list.setPadding(dp(12), dp(12), dp(12), bottom);
    }

    private ImageButton privateModeButton(boolean active, View.OnClickListener listener) {
        ImageButton button = iconButton(R.drawable.ic_private_glasses,
                text("\u30d7\u30e9\u30a4\u30d9\u30fc\u30c8", "Private"), listener);
        button.setBackground(roundedDrawable(privateButtonFill(active),
                privateButtonStroke(active), dp(20)));
        button.setColorFilter(privateButtonIcon(active));
        button.setPadding(dp(7), dp(7), dp(7), dp(7));
        button.setTranslationY(-dp(2));
        return button;
    }

    private void addPrivateModeOverlay(FrameLayout root, boolean active, View.OnClickListener listener) {
        ImageButton button = privateModeButton(active, listener);
        FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(dp(38), dp(38), Gravity.TOP | Gravity.RIGHT);
        params.setMargins(0, dp(10), dp(12), 0);
        root.addView(button, params);
    }

    private void togglePendingPrivateNewTab() {
        if (!pendingNewTab) {
            return;
        }
        pendingPrivateNewTab = !pendingPrivateNewTab;
        contentFrame.setBackgroundColor(bgColor());
        contentFrame.removeAllViews();
        String page = newTabNavigationIndex >= 0 && newTabNavigationIndex < newTabNavigationHistory.size()
                ? newTabNavigationHistory.get(newTabNavigationIndex) : (pendingHistoryAll ? "history" : "home");
        renderNewTabPage(page, false);
        renderTabs();
    }

    private void toggleTabOverviewPrivateMode() {
        rememberTabOverviewScroll();
        tabOverviewPrivateMode = !tabOverviewPrivateMode;
        if (tabOverviewVisible && contentFrame != null) {
            contentFrame.removeAllViews();
            contentFrame.setBackgroundColor(bgColor());
            attachTabOverviewView();
            renderTabs();
        }
    }

    private void addTabOverviewSection(ScrollView scroll, LinearLayout list, boolean privateSection) {
        addTabOverviewSection(scroll, list, privateSection, true);
    }

    private void addTabOverviewSection(ScrollView scroll, LinearLayout list,
                                       boolean privateSection, boolean allowSort) {
        List<Integer> indices = tabOverviewIndices(privateSection, allowSort);
        if (indices.isEmpty()) {
            TextView empty = helperLine(privateSection
                    ? text("\u30d7\u30e9\u30a4\u30d9\u30fc\u30c8\u30bf\u30d6\u306a\u3057", "No private tabs.")
                    : text("\u901a\u5e38\u30bf\u30d6\u306a\u3057", "No normal tabs."));
            empty.setTag(TAB_OVERVIEW_EMPTY_TAG);
            empty.setOnDragListener((v, event) -> {
                autoScrollDuringDrag(v, event);
                if (event.getAction() == android.view.DragEvent.ACTION_DROP) {
                    Object local = event.getLocalState();
                    if (local instanceof DragPayload) {
                        return moveBookmarkToTabsFromPayload((DragPayload) local, tabs.size());
                    }
                }
                return true;
            });
            list.addView(empty);
            if (!(list.getTag() instanceof VirtualTabOverviewState)) {
                setupVirtualTabOverviewRefresh(scroll, list);
            }
        } else {
            renderVirtualTabOverviewSlots(scroll, list, indices);
        }
    }

    private void scheduleDeferredTabOverviewSort(LinearLayout list, boolean privateMode) {
        if (list == null || !preferences.getBoolean(PREF_TAB_SORT_ENABLED, false)) {
            return;
        }
        scheduleDeferredTabOverviewSort(list, privateMode, 0);
    }

    private void scheduleDeferredTabOverviewSort(LinearLayout list, boolean privateMode, int attempt) {
        list.postDelayed(() -> {
            if (!tabOverviewVisible || tabOverviewPrivateMode != privateMode
                    || contentFrame == null || list.getParent() == null) {
                return;
            }
            VirtualTabOverviewState state = list.getTag() instanceof VirtualTabOverviewState
                    ? (VirtualTabOverviewState) list.getTag() : null;
            if (state != null && state.appendingSlots && attempt < 20) {
                scheduleDeferredTabOverviewSort(list, privateMode, attempt + 1);
                return;
            }
            refreshTabOverviewTabSlotsOnly();
        }, TAB_OVERVIEW_DEFERRED_SORT_DELAY_MS);
    }

    private void renderVirtualTabOverviewSlots(ScrollView scroll, LinearLayout list, List<Integer> indices) {
        int initialCount = Math.min(indices.size(), TAB_OVERVIEW_INITIAL_SLOT_BATCH);
        appendVirtualTabOverviewSlots(list, indices, 0, initialCount);
        VirtualTabOverviewState state = setupVirtualTabOverviewRefresh(scroll, list);
        if (initialCount < indices.size()) {
            state.appendingSlots = true;
            list.post(() -> appendDeferredVirtualTabOverviewSlots(scroll, list, indices, state, initialCount));
        }
    }

    private void appendDeferredVirtualTabOverviewSlots(ScrollView scroll, LinearLayout list,
                                                       List<Integer> indices,
                                                       VirtualTabOverviewState state, int start) {
        if (list == null || indices == null || list.getTag() != state) {
            return;
        }
        int end = Math.min(indices.size(), start + TAB_OVERVIEW_DEFERRED_SLOT_BATCH);
        appendVirtualTabOverviewSlots(list, indices, start, end);
        scheduleTabOverviewSlotRefresh(list);
        if (end < indices.size()) {
            list.postDelayed(() -> appendDeferredVirtualTabOverviewSlots(scroll, list, indices, state, end),
                    TAB_OVERVIEW_DEFERRED_SLOT_DELAY_MS);
        } else {
            state.appendingSlots = false;
        }
    }

    private void appendVirtualTabOverviewSlots(LinearLayout list, List<Integer> indices, int start, int end) {
        if (list == null || indices == null) {
            return;
        }
        for (int i = Math.max(0, start); i < end && i < indices.size(); i++) {
            int index = indices.get(i);
            if (index >= 0 && index < tabs.size()) {
                addVirtualTabOverviewSlot(list, new VirtualTabOverviewSlot(index, tabs.get(index)));
            }
        }
    }

    private void addVirtualTabOverviewSlot(LinearLayout list, VirtualTabOverviewSlot slot) {
        list.addView(createTabOverviewSlotHolder(slot), tabOverviewSlotLayoutParams());
    }

    private FrameLayout createTabOverviewSlotHolder(VirtualTabOverviewSlot slot) {
        FrameLayout holder = new FrameLayout(this);
        bindTabOverviewSlot(holder, slot);
        holder.addView(tabOverviewSlotSpacer(slot.height), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, slot.height));
        return holder;
    }

    private LinearLayout.LayoutParams tabOverviewSlotLayoutParams() {
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        params.setMargins(0, 0, 0, dp(8));
        return params;
    }

    private void bindTabOverviewSlot(FrameLayout holder, VirtualTabOverviewSlot slot) {
        if (holder == null || slot == null) {
            return;
        }
        holder.setTag(slot);
        holder.setOnDragListener(tabOverviewDropListener(slot.index));
    }

    private View.OnDragListener tabOverviewDropListener(int index) {
        return (v, event) -> {
            autoScrollDuringDrag(v, event);
            if (event.getAction() == android.view.DragEvent.ACTION_DROP) {
                Object local = event.getLocalState();
                if (local instanceof DragPayload) {
                    DragPayload payload = (DragPayload) local;
                    if ("tabs".equals(payload.key)) {
                        moveTabInOverview(payload, index);
                        return true;
                    }
                    if (moveBookmarkToTabsFromPayload(payload, index)) {
                        return true;
                    }
                }
            }
            return true;
        };
    }

    private VirtualTabOverviewState setupVirtualTabOverviewRefresh(ScrollView scroll, LinearLayout list) {
        VirtualTabOverviewState state = new VirtualTabOverviewState();
        list.setTag(state);
        state.refreshTask = () -> {
            state.refreshPending = false;
            refreshTabOverviewSlots(scroll, list);
        };
        scroll.getViewTreeObserver().addOnScrollChangedListener(() -> {
            if (list.getTag() instanceof VirtualTabOverviewState) {
                ((VirtualTabOverviewState) list.getTag()).lastScrollAt = android.os.SystemClock.uptimeMillis();
            }
            scheduleTabOverviewSlotRefresh(list);
        });
        scheduleTabOverviewSlotRefresh(list);
        return state;
    }

    private void scheduleTabOverviewSlotRefresh(LinearLayout list) {
        if (list == null || !(list.getTag() instanceof VirtualTabOverviewState)) {
            return;
        }
        VirtualTabOverviewState state = (VirtualTabOverviewState) list.getTag();
        if (state.refreshTask == null || state.refreshPending) {
            return;
        }
        state.refreshPending = true;
        list.post(state.refreshTask);
    }

    private void refreshTabOverviewSlots(ScrollView scroll, LinearLayout list) {
        if (scroll == null || list == null) {
            return;
        }
        int scrollY = scroll.getScrollY();
        int height = scroll.getHeight();
        if (height <= 0) {
            return;
        }
        VirtualTabOverviewState state = list.getTag() instanceof VirtualTabOverviewState
                ? (VirtualTabOverviewState) list.getTag() : null;
        boolean scrolling = state != null
                && android.os.SystemClock.uptimeMillis() - state.lastScrollAt < 180;
        int renderTop = Math.max(0, scrollY - (scrolling ? height / 2 : height));
        int renderBottom = scrollY + height + (scrolling ? height : height * 2);
        int keepTop = Math.max(0, scrollY - (scrolling ? height : height * 2));
        int keepBottom = scrollY + height + (scrolling ? height * 2 : height * 3);
        int visibleStart = firstChildWithBottomAtLeast(list, scrollY);
        int visibleEnd = lastChildWithTopAtMost(list, scrollY + height);
        int start = firstChildWithBottomAtLeast(list, renderTop);
        int end = lastChildWithTopAtMost(list, renderBottom);
        int keepStart = firstChildWithBottomAtLeast(list, keepTop);
        int keepEnd = lastChildWithTopAtMost(list, keepBottom);
        Set<FrameLayout> keep = new LinkedHashSet<>();
        collectTabOverviewSlotsInRange(list, keepStart, keepEnd, keep);
        int[] rendered = {0};
        boolean[] budgetReached = {false};
        renderTabOverviewSlotsInRange(list, visibleStart, visibleEnd, TAB_OVERVIEW_VISIBLE_RENDER_BUDGET,
                rendered, budgetReached, keep);
        int budget = scrolling ? TAB_OVERVIEW_SCROLL_RENDER_BUDGET : TAB_OVERVIEW_IDLE_RENDER_BUDGET;
        renderTabOverviewSlotsInRange(list, start, end, budget, rendered, budgetReached, keep);
        if (budgetReached[0]) {
            scheduleTabOverviewSlotRefresh(list);
        }
        if (!scrolling && state != null && !state.renderedSlots.isEmpty()) {
            for (FrameLayout holder : new ArrayList<>(state.renderedSlots)) {
                if (keep.contains(holder)) {
                    continue;
                }
                Object tag = holder.getTag();
                if (tag instanceof VirtualTabOverviewSlot) {
                    recycleTabOverviewSlot(holder, (VirtualTabOverviewSlot) tag);
                } else if (tag instanceof VirtualBookmarkOverviewSlot) {
                    recycleBookmarkOverviewSlot(holder, (VirtualBookmarkOverviewSlot) tag);
                }
            }
        }
    }

    private void collectTabOverviewSlotsInRange(ViewGroup list, int start, int end, Set<FrameLayout> keep) {
        if (list == null || keep == null || start > end || end < 0) {
            return;
        }
        int childCount = list.getChildCount();
        for (int i = Math.max(0, start); i <= end && i < childCount; i++) {
            View child = list.getChildAt(i);
            if (child instanceof FrameLayout && isVirtualTabOverviewChild(child.getTag())) {
                keep.add((FrameLayout) child);
            }
        }
    }

    private void renderTabOverviewSlotsInRange(ViewGroup list, int start, int end, int budget,
                                               int[] rendered, boolean[] budgetReached,
                                               Set<FrameLayout> keep) {
        if (list == null || start > end || end < 0) {
            return;
        }
        int childCount = list.getChildCount();
        for (int i = Math.max(0, start); i <= end && i < childCount; i++) {
            View child = list.getChildAt(i);
            Object tag = child.getTag();
            if (!(child instanceof FrameLayout) || !isVirtualTabOverviewChild(tag)) {
                continue;
            }
            FrameLayout holder = (FrameLayout) child;
            if (keep != null) {
                keep.add(holder);
            }
            if (virtualTabOverviewChildRendered(tag)) {
                continue;
            }
            if (rendered[0] >= budget) {
                budgetReached[0] = true;
                return;
            }
            renderVirtualTabOverviewChild(holder, tag);
            rendered[0]++;
        }
    }

    private boolean isVirtualTabOverviewChild(Object tag) {
        return tag instanceof VirtualTabOverviewSlot || tag instanceof VirtualBookmarkOverviewSlot;
    }

    private boolean virtualTabOverviewChildRendered(Object tag) {
        if (tag instanceof VirtualTabOverviewSlot) {
            return ((VirtualTabOverviewSlot) tag).rendered;
        }
        if (tag instanceof VirtualBookmarkOverviewSlot) {
            return ((VirtualBookmarkOverviewSlot) tag).rendered;
        }
        return false;
    }

    private void renderVirtualTabOverviewChild(FrameLayout holder, Object tag) {
        if (tag instanceof VirtualTabOverviewSlot) {
            renderTabOverviewSlot(holder, (VirtualTabOverviewSlot) tag);
        } else if (tag instanceof VirtualBookmarkOverviewSlot) {
            renderBookmarkOverviewSlot(holder, (VirtualBookmarkOverviewSlot) tag);
        }
    }

    private void renderTabOverviewSlot(FrameLayout holder, VirtualTabOverviewSlot slot) {
        if (holder == null || slot == null || slot.rendered) {
            return;
        }
        CuspTab tab = slot.tab;
        int index = tab == null ? slot.index : tabs.indexOf(tab);
        if (index < 0 || index >= tabs.size()) {
            return;
        }
        slot.index = index;
        slot.tab = tabs.get(index);
        bindTabOverviewSlot(holder, slot);
        holder.removeAllViews();
        holder.addView(tabOverviewRow(slot.tab, slot.index), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        slot.rendered = true;
        slot.selected = !pendingNewTab && slot.index == currentIndex;
        tabOverviewValueDirtyTabs.remove(slot.tab);
        if (holder.getParent() instanceof View) {
            View parent = (View) holder.getParent();
            if (parent instanceof LinearLayout && parent.getTag() instanceof VirtualTabOverviewState) {
                ((VirtualTabOverviewState) parent.getTag()).renderedSlots.add(holder);
            }
        }
    }

    private void refreshTabOverviewSlotForTab(CuspTab tab) {
        if (!tabOverviewVisible || contentFrame == null || tab == null
                || tab.privateBrowsing != tabOverviewPrivateMode) {
            return;
        }
        ScrollView scroll = findScrollView(contentFrame);
        if (scroll == null || scroll.getChildCount() == 0 || !(scroll.getChildAt(0) instanceof LinearLayout)) {
            return;
        }
        LinearLayout list = (LinearLayout) scroll.getChildAt(0);
        VirtualTabOverviewState state = list.getTag() instanceof VirtualTabOverviewState
                ? (VirtualTabOverviewState) list.getTag() : null;
        tabOverviewResultCache.remove(tab);
        for (FrameLayout holder : tabOverviewSlotHolders(list)) {
            Object tag = holder.getTag();
            if (!(tag instanceof VirtualTabOverviewSlot)) {
                continue;
            }
            VirtualTabOverviewSlot slot = (VirtualTabOverviewSlot) tag;
            if (slot.tab != tab) {
                continue;
            }
            slot.index = tabs.indexOf(tab);
            if (slot.index < 0) {
                return;
            }
            if (slot.rendered) {
                slot.rendered = false;
                if (state != null) {
                    state.renderedSlots.remove(holder);
                }
                renderTabOverviewSlot(holder, slot);
            } else {
                bindTabOverviewSlot(holder, slot);
            }
            return;
        }
    }

    private void refreshTabOverviewValuesForTab(CuspTab tab) {
        if (tab == null) {
            return;
        }
        tabOverviewResultCache.remove(tab);
        tabOverviewValueDirtyTabs.add(tab);
        refreshBookmarkOverviewValuesForTab(tab);
        if (tabOverviewVisible && preferences != null && preferences.getBoolean(PREF_TAB_SORT_ENABLED, false)) {
            refreshTabOverviewTabSlotsOnly();
            return;
        }
        refreshTabOverviewSlotForTab(tab);
    }

    private void refreshBookmarkOverviewValuesForTab(CuspTab tab) {
        String url = threadUrl(tab);
        if (url == null || url.trim().isEmpty()
                || !showBookmarksInTabOverview()
                || !savedItemExists(PREF_THREAD_BOOKMARKS, url)) {
            return;
        }
        markBookmarkOverviewDirty();
        if (tabOverviewVisible && !tabOverviewPrivateMode && contentFrame != null) {
            refreshTabOverviewBookmarkSectionOnly(contentFrame);
            return;
        }
        if (tabOverviewNormalView != null) {
            refreshTabOverviewBookmarkSectionOnly(tabOverviewNormalView);
        }
    }

    private void recycleTabOverviewSlot(FrameLayout holder, VirtualTabOverviewSlot slot) {
        if (holder == null || slot == null || !slot.rendered) {
            return;
        }
        holder.removeAllViews();
        bindTabOverviewSlot(holder, slot);
        holder.addView(tabOverviewSlotSpacer(slot.height), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, slot.height));
        slot.rendered = false;
        slot.selected = false;
        if (holder.getParent() instanceof View) {
            View parent = (View) holder.getParent();
            if (parent instanceof LinearLayout && parent.getTag() instanceof VirtualTabOverviewState) {
                ((VirtualTabOverviewState) parent.getTag()).renderedSlots.remove(holder);
            }
        }
    }

    private View tabOverviewSlotSpacer(int height) {
        View spacer = new View(this);
        spacer.setMinimumHeight(Math.max(dp(86), height));
        return spacer;
    }

    private List<Integer> tabOverviewIndices(boolean privateSection) {
        return tabOverviewIndices(privateSection, true);
    }

    private List<Integer> tabOverviewIndices(boolean privateSection, boolean allowSort) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < tabs.size(); i++) {
            CuspTab tab = tabs.get(i);
            if (tab.privateBrowsing == privateSection && isNormalTabScope(tab)) {
                indices.add(i);
            }
        }
        List<Integer> restored = restoredTabOverviewIndices(privateSection, indices);
        if (restored != null) {
            rememberTabOverviewOrderSnapshot(privateSection, restored);
            return restored;
        }
        if (!allowSort) {
            return indices;
        }
        if (!preferences.getBoolean(PREF_TAB_SORT_ENABLED, false)) {
            rememberTabOverviewOrderSnapshot(privateSection, indices);
            return indices;
        }
        final String key = preferences.getString(PREF_TAB_SORT_KEY, BOARD_SORT_VELOCITY);
        final boolean desc = preferences.getBoolean(PREF_TAB_SORT_DESC, true);
        final boolean nonThreadTop = preferences.getBoolean(PREF_TAB_NON_THREAD_TOP, true);
        for (int index : indices) {
            cachedSearchResultForTabOverview(tabs.get(index));
        }
        Collections.sort(indices, (leftIndex, rightIndex) -> {
            CuspTab leftTab = tabs.get(leftIndex);
            CuspTab rightTab = tabs.get(rightIndex);
            SearchResult left = cachedSearchResultForTabOverview(leftTab);
            SearchResult right = cachedSearchResultForTabOverview(rightTab);
            boolean leftThread = left != null;
            boolean rightThread = right != null;
            if (leftThread != rightThread) {
                return leftThread ? (nonThreadTop ? 1 : -1) : (nonThreadTop ? -1 : 1);
            }
            if (!leftThread) {
                return Integer.compare(leftIndex, rightIndex);
            }
            int compared = compareBoardSortValue(left, right, key);
            if (compared != 0) {
                return desc ? -compared : compared;
            }
            return Integer.compare(leftIndex, rightIndex);
        });
        rememberTabOverviewOrderSnapshot(privateSection, indices);
        return indices;
    }

    private List<Integer> restoredTabOverviewIndices(boolean privateSection, List<Integer> availableIndices) {
        if (privateSection || availableIndices == null || restoredTabOverviewNormalOrder.isEmpty()
                || !tabOverviewSortSignature().equals(restoredTabOverviewOrderSignature)
                || !tabOverviewOrderMatchesCurrent(restoredTabOverviewNormalOrder, false)) {
            return null;
        }
        Map<String, List<Integer>> indicesByKey = new LinkedHashMap<>();
        for (int index : availableIndices) {
            String key = tabOverviewIdentity(tabs.get(index));
            List<Integer> values = indicesByKey.get(key);
            if (values == null) {
                values = new ArrayList<>();
                indicesByKey.put(key, values);
            }
            values.add(index);
        }
        List<Integer> result = new ArrayList<>();
        for (String key : restoredTabOverviewNormalOrder) {
            List<Integer> values = indicesByKey.get(key);
            if (values == null || values.isEmpty()) {
                return null;
            }
            result.add(values.remove(0));
        }
        if (result.size() != availableIndices.size()) {
            return null;
        }
        clearRestoredTabOverviewOrderSnapshot();
        return result;
    }

    private void rememberTabOverviewOrderSnapshot(boolean privateSection, List<Integer> indices) {
        if (privateSection || indices == null) {
            return;
        }
        lastTabOverviewNormalOrder.clear();
        for (int index : indices) {
            if (index >= 0 && index < tabs.size()) {
                lastTabOverviewNormalOrder.add(tabOverviewIdentity(tabs.get(index)));
            }
        }
        lastTabOverviewOrderSignature = tabOverviewSortSignature();
    }

    private void clearRestoredTabOverviewOrderSnapshot() {
        restoredTabOverviewNormalOrder.clear();
        restoredTabOverviewOrderSignature = "";
    }

    private boolean tabOverviewOrderMatchesCurrent(List<String> order, boolean privateSection) {
        if (order == null) {
            return false;
        }
        Map<String, Integer> counts = new LinkedHashMap<>();
        int currentCount = 0;
        for (CuspTab tab : tabs) {
            if (tab == null || tab.privateBrowsing != privateSection || !isNormalTabScope(tab)) {
                continue;
            }
            String key = tabOverviewIdentity(tab);
            counts.put(key, counts.containsKey(key) ? counts.get(key) + 1 : 1);
            currentCount++;
        }
        if (order.size() != currentCount) {
            return false;
        }
        for (String key : order) {
            Integer count = counts.get(key);
            if (count == null || count <= 0) {
                return false;
            }
            counts.put(key, count - 1);
        }
        return true;
    }

    private String tabOverviewIdentity(CuspTab tab) {
        if (tab == null) {
            return "";
        }
        return (tab.nativeKind == null ? "" : tab.nativeKind) + "\n"
                + tab.tabScope.name() + "\n"
                + normalizeSavedFolder(tab.bookmarkOverviewFolder) + "\n"
                + normalizeHistoryUrl(tab.url == null ? "" : tab.url);
    }

    private String tabOverviewSortSignature() {
        if (preferences == null || !preferences.getBoolean(PREF_TAB_SORT_ENABLED, false)) {
            return "off";
        }
        return "on\n"
                + preferences.getString(PREF_TAB_SORT_KEY, BOARD_SORT_VELOCITY) + "\n"
                + preferences.getBoolean(PREF_TAB_SORT_DESC, true) + "\n"
                + preferences.getBoolean(PREF_TAB_NON_THREAD_TOP, true);
    }

    private boolean moveBookmarkToTabsFromPayload(DragPayload payload, int index) {
        if (payload == null) {
            return false;
        }
        if (PREF_THREAD_BOOKMARKS.equals(payload.key)) {
            moveBookmarkToTabsFromOverview(payload.index, index);
            return true;
        }
        String movingKey = bookmarkNodeDragValue(payload.key);
        if (movingKey.startsWith("I:")) {
            SavedItem item = savedItemByBookmarkKey(movingKey);
            int bookmarkIndex = savedItemIndex(PREF_THREAD_BOOKMARKS, item);
            if (bookmarkIndex >= 0) {
                moveBookmarkToTabsFromOverview(bookmarkIndex, index);
                return true;
            }
        }
        return false;
    }

    private View closedTabUndoBar() {
        LinearLayout bar = new LinearLayout(this);
        bar.setTag(CLOSED_TAB_UNDO_TAG);
        bar.setOrientation(LinearLayout.HORIZONTAL);
        bar.setGravity(Gravity.CENTER_VERTICAL);
        bar.setPadding(dp(14), 0, dp(6), 0);
        bar.setBackground(roundedDrawable(menuColor(), borderColor(), dp(8)));
        TextView message = new TextView(this);
        message.setText(text("\u30bf\u30d6\u3092\u9589\u3058\u307e\u3057\u305f", "Tab closed"));
        message.setTextColor(textColor());
        message.setTextSize(14);
        bar.addView(message, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        TextView undo = new TextView(this);
        undo.setText(text("\u5143\u306b\u623b\u3059", "Undo"));
        undo.setTextColor(TEAL);
        undo.setTextSize(14);
        undo.setGravity(Gravity.CENTER);
        undo.setPadding(dp(12), 0, dp(12), 0);
        undo.setOnClickListener(v -> undoClosedTab());
        bar.addView(undo, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.MATCH_PARENT));
        attachDismissSwipe(bar, () -> {
            recentlyClosedTab = null;
            if (clearClosedTabUndoTask != null) {
                mainHandler.removeCallbacks(clearClosedTabUndoTask);
                clearClosedTabUndoTask = null;
            }
            if (tabOverviewVisible) {
                syncClosedTabUndoBar();
            }
        });
        return bar;
    }

    private FrameLayout.LayoutParams closedTabUndoParams() {
        FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(48), Gravity.BOTTOM);
        params.setMargins(dp(12), 0, dp(12), dp(88));
        return params;
    }

    private void attachDismissSwipe(View view, Runnable dismiss) {
        final float[] downX = new float[1];
        final boolean[] dragging = new boolean[1];
        view.setOnTouchListener((v, event) -> {
            if (event.getAction() == MotionEvent.ACTION_DOWN) {
                downX[0] = event.getRawX();
                dragging[0] = false;
                v.clearAnimation();
                return true;
            }
            if (event.getAction() == MotionEvent.ACTION_MOVE) {
                float dx = event.getRawX() - downX[0];
                if (!dragging[0] && Math.abs(dx) > dp(10)) {
                    dragging[0] = true;
                }
                if (dragging[0]) {
                    v.setTranslationX(dx);
                    v.setAlpha(Math.max(0.25f, 1f - Math.abs(dx) / Math.max(1f, v.getWidth())));
                    return true;
                }
            }
            if (event.getAction() == MotionEvent.ACTION_UP || event.getAction() == MotionEvent.ACTION_CANCEL) {
                if (dragging[0] && Math.abs(v.getTranslationX()) > dp(90)) {
                    float target = v.getTranslationX() < 0 ? -v.getWidth() : v.getWidth();
                    v.animate().translationX(target).alpha(0f).setDuration(140).withEndAction(dismiss).start();
                    return true;
                }
                v.animate().translationX(0).alpha(1f).setDuration(120).start();
                return true;
            }
            return true;
        });
    }

    private View tabOverviewRow(CuspTab tab, int index) {
        boolean selected = !pendingNewTab && index == currentIndex;
        View.OnDragListener dragListener = (v, event) -> {
            autoScrollDuringDrag(v, event);
            if (event.getAction() == android.view.DragEvent.ACTION_DROP) {
                Object local = event.getLocalState();
                if (local instanceof DragPayload) {
                    DragPayload payload = (DragPayload) local;
                    if ("tabs".equals(payload.key)) {
                        moveTabInOverview(payload, index);
                        return true;
                    }
                    if (moveBookmarkToTabsFromPayload(payload, index)) {
                        return true;
                    }
                }
            }
            return true;
        };
        return tabOverviewRowShell(tab, selected,
                dragListener,
                v -> selectTabFromOverview(index),
                (row, shell) -> {
                    row.startDragAndDrop(ClipData.newPlainText("tab", String.valueOf(index)),
                            new View.DragShadowBuilder(shell), new DragPayload("tabs", index), 0);
                    return true;
                },
                text("\u30bf\u30d6\u3092\u9589\u3058\u308b", "Close tab"),
                shell -> closeTabFromOverview(tabs.indexOf(tab), shell),
                (row, deleteLeft, deleteRight, shell) ->
                        attachTabOverviewSwipe(row, deleteLeft, deleteRight, tab, index, shell));
    }

    private FrameLayout tabOverviewRowShell(CuspTab tab, boolean selected, View.OnDragListener dragListener,
                                            View.OnClickListener clickListener,
                                            TabOverviewLongClick longClickListener,
                                            String closeLabel,
                                            TabOverviewClose closeListener,
                                            TabOverviewSwipeSetup swipeSetup) {
        FrameLayout shell = new FrameLayout(this);
        shell.setClipChildren(false);
        shell.setBackgroundColor(Color.TRANSPARENT);
        shell.setOnDragListener(dragListener);
        ImageView deleteLeft = swipeActionIcon(R.drawable.ic_delete, Gravity.LEFT | Gravity.CENTER_VERTICAL);
        deleteLeft.setColorFilter(TEAL);
        ImageView deleteRight = swipeActionIcon(R.drawable.ic_delete, Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        deleteRight.setColorFilter(TEAL);
        shell.addView(deleteLeft);
        shell.addView(deleteRight);

        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(10), dp(7), dp(8), dp(7));
        row.setMinimumHeight(dp(86));
        row.setBackground(roundedDrawable(postColor(), selected ? TEAL : borderColor(), dp(8)));
        row.setOnClickListener(clickListener);
        row.setOnDragListener(dragListener);
        if (longClickListener != null) {
            row.setOnLongClickListener(v -> longClickListener.onLongClick(row, shell));
        }

        LinearLayout textBox = new LinearLayout(this);
        textBox.setOrientation(LinearLayout.VERTICAL);
        textBox.setOnDragListener(dragListener);
        TextView title = new TextView(this);
        String rowTitle = displayTitleForTab(tab);
        if (tab.threadPage != null) {
            setThreadTitleText(title, tab.threadPage, rowTitle);
        } else if (tab.knownThreadArchived) {
            setThreadTitleText(title, rowTitle, true);
        } else {
            title.setText(rowTitle);
        }
        tab.overviewTitle = rowTitle;
        title.setTextColor(textColor());
        title.setOnDragListener(dragListener);
        title.setTextSize(14);
        title.setSingleLine(false);
        title.setMaxLines(2);
        title.setEllipsize(TextUtils.TruncateAt.END);
        title.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
        title.setIncludeFontPadding(false);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            title.setAutoSizeTextTypeUniformWithConfiguration(11, 14, 1, TypedValue.COMPLEX_UNIT_SP);
        }
        textBox.addView(title, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(38)));
        View meta = tabOverviewMetaView(tab);
        meta.setOnDragListener(dragListener);
        textBox.addView(meta, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(30)));
        row.addView(textBox, new LinearLayout.LayoutParams(0, dp(68), 1));

        if (tab.privateBrowsing) {
            ImageView privateIcon = new ImageView(this);
            privateIcon.setImageResource(R.drawable.ic_private_glasses);
            privateIcon.setColorFilter(privateButtonIcon(true));
            LinearLayout.LayoutParams privateIconParams = new LinearLayout.LayoutParams(dp(26), dp(26));
            privateIconParams.setMargins(dp(8), 0, 0, 0);
            row.addView(privateIcon, privateIconParams);
        }

        ImageButton close = iconButton(R.drawable.ic_close, closeLabel, v -> closeListener.close(shell));
        close.setOnDragListener(dragListener);
        LinearLayout.LayoutParams closeParams = new LinearLayout.LayoutParams(dp(42), dp(40));
        closeParams.setMargins(dp(8), 0, 0, 0);
        row.addView(close, closeParams);

        LinearLayout.LayoutParams rowParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(86));
        rowParams.setMargins(0, 0, 0, dp(8));
        shell.setLayoutParams(rowParams);
        shell.addView(row, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(86)));
        swipeSetup.attach(row, deleteLeft, deleteRight, shell);
        return shell;
    }

    private View tabOverviewMetaView(CuspTab tab) {
        SearchResult result = cachedSearchResultForTabOverview(tab);
        if (result == null) {
            TextView empty = new TextView(this);
            empty.setText("");
            empty.setIncludeFontPadding(false);
            return empty;
        }
        return boardThreadMetaView(result, true);
    }

    private void clearTabOverviewResultCache() {
        tabOverviewResultCache.clear();
        tabOverviewBoardTitleCache.clear();
        tabOverviewHistoryUrlCache = null;
    }

    private SearchResult cachedSearchResultForTabOverview(CuspTab tab) {
        if (tab == null) {
            return null;
        }
        if (tabOverviewResultCache.containsKey(tab)) {
            return tabOverviewResultCache.get(tab);
        }
        SearchResult result = searchResultForTabOverview(tab);
        tabOverviewResultCache.put(tab, result);
        return result;
    }

    private String cachedBoardTitleForTabOverview(String url) {
        String key = url == null ? "" : url.trim();
        if (tabOverviewBoardTitleCache.containsKey(key)) {
            return tabOverviewBoardTitleCache.get(key);
        }
        String title = displayBoardTitle(url);
        tabOverviewBoardTitleCache.put(key, title);
        return title;
    }

    private boolean cachedThreadHistoryContainsForTabOverview(String url) {
        String target = normalizeHistoryUrl(url);
        if (target.isEmpty()) {
            return false;
        }
        if (tabOverviewHistoryUrlCache == null) {
            tabOverviewHistoryUrlCache = new LinkedHashSet<>();
            for (ThreadHistoryItem item : threadHistory()) {
                String normalized = normalizeHistoryUrl(item.url);
                if (!normalized.isEmpty()) {
                    tabOverviewHistoryUrlCache.add(normalized);
                }
            }
        }
        return tabOverviewHistoryUrlCache.contains(target);
    }

    private SearchResult searchResultForTabOverview(CuspTab tab) {
        DatAddress address = tab == null || tab.url == null || tab.url.trim().isEmpty()
                ? null : datAddress(tab.url);
        if (tab == null || tab.url == null || tab.url.trim().isEmpty() || address == null) {
            return null;
        }
        SearchResult result = new SearchResult();
        result.url = tab.url;
        result.boardName = tab.overviewBoardName == null || tab.overviewBoardName.trim().isEmpty()
                ? cachedBoardTitleForTabOverview(tab.url)
                : tab.overviewBoardName;
        tab.overviewBoardName = result.boardName;
        result.responses = Math.max(tab.knownMaxPostNumber, tab.knownPostCount);
        if (result.responses <= 0 && tab.threadPage != null) {
            result.responses = maxPostNumber(tab.threadPage);
        }
        result.createdAt = threadCreatedAtMillis(address.key);
        result.velocity = threadVelocity(address.key, result.responses);
        result.boardOrder = Math.max(0, tab.knownBoardOrder);
        result.hasReadHistory = cachedThreadHistoryContainsForTabOverview(tab.url)
                || tab.readPostNumber > 0 || result.responses > 0;
        result.unread = unreadCount(tab);
        return result;
    }

    private void restoreSavedTabOverviewResult(CuspTab tab) {
        DatAddress address = tab == null || tab.url == null || tab.url.trim().isEmpty()
                ? null : datAddress(tab.url);
        if (tab == null || tab.privateBrowsing || address == null
                || (!tab.hasThreadStats && tab.knownBoardOrder <= 0
                && (tab.overviewBoardName == null || tab.overviewBoardName.trim().isEmpty()))) {
            return;
        }
        boolean needsBoardName = showMetaField(PREF_BOARD_SHOW_BOARD_NAME, PREF_TAB_SHOW_BOARD_NAME, true)
                || BOARD_SORT_BOARD_NAME.equals(preferences.getString(PREF_TAB_SORT_KEY, BOARD_SORT_VELOCITY));
        if (needsBoardName && (tab.overviewBoardName == null || tab.overviewBoardName.trim().isEmpty())) {
            return;
        }
        SearchResult result = new SearchResult();
        result.url = tab.url;
        result.boardName = tab.overviewBoardName == null ? "" : tab.overviewBoardName;
        result.responses = Math.max(tab.knownMaxPostNumber, tab.knownPostCount);
        result.createdAt = threadCreatedAtMillis(address.key);
        result.velocity = threadVelocity(address.key, result.responses);
        result.boardOrder = Math.max(0, tab.knownBoardOrder);
        result.hasReadHistory = tab.readPostNumber > 0 || result.responses > 0 || tab.hasThreadStats;
        result.unread = Math.max(0, tab.cachedUnreadCount);
        tabOverviewResultCache.put(tab, result);
        if (!result.boardName.trim().isEmpty()) {
            tabOverviewBoardTitleCache.put(tab.url.trim(), result.boardName);
        }
    }

    private String overviewBoardNameForSave(CuspTab tab) {
        if (tab == null || tab.url == null || tab.url.trim().isEmpty() || datAddress(tab.url) == null) {
            return "";
        }
        SearchResult cached = tabOverviewResultCache.get(tab);
        if (cached != null && cached.boardName != null && !cached.boardName.trim().isEmpty()) {
            tab.overviewBoardName = cached.boardName.trim();
            return tab.overviewBoardName;
        }
        if (tab.overviewBoardName != null && !tab.overviewBoardName.trim().isEmpty()) {
            return tab.overviewBoardName.trim();
        }
        String cachedTitle = tabOverviewBoardTitleCache.get(tab.url.trim());
        if (cachedTitle != null && !cachedTitle.trim().isEmpty()) {
            tab.overviewBoardName = cachedTitle.trim();
            return tab.overviewBoardName;
        }
        return "";
    }

    private String overviewTitleForSave(CuspTab tab) {
        if (tab == null) {
            return "";
        }
        if (tab.overviewTitle != null && !tab.overviewTitle.trim().isEmpty()) {
            return tab.overviewTitle.trim();
        }
        String title = tab.title;
        return title == null ? "" : title.trim();
    }

    private interface TabOverviewLongClick {
        boolean onLongClick(View row, FrameLayout shell);
    }

    private interface TabOverviewClose {
        void close(FrameLayout shell);
    }

    private interface TabOverviewSwipeSetup {
        void attach(View row, View deleteLeft, View deleteRight, FrameLayout shell);
    }

    private void attachTabOverviewSwipe(View row, View deleteLeft, View deleteRight, CuspTab tab, int index, View shell) {
        final float[] downX = new float[1];
        final float[] downY = new float[1];
        final boolean[] dragging = new boolean[1];
        row.setOnTouchListener((v, event) -> {
            if (event.getAction() == MotionEvent.ACTION_DOWN) {
                downX[0] = event.getRawX();
                downY[0] = event.getRawY();
                dragging[0] = false;
                row.clearAnimation();
                return false;
            }
            if (event.getAction() == MotionEvent.ACTION_MOVE) {
                float dx = event.getRawX() - downX[0];
                float dy = event.getRawY() - downY[0];
                if (!dragging[0] && Math.abs(dx) > dp(12) && Math.abs(dx) > Math.abs(dy) * 1.4f) {
                    dragging[0] = true;
                    v.getParent().requestDisallowInterceptTouchEvent(true);
                }
                if (dragging[0]) {
                    float translation = Math.max(-dp(108), Math.min(dp(108), dx * 0.58f));
                    row.setTranslationX(translation);
                    deleteLeft.setAlpha(Math.max(0f, Math.min(1f, translation / dp(64))));
                    deleteRight.setAlpha(Math.max(0f, Math.min(1f, -translation / dp(64))));
                    return true;
                }
            }
            if (event.getAction() == MotionEvent.ACTION_UP || event.getAction() == MotionEvent.ACTION_CANCEL) {
                if (dragging[0]) {
                    float tx = row.getTranslationX();
                    row.animate().translationX(0).setDuration(130).start();
                    deleteLeft.animate().alpha(0f).setDuration(130).start();
                    deleteRight.animate().alpha(0f).setDuration(130).start();
                    if (event.getAction() == MotionEvent.ACTION_UP && Math.abs(tx) >= dp(54)) {
                        int closeIndex = tabs.indexOf(tab);
                        closeTabFromOverview(closeIndex, shell);
                    }
                    return true;
                }
            }
            return false;
        });
    }

    private void selectTabFromOverview(int index) {
        if (index < 0 || index >= tabs.size()) {
            return;
        }
        CuspTab target = tabs.get(index);
        rememberTabOverviewScroll();
        tabOverviewVisible = false;
        pendingNewTab = false;
        pendingHistoryAll = false;
        contentFrame.removeAllViews();
        contentFrame.addView(loadingView(""));
        updateBottomThreadBar(target);
        renderTabs();
        mainHandler.post(() -> {
            int liveIndex = tabs.indexOf(target);
            if (liveIndex >= 0) {
                switchToTab(liveIndex, true);
            }
        });
    }

    private void moveTabInOverview(DragPayload payload, int to) {
        int from = payload.index;
        if (from < 0 || from >= tabs.size() || to < 0 || to >= tabs.size() || from == to) {
            return;
        }
        CuspTab selected = currentTab();
        CuspTab moved = tabs.remove(from);
        tabs.add(to, moved);
        clearRestoredTabOverviewOrderSnapshot();
        currentIndex = selected == null ? Math.min(to, tabs.size() - 1) : tabs.indexOf(selected);
        payload.index = to;
        renderTabs();
        saveTabs(false);
        if (tabOverviewVisible) {
            refreshTabOverviewTabSlotsOnly();
        }
    }

    private boolean refreshTabOverviewTabSlotsOnly() {
        ScrollView scroll = findScrollView(contentFrame);
        if (scroll == null || scroll.getChildCount() == 0 || !(scroll.getChildAt(0) instanceof LinearLayout)) {
            return false;
        }
        LinearLayout list = (LinearLayout) scroll.getChildAt(0);
        if (!isTabOverviewList(list)) {
            return false;
        }
        setTabOverviewListPadding(list);
        List<Integer> desiredIndices = tabOverviewIndices(tabOverviewPrivateMode);
        List<FrameLayout> holders = tabOverviewSlotHolders(list);
        if (holders.isEmpty()) {
            return populateEmptyTabOverviewSlots(scroll, list, desiredIndices);
        }
        VirtualTabOverviewState state = list.getTag() instanceof VirtualTabOverviewState
                ? (VirtualTabOverviewState) list.getTag() : null;
        if (syncTabOverviewSlotsInPlace(list, holders, desiredIndices, state)) {
            scheduleTabOverviewSlotRefresh(list);
            syncClosedTabUndoBar();
            return true;
        }
        Map<CuspTab, FrameLayout> holderByTab = new LinkedHashMap<>();
        for (FrameLayout holder : holders) {
            Object tag = holder.getTag();
            if (!(tag instanceof VirtualTabOverviewSlot)) {
                continue;
            }
            VirtualTabOverviewSlot slot = (VirtualTabOverviewSlot) tag;
            CuspTab tab = slot.tab;
            if (tab == null && slot.index >= 0 && slot.index < tabs.size()) {
                tab = tabs.get(slot.index);
            }
            if (tab != null) {
                holderByTab.put(tab, holder);
            }
        }

        int insertAt = list.indexOfChild(holders.get(0));
        if (desiredIndices.isEmpty()) {
            for (int i = holders.size() - 1; i >= 0; i--) {
                FrameLayout holder = holders.get(i);
                if (state != null) {
                    state.renderedSlots.remove(holder);
                }
                list.removeView(holder);
            }
            addEmptyTabOverviewRow(list);
            syncClosedTabUndoBar();
            return true;
        }

        for (int i = 0; i < desiredIndices.size(); i++) {
            int tabIndex = desiredIndices.get(i);
            if (tabIndex < 0 || tabIndex >= tabs.size()) {
                continue;
            }
            CuspTab tab = tabs.get(tabIndex);
            FrameLayout holder = holderByTab.remove(tab);
            if (holder == null) {
                holder = createTabOverviewSlotHolder(new VirtualTabOverviewSlot(tabIndex, tab));
            }
            int currentChildIndex = list.indexOfChild(holder);
            if (currentChildIndex >= 0 && currentChildIndex != insertAt) {
                list.removeView(holder);
                if (currentChildIndex < insertAt) {
                    insertAt--;
                }
                list.addView(holder, Math.max(0, Math.min(insertAt, list.getChildCount())),
                        holder.getLayoutParams() == null ? tabOverviewSlotLayoutParams() : holder.getLayoutParams());
            } else if (currentChildIndex < 0) {
                list.addView(holder, Math.max(0, Math.min(insertAt, list.getChildCount())),
                        holder.getLayoutParams() == null ? tabOverviewSlotLayoutParams() : holder.getLayoutParams());
            }
            VirtualTabOverviewSlot slot = holder.getTag() instanceof VirtualTabOverviewSlot
                    ? (VirtualTabOverviewSlot) holder.getTag()
                    : new VirtualTabOverviewSlot(tabIndex, tab);
            slot.index = tabIndex;
            slot.tab = tab;
            bindTabOverviewSlot(holder, slot);
            if (slot.rendered) {
                slot.rendered = false;
                if (state != null) {
                    state.renderedSlots.remove(holder);
                }
                renderTabOverviewSlot(holder, slot);
            }
            insertAt++;
        }

        for (FrameLayout holder : holderByTab.values()) {
            if (state != null) {
                state.renderedSlots.remove(holder);
            }
            if (holder.getParent() == list) {
                list.removeView(holder);
            }
        }
        scheduleTabOverviewSlotRefresh(list);
        syncClosedTabUndoBar();
        return true;
    }

    private boolean populateEmptyTabOverviewSlots(ScrollView scroll, LinearLayout list, List<Integer> desiredIndices) {
        if (list == null || desiredIndices == null) {
            return false;
        }
        int insertAt = tabOverviewTabSectionStart(list);
        if (insertAt < 0) {
            return false;
        }
        if (desiredIndices.isEmpty()) {
            syncClosedTabUndoBar();
            return true;
        }
        View existing = insertAt < list.getChildCount() ? list.getChildAt(insertAt) : null;
        if (existing != null && TAB_OVERVIEW_EMPTY_TAG.equals(existing.getTag())) {
            list.removeViewAt(insertAt);
        }
        if (!(list.getTag() instanceof VirtualTabOverviewState)) {
            setupVirtualTabOverviewRefresh(scroll, list);
        }
        for (int i = 0; i < desiredIndices.size(); i++) {
            int tabIndex = desiredIndices.get(i);
            if (tabIndex < 0 || tabIndex >= tabs.size()) {
                continue;
            }
            CuspTab tab = tabs.get(tabIndex);
            FrameLayout holder = createTabOverviewSlotHolder(new VirtualTabOverviewSlot(tabIndex, tab));
            list.addView(holder, Math.max(0, Math.min(insertAt + i, list.getChildCount())),
                    tabOverviewSlotLayoutParams());
            Object tag = holder.getTag();
            if (tag instanceof VirtualTabOverviewSlot) {
                renderTabOverviewSlot(holder, (VirtualTabOverviewSlot) tag);
            }
        }
        scheduleTabOverviewSlotRefresh(list);
        syncClosedTabUndoBar();
        return true;
    }

    private boolean syncTabOverviewSlotsInPlace(LinearLayout list, List<FrameLayout> holders,
                                                List<Integer> desiredIndices,
                                                VirtualTabOverviewState state) {
        if (list == null || holders == null || desiredIndices == null || desiredIndices.isEmpty()) {
            return false;
        }
        Map<CuspTab, Integer> desiredIndexByTab = new LinkedHashMap<>();
        List<CuspTab> desiredTabs = new ArrayList<>();
        for (int index : desiredIndices) {
            if (index < 0 || index >= tabs.size()) {
                continue;
            }
            CuspTab tab = tabs.get(index);
            desiredTabs.add(tab);
            desiredIndexByTab.put(tab, index);
        }
        if (desiredTabs.isEmpty()) {
            return false;
        }

        for (FrameLayout holder : new ArrayList<>(holders)) {
            Object tag = holder.getTag();
            if (!(tag instanceof VirtualTabOverviewSlot)) {
                return false;
            }
            VirtualTabOverviewSlot slot = (VirtualTabOverviewSlot) tag;
            if (!desiredIndexByTab.containsKey(slot.tab)) {
                if (state != null) {
                    state.renderedSlots.remove(holder);
                }
                list.removeView(holder);
                holders.remove(holder);
            }
        }
        if (holders.size() != desiredTabs.size()) {
            return false;
        }
        for (int i = 0; i < holders.size(); i++) {
            Object tag = holders.get(i).getTag();
            if (!(tag instanceof VirtualTabOverviewSlot)
                    || ((VirtualTabOverviewSlot) tag).tab != desiredTabs.get(i)) {
                return false;
            }
        }
        for (int i = 0; i < holders.size(); i++) {
            FrameLayout holder = holders.get(i);
            VirtualTabOverviewSlot slot = (VirtualTabOverviewSlot) holder.getTag();
            CuspTab tab = desiredTabs.get(i);
            int nextIndex = desiredIndexByTab.get(tab);
            boolean nextSelected = !pendingNewTab && nextIndex == currentIndex;
            boolean needsRender = slot.rendered && (slot.index != nextIndex
                    || slot.selected != nextSelected
                    || tabOverviewValueDirtyTabs.contains(tab));
            slot.index = nextIndex;
            slot.tab = tab;
            bindTabOverviewSlot(holder, slot);
            if (needsRender) {
                if (state != null) {
                    state.renderedSlots.remove(holder);
                }
                slot.rendered = false;
                renderTabOverviewSlot(holder, slot);
            }
        }
        return true;
    }

    private List<FrameLayout> tabOverviewSlotHolders(LinearLayout list) {
        List<FrameLayout> holders = new ArrayList<>();
        if (list == null) {
            return holders;
        }
        for (int i = 0; i < list.getChildCount(); i++) {
            View child = list.getChildAt(i);
            if (child instanceof FrameLayout && child.getTag() instanceof VirtualTabOverviewSlot) {
                holders.add((FrameLayout) child);
            }
        }
        return holders;
    }

    private void addEmptyTabOverviewRow(LinearLayout list) {
        if (list == null) {
            return;
        }
        TextView empty = helperLine(tabOverviewPrivateMode
                ? text("\u30d7\u30e9\u30a4\u30d9\u30fc\u30c8\u30bf\u30d6\u306a\u3057", "No private tabs.")
                : text("\u901a\u5e38\u30bf\u30d6\u306a\u3057", "No normal tabs."));
        empty.setTag(TAB_OVERVIEW_EMPTY_TAG);
        empty.setOnDragListener((v, event) -> {
            autoScrollDuringDrag(v, event);
            if (event.getAction() == android.view.DragEvent.ACTION_DROP) {
                Object local = event.getLocalState();
                if (local instanceof DragPayload) {
                    return moveBookmarkToTabsFromPayload((DragPayload) local, tabs.size());
                }
            }
            return true;
        });
        list.addView(empty);
    }

    private void autoScrollDuringDrag(View anchor, android.view.DragEvent event) {
        if (event == null || anchor == null) {
            return;
        }
        int action = event.getAction();
        if (action == android.view.DragEvent.ACTION_DRAG_ENDED
                || action == android.view.DragEvent.ACTION_DROP
                || action == android.view.DragEvent.ACTION_DRAG_EXITED) {
            stopDragAutoScroll();
            return;
        }
        if (action != android.view.DragEvent.ACTION_DRAG_LOCATION) {
            return;
        }
        ScrollView scroll = anchor instanceof ScrollView ? (ScrollView) anchor : findParentScrollView(anchor);
        if (scroll == null || scroll.getHeight() <= 0) {
            stopDragAutoScroll();
            return;
        }
        int[] anchorLocation = new int[2];
        anchor.getLocationOnScreen(anchorLocation);
        float screenY = anchorLocation[1] + event.getY();
        Rect visibleFrame = new Rect();
        getWindow().getDecorView().getWindowVisibleDisplayFrame(visibleFrame);
        int edge = dp(48);
        int maxStep = dp(34);
        int minStep = dp(5);
        int nextDelta = 0;
        if (screenY <= visibleFrame.top + edge) {
            float ratio = Math.min(1f, Math.max(0f, (visibleFrame.top + edge - screenY) / Math.max(1f, edge)));
            nextDelta = -Math.max(minStep, Math.round(maxStep * ratio));
        } else if (screenY >= visibleFrame.bottom - edge) {
            float ratio = Math.min(1f, Math.max(0f, (screenY - (visibleFrame.bottom - edge)) / Math.max(1f, edge)));
            nextDelta = Math.max(minStep, Math.round(maxStep * ratio));
        }
        if (nextDelta == 0) {
            stopDragAutoScroll();
            return;
        }
        dragAutoScrollView = scroll;
        dragAutoScrollDelta = nextDelta;
        startDragAutoScroll();
    }

    private void startDragAutoScroll() {
        if (dragAutoScrollTask != null) {
            return;
        }
        dragAutoScrollTask = new Runnable() {
            @Override
            public void run() {
                if (dragAutoScrollView == null || dragAutoScrollDelta == 0) {
                    dragAutoScrollTask = null;
                    return;
                }
                dragAutoScrollView.scrollBy(0, dragAutoScrollDelta);
                mainHandler.postDelayed(this, 16);
            }
        };
        mainHandler.post(dragAutoScrollTask);
    }

    private void stopDragAutoScroll() {
        dragAutoScrollView = null;
        dragAutoScrollDelta = 0;
        if (dragAutoScrollTask != null) {
            mainHandler.removeCallbacks(dragAutoScrollTask);
            dragAutoScrollTask = null;
        }
    }

    private ScrollView findParentScrollView(View view) {
        View current = view;
        while (current != null) {
            if (current instanceof ScrollView) {
                return (ScrollView) current;
            }
            ViewParent parent = current.getParent();
            current = parent instanceof View ? (View) parent : null;
        }
        return findScrollView(view);
    }

    private void closeTabFromOverview(int index) {
        closeTabFromOverview(index, null);
    }

    private void closeTabFromOverview(int index, View rowView) {
        ClosedTab closed = removeTabForOverview(index);
        if (closed == null) {
            return;
        }
        showClosedTabUndo(closed);
        syncClosedTabUndoBar();
        tabOverviewVisible = true;
        pendingNewTab = tabs.isEmpty();
        syncLoadingUiWithCurrentSurface();
        updateBottomThreadBar(currentTab());
        renderTabs();
        if (rowView == null || rowView.getParent() == null) {
            if (!refreshTabOverviewTabSlotsOnly()) {
                refreshTabOverviewListOnly();
            }
            return;
        }
        animateTabOverviewRowRemoval(rowView);
    }

    private void animateTabOverviewRowRemoval(View rowView) {
        Object slotTag = tabOverviewSlotTagForRow(rowView);
        boolean tabSlotRow = slotTag instanceof VirtualTabOverviewSlot;
        boolean bookmarkSlotRow = slotTag instanceof VirtualBookmarkOverviewSlot;
        boolean slotRow = tabSlotRow || bookmarkSlotRow;
        View animatedGap = slotRow && rowView.getParent() instanceof View
                ? (View) rowView.getParent() : rowView;
        int startHeight = animatedGap.getHeight() > 0 ? animatedGap.getHeight() : dp(86);
        rowView.animate().cancel();
        rowView.setAlpha(0f);
        rowView.setVisibility(View.INVISIBLE);
        rowView.setTranslationX(0f);
        ValueAnimator heightAnimator = ValueAnimator.ofInt(startHeight, 0);
        heightAnimator.setDuration(130);
        heightAnimator.addUpdateListener(animation -> {
            ViewGroup.LayoutParams params = animatedGap.getLayoutParams();
            if (params != null) {
                params.height = (Integer) animation.getAnimatedValue();
                animatedGap.setLayoutParams(params);
            }
        });
        heightAnimator.addListener(new android.animation.AnimatorListenerAdapter() {
            @Override
            public void onAnimationEnd(android.animation.Animator animation) {
                if (contentFrame != null && tabOverviewVisible) {
                    if (tabSlotRow) {
                        if (!refreshTabOverviewTabSlotsOnly()) {
                            refreshTabOverviewListOnly();
                        }
                    } else if (bookmarkSlotRow) {
                        if (!refreshTabOverviewBookmarkSectionOnly()) {
                            refreshTabOverviewListOnly();
                        }
                    } else {
                        refreshTabOverview();
                    }
                }
            }
        });
        heightAnimator.start();
    }

    private Object tabOverviewSlotTagForRow(View rowView) {
        if (rowView == null || !(rowView.getParent() instanceof FrameLayout)) {
            return null;
        }
        Object tag = ((FrameLayout) rowView.getParent()).getTag();
        return tag instanceof VirtualTabOverviewSlot || tag instanceof VirtualBookmarkOverviewSlot
                ? tag : null;
    }

    private void resetNewTabHistory() {
        newTabNavigationHistory.clear();
        newTabNavigationHistory.add("home");
        newTabNavigationIndex = 0;
    }

    private void recordNewTabPage(String page) {
        if (!pendingNewTab || page == null || page.isEmpty()) {
            return;
        }
        if (newTabNavigationIndex >= 0
                && newTabNavigationIndex < newTabNavigationHistory.size()
                && page.equals(newTabNavigationHistory.get(newTabNavigationIndex))) {
            return;
        }
        while (newTabNavigationHistory.size() > newTabNavigationIndex + 1) {
            newTabNavigationHistory.remove(newTabNavigationHistory.size() - 1);
        }
        newTabNavigationHistory.add(page);
        newTabNavigationIndex = newTabNavigationHistory.size() - 1;
    }

    private String encodeNewTabToken(String value) {
        try {
            return URLEncoder.encode(value == null ? "" : value, "UTF-8");
        } catch (Exception error) {
            return value == null ? "" : value;
        }
    }

    private String decodeNewTabToken(String value) {
        try {
            return URLDecoder.decode(value == null ? "" : value, "UTF-8");
        } catch (Exception error) {
            return value == null ? "" : value;
        }
    }

    private void navigateNewTabHistory(int direction) {
        int next = newTabNavigationIndex + direction;
        if (next < 0 || next >= newTabNavigationHistory.size()) {
            return;
        }
        newTabNavigationIndex = next;
        renderNewTabPage(newTabNavigationHistory.get(newTabNavigationIndex), false);
    }

    private void renderNewTabPage(String page, boolean record) {
        progressBar.setVisibility(View.GONE);
        if (record) {
            recordNewTabPage(page);
        }
        if ("history".equals(page)) {
            pendingHistoryAll = true;
            contentFrame.removeAllViews();
            contentFrame.addView(buildHistoryView());
        } else if ("fulltext-search".equals(page)) {
            pendingHistoryAll = false;
            contentFrame.removeAllViews();
            contentFrame.addView(buildFullTextSearchHomeView(false));
        } else if ("5ch".equals(page)) {
            showFiveChBoardsView(record);
        } else if (page != null && page.startsWith("bbs:")) {
            String menuUrl = decodeNewTabToken(page.substring("bbs:".length()));
            showBbsDirectoryIndexView(menuUrl, bbsRootPageKey(menuUrl), record);
        } else if (page != null && page.startsWith("5ch-category:")) {
            showFiveChCategoryView(page.substring("5ch-category:".length()), record);
        } else if (page != null && page.startsWith("bbs-category:")) {
            showBbsCategoryView(page.substring("bbs-category:".length()), record);
        } else if (page != null && page.startsWith("saved:")) {
            SavedPage savedPage = savedPageFromToken(page.substring("saved:".length()));
            showSavedItemsView(savedPage.key, savedPage.folder, record);
        } else {
            pendingHistoryAll = false;
            contentFrame.removeAllViews();
            contentFrame.addView(buildSearchHomeView(false));
        }
        addressBar.setText("");
        clearAddressFocus();
        renderTabs();
    }

    private ClosedTab removeTabForOverview(int index) {
        if (tabs.isEmpty() || index < 0 || index >= tabs.size()) {
            return null;
        }
        int oldCurrent = currentIndex;
        CuspTab closing = tabs.get(index);
        clearLoadingUiForClosedTab(closing, index == oldCurrent);
        tabs.remove(index);
        for (CuspTab tab : tabs) {
            if (tab.returnToIndex == index) {
                tab.returnToIndex = -1;
            } else if (tab.returnToIndex > index) {
                tab.returnToIndex--;
            }
        }
        if (tabs.isEmpty()) {
            currentIndex = -1;
        } else if (index < currentIndex) {
            currentIndex--;
        } else if (index == currentIndex) {
            currentIndex = Math.max(0, Math.min(index, tabs.size() - 1));
        } else {
            currentIndex = Math.max(0, Math.min(currentIndex, tabs.size() - 1));
        }
        requestSaveTabsSoon();
        return new ClosedTab(closing, index, oldCurrent);
    }

    private void showClosedTabUndo(ClosedTab closed) {
        recentlyClosedTab = closed;
        if (clearClosedTabUndoTask != null) {
            mainHandler.removeCallbacks(clearClosedTabUndoTask);
        }
        clearClosedTabUndoTask = () -> {
            recentlyClosedTab = null;
            clearClosedTabUndoTask = null;
            if (tabOverviewVisible && contentFrame != null) {
                syncClosedTabUndoBar();
            }
        };
        mainHandler.postDelayed(clearClosedTabUndoTask, 4500);
    }

    private void undoClosedTab() {
        ClosedTab closed = recentlyClosedTab;
        if (closed == null) {
            return;
        }
        if (clearClosedTabUndoTask != null) {
            mainHandler.removeCallbacks(clearClosedTabUndoTask);
            clearClosedTabUndoTask = null;
        }
        if (closed.savedItem != null) {
            restoreDeletedBookmark(closed.savedItem, closed.savedItemIndex);
            recentlyClosedTab = null;
            refreshTabOverview();
            return;
        }
        int insertIndex = Math.max(0, Math.min(closed.index, tabs.size()));
        tabs.add(insertIndex, closed.tab);
        for (CuspTab tab : tabs) {
            if (tab != closed.tab && tab.returnToIndex >= insertIndex) {
                tab.returnToIndex++;
            }
        }
        if (closed.oldCurrentIndex < 0 || tabs.size() == 1) {
            currentIndex = insertIndex;
        } else if (closed.oldCurrentIndex >= insertIndex) {
            currentIndex = Math.min(tabs.size() - 1, closed.oldCurrentIndex);
        } else {
            currentIndex = Math.min(tabs.size() - 1, closed.oldCurrentIndex);
        }
        pendingNewTab = false;
        recentlyClosedTab = null;
        requestSaveTabsSoon();
        if (tabOverviewVisible && contentFrame != null) {
            if (!refreshTabOverviewTabSlotsOnly()) {
                refreshTabOverviewListOnly();
            }
            updateBottomThreadBar(currentTab());
            renderTabs();
        }
    }

    private View savedListButton(String label, String key) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(10), dp(8), dp(10), dp(8));
        row.setBackgroundColor(postColor());
        LinearLayout.LayoutParams rowParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        rowParams.setMargins(0, 0, 0, dp(8));
        row.setLayoutParams(rowParams);

        ImageView icon = new ImageView(this);
        icon.setImageResource(R.drawable.ic_star);
        icon.setColorFilter(TEAL);
        row.addView(icon, new LinearLayout.LayoutParams(dp(26), dp(26)));

        TextView textView = new TextView(this);
        textView.setText(label + "  " + readSavedItems(key).size());
        textView.setTextColor(TEAL);
        textView.setTextSize(14);
        textView.setPadding(dp(10), 0, 0, 0);
        row.addView(textView, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        row.setOnClickListener(v -> showSavedItemsView(key));
        return row;
    }

    private void showSavedItemsView(String key) {
        showSavedItemsView(key, "", true);
    }

    private void showSavedItemsView(String key, boolean recordHistory) {
        showSavedItemsView(key, "", recordHistory);
    }

    private void showSavedItemsView(String key, String folder) {
        showSavedItemsView(key, folder, true);
    }

    private void showSavedItemsView(String key, String folder, boolean recordHistory) {
        folder = normalizeSavedFolder(folder);
        final String targetKey = key == null ? "" : key;
        final String targetFolder = folder;
        if (pendingNewTab) {
            String page = "saved:" + savedPageToken(targetKey, targetFolder);
            if (recordHistory) {
                recordNewTabPage(page);
            }
            contentFrame.removeAllViews();
            contentFrame.addView(loadingView(""));
            renderTabs();
            mainHandler.post(() -> {
                String currentPage = newTabNavigationIndex >= 0
                        && newTabNavigationIndex < newTabNavigationHistory.size()
                        ? newTabNavigationHistory.get(newTabNavigationIndex) : "";
                if (!pendingNewTab || !page.equals(currentPage)) {
                    return;
                }
                View view = buildSavedItemsView(targetKey, targetFolder);
                contentFrame.removeAllViews();
                contentFrame.addView(view);
                renderTabs();
            });
        } else {
            CuspTab tab = currentTab();
            if (tab != null) {
                String url = savedPageUrl(targetKey, targetFolder);
                tab.readerMode = true;
                tab.nativeKind = NATIVE_SAVED;
                tab.url = url;
                tab.title = savedListTitle(targetKey, targetFolder);
                tab.threadPage = null;
                tab.searchPage = null;
                tab.threadScroll = null;
                tab.postViews = null;
                tab.readerView = loadingView("");
                showCurrentReaderView(tab);
                renderTabs();
                CuspTab targetTab = tab;
                mainHandler.post(() -> {
                    if (!tabs.contains(targetTab) || !NATIVE_SAVED.equals(targetTab.nativeKind)
                            || !url.equals(targetTab.url)) {
                        return;
                    }
                    View view = buildSavedItemsView(targetKey, targetFolder);
                    targetTab.readerView = view;
                    if (targetTab == currentTab() && !tabOverviewVisible && !pendingNewTab) {
                        showCurrentReaderView(targetTab);
                        renderTabs();
                    }
                    requestSaveTabsSoon();
                });
            }
        }
    }

    private void moveBookmarkToTabsFromOverview(int bookmarkIndex, int to) {
        List<SavedItem> items = readSavedItems(PREF_THREAD_BOOKMARKS);
        if (bookmarkIndex < 0 || bookmarkIndex >= items.size()) {
            return;
        }
        SavedItem item = items.get(bookmarkIndex);
        CuspTab tab = bookmarkOverviewTab(item);
        applyThreadTabScope(tab, TabScope.NORMAL, "");
        tab.readerView = loadingView("");
        int insert = Math.max(0, Math.min(to, tabs.size()));
        tabs.add(insert, tab);
        removeSavedItem(PREF_THREAD_BOOKMARKS, item);
        if (currentIndex >= insert) {
            currentIndex++;
        }
        requestSaveTabsSoon();
        renderTabs();
        if (tabOverviewVisible && contentFrame != null) {
            refreshTabOverviewListOnly();
        }
    }

    private void addBookmarkOverviewSection(LinearLayout list) {
        addBookmarkOverviewSection(list, false);
    }

    private void addBookmarkOverviewSection(LinearLayout list, boolean deferRows) {
        addBookmarkOverviewSection(list, deferRows, bookmarkOverviewSnapshot());
    }

    private void addBookmarkOverviewSection(LinearLayout list, boolean deferRows,
                                            BookmarkOverviewSnapshot snapshot) {
        if (list == null || snapshot == null) {
            return;
        }
        int generation = ++bookmarkOverviewRenderGeneration;
        List<SavedItem> bookmarks = snapshot.bookmarks;
        String selectedFolder = selectedBookmarkOverviewFolder(bookmarks);
        String rootKey = bookmarkOverviewExpandedKey("");
        boolean rootExpanded = bookmarkOverviewExpanded(rootKey, true);
        View rootRow = bookmarkOverviewFolderRow(snapshot, "", selectedFolder, 0);
        int tabStart = tabOverviewTabSectionStart(list);
        if (tabStart >= 0) {
            list.addView(rootRow, tabStart);
        } else {
            list.addView(rootRow);
        }
        if (!rootExpanded) {
            bookmarkOverviewDirty = false;
            return;
        }
        List<BookmarkOverviewEntry> entries = new ArrayList<>();
        collectBookmarkOverviewEntries(entries, snapshot, bookmarkChildren("", snapshot), 1);
        int initialEnd = deferRows ? Math.min(entries.size(), TAB_OVERVIEW_INITIAL_SLOT_BATCH) : entries.size();
        appendBookmarkOverviewEntries(list, snapshot, selectedFolder, entries, 0, initialEnd);
        if (deferRows && initialEnd < entries.size()) {
            list.post(() -> appendDeferredBookmarkOverviewEntries(
                    list, snapshot, selectedFolder, entries, generation, initialEnd));
        }
        bookmarkOverviewDirty = false;
    }

    private void collectBookmarkOverviewEntries(List<BookmarkOverviewEntry> entries,
                                                BookmarkOverviewSnapshot snapshot,
                                                List<BookmarkNode> nodes,
                                                int indentLevel) {
        if (entries == null || nodes == null) {
            return;
        }
        for (BookmarkNode node : nodes) {
            if (node.folderNode) {
                entries.add(BookmarkOverviewEntry.folder(node.folder, indentLevel));
                if (bookmarkOverviewExpanded(bookmarkOverviewExpandedKey(node.folder), false)) {
                    collectBookmarkOverviewEntries(entries, snapshot,
                            bookmarkChildren(node.folder, snapshot), indentLevel + 1);
                }
            } else {
                entries.add(BookmarkOverviewEntry.item(node.item, indentLevel));
            }
        }
    }

    private void appendBookmarkOverviewEntries(LinearLayout list, BookmarkOverviewSnapshot snapshot,
                                               String selectedFolder,
                                               List<BookmarkOverviewEntry> entries,
                                               int start, int end) {
        if (list == null || entries == null) {
            return;
        }
        int insert = Math.max(0, Math.min(list.getChildCount(), tabOverviewTabSectionStart(list)));
        if (insert <= 0) {
            insert = list.getChildCount();
        }
        for (int i = Math.max(0, start); i < end && i < entries.size(); i++) {
            BookmarkOverviewEntry entry = entries.get(i);
            View child = entry.folderNode
                    ? bookmarkOverviewFolderRow(snapshot, entry.folder, selectedFolder, entry.indentLevel)
                    : bookmarkOverviewItemSlot(entry.item, entry.indentLevel, snapshot);
            list.addView(child, Math.max(0, Math.min(insert++, list.getChildCount())));
        }
    }

    private void appendDeferredBookmarkOverviewEntries(LinearLayout list, BookmarkOverviewSnapshot snapshot,
                                                       String selectedFolder,
                                                       List<BookmarkOverviewEntry> entries,
                                                       int generation, int start) {
        if (!tabOverviewVisible || list == null || list.getParent() == null
                || generation != bookmarkOverviewRenderGeneration) {
            return;
        }
        int end = Math.min(entries.size(), start + TAB_OVERVIEW_DEFERRED_SLOT_BATCH);
        appendBookmarkOverviewEntries(list, snapshot, selectedFolder, entries, start, end);
        scheduleTabOverviewSlotRefresh(list);
        if (end < entries.size()) {
            list.postDelayed(() -> appendDeferredBookmarkOverviewEntries(
                    list, snapshot, selectedFolder, entries, generation, end),
                    TAB_OVERVIEW_DEFERRED_SLOT_DELAY_MS);
        }
    }

    private BookmarkOverviewSnapshot bookmarkOverviewSnapshot() {
        return bookmarkOverviewSnapshot(bookmarkOverviewOpenThreadTabs(), -1);
    }

    private BookmarkOverviewSnapshot bookmarkOverviewSnapshot(Map<String, CuspTab> openThreadTabs,
                                                               int expectedGeneration) {
        BookmarkOverviewSnapshot cached = readBookmarkOverviewRenderCache(openThreadTabs);
        if (cached != null) {
            return cached;
        }
        List<SavedItem> bookmarks = readSavedItems(PREF_THREAD_BOOKMARKS);
        List<String> folders = readSavedFolders(PREF_THREAD_BOOKMARKS, bookmarks);
        JSONObject orderRoot = preferenceJsonObject(PREF_BOOKMARK_ORDER);
        JSONObject statusRoot = preferenceJsonObject(PREF_BOOKMARK_OVERVIEW_STATUS);
        JSONObject readPosts = readHistoryEnabled() ? preferenceJsonObject(PREF_READ_POSTS) : new JSONObject();
        Map<String, Integer> itemIndices = new LinkedHashMap<>();
        Map<String, Integer> unreadByFolder = new LinkedHashMap<>();
        Map<String, CuspTab> safeOpenThreadTabs = openThreadTabs == null
                ? new LinkedHashMap<>() : openThreadTabs;
        for (int i = 0; i < bookmarks.size(); i++) {
            SavedItem bookmark = bookmarks.get(i);
            itemIndices.put(savedItemIdentity(bookmark.url, bookmark.folder), i);
            if (!bookmarkSupportsUnread(bookmark)) {
                continue;
            }
            BookmarkOverviewStatus status = bookmarkOverviewStatus(bookmark.url, statusRoot);
            int responseCount = status == null ? 0 : status.responseCount;
            CuspTab openTab = matchingBookmarkOverviewOpenTab(bookmark.url, safeOpenThreadTabs);
            if (openTab != null && openTab.hasThreadStats) {
                responseCount = Math.max(responseCount, Math.max(openTab.knownMaxPostNumber, openTab.knownPostCount));
            }
            if (responseCount <= 0) {
                continue;
            }
            int read = readPosts.optInt(bookmark.url, 0);
            if (openTab != null) {
                read = Math.max(read, openTab.readPostNumber);
            }
            int unread = Math.max(0, responseCount - read);
            if (unread <= 0) {
                continue;
            }
            addBookmarkOverviewUnread(unreadByFolder, "", unread);
            String folder = normalizeSavedFolder(bookmark.folder);
            while (!folder.isEmpty()) {
                addBookmarkOverviewUnread(unreadByFolder, folder, unread);
                folder = parentSavedFolder(folder);
            }
        }
        BookmarkOverviewSnapshot snapshot = new BookmarkOverviewSnapshot(
                bookmarks, folders, orderRoot, statusRoot, readPosts, itemIndices, unreadByFolder,
                safeOpenThreadTabs);
        if (expectedGeneration < 0 || expectedGeneration == bookmarkOverviewRenderGeneration) {
            writeBookmarkOverviewRenderCache(snapshot);
        }
        return snapshot;
    }

    private Map<String, CuspTab> bookmarkOverviewOpenThreadTabs() {
        Map<String, CuspTab> openTabs = new LinkedHashMap<>();
        for (CuspTab tab : tabs) {
            if (tab == null || isBookmarkTabScope(tab) || !NATIVE_THREAD.equals(tab.nativeKind)) {
                continue;
            }
            for (String key : threadHistoryKeys(threadUrl(tab))) {
                if (!key.isEmpty() && !openTabs.containsKey(key)) {
                    openTabs.put(key, tab);
                }
            }
        }
        return openTabs;
    }

    private CuspTab matchingBookmarkOverviewOpenTab(String url, BookmarkOverviewSnapshot snapshot) {
        return snapshot == null ? matchingThreadTab(url)
                : matchingBookmarkOverviewOpenTab(url, snapshot.openThreadTabs);
    }

    private CuspTab matchingBookmarkOverviewOpenTab(String url, Map<String, CuspTab> openTabs) {
        if (url == null || url.trim().isEmpty() || openTabs == null || openTabs.isEmpty()) {
            return null;
        }
        for (String key : threadHistoryKeys(url)) {
            CuspTab tab = openTabs.get(key);
            if (tab != null) {
                return tab;
            }
        }
        return null;
    }

    private JSONObject preferenceJsonObject(String key) {
        try {
            return new JSONObject(preferences.getString(key, "{}"));
        } catch (Exception ignored) {
            return new JSONObject();
        }
    }

    private void addBookmarkOverviewUnread(Map<String, Integer> unreadByFolder, String folder, int unread) {
        unreadByFolder.put(folder, unreadByFolder.getOrDefault(folder, 0) + unread);
    }

    private void markBookmarkOverviewDirty() {
        bookmarkOverviewDirty = true;
        bookmarkOverviewRenderGeneration++;
        if (preferences != null) {
            preferences.edit().remove(PREF_BOOKMARK_OVERVIEW_RENDER_CACHE).apply();
        }
    }

    private BookmarkOverviewSnapshot readBookmarkOverviewRenderCache() {
        return readBookmarkOverviewRenderCache(bookmarkOverviewOpenThreadTabs());
    }

    private BookmarkOverviewSnapshot readBookmarkOverviewRenderCache(Map<String, CuspTab> openThreadTabs) {
        if (preferences == null) {
            return null;
        }
        try {
            String raw = preferences.getString(PREF_BOOKMARK_OVERVIEW_RENDER_CACHE, "");
            if (raw == null || raw.isEmpty()) {
                return null;
            }
            JSONObject root = new JSONObject(raw);
            JSONArray bookmarkArray = root.optJSONArray("bookmarks");
            JSONArray folderArray = root.optJSONArray("folders");
            JSONObject unreadObject = root.optJSONObject("unreadByFolder");
            if (bookmarkArray == null || folderArray == null || unreadObject == null) {
                return null;
            }
            List<SavedItem> bookmarks = new ArrayList<>();
            Map<String, Integer> itemIndices = new LinkedHashMap<>();
            Set<String> seen = new LinkedHashSet<>();
            for (int i = 0; i < bookmarkArray.length(); i++) {
                JSONObject item = bookmarkArray.optJSONObject(i);
                if (item == null) {
                    continue;
                }
                String title = item.optString("title", "").trim();
                String url = item.optString("url", "").trim();
                String folder = normalizeSavedFolder(item.optString("folder", ""));
                String identity = savedItemIdentity(url, folder);
                if (title.isEmpty() || url.isEmpty() || seen.contains(identity)) {
                    continue;
                }
                itemIndices.put(identity, bookmarks.size());
                bookmarks.add(new SavedItem(title, url, folder));
                seen.add(identity);
            }
            List<String> folders = new ArrayList<>();
            for (int i = 0; i < folderArray.length(); i++) {
                String folder = normalizeSavedFolder(folderArray.optString(i, ""));
                if (!folder.isEmpty() && !folders.contains(folder)) {
                    folders.add(folder);
                }
            }
            Map<String, Integer> unreadByFolder = new LinkedHashMap<>();
            Iterator<String> unreadKeys = unreadObject.keys();
            while (unreadKeys.hasNext()) {
                String folder = normalizeSavedFolder(unreadKeys.next());
                int unread = unreadObject.optInt(folder, 0);
                if (unread > 0) {
                    unreadByFolder.put(folder, unread);
                }
            }
            return new BookmarkOverviewSnapshot(
                    bookmarks,
                    folders,
                    preferenceJsonObject(PREF_BOOKMARK_ORDER),
                    preferenceJsonObject(PREF_BOOKMARK_OVERVIEW_STATUS),
                    readHistoryEnabled() ? preferenceJsonObject(PREF_READ_POSTS) : new JSONObject(),
                    itemIndices,
                    unreadByFolder,
                    openThreadTabs);
        } catch (Exception ignored) {
            return null;
        }
    }

    private void writeBookmarkOverviewRenderCache(BookmarkOverviewSnapshot snapshot) {
        if (preferences == null || snapshot == null) {
            return;
        }
        try {
            JSONArray bookmarks = new JSONArray();
            for (SavedItem item : snapshot.bookmarks) {
                JSONObject object = new JSONObject();
                object.put("title", item.title == null ? "" : item.title);
                object.put("url", item.url == null ? "" : item.url);
                object.put("folder", normalizeSavedFolder(item.folder));
                bookmarks.put(object);
            }
            JSONArray folders = new JSONArray();
            for (String folder : snapshot.folders) {
                String value = normalizeSavedFolder(folder);
                if (!value.isEmpty()) {
                    folders.put(value);
                }
            }
            JSONObject unreadByFolder = new JSONObject();
            for (Map.Entry<String, Integer> entry : snapshot.unreadByFolder.entrySet()) {
                if (entry.getValue() != null && entry.getValue() > 0) {
                    unreadByFolder.put(normalizeSavedFolder(entry.getKey()), entry.getValue());
                }
            }
            JSONObject root = new JSONObject();
            root.put("bookmarks", bookmarks);
            root.put("folders", folders);
            root.put("unreadByFolder", unreadByFolder);
            root.put("updatedAt", System.currentTimeMillis());
            preferences.edit().putString(PREF_BOOKMARK_OVERVIEW_RENDER_CACHE, root.toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private void populateHomeBookmarkSection(LinearLayout section) {
        section.removeAllViews();
        section.addView(sectionTitleView(text("\u30d6\u30c3\u30af\u30de\u30fc\u30af", "Bookmarks")));
        addHomeBookmarkSection(section);
    }

    private boolean refreshHomeBookmarkSectionOnly() {
        LinearLayout section = findTaggedLinearLayout(contentFrame, HOME_BOOKMARK_SECTION_TAG);
        if (section == null) {
            return false;
        }
        populateHomeBookmarkSection(section);
        return true;
    }

    private LinearLayout findTaggedLinearLayout(View view, Object tag) {
        if (view == null) {
            return null;
        }
        if (view instanceof LinearLayout && tag.equals(view.getTag())) {
            return (LinearLayout) view;
        }
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) {
                LinearLayout found = findTaggedLinearLayout(group.getChildAt(i), tag);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

    private void refreshHomeBookmarksOrCurrentView() {
        if (!refreshHomeBookmarkSectionOnly()) {
            refreshCurrentHomeOrHistoryView();
        }
    }

    private void addHomeBookmarkSection(LinearLayout list) {
        BookmarkOverviewSnapshot snapshot = bookmarkOverviewSnapshot();
        List<SavedItem> bookmarks = snapshot.bookmarks;
        List<String> folders = snapshot.folders;
        String rootKey = bookmarkOverviewExpandedKey("home:__root__");
        boolean rootExpanded = bookmarkOverviewExpanded(rootKey, true);
        list.addView(homeBookmarkRootRow(rootExpanded, snapshot, v -> {
            toggleBookmarkOverviewExpanded(rootKey, false);
        }));
        if (rootExpanded) {
            addHomeBookmarkNodesContainer(list, snapshot, bookmarkChildren("", snapshot), 1);
        }
        if (bookmarks.isEmpty() && folders.isEmpty()) {
            list.addView(helperLine(text("\u307e\u3060\u3042\u308a\u307e\u305b\u3093", "Nothing saved yet.")));
        }
    }

    private void addHomeBookmarkFolder(LinearLayout list, List<SavedItem> bookmarks, List<String> folders,
                                       BookmarkOverviewSnapshot snapshot, String folder, int indentLevel) {
        String key = bookmarkOverviewExpandedKey("home:" + folder);
        boolean expanded = bookmarkOverviewExpanded(key, false);
        list.addView(homeBookmarkFolderRow(folder, expanded, indentLevel, snapshot,
                v -> {
                    toggleBookmarkOverviewExpanded(key, false);
                }));
        if (!expanded) {
            return;
        }
        addHomeBookmarkNodesContainer(list, snapshot, bookmarkChildren(folder, snapshot), indentLevel + 1);
    }

    private void addHomeBookmarkNodesContainer(LinearLayout list, BookmarkOverviewSnapshot snapshot,
                                               List<BookmarkNode> nodes, int indentLevel) {
        if (nodes == null || nodes.isEmpty()) {
            return;
        }
        LinearLayout container = new LinearLayout(this);
        container.setOrientation(LinearLayout.VERTICAL);
        list.addView(container);
        int firstEnd = Math.min(nodes.size(), BOOKMARK_OVERVIEW_SYNC_CHILDREN);
        appendHomeBookmarkNodes(container, snapshot, nodes, indentLevel, 0, firstEnd);
        if (firstEnd < nodes.size()) {
            container.post(() -> appendHomeBookmarkNodesDeferred(container, snapshot, nodes,
                    indentLevel, firstEnd));
        }
    }

    private void appendHomeBookmarkNodesDeferred(LinearLayout container, BookmarkOverviewSnapshot snapshot,
                                                 List<BookmarkNode> nodes, int indentLevel, int start) {
        if (container.getParent() == null || nodes == null || start >= nodes.size()) {
            return;
        }
        int end = Math.min(nodes.size(), start + BOOKMARK_OVERVIEW_DEFERRED_CHILDREN);
        appendHomeBookmarkNodes(container, snapshot, nodes, indentLevel, start, end);
        if (end < nodes.size()) {
            container.postDelayed(() -> appendHomeBookmarkNodesDeferred(container, snapshot, nodes,
                    indentLevel, end), 16);
        }
    }

    private void appendHomeBookmarkNodes(LinearLayout list, BookmarkOverviewSnapshot snapshot,
                                         List<BookmarkNode> nodes, int indentLevel, int start, int end) {
        for (int i = start; i < end && i < nodes.size(); i++) {
            BookmarkNode node = nodes.get(i);
            if (node.folderNode) {
                addHomeBookmarkFolder(list, snapshot.bookmarks, snapshot.folders, snapshot,
                        node.folder, indentLevel);
            } else {
                list.addView(homeBookmarkItemRow(node.item, indentLevel, snapshot));
            }
        }
    }

    private View homeBookmarkRootRow(boolean expanded, BookmarkOverviewSnapshot snapshot, View.OnClickListener listener) {
        View row = homeBookmarkFolderRow("", expanded, 0, snapshot, listener);
        return row;
    }

