    private View bookmarkOverviewItemRow(SavedItem item, int indentLevel) {
        return bookmarkOverviewItemRow(item, indentLevel, null);
    }

    private View bookmarkOverviewItemRow(SavedItem item, int indentLevel, BookmarkOverviewSnapshot snapshot) {
        int itemIndex = snapshot == null
                ? savedItemIndex(PREF_THREAD_BOOKMARKS, item)
                : snapshot.itemIndices.getOrDefault(savedItemIdentity(item.url, item.folder), -1);
        return bookmarkOverviewShell(
                bookmarkOverviewItemContent(item, itemIndex, snapshot),
                indentLevel,
                dp(86));
    }

    private View bookmarkOverviewItemSlot(SavedItem item, int indentLevel, BookmarkOverviewSnapshot snapshot) {
        int itemIndex = snapshot == null
                ? savedItemIndex(PREF_THREAD_BOOKMARKS, item)
                : snapshot.itemIndices.getOrDefault(savedItemIdentity(item.url, item.folder), -1);
        VirtualBookmarkOverviewSlot slot = new VirtualBookmarkOverviewSlot(item, itemIndex, indentLevel, snapshot);
        FrameLayout holder = new FrameLayout(this);
        holder.setLayoutParams(bookmarkOverviewShellLayoutParams(indentLevel, slot.height));
        bindBookmarkOverviewSlot(holder, slot);
        holder.addView(bookmarkOverviewSlotSpacer(slot.height), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, slot.height));
        return holder;
    }

    private View bookmarkOverviewItemContent(SavedItem item, int itemIndex, BookmarkOverviewSnapshot snapshot) {
        CuspTab overviewTab = bookmarkOverviewTab(item, snapshot);
        FrameLayout shell = new FrameLayout(this);
        shell.setClipChildren(false);
        shell.setBackgroundColor(Color.TRANSPARENT);
        View.OnDragListener dragListener = bookmarkOverviewItemDropListener(item, itemIndex);
        shell.setOnDragListener(dragListener);
        ImageView deleteLeft = swipeActionIcon(R.drawable.ic_delete, Gravity.LEFT | Gravity.CENTER_VERTICAL);
        deleteLeft.setColorFilter(TEAL);
        ImageView deleteRight = swipeActionIcon(R.drawable.ic_delete, Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        deleteRight.setColorFilter(TEAL);
        shell.addView(deleteLeft);
        shell.addView(deleteRight);

        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(10), dp(7), dp(8), dp(7));
        row.setMinimumHeight(dp(86));
        row.setBackground(roundedDrawable(postColor(), bookmarkOverviewItemSelected(item) ? TEAL : borderColor(), dp(8)));
        row.setOnClickListener(v -> openBookmarkOverviewItem(item));
        row.setOnDragListener(dragListener);
        row.setOnLongClickListener(v -> {
            if (itemIndex < 0) {
                return false;
            }
            row.startDragAndDrop(ClipData.newPlainText("bookmark", item.url),
                    new View.DragShadowBuilder(shell),
                    new DragPayload(bookmarkNodeDragKey(BookmarkNode.item(item)), itemIndex), 0);
            return true;
        });

        LinearLayout textBox = new LinearLayout(this);
        textBox.setOrientation(LinearLayout.VERTICAL);
        textBox.setOnDragListener(dragListener);
        TextView title = new TextView(this);
        String rowTitle = displayTitleForTab(overviewTab);
        if (overviewTab.knownThreadArchived) {
            setThreadTitleText(title, rowTitle, true);
        } else {
            title.setText(rowTitle);
        }
        title.setTextColor(textColor());
        title.setOnDragListener(dragListener);
        title.setTextSize(14);
        title.setSingleLine(false);
        title.setMaxLines(2);
        title.setEllipsize(TextUtils.TruncateAt.END);
        title.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
        title.setIncludeFontPadding(false);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            title.setAutoSizeTextTypeUniformWithConfiguration(11, 14, 1, TypedValue.COMPLEX_UNIT_SP);
        }
        textBox.addView(title, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(38)));
        View meta = bookmarkOverviewMetaView(item, overviewTab, snapshot);
        meta.setOnDragListener(dragListener);
        textBox.addView(meta, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(30)));
        row.addView(textBox, new LinearLayout.LayoutParams(0, dp(68), 1));

        ImageButton close = iconButton(R.drawable.ic_close,
                text("\u30d6\u30c3\u30af\u30de\u30fc\u30af\u3092\u524a\u9664", "Delete bookmark"),
                v -> deleteBookmarkFromOverview(item, shell));
        close.setColorFilter(mutedColor());
        close.setBackgroundColor(Color.TRANSPARENT);
        close.setOnDragListener(dragListener);
        LinearLayout.LayoutParams closeParams = new LinearLayout.LayoutParams(dp(42), dp(40));
        closeParams.setMargins(dp(8), 0, 0, 0);
        row.addView(close, closeParams);

        shell.addView(row, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(86)));
        attachBookmarkOverviewSwipe(row, deleteLeft, deleteRight, item, shell);
        return shell;
    }

    private String bookmarkOverviewItemMeta(SavedItem item, BookmarkOverviewSnapshot snapshot) {
        String url = item == null || item.url == null ? "" : item.url;
        BookmarkOverviewStatus status = item == null ? null
                : snapshot == null ? bookmarkOverviewStatus(url) : bookmarkOverviewStatus(url, snapshot.statusRoot);
        if (isThreadUrl(url) && status != null && status.responseCount > 0) {
            int read = snapshot == null ? visibleReadPostNumber(url) : snapshot.readPosts.optInt(url, 0);
            int unread = Math.max(0, status.responseCount - read);
            return text("\u30ec\u30b9: ", "Posts: ") + status.responseCount
                    + (unread > 0 ? "  " + text("\u672a\u8aad: ", "Unread: ") + unread : "");
        }
        return url.replaceFirst("https?://", "");
    }

    private View bookmarkOverviewMetaView(SavedItem item, CuspTab tab, BookmarkOverviewSnapshot snapshot) {
        SearchResult result = bookmarkOverviewSearchResult(item, tab, snapshot);
        if (result == null) {
            TextView empty = new TextView(this);
            empty.setText("");
            empty.setIncludeFontPadding(false);
            return empty;
        }
        return boardThreadMetaView(result, true);
    }

    private SearchResult bookmarkOverviewSearchResult(SavedItem item, CuspTab tab,
                                                      BookmarkOverviewSnapshot snapshot) {
        if (snapshot == null || item == null) {
            return searchResultForTabOverview(tab);
        }
        String identity = savedItemIdentity(item.url, item.folder);
        if (snapshot.itemResults.containsKey(identity)) {
            return snapshot.itemResults.get(identity);
        }
        SearchResult result = searchResultForTabOverview(tab);
        snapshot.itemResults.put(identity, result);
        return result;
    }

    private View.OnDragListener bookmarkOverviewItemDropListener(SavedItem item, int itemIndex) {
        return (v, event) -> {
            autoScrollDuringDrag(v, event);
            if (event.getAction() != android.view.DragEvent.ACTION_DROP) {
                return true;
            }
            Object local = event.getLocalState();
            if (!(local instanceof DragPayload)) {
                return true;
            }
            DragPayload payload = (DragPayload) local;
            if ("tabs".equals(payload.key) && itemIndex >= 0) {
                moveTabToBookmarksFromOverview(payload.index, normalizeSavedFolder(item.folder), itemIndex);
                return true;
            }
            if (PREF_THREAD_BOOKMARKS.equals(payload.key) && itemIndex >= 0) {
                List<SavedItem> items = readSavedItems(PREF_THREAD_BOOKMARKS);
                if (payload.index >= 0 && payload.index < items.size()) {
                    SavedItem moved = items.get(payload.index);
                    moveBookmarkNodeToParentNear(BookmarkNode.item(moved).orderKey(),
                            normalizeSavedFolder(item.folder), BookmarkNode.item(item).orderKey(),
                            bookmarkDropZone(event, v, false) > 0);
                }
                payload.index = itemIndex;
                refreshTabOverview();
                return true;
            }
            String movingKey = bookmarkNodeDragValue(payload.key);
            if (!movingKey.isEmpty()) {
                moveBookmarkNodeToParentNear(movingKey, normalizeSavedFolder(item.folder),
                        BookmarkNode.item(item).orderKey(), bookmarkDropZone(event, v, false) > 0);
                refreshTabOverview();
                return true;
            }
            if ((PREF_THREAD_BOOKMARKS + ":folder").equals(payload.key) && itemIndex >= 0) {
                moveBookmarkOverviewFolderBeforeItem(payload.index, itemIndex);
                refreshTabOverview();
                return true;
            }
            return true;
        };
    }

    private void openBookmarkOverviewItem(SavedItem item) {
        if (item == null || item.url == null || item.url.trim().isEmpty()) {
            return;
        }
        rememberTabOverviewScroll();
        pendingHistoryAll = false;
        createBookmarkOverviewTab(item);
    }

    private FrameLayout bookmarkOverviewShell(View row, int indentLevel, int height) {
        FrameLayout shell = new FrameLayout(this);
        shell.setLayoutParams(bookmarkOverviewShellLayoutParams(indentLevel, height));
        shell.addView(row, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, height));
        return shell;
    }

    private LinearLayout.LayoutParams bookmarkOverviewShellLayoutParams(int indentLevel, int height) {
        int indent = dp(18 * Math.max(0, indentLevel));
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, height);
        params.setMargins(indent, 0, 0, dp(8));
        return params;
    }

    private void bindBookmarkOverviewSlot(FrameLayout holder, VirtualBookmarkOverviewSlot slot) {
        if (holder == null || slot == null) {
            return;
        }
        holder.setTag(slot);
        holder.setOnDragListener(bookmarkOverviewItemDropListener(slot.item, slot.itemIndex));
    }

    private void renderBookmarkOverviewSlot(FrameLayout holder, VirtualBookmarkOverviewSlot slot) {
        if (holder == null || slot == null || slot.rendered) {
            return;
        }
        bindBookmarkOverviewSlot(holder, slot);
        holder.removeAllViews();
        holder.addView(bookmarkOverviewItemContent(slot.item, slot.itemIndex, slot.snapshot),
                new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, slot.height));
        slot.rendered = true;
        slot.selected = bookmarkOverviewItemSelected(slot.item);
        if (holder.getParent() instanceof LinearLayout
                && ((LinearLayout) holder.getParent()).getTag() instanceof VirtualTabOverviewState) {
            ((VirtualTabOverviewState) ((LinearLayout) holder.getParent()).getTag()).renderedSlots.add(holder);
        }
    }

    private void recycleBookmarkOverviewSlot(FrameLayout holder, VirtualBookmarkOverviewSlot slot) {
        if (holder == null || slot == null || !slot.rendered) {
            return;
        }
        holder.removeAllViews();
        bindBookmarkOverviewSlot(holder, slot);
        holder.addView(bookmarkOverviewSlotSpacer(slot.height), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, slot.height));
        slot.rendered = false;
        slot.selected = false;
        if (holder.getParent() instanceof LinearLayout
                && ((LinearLayout) holder.getParent()).getTag() instanceof VirtualTabOverviewState) {
            ((VirtualTabOverviewState) ((LinearLayout) holder.getParent()).getTag()).renderedSlots.remove(holder);
        }
    }

    private View bookmarkOverviewSlotSpacer(int height) {
        View spacer = new View(this);
        spacer.setMinimumHeight(Math.max(dp(86), height));
        return spacer;
    }

    private String selectedBookmarkOverviewFolder(List<SavedItem> bookmarks) {
        CuspTab tab = currentTab();
        if (!isBookmarkTabScope(tab) || bookmarks == null || bookmarks.isEmpty()) {
            return null;
        }
        String targetUrl = threadUrl(tab);
        String targetFolder = bookmarkTabFolder(tab);
        for (SavedItem bookmark : bookmarks) {
            if (bookmark != null
                    && sameSavedUrl(targetUrl, bookmark.url)
                    && targetFolder.equals(normalizeSavedFolder(bookmark.folder))) {
                return normalizeSavedFolder(bookmark.folder);
            }
        }
        return null;
    }

    private boolean bookmarkOverviewItemSelected(SavedItem item) {
        CuspTab tab = currentTab();
        return isBookmarkTabScope(tab)
                && item != null && item.url != null
                && sameSavedUrl(threadUrl(tab), item.url)
                && bookmarkTabFolder(tab).equals(normalizeSavedFolder(item.folder));
    }

    private CuspTab bookmarkOverviewTab(SavedItem item) {
        return bookmarkOverviewTab(item, null);
    }

    private CuspTab bookmarkOverviewTab(SavedItem item, BookmarkOverviewSnapshot snapshot) {
        if (snapshot != null && item != null) {
            String identity = savedItemIdentity(item.url, item.folder);
            CuspTab cached = snapshot.itemTabs.get(identity);
            if (cached != null) {
                return cached;
            }
            CuspTab tab = buildBookmarkOverviewTab(item, snapshot);
            snapshot.itemTabs.put(identity, tab);
            return tab;
        }
        return buildBookmarkOverviewTab(item, snapshot);
    }

    private CuspTab buildBookmarkOverviewTab(SavedItem item, BookmarkOverviewSnapshot snapshot) {
        CuspTab tab = new CuspTab();
        tab.url = item == null ? "" : item.url;
        tab.title = item == null ? "" : item.title;
        applyThreadTabScope(tab, TabScope.BOOKMARK, item == null ? "" : item.folder);
        tab.readerMode = true;
        tab.nativeKind = isThreadUrl(tab.url) ? NATIVE_THREAD
                : isBoardUrl(tab.url) || isBbsDirectoryUrl(tab.url) ? NATIVE_BOARD : null;
        BookmarkOverviewStatus status = item == null ? null
                : snapshot == null
                ? bookmarkOverviewStatus(item.url)
                : bookmarkOverviewStatus(item.url, snapshot.statusRoot);
        if (status != null) {
            if (status.title != null && !status.title.trim().isEmpty()) {
                tab.title = status.title.trim();
            }
            tab.knownThreadArchived = status.archived;
            tab.knownBoardOrder = Math.max(0, status.boardOrder);
            if (isThreadUrl(tab.url) && status.responseCount > 0) {
                tab.knownMaxPostNumber = status.responseCount;
                tab.knownPostCount = status.responseCount;
                tab.readPostNumber = snapshot == null
                        ? visibleReadPostNumber(item.url)
                        : snapshot.readPosts.optInt(item.url, 0);
                tab.cachedUnreadCount = Math.max(0, status.responseCount - tab.readPostNumber);
                tab.hasThreadStats = true;
            }
        }
        CuspTab openTab = matchingBookmarkOverviewOpenTab(item == null ? "" : item.url, snapshot);
        if (openTab != null) {
            if ((tab.title == null || tab.title.trim().isEmpty()) && openTab.title != null) {
                tab.title = openTab.title;
            }
            tab.knownThreadArchived = tab.knownThreadArchived || openTab.knownThreadArchived
                    || (openTab.threadPage != null && openTab.threadPage.archived);
            if (openTab.hasThreadStats) {
                tab.knownMaxPostNumber = Math.max(tab.knownMaxPostNumber, openTab.knownMaxPostNumber);
                tab.knownPostCount = Math.max(tab.knownPostCount, openTab.knownPostCount);
                int read = snapshot == null ? visibleReadPostNumber(tab.url) : snapshot.readPosts.optInt(tab.url, 0);
                tab.readPostNumber = Math.max(read, openTab.readPostNumber);
                tab.cachedUnreadCount = Math.max(0,
                        Math.max(tab.knownMaxPostNumber, tab.knownPostCount) - tab.readPostNumber);
                tab.hasThreadStats = true;
            }
        }
        return tab;
    }

    private CuspTab matchingThreadTab(String url) {
        if (url == null || url.trim().isEmpty()) {
            return null;
        }
        for (CuspTab tab : tabs) {
            if (tab == null || isBookmarkTabScope(tab) || !NATIVE_THREAD.equals(tab.nativeKind)) {
                continue;
            }
            String tabUrl = threadUrl(tab);
            if (sameThreadIdentity(tabUrl, url)) {
                return tab;
            }
        }
        return null;
    }

    private int savedItemIndex(String key, String url) {
        String normalized = trimSlash(normalizeUrl(url));
        List<SavedItem> items = readSavedItems(key);
        for (int i = 0; i < items.size(); i++) {
            if (trimSlash(normalizeUrl(items.get(i).url)).equals(normalized)) {
                return i;
            }
        }
        return -1;
    }

    private int savedItemIndex(String key, SavedItem target) {
        if (target == null) {
            return -1;
        }
        List<SavedItem> items = readSavedItems(key);
        for (int i = 0; i < items.size(); i++) {
            if (sameSavedItem(items.get(i), target)) {
                return i;
            }
        }
        return -1;
    }

    private void attachBookmarkOverviewSwipe(View row, View deleteLeft, View deleteRight, SavedItem item, View shell) {
        final float[] downX = new float[1];
        final float[] downY = new float[1];
        final boolean[] dragging = new boolean[1];
        row.setOnTouchListener((v, event) -> {
            if (event.getAction() == MotionEvent.ACTION_DOWN) {
                downX[0] = event.getRawX();
                downY[0] = event.getRawY();
                dragging[0] = false;
                row.clearAnimation();
                return false;
            }
            if (event.getAction() == MotionEvent.ACTION_MOVE) {
                float dx = event.getRawX() - downX[0];
                float dy = event.getRawY() - downY[0];
                if (!dragging[0] && Math.abs(dx) > dp(12) && Math.abs(dx) > Math.abs(dy) * 1.4f) {
                    dragging[0] = true;
                    v.getParent().requestDisallowInterceptTouchEvent(true);
                }
                if (dragging[0]) {
                    float translation = Math.max(-dp(108), Math.min(dp(108), dx * 0.58f));
                    row.setTranslationX(translation);
                    deleteLeft.setAlpha(Math.max(0f, Math.min(1f, translation / dp(64))));
                    deleteRight.setAlpha(Math.max(0f, Math.min(1f, -translation / dp(64))));
                    return true;
                }
            }
            if (event.getAction() == MotionEvent.ACTION_UP || event.getAction() == MotionEvent.ACTION_CANCEL) {
                if (dragging[0]) {
                    float tx = row.getTranslationX();
                    row.animate().translationX(0).setDuration(130).start();
                    deleteLeft.animate().alpha(0f).setDuration(130).start();
                    deleteRight.animate().alpha(0f).setDuration(130).start();
                    if (event.getAction() == MotionEvent.ACTION_UP && Math.abs(tx) >= dp(54)) {
                        deleteBookmarkFromOverview(item, shell);
                    }
                    return true;
                }
            }
            return false;
        });
    }

    private void deleteBookmarkFromOverview(SavedItem item) {
        deleteBookmarkFromOverview(item, null);
    }

    private void deleteBookmarkFromOverview(SavedItem item, View rowView) {
        if (item == null) {
            return;
        }
        showBookmarkClosedUndo(item);
        syncClosedTabUndoBar();
        removeSavedItem(PREF_THREAD_BOOKMARKS, item);
        if (rowView == null || rowView.getParent() == null) {
            refreshTabOverview();
        } else {
            animateTabOverviewRowRemoval(rowView);
        }
    }

    private void showBookmarkClosedUndo(SavedItem item) {
        ClosedTab closed = new ClosedTab(item, savedItemIndex(PREF_THREAD_BOOKMARKS, item));
        showClosedTabUndo(closed);
    }

    private void restoreDeletedBookmark(SavedItem item, int index) {
        List<SavedItem> items = readSavedItems(PREF_THREAD_BOOKMARKS);
        for (SavedItem existing : items) {
            if (sameSavedItem(existing, item)) {
                return;
            }
        }
        int insert = Math.max(0, Math.min(index, items.size()));
        items.add(insert, item);
        writeSavedItems(PREF_THREAD_BOOKMARKS, items);
        String folder = normalizeSavedFolder(item.folder);
        if (!folder.isEmpty()) {
            createSavedFolder(PREF_THREAD_BOOKMARKS, folder);
        }
    }

    private void moveTabToBookmarksFromOverview(int tabIndex, String folder, int beforeItemIndex) {
        if (tabIndex < 0 || tabIndex >= tabs.size()) {
            return;
        }
        CuspTab tab = tabs.get(tabIndex);
        if (tab == null || tab.url == null || tab.url.trim().isEmpty()) {
            return;
        }
        addBookmarkFromTab(tab, folder, beforeItemIndex);
        applyThreadTabScope(tab, TabScope.BOOKMARK, folder);
        currentIndex = tabIndex;
        pendingNewTab = false;
        requestSaveTabsSoon();
        renderTabs();
        refreshTabOverview();
    }

    private void addBookmarkFromTab(CuspTab tab, String folder, int beforeItemIndex) {
        List<SavedItem> items = readSavedItems(PREF_THREAD_BOOKMARKS);
        String url = tab.url;
        folder = normalizeSavedFolder(folder);
        for (int i = items.size() - 1; i >= 0; i--) {
            if (sameSavedItem(items.get(i), url, folder)) {
                items.remove(i);
            }
        }
        String title = tab.title == null || tab.title.trim().isEmpty() ? hostTitle(url) : tab.title;
        SavedItem added = new SavedItem(cleanTitle(title, url), url, folder);
        int insert = 0;
        if (beforeItemIndex >= 0) {
            String beforeUrl = "";
            List<SavedItem> current = readSavedItems(PREF_THREAD_BOOKMARKS);
            if (beforeItemIndex < current.size()) {
                beforeUrl = current.get(beforeItemIndex).url;
            }
            insert = items.size();
            for (int i = 0; i < items.size(); i++) {
                if (sameSavedItem(items.get(i), beforeUrl, folder)) {
                    insert = i;
                    break;
                }
            }
        } else if (!folder.isEmpty()) {
            insert = items.size();
            for (int i = 0; i < items.size(); i++) {
                if (folder.equals(normalizeSavedFolder(items.get(i).folder))) {
                    insert = i;
                    break;
                }
            }
        }
        items.add(Math.max(0, Math.min(insert, items.size())), added);
        writeSavedItems(PREF_THREAD_BOOKMARKS, items);
        if (!folder.isEmpty()) {
            List<String> folders = readSavedFolders(PREF_THREAD_BOOKMARKS);
            if (!folders.contains(folder)) {
                folders.add(folder);
                writeSavedFolders(PREF_THREAD_BOOKMARKS, folders);
            }
        }
        if (tab.hasThreadStats || tab.knownThreadArchived) {
            ThreadOverviewStatus status = new ThreadOverviewStatus();
            status.url = url;
            status.title = title;
            status.responseCount = Math.max(tab.knownMaxPostNumber, tab.knownPostCount);
            status.boardOrder = Math.max(0, tab.knownBoardOrder);
            status.archived = tab.knownThreadArchived || (tab.threadPage != null && tab.threadPage.archived);
            saveBookmarkOverviewStatus(url, status);
        }
    }

    private void moveBookmarkOverviewItem(int from, int to) {
        List<SavedItem> items = readSavedItems(PREF_THREAD_BOOKMARKS);
        if (from < 0 || from >= items.size() || to < 0 || to >= items.size() || from == to) {
            return;
        }
        String targetFolder = normalizeSavedFolder(items.get(to).folder);
        SavedItem moved = items.remove(from);
        int insert = to;
        if (from < insert) {
            insert--;
        }
        if (!normalizeSavedFolder(moved.folder).equals(targetFolder)) {
            persistCurrentSavedFolders(PREF_THREAD_BOOKMARKS);
        }
        items.add(insert, new SavedItem(moved.title, moved.url, targetFolder));
        writeSavedItems(PREF_THREAD_BOOKMARKS, items);
    }

    private void moveSavedFolder(String key, int from, int to) {
        List<String> folders = readSavedFolders(key);
        if (from < 0 || from >= folders.size() || to < 0 || to >= folders.size() || from == to) {
            return;
        }
        String folder = folders.remove(from);
        int insert = to;
        if (from < insert) {
            insert--;
        }
        folders.add(insert, folder);
        writeSavedFolders(key, folders);
    }

    private void moveBookmarkOverviewFolder(int from, int to) {
        List<String> folders = readSavedFolders(PREF_THREAD_BOOKMARKS);
        if (from < 0 || from >= folders.size() || to < 0 || to >= folders.size() || from == to) {
            return;
        }
        String targetFolder = folders.get(to);
        moveSavedFolder(PREF_THREAD_BOOKMARKS, from, to);
        moveBookmarkFolderItemsBeforeTarget(folders.get(from), targetFolder, -1);
    }

    private void moveBookmarkOverviewFolderBeforeItem(int folderIndex, int targetItemIndex) {
        List<String> folders = readSavedFolders(PREF_THREAD_BOOKMARKS);
        if (folderIndex < 0 || folderIndex >= folders.size()) {
            return;
        }
        String folder = folders.get(folderIndex);
        moveBookmarkFolderItemsBeforeTarget(folder, null, targetItemIndex);
    }

    private void moveBookmarkFolderItemsBeforeTarget(String folder, String targetFolder, int targetItemIndex) {
        folder = normalizeSavedFolder(folder);
        targetFolder = targetFolder == null ? null : normalizeSavedFolder(targetFolder);
        if (folder.isEmpty() || folder.equals(targetFolder)) {
            return;
        }
        List<SavedItem> items = readSavedItems(PREF_THREAD_BOOKMARKS);
        List<SavedItem> moved = new ArrayList<>();
        List<SavedItem> rest = new ArrayList<>();
        for (SavedItem item : items) {
            if (folder.equals(normalizeSavedFolder(item.folder))) {
                moved.add(item);
            } else {
                rest.add(item);
            }
        }
        if (moved.isEmpty()) {
            return;
        }
        int insert = rest.size();
        if (targetFolder != null) {
            for (int i = 0; i < rest.size(); i++) {
                if (targetFolder.equals(normalizeSavedFolder(rest.get(i).folder))) {
                    insert = i;
                    break;
                }
            }
        } else if (targetItemIndex >= 0 && targetItemIndex < items.size()) {
            String targetUrl = items.get(targetItemIndex).url;
            for (int i = 0; i < rest.size(); i++) {
                if (sameSavedUrl(rest.get(i).url, targetUrl)) {
                    insert = i;
                    break;
                }
            }
        }
        rest.addAll(insert, moved);
        writeSavedItems(PREF_THREAD_BOOKMARKS, rest);
    }

    private boolean sameSavedUrl(String left, String right) {
        return trimSlash(normalizeUrl(left)).equals(trimSlash(normalizeUrl(right)));
    }

    private boolean sameSavedItem(SavedItem left, SavedItem right) {
        return right != null && sameSavedItem(left, right.url, right.folder);
    }

    private boolean sameSavedItem(SavedItem item, String url, String folder) {
        return item != null
                && sameSavedUrl(item.url, url)
                && normalizeSavedFolder(item.folder).equals(normalizeSavedFolder(folder));
    }

    private void refreshTabOverview() {
        if (tabOverviewVisible && contentFrame != null) {
            boolean updatedBookmarks = refreshTabOverviewBookmarkSectionOnly();
            boolean updatedTabs = refreshTabOverviewTabSlotsOnly();
            if (!updatedBookmarks && !updatedTabs) {
                refreshTabOverviewListOnly();
            }
            renderTabs();
        }
    }

    private void refreshTabOverviewFromTop(View loader) {
        if (!tabOverviewVisible || contentFrame == null) {
            resetTopRefreshLoader(loader);
            return;
        }
        reloadAllTabs(false, () -> resetTopRefreshLoader(loader));
    }

    private boolean refreshTabOverviewBookmarkSectionOnly() {
        return refreshTabOverviewBookmarkSectionOnly(contentFrame);
    }

    private boolean refreshBookmarkOverviewSelectionInPlace(View root) {
        ScrollView scroll = findScrollView(root);
        if (scroll == null || scroll.getChildCount() == 0 || !(scroll.getChildAt(0) instanceof LinearLayout)) {
            return false;
        }
        LinearLayout list = (LinearLayout) scroll.getChildAt(0);
        int sectionStart = 1;
        int tabSectionStart = tabOverviewTabSectionStart(list);
        if (tabSectionStart < sectionStart) {
            return false;
        }
        VirtualTabOverviewState state = list.getTag() instanceof VirtualTabOverviewState
                ? (VirtualTabOverviewState) list.getTag() : null;
        BookmarkOverviewSnapshot snapshot = bookmarkOverviewSnapshot();
        String selectedFolder = selectedBookmarkOverviewFolder(snapshot.bookmarks);
        boolean changed = false;
        for (int i = sectionStart; i < tabSectionStart && i < list.getChildCount(); i++) {
            View child = list.getChildAt(i);
            Object tag = child.getTag();
            if (tag instanceof BookmarkOverviewFolderSlot) {
                BookmarkOverviewFolderSlot slot = (BookmarkOverviewFolderSlot) tag;
                boolean expanded = bookmarkOverviewExpanded(slot.key, slot.folder.isEmpty());
                boolean selected = bookmarkOverviewFolderSelected(slot.folder, selectedFolder, expanded);
                if (slot.selected == selected) {
                    continue;
                }
                unregisterRenderedOverviewSlots(child, state);
                View replacement = bookmarkOverviewFolderRow(
                        snapshot, slot.folder, selectedFolder, slot.indentLevel);
                list.removeViewAt(i);
                list.addView(replacement, i);
                changed = true;
            } else if (child instanceof FrameLayout && tag instanceof VirtualBookmarkOverviewSlot) {
                VirtualBookmarkOverviewSlot slot = (VirtualBookmarkOverviewSlot) tag;
                boolean selected = bookmarkOverviewItemSelected(slot.item);
                if (slot.selected == selected) {
                    continue;
                }
                slot.selected = selected;
                if (slot.rendered) {
                    if (state != null) {
                        state.renderedSlots.remove((FrameLayout) child);
                    }
                    slot.rendered = false;
                    renderBookmarkOverviewSlot((FrameLayout) child, slot);
                    changed = true;
                }
            }
        }
        if (changed) {
            scheduleTabOverviewSlotRefresh(list);
        }
        return changed;
    }

    private boolean refreshTabOverviewBookmarkSectionOnly(View root) {
        ScrollView scroll = findScrollView(root);
        if (scroll == null || scroll.getChildCount() == 0 || !(scroll.getChildAt(0) instanceof LinearLayout)) {
            return false;
        }
        LinearLayout list = (LinearLayout) scroll.getChildAt(0);
        int sectionStart = 1;
        int tabSectionStart = tabOverviewTabSectionStart(list);
        if (tabSectionStart < sectionStart) {
            return false;
        }
        VirtualTabOverviewState state = list.getTag() instanceof VirtualTabOverviewState
                ? (VirtualTabOverviewState) list.getTag() : null;
        setTabOverviewListPadding(list);
        LinearLayout temp = new LinearLayout(this);
        temp.setOrientation(LinearLayout.VERTICAL);
        if (!tabOverviewPrivateMode && showBookmarksInTabOverview()) {
            addBookmarkOverviewSection(temp);
        }
        syncBookmarkOverviewSectionChildren(list, temp, sectionStart, state);
        scheduleTabOverviewSlotRefresh(list);
        syncClosedTabUndoBar();
        return true;
    }

    private void syncBookmarkOverviewSectionChildren(LinearLayout list, LinearLayout desired,
                                                     int sectionStart, VirtualTabOverviewState state) {
        if (list == null || desired == null) {
            return;
        }
        int insert = sectionStart;
        while (desired.getChildCount() > 0) {
            View child = desired.getChildAt(0);
            desired.removeViewAt(0);
            String key = bookmarkOverviewChildKey(child);
            int sectionEnd = tabOverviewTabSectionStart(list);
            if (sectionEnd < sectionStart) {
                sectionEnd = list.getChildCount();
            }
            View existing = insert < sectionEnd ? list.getChildAt(insert) : null;
            if (!key.isEmpty() && existing != null && key.equals(bookmarkOverviewChildKey(existing))) {
                updateBookmarkOverviewChildAt(list, insert, child, state);
                insert++;
                continue;
            }
            int reusableIndex = key.isEmpty() ? -1
                    : bookmarkOverviewChildIndex(list, key, insert + 1, sectionEnd);
            if (reusableIndex >= 0) {
                View reusable = list.getChildAt(reusableIndex);
                list.removeViewAt(reusableIndex);
                View synced = syncBookmarkOverviewChild(reusable, child, state);
                if (synced != reusable) {
                    unregisterRenderedOverviewSlots(reusable, state);
                }
                list.addView(synced, insert);
            } else {
                list.addView(child, insert);
            }
            insert++;
        }
        int sectionEnd = tabOverviewTabSectionStart(list);
        if (sectionEnd < sectionStart) {
            sectionEnd = list.getChildCount();
        }
        while (insert < sectionEnd && insert < list.getChildCount()) {
            unregisterRenderedOverviewSlots(list.getChildAt(insert), state);
            list.removeViewAt(insert);
            sectionEnd--;
        }
    }

    private void updateBookmarkOverviewChildAt(LinearLayout list, int index, View desired,
                                               VirtualTabOverviewState state) {
        View existing = list.getChildAt(index);
        View synced = syncBookmarkOverviewChild(existing, desired, state);
        if (synced == existing) {
            return;
        }
        unregisterRenderedOverviewSlots(existing, state);
        list.removeViewAt(index);
        list.addView(synced, index);
    }

    private View syncBookmarkOverviewChild(View existing, View desired, VirtualTabOverviewState state) {
        if (existing instanceof FrameLayout && desired instanceof FrameLayout
                && existing.getTag() instanceof VirtualBookmarkOverviewSlot
                && desired.getTag() instanceof VirtualBookmarkOverviewSlot) {
            VirtualBookmarkOverviewSlot current = (VirtualBookmarkOverviewSlot) existing.getTag();
            VirtualBookmarkOverviewSlot next = (VirtualBookmarkOverviewSlot) desired.getTag();
            current.item = next.item;
            current.snapshot = next.snapshot;
            current.indentLevel = next.indentLevel;
            current.itemIndex = next.itemIndex;
            existing.setLayoutParams(desired.getLayoutParams());
            bindBookmarkOverviewSlot((FrameLayout) existing, current);
            if (current.rendered) {
                if (state != null) {
                    state.renderedSlots.remove((FrameLayout) existing);
                }
                current.rendered = false;
                renderBookmarkOverviewSlot((FrameLayout) existing, current);
            }
            return existing;
        }
        return desired;
    }

    private int bookmarkOverviewChildIndex(LinearLayout list, String key, int start, int end) {
        if (list == null || key == null || key.isEmpty()) {
            return -1;
        }
        int childCount = list.getChildCount();
        for (int i = Math.max(0, start); i < end && i < childCount; i++) {
            if (key.equals(bookmarkOverviewChildKey(list.getChildAt(i)))) {
                return i;
            }
        }
        return -1;
    }

    private String bookmarkOverviewChildKey(View child) {
        if (child == null) {
            return "";
        }
        Object tag = child.getTag();
        if (tag instanceof BookmarkOverviewFolderSlot) {
            BookmarkOverviewFolderSlot slot = (BookmarkOverviewFolderSlot) tag;
            return "F:" + slot.key;
        }
        if (tag instanceof VirtualBookmarkOverviewSlot) {
            VirtualBookmarkOverviewSlot slot = (VirtualBookmarkOverviewSlot) tag;
            SavedItem item = slot.item;
            return item == null ? "" : "I:" + savedItemIdentity(item.url, item.folder);
        }
        return "";
    }

    private void unregisterRenderedOverviewSlots(View view, VirtualTabOverviewState state) {
        if (view == null || state == null) {
            return;
        }
        if (view instanceof FrameLayout && isVirtualTabOverviewChild(view.getTag())) {
            state.renderedSlots.remove((FrameLayout) view);
        }
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) {
                unregisterRenderedOverviewSlots(group.getChildAt(i), state);
            }
        }
    }

    private int tabOverviewTabSectionStart(LinearLayout list) {
        if (list == null) {
            return -1;
        }
        for (int i = 1; i < list.getChildCount(); i++) {
            View child = list.getChildAt(i);
            if (child instanceof FrameLayout && child.getTag() instanceof VirtualTabOverviewSlot) {
                return i;
            }
            if (TAB_OVERVIEW_EMPTY_TAG.equals(child.getTag())) {
                return i;
            }
        }
        return -1;
    }

    private void addUnreadBadgeIfNeeded(LinearLayout row, int unread) {
        if (unread <= 0) {
            return;
        }
        TextView unreadBadge = new TextView(this);
        unreadBadge.setText(String.valueOf(unread));
        unreadBadge.setTextColor(Color.WHITE);
        unreadBadge.setTextSize(12);
        unreadBadge.setGravity(Gravity.CENTER);
        unreadBadge.setBackground(roundedDrawable(Color.rgb(15, 118, 110), Color.rgb(15, 118, 110), dp(12)));
        LinearLayout.LayoutParams unreadParams = new LinearLayout.LayoutParams(dp(34), dp(24));
        unreadParams.setMargins(dp(8), 0, 0, 0);
        row.addView(unreadBadge, unreadParams);
    }

    private String bookmarkOverviewExpandedKey(String folder) {
        return normalizeSavedFolder(folder).isEmpty()
                ? "__root__"
                : normalizeSavedFolder(folder);
    }

    private boolean bookmarkOverviewExpanded(String key, boolean defaultValue) {
        try {
            JSONObject object = new JSONObject(preferences.getString(PREF_BOOKMARK_OVERVIEW_EXPANDED, "{}"));
            return object.has(key) ? object.optBoolean(key, defaultValue) : defaultValue;
        } catch (Exception ignored) {
            return defaultValue;
        }
    }

    private void toggleBookmarkOverviewExpanded(String key) {
        toggleBookmarkOverviewExpanded(key, true);
    }

    private void toggleBookmarkOverviewExpanded(String key, boolean refreshTabOverviewAfterToggle) {
        try {
            JSONObject object = new JSONObject(preferences.getString(PREF_BOOKMARK_OVERVIEW_EXPANDED, "{}"));
            boolean next = !object.optBoolean(key, "__root__".equals(key));
            object.put(key, next);
            preferences.edit().putString(PREF_BOOKMARK_OVERVIEW_EXPANDED, object.toString()).apply();
        } catch (Exception ignored) {
        }
        if (refreshTabOverviewAfterToggle && tabOverviewVisible && contentFrame != null) {
            // Folder totals are stored in the overview snapshot, while item rows can read live tab state.
            // Rebuild the snapshot before folding so the aggregate never comes from an older read position.
            markBookmarkOverviewDirty();
            if (refreshBookmarkOverviewFolderExpansionInPlace(key)) {
                bookmarkOverviewDirty = false;
                renderTabs();
                return;
            }
            markBookmarkOverviewDirty();
            if (!refreshTabOverviewBookmarkSectionOnly()) {
                refreshTabOverviewListOnly();
            }
            renderTabs();
        } else if (!refreshTabOverviewAfterToggle) {
            markBookmarkOverviewDirty();
            refreshHomeBookmarksOrCurrentView();
        } else {
            markBookmarkOverviewDirty();
        }
    }

    private boolean refreshBookmarkOverviewFolderExpansionInPlace(String key) {
        ScrollView scroll = findScrollView(contentFrame);
        if (scroll == null || scroll.getChildCount() == 0 || !(scroll.getChildAt(0) instanceof LinearLayout)) {
            return false;
        }
        LinearLayout list = (LinearLayout) scroll.getChildAt(0);
        int folderIndex = bookmarkOverviewFolderRowIndex(list, key);
        if (folderIndex < 0) {
            return false;
        }
        Object tag = list.getChildAt(folderIndex).getTag();
        if (!(tag instanceof BookmarkOverviewFolderSlot)) {
            return false;
        }
        BookmarkOverviewFolderSlot slot = (BookmarkOverviewFolderSlot) tag;
        VirtualTabOverviewState state = list.getTag() instanceof VirtualTabOverviewState
                ? (VirtualTabOverviewState) list.getTag() : null;
        removeBookmarkOverviewDescendants(list, folderIndex, slot.indentLevel, state);
        BookmarkOverviewSnapshot snapshot = bookmarkOverviewSnapshot();
        String selectedFolder = selectedBookmarkOverviewFolder(snapshot.bookmarks);
        View replacement = bookmarkOverviewFolderRow(snapshot, slot.folder, selectedFolder, slot.indentLevel);
        list.removeViewAt(folderIndex);
        list.addView(replacement, folderIndex);
        if (bookmarkOverviewExpanded(key, slot.folder.isEmpty())) {
            LinearLayout temp = new LinearLayout(this);
            temp.setOrientation(LinearLayout.VERTICAL);
            addBookmarkOverviewNodesContainer(temp, snapshot, bookmarkChildren(slot.folder, snapshot),
                    selectedFolder, slot.indentLevel + 1);
            int insert = folderIndex + 1;
            while (temp.getChildCount() > 0) {
                View child = temp.getChildAt(0);
                temp.removeViewAt(0);
                list.addView(child, insert++);
            }
        }
        scheduleTabOverviewSlotRefresh(list);
        syncClosedTabUndoBar();
        return true;
    }

    private int bookmarkOverviewFolderRowIndex(LinearLayout list, String key) {
        if (list == null || key == null) {
            return -1;
        }
        for (int i = 1; i < list.getChildCount(); i++) {
            View child = list.getChildAt(i);
            Object tag = child.getTag();
            if (tag instanceof BookmarkOverviewFolderSlot) {
                if (key.equals(((BookmarkOverviewFolderSlot) tag).key)) {
                    return i;
                }
            } else if (tag instanceof VirtualTabOverviewSlot || TAB_OVERVIEW_EMPTY_TAG.equals(tag)) {
                return -1;
            }
        }
        return -1;
    }

    private void removeBookmarkOverviewDescendants(LinearLayout list, int folderIndex, int indentLevel,
                                                   VirtualTabOverviewState state) {
        int index = folderIndex + 1;
        while (index < list.getChildCount()) {
            View child = list.getChildAt(index);
            int childIndent = bookmarkOverviewChildIndent(child);
            if (childIndent < 0 || childIndent <= indentLevel) {
                break;
            }
            unregisterRenderedOverviewSlots(child, state);
            list.removeViewAt(index);
        }
    }

    private int bookmarkOverviewChildIndent(View child) {
        if (child == null) {
            return -1;
        }
        Object tag = child.getTag();
        if (tag instanceof BookmarkOverviewFolderSlot) {
            return ((BookmarkOverviewFolderSlot) tag).indentLevel;
        }
        if (tag instanceof VirtualBookmarkOverviewSlot) {
            return ((VirtualBookmarkOverviewSlot) tag).indentLevel;
        }
        return -1;
    }

    private void refreshTabOverviewListOnly() {
        ScrollView scroll = findScrollView(contentFrame);
        if (scroll == null || scroll.getChildCount() == 0 || !(scroll.getChildAt(0) instanceof LinearLayout)) {
            if (contentFrame != null) {
                contentFrame.removeAllViews();
                attachTabOverviewView();
            }
            return;
        }
        LinearLayout list = (LinearLayout) scroll.getChildAt(0);
        populateTabOverviewList(scroll, list);
        syncClosedTabUndoBar();
    }

    private void syncClosedTabUndoBar() {
        FrameLayout root = tabOverviewFrameRoot(contentFrame);
        if (root == null) {
            return;
        }
        ScrollView scroll = findScrollView(root);
        if (scroll != null && scroll.getChildCount() > 0 && scroll.getChildAt(0) instanceof LinearLayout) {
            LinearLayout list = (LinearLayout) scroll.getChildAt(0);
            if (isTabOverviewList(list)) {
                setTabOverviewListPadding(list);
            }
        }
        for (int i = root.getChildCount() - 1; i >= 0; i--) {
            View child = root.getChildAt(i);
            if (CLOSED_TAB_UNDO_TAG.equals(child.getTag())) {
                root.removeViewAt(i);
            }
        }
        if (recentlyClosedTab != null) {
            root.addView(closedTabUndoBar(), closedTabUndoParams());
        }
    }

    private FrameLayout tabOverviewFrameRoot(View root) {
        if (root == null) {
            return null;
        }
        if (root == contentFrame && contentFrame != null && contentFrame.getChildCount() > 0
                && contentFrame.getChildAt(0) instanceof FrameLayout
                && containsTabOverviewList(contentFrame.getChildAt(0))) {
            return (FrameLayout) contentFrame.getChildAt(0);
        }
        if (root instanceof FrameLayout && containsTabOverviewList(root)) {
            return (FrameLayout) root;
        }
        return null;
    }

    private boolean containsTabOverviewList(View root) {
        ScrollView scroll = findScrollView(root);
        return scroll != null
                && scroll.getChildCount() > 0
                && scroll.getChildAt(0) instanceof LinearLayout
                && isTabOverviewList((LinearLayout) scroll.getChildAt(0));
    }

    private boolean isTabOverviewList(LinearLayout list) {
        return list != null
                && (list.getTag() instanceof VirtualTabOverviewState
                || tabOverviewTabSectionStart(list) >= 1);
    }

    private View buildSavedItemsView(String key) {
        return buildSavedItemsView(key, "");
    }

    private View buildSavedItemsView(String key, String folder) {
        folder = normalizeSavedFolder(folder);
        final String currentFolder = folder;
        ScrollView scroll = new ScrollView(this);
        scroll.setVerticalScrollBarEnabled(false);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setPadding(dp(12), dp(12), dp(12), dp(24));
        scroll.addView(list, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        list.addView(sectionTitleView(savedListTitle(key, folder)));
        List<SavedItem> items = readSavedItems(key);
        List<String> folders = readSavedFolders(key, items);
        boolean hasFolders = false;
        if (folder.isEmpty()) {
            list.addView(rootSavedFolderRow(key));
            for (String childFolder : childSavedFolders(folder, folders)) {
                list.addView(savedFolderRow(key, childFolder, items));
                hasFolders = true;
            }
        } else {
            list.addView(actionButtonRow(R.drawable.ic_arrow_back,
                    text("\u4e00\u89a7\u306b\u623b\u308b", "Back to list"),
                    v -> showSavedItemsView(key, parentSavedFolder(currentFolder))));
            for (String childFolder : childSavedFolders(folder, folders)) {
                list.addView(savedFolderRow(key, childFolder, items));
                hasFolders = true;
            }
        }
        List<SavedItem> visibleItems = new ArrayList<>();
        List<Integer> visibleIndices = new ArrayList<>();
        for (int i = 0; i < items.size(); i++) {
            SavedItem item = items.get(i);
            if (!folder.equals(normalizeSavedFolder(item.folder))) {
                continue;
            }
            visibleItems.add(item);
            visibleIndices.add(i);
        }
        int firstEnd = Math.min(visibleItems.size(), SAVED_ITEMS_SYNC_ROWS);
        appendSavedItemRows(list, key, visibleItems, visibleIndices, folder, 0, firstEnd);
        if (firstEnd < visibleItems.size()) {
            list.post(() -> appendSavedItemRowsDeferred(list, key, visibleItems, visibleIndices,
                    currentFolder, firstEnd));
        }
        if (visibleItems.isEmpty() && !hasFolders) {
            list.addView(helperLine(text("\u307e\u3060\u3042\u308a\u307e\u305b\u3093", "Nothing saved yet.")));
        }
        return scroll;
    }

    private void appendSavedItemRowsDeferred(LinearLayout list, String key, List<SavedItem> items,
                                             List<Integer> indices, String folder, int start) {
        if (list.getParent() == null || items == null || start >= items.size()) {
            return;
        }
        int end = Math.min(items.size(), start + SAVED_ITEMS_DEFERRED_ROWS);
        appendSavedItemRows(list, key, items, indices, folder, start, end);
        if (end < items.size()) {
            list.postDelayed(() -> appendSavedItemRowsDeferred(list, key, items, indices, folder, end), 16);
        }
    }

    private void appendSavedItemRows(LinearLayout list, String key, List<SavedItem> items,
                                     List<Integer> indices, String folder, int start, int end) {
        for (int i = start; i < end && i < items.size(); i++) {
            int originalIndex = i < indices.size() ? indices.get(i) : i;
            list.addView(savedItemRow(key, items.get(i), originalIndex, folder));
        }
    }

