    private void deferPostTextDecoration(TextView text, String value, ThreadPage page, String highlight) {
        DeferredTextDecoration decoration = new DeferredTextDecoration(text, value, page, highlight);
        text.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override
            public void onViewAttachedToWindow(View view) {
                if (!deferredTextDecorations.contains(decoration)) {
                    deferredTextDecorations.add(decoration);
                }
                scheduleDeferredTextDecorations();
            }

            @Override
            public void onViewDetachedFromWindow(View view) {
                deferredTextDecorations.remove(decoration);
            }
        });
        if (text.isAttachedToWindow()) {
            deferredTextDecorations.add(decoration);
            scheduleDeferredTextDecorations();
        }
    }

    private List<ImgurLink> imgurLinks(String value) {
        List<ImgurLink> links = new ArrayList<>();
        if (value == null || value.isEmpty() || !showMediaPreviews()) {
            return links;
        }
        Matcher matcher = URL_TEXT_PATTERN.matcher(value);
        Set<String> added = new LinkedHashSet<>();
        while (matcher.find()) {
            String cleanUrl = stripTrailingUrlPunctuation(matcher.group());
            ImgurLink media = previewMediaLink(cleanUrl);
            if (media != null && added.add(media.imageUrl)) {
                links.add(media);
            }
        }
        return links;
    }

    private List<ImgurLink> imgurLinks(Post post) {
        if (!showMediaPreviews()) {
            return new ArrayList<>();
        }
        if (post == null) {
            return new ArrayList<>();
        }
        if (post.cachedImgurLinks == null) {
            post.cachedImgurLinks = imgurLinks(post.body);
        }
        return post.cachedImgurLinks;
    }

    private List<ImgurLink> threadMediaLinks(Post post) {
        List<ImgurLink> links = new ArrayList<>();
        if (post == null || post.body == null || post.body.isEmpty()) {
            return links;
        }
        Matcher matcher = URL_TEXT_PATTERN.matcher(post.body);
        Set<String> added = new LinkedHashSet<>();
        while (matcher.find()) {
            String cleanUrl = stripTrailingUrlPunctuation(matcher.group());
            ImgurLink media = previewMediaLink(cleanUrl);
            if (media != null && added.add(media.imageUrl)) {
                links.add(media);
            }
        }
        return links;
    }

    private List<ThreadExtractItem> threadExtractItems(ThreadExtractMode mode) {
        return threadExtractItems(mode, popularReplyThreshold());
    }

    private List<ThreadExtractItem> threadExtractItems(ThreadExtractMode mode, int popularThreshold) {
        List<ThreadExtractItem> items = new ArrayList<>();
        CuspTab tab = currentTab();
        ThreadPage page = tab == null ? null : tab.threadPage;
        if (page == null || page.posts == null) {
            return items;
        }
        if (mode == ThreadExtractMode.POPULAR) {
            Map<Integer, Integer> replyCounts = popularReplyCounts(page);
            int threshold = Math.max(1, popularThreshold);
            for (Post post : page.posts) {
                if (post == null) {
                    continue;
                }
                int replyCount = replyCounts.containsKey(post.number) ? replyCounts.get(post.number) : 0;
                if (replyCount >= threshold) {
                    items.add(new ThreadExtractItem(post.number, valueOr(post.body, ""), null, replyCount, post));
                }
            }
            return items;
        }
        for (Post post : page.posts) {
            if (post == null || post.body == null) {
                continue;
            }
            if (mode == ThreadExtractMode.MEDIA) {
                for (ImgurLink link : threadMediaLinks(post)) {
                    items.add(new ThreadExtractItem(
                            post.number, link.originalUrl, link, 0, post));
                }
            } else {
                Matcher matcher = URL_TEXT_PATTERN.matcher(post.body);
                while (matcher.find()) {
                    String cleanUrl = stripTrailingUrlPunctuation(matcher.group());
                    if (!cleanUrl.isEmpty() && previewMediaLink(cleanUrl) == null) {
                        items.add(new ThreadExtractItem(post.number, cleanUrl, null));
                    }
                }
            }
        }
        return items;
    }

    private int popularReplyThreshold() {
        return Math.max(1, preferences.getInt(PREF_POPULAR_REPLY_THRESHOLD, 3));
    }

    private Map<Integer, Integer> popularReplyCounts(ThreadPage page) {
        Map<Integer, Integer> counts = new LinkedHashMap<>();
        if (page == null || page.posts == null || page.posts.isEmpty()) {
            return counts;
        }
        Set<Integer> postNumbers = new LinkedHashSet<>();
        for (Post post : page.posts) {
            if (post != null && post.number > 0) {
                postNumbers.add(post.number);
            }
        }
        for (Post post : page.posts) {
            if (post == null || post.body == null) {
                continue;
            }
            Set<Integer> targets = replyTargetsForPopular(post.body, post.number, postNumbers);
            for (Integer target : targets) {
                counts.put(target, counts.containsKey(target) ? counts.get(target) + 1 : 1);
            }
        }
        return counts;
    }

    private Set<Integer> replyTargetsForPopular(String body, int sourceNumber, Set<Integer> postNumbers) {
        Set<Integer> targets = new LinkedHashSet<>();
        Matcher matcher = REPLY_PATTERN.matcher(valueOr(body, ""));
        while (matcher.find()) {
            int from = parsePositiveInt(matcher.group(1), -1);
            int to = matcher.group(2) == null ? from : parsePositiveInt(matcher.group(2), from);
            int first = Math.min(from, to);
            int last = Math.max(from, to);
            for (int number = first; number <= last; number++) {
                if (number > 0 && number != sourceNumber && postNumbers.contains(number)) {
                    targets.add(number);
                }
            }
        }
        return targets;
    }

    private void showThreadExtractList(ThreadExtractMode mode) {
        showThreadExtractList(mode, popularReplyThreshold());
    }

    private void showThreadExtractList(ThreadExtractMode mode, int popularThreshold) {
        List<ThreadExtractItem> items = threadExtractItems(mode, popularThreshold);
        if (items.isEmpty() && mode != ThreadExtractMode.POPULAR) {
            Toast.makeText(this, noThreadExtractText(mode), Toast.LENGTH_SHORT).show();
            return;
        }
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setPadding(dp(8), dp(8), dp(8), dp(8));
        root.setBackgroundColor(surfaceColor());

        final Dialog[] popupRef = new Dialog[1];
        root.addView(threadExtractTitleRow(mode, popularThreshold, items.size(), popupRef),
                new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        ScrollView scroll = new ScrollView(this);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        scroll.addView(list, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        int width = Math.max(dp(280), getResources().getDisplayMetrics().widthPixels - dp(24));
        int height = Math.max(dp(240), (int) (getResources().getDisplayMetrics().heightPixels * 0.72f));
        AlertDialog popup = createUnifiedPopupDialog(root);
        popupRef[0] = popup;
        root.setTag(popup);
        if (items.isEmpty()) {
            TextView empty = postText(noThreadExtractText(mode), null);
            empty.setTextColor(mutedColor());
            empty.setPadding(dp(10), dp(12), dp(10), dp(12));
            list.addView(empty, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        } else {
            renderThreadExtractSlots(scroll, list, threadExtractGroups(items), mode, popup);
        }
        root.addView(scroll, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, 0, 1));

        showUnifiedPopupDialog(popup, width, height);
    }

    private String noThreadExtractText(ThreadExtractMode mode) {
        if (mode == ThreadExtractMode.MEDIA) return text("\u30e1\u30c7\u30a3\u30a2\u306a\u3057", "No media.");
        if (mode == ThreadExtractMode.POPULAR) return text("\u4eba\u6c17\u30ec\u30b9\u306a\u3057", "No popular posts.");
        return text("\u30ea\u30f3\u30af\u306a\u3057", "No links.");
    }

    private String threadExtractTitle(ThreadExtractMode mode) {
        if (mode == ThreadExtractMode.MEDIA) return text("\u30e1\u30c7\u30a3\u30a2", "Media");
        if (mode == ThreadExtractMode.POPULAR) {
            return text("\u4eba\u6c17\u30ec\u30b9", "Popular posts");
        }
        return text("\u30ea\u30f3\u30af", "Links");
    }

    private View threadExtractTitleRow(ThreadExtractMode mode, int threshold, int count, Dialog[] popupRef) {
        if (mode != ThreadExtractMode.POPULAR) {
            return popupTitleRow(threadExtractTitle(mode), count);
        }
        PopupEditHeader header = popupEditHeader(
                threadExtractTitle(mode), count, String.valueOf(Math.max(1, threshold)),
                text("\u95be\u5024", "Threshold"), true,
                text("\u66f4\u65b0", "Update"));
        Runnable refresh = () -> {
            int value = Math.max(1, parsePositiveInt(header.input.getText().toString(), Math.max(1, threshold)));
            preferences.edit().putInt(PREF_POPULAR_REPLY_THRESHOLD, value).apply();
            Dialog extractPopup = popupRef == null ? null : popupRef[0];
            if (extractPopup != null && extractPopup.isShowing()) {
                extractPopup.dismiss();
            }
            showThreadExtractList(ThreadExtractMode.POPULAR, value);
        };
        header.apply.setContentDescription(text("\u4eba\u6c17\u30ec\u30b9\u306e\u95be\u5024\u3092\u66f4\u65b0", "Update popular post threshold"));
        header.apply.setOnClickListener(v -> refresh.run());
        header.input.setOnEditorActionListener((v, actionId, event) -> {
            refresh.run();
            return true;
        });
        return header.root;
    }

