    private void showWriteDialog(String initialMessage, boolean creatingThread) {
        CuspTab tab = currentTab();
        DatAddress writeAddress = creatingThread ? boardWriteAddress(tab) : tab == null ? null : datAddress(tab.url);
        boolean validTarget = tab != null && writeAddress != null
                && (creatingThread ? NATIVE_BOARD.equals(tab.nativeKind) : NATIVE_THREAD.equals(tab.nativeKind));
        if (!validTarget) {
            Toast.makeText(this, creatingThread
                    ? text("\u3053\u306e\u677f\u3067\u306f\u30b9\u30ec\u3092\u4f5c\u6210\u3067\u304d\u307e\u305b\u3093", "A thread cannot be created on this board.")
                    : text("\u3053\u3053\u304b\u3089\u306f\u66f8\u304d\u8fbc\u3081\u307e\u305b\u3093", "This thread cannot be written from here."),
                    Toast.LENGTH_SHORT).show();
            return;
        }
        clearAddressFocus();

        LinearLayout form = new LinearLayout(this);
        form.setOrientation(LinearLayout.VERTICAL);
        form.setPadding(dp(18), dp(10), dp(18), dp(6));
        form.setBackgroundColor(surfaceColor());

        EditText subject = null;
        if (creatingThread) {
            subject = new EditText(this);
            subject.setSingleLine(true);
            subject.setHint(text("\u30b9\u30ec\u30bf\u30a4\u30c8\u30eb", "Thread title"));
            subject.setTextColor(textColor());
            subject.setHintTextColor(mutedColor());
            subject.setBackground(addressBarBackground());
            subject.setPadding(dp(12), 0, dp(12), 0);
            LinearLayout.LayoutParams subjectParams = new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, dp(48));
            subjectParams.setMargins(0, 0, 0, dp(8));
            form.addView(subject, subjectParams);
        }

        EditText name = new EditText(this);
        name.setSingleLine(true);
        name.setHint(text("\u540d\u524d", "Name"));
        name.setTextColor(textColor());
        name.setHintTextColor(mutedColor());
        name.setBackground(addressBarBackground());
        name.setPadding(dp(12), 0, dp(12), 0);
        LinearLayout.LayoutParams nameParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(48));
        nameParams.setMargins(0, 0, 0, dp(8));
        form.addView(name, nameParams);

        EditText mail = new EditText(this);
        mail.setSingleLine(true);
        mail.setHint(text("\u30e1\u30fc\u30eb", "Mail"));
        mail.setTextColor(textColor());
        mail.setHintTextColor(mutedColor());
        mail.setBackground(addressBarBackground());
        mail.setPadding(dp(12), 0, dp(12), 0);
        LinearLayout.LayoutParams mailParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(48));
        mailParams.setMargins(0, 0, 0, dp(10));
        form.addView(mail, mailParams);

        EditText message = new EditText(this);
        message.setMinLines(9);
        message.setGravity(Gravity.TOP | Gravity.START);
        message.setHint(text("\u672c\u6587", "Message"));
        message.setTextColor(textColor());
        message.setHintTextColor(mutedColor());
        message.setBackground(addressBarBackground());
        message.setPadding(dp(12), dp(10), dp(12), dp(10));
        message.setText(initialMessage == null ? "" : initialMessage);
        message.setSelection(message.getText().length());
        applyWriteMessageAaMode(message, false);

        boolean[] writeAaMode = new boolean[]{false};
        TextView[] aaToggleLabel = new TextView[1];
        ImageButton writeMenu = iconButton(R.drawable.ic_more_vert, text("\u66f8\u304d\u8fbc\u307f\u30e1\u30cb\u30e5\u30fc", "Write menu"),
                v -> showWriteActionMenu(v, tab, name, mail, message, writeAaMode, aaToggleLabel));
        writeMenu.setColorFilter(textColor());

        message.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                if (writeAaMode[0]) {
                    message.post(() -> fitAaTextSize(message));
                }
            }

            @Override
            public void afterTextChanged(Editable s) {
            }
        });
        form.addView(message, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(280)));

        LinearLayout titleRow = writeDialogTitleRow(
                creatingThread ? text("\u30b9\u30ec\u3092\u4f5c\u6210", "Create thread")
                        : tab.threadPage == null ? text("\u66f8\u304d\u8fbc\u307f", "Write") : tab.threadPage.title,
                writeMenu);
        EditText subjectInput = subject;
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setCustomTitle(titleRow)
                .setView(form)
                .setNegativeButton("Cancel", null)
                .setPositiveButton(creatingThread ? text("\u4f5c\u6210", "Create") : "Post", null)
                .create();
        dialog.setOnShowListener(d -> {
            Theme.styleDialog(dialog, this, surfaceColor(), textColor(), accentColor(), borderColor());
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v -> {
            String subjectValue = subjectInput == null ? "" : subjectInput.getText().toString();
            if (creatingThread && subjectValue.trim().isEmpty()) {
                Toast.makeText(this, text("\u30b9\u30ec\u30bf\u30a4\u30c8\u30eb\u3092\u5165\u529b", "Enter a thread title."), Toast.LENGTH_SHORT).show();
                return;
            }
            String body = message.getText().toString();
            if (body.trim().isEmpty()) {
                Toast.makeText(this, text("\u672c\u6587\u3092\u5165\u529b", "Enter a message."), Toast.LENGTH_SHORT).show();
                return;
            }
            dialog.dismiss();
            String nameValue = name.getText().toString();
            String mailValue = mail.getText().toString();
            saveWriteIdentityHistory(nameValue, mailValue);
            if (creatingThread) {
                submitNewThread(tab, writeAddress, subjectValue, nameValue, mailValue, body);
            } else {
                submitPost(tab, nameValue, mailValue, body);
            }
            });
        });
        dialog.show();
        Theme.styleDialog(dialog, this, surfaceColor(), textColor(), accentColor(), borderColor());
        EditText initialFocus = creatingThread && subjectInput != null ? subjectInput : message;
        initialFocus.requestFocus();
        initialFocus.postDelayed(() -> {
            try {
                InputMethodManager manager = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
                manager.showSoftInput(initialFocus, InputMethodManager.SHOW_IMPLICIT);
            } catch (Exception ignored) {
            }
        }, 120);
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == REQUEST_IMGBB_IMAGE && resultCode == RESULT_OK && data != null) {
            List<Uri> uris = selectedMediaUris(data);
            if (uris.isEmpty()) {
                Toast.makeText(this, text("\u753b\u50cf\u304c\u9078\u629e\u3055\u308c\u3066\u3044\u307e\u305b\u3093", "No image selected."), Toast.LENGTH_SHORT).show();
                return;
            }
            addPendingImgbbUploadUris(uris);
            renderPendingImgbbMedia();
        } else if (requestCode == REQUEST_WRITE_IDENTITY_HISTORY && resultCode == RESULT_OK && data != null) {
            String name = data.getStringExtra(WriteIdentityHistoryActivity.EXTRA_NAME);
            String mail = data.getStringExtra(WriteIdentityHistoryActivity.EXTRA_MAIL);
            if (pendingWriteNameInput != null) {
                pendingWriteNameInput.setText(name == null ? "" : name);
                pendingWriteNameInput.setSelection(pendingWriteNameInput.getText().length());
            }
            if (pendingWriteMailInput != null) {
                pendingWriteMailInput.setText(mail == null ? "" : mail);
                pendingWriteMailInput.setSelection(pendingWriteMailInput.getText().length());
            }
        } else if (requestCode == REQUEST_EDGE_AUTH) {
            Runnable retry = pendingEdgeAuthRetry;
            pendingEdgeAuthRetry = null;
            if (resultCode == RESULT_OK && retry != null) {
                mainHandler.post(retry);
            }
        }
    }

