    private void openExternal(String url) {
        if (externalLinksInApp() && openInDefaultBrowserCustomTab(url)) {
            return;
        }
        openInDefaultBrowser(url);
    }

    private boolean openInDefaultBrowserCustomTab(String url) {
        try {
            Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse(url));
            intent.addCategory(Intent.CATEGORY_BROWSABLE);
            intent.putExtra("android.support.customtabs.extra.SESSION", (android.os.Bundle) null);
            intent.putExtra("android.support.customtabs.extra.TITLE_VISIBILITY", 1);
            String browserPackage = defaultBrowserPackage(url);
            if (browserPackage != null && !browserPackage.equals(getPackageName())) {
                intent.setPackage(browserPackage);
            }
            startActivity(intent);
            return true;
        } catch (ActivityNotFoundException error) {
            return false;
        }
    }

    private void openInDefaultBrowser(String url) {
        try {
            Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse(url));
            intent.addCategory(Intent.CATEGORY_BROWSABLE);
            String browserPackage = defaultBrowserPackage(url);
            if (browserPackage != null && !browserPackage.equals(getPackageName())) {
                intent.setPackage(browserPackage);
            }
            startActivity(intent);
        } catch (ActivityNotFoundException error) {
            Toast.makeText(this, text("\u958b\u3051\u308b\u30a2\u30d7\u30ea\u304c\u3042\u308a\u307e\u305b\u3093", "No app can open this link."), Toast.LENGTH_SHORT).show();
        }
    }

    private String defaultBrowserPackage(String url) {
        try {
            Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse(url));
            intent.addCategory(Intent.CATEGORY_BROWSABLE);
            ResolveInfo info = getPackageManager().resolveActivity(intent, 0);
            if (info == null || info.activityInfo == null) {
                return null;
            }
            String packageName = info.activityInfo.packageName;
            if (packageName == null || packageName.equals("android")) {
                return null;
            }
            return packageName;
        } catch (Exception ignored) {
            return null;
        }
    }

    private void openSettings() {
        startActivity(new Intent(this, SettingsActivity.class));
    }

    private boolean sync2chEnabled() {
        return preferences != null && preferences.getBoolean(PREF_SYNC2CH_ENABLED, false);
    }

    private void runSync2chNow() {
        saveTabs(true);
        Toast.makeText(this, text("Sync2ch\u3067\u540c\u671f\u4e2d", "Syncing with Sync2ch..."), Toast.LENGTH_SHORT).show();
        ioExecutor.execute(() -> {
            try {
                Sync2chClient.Result result = Sync2chClient.sync(getApplicationContext(), preferences);
                mainHandler.post(() -> {
                    appliedSync2chUpdateAt = preferences.getLong(PREF_SYNC2CH_UPDATED_AT, 0L);
                    if (restoreTabs() && currentIndex >= 0 && currentIndex < tabs.size()) {
                        switchToTab(currentIndex);
                    } else {
                        renderTabs();
                    }
                    Toast.makeText(this,
                            text("Sync2ch\u540c\u671f\u5b8c\u4e86", "Sync2ch sync complete")
                                    + "\n" + text("\u8ffd\u52a0\u30bf\u30d6: ", "Added tabs: ")
                                    + result.addedOpenThreads
                                    + "  " + text("\u8ffd\u52a0\u30d6\u30c3\u30af\u30de\u30fc\u30af: ", "Added bookmarks: ")
                                    + result.addedBookmarks,
                            Toast.LENGTH_LONG).show();
                });
            } catch (Exception error) {
                mainHandler.post(() -> Toast.makeText(this,
                        text("Sync2ch\u540c\u671f\u5931\u6557: ", "Sync2ch sync failed: ")
                                + error.getMessage(), Toast.LENGTH_LONG).show());
            }
        });
    }

    private void openCurrentThreadInWebView() {
        CuspTab tab = currentTab();
        if (tab == null || tab.url == null || tab.url.trim().isEmpty()) {
            Toast.makeText(this, text("\u958b\u304fURL\u304c\u3042\u308a\u307e\u305b\u3093", "No thread URL to open."), Toast.LENGTH_SHORT).show();
            return;
        }
        inlineWebViewMode = true;
        inlineWebViewUrl = tab.url;
        inlineWebView = new WebView(this);
        inlineWebView.setBackgroundColor(bgColor());
        CookieManager cookieManager = CookieManager.getInstance();
        cookieManager.setAcceptCookie(true);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
            cookieManager.setAcceptThirdPartyCookies(inlineWebView, true);
        }
        WebSettings settings = inlineWebView.getSettings();
        settings.setJavaScriptEnabled(true);
        settings.setDomStorageEnabled(true);
        settings.setLoadWithOverviewMode(true);
        settings.setUseWideViewPort(true);
        inlineWebView.setFindListener((activeMatchOrdinal, numberOfMatches, isDoneCounting) -> {
            inlineWebViewFindIndex = numberOfMatches <= 0 ? -1 : activeMatchOrdinal;
            inlineWebViewFindCount = numberOfMatches;
            updatePageSearchCount();
        });
        inlineWebView.setWebViewClient(new WebViewClient() {
            @Override
            public void onPageStarted(WebView view, String url, Bitmap favicon) {
                inlineWebViewUrl = url == null ? "" : url;
                updateAddressBarDisplay(false);
                updateAddressBarButtons(currentTab());
            }

            @Override
            public void onPageFinished(WebView view, String url) {
                CookieManager.getInstance().flush();
                inlineWebViewUrl = url == null ? inlineWebViewUrl : url;
                updateAddressBarDisplay(false);
                updateAddressBarButtons(currentTab());
            }

        });
        contentFrame.removeAllViews();
        contentFrame.addView(inlineWebView, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        rebuildAddressBarButtons();
        updateBottomThreadBar(tab);
        updateAddressBarDisplay(false);
        inlineWebView.loadUrl(tab.url);
    }

    private void closeInlineWebView() {
        if (!inlineWebViewMode) {
            return;
        }
        if (pageSearchOpen) {
            closeThreadSearch();
        }
        inlineWebViewMode = false;
        WebView closing = inlineWebView;
        inlineWebView = null;
        inlineWebViewUrl = "";
        inlineWebViewFindIndex = -1;
        inlineWebViewFindCount = 0;
        if (closing != null) {
            contentFrame.removeView(closing);
            closing.stopLoading();
            closing.loadUrl("about:blank");
            closing.destroy();
        }
        rebuildAddressBarButtons();
        if (currentIndex >= 0 && currentIndex < tabs.size()) {
            switchToTab(currentIndex, true);
        } else {
            updateAddressBarDisplay(false);
            updateBottomThreadBar(currentTab());
        }
    }

    private void showThreadSearchDialog() {
        CuspTab tab = currentTab();
        if (tab != null && tab.threadPage != null && !tab.threadPage.posts.isEmpty()) {
            pageSearchOpen = false;
            tab.threadSearchOpen = true;
            updateThreadSearchBar(tab);
        } else {
            pageSearchOpen = true;
            pageSearchQuery = "";
            pageSearchMatches.clear();
            updateThreadSearchBar(tab);
        }
        focusThreadSearchInput();
    }

    private void openInlineWebViewFind() {
        if (!inlineWebViewMode || inlineWebView == null) {
            return;
        }
        pageSearchOpen = true;
        pageSearchQuery = "";
        inlineWebViewFindIndex = -1;
        inlineWebViewFindCount = 0;
        inlineWebView.clearMatches();
        updateThreadSearchBar(currentTab());
        focusThreadSearchInput();
    }

    private boolean isThreadPageSearchActive() {
        CuspTab tab = currentTab();
        return tab != null && tab.threadSearchOpen && tab.threadPage != null && NATIVE_THREAD.equals(tab.nativeKind);
    }

    private boolean isPageSearchOpen() {
        CuspTab tab = currentTab();
        return pageSearchOpen || (tab != null && tab.threadSearchOpen);
    }

    private void focusThreadSearchInput() {
        if (threadSearchInput == null) {
            return;
        }
        threadSearchInput.requestFocus();
        threadSearchInput.selectAll();
        mainHandler.postDelayed(() -> {
            threadSearchInput.requestFocus();
            InputMethodManager imm = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
            if (imm != null) {
                imm.showSoftInput(threadSearchInput, InputMethodManager.SHOW_FORCED);
            }
        }, 80);
    }

    private void scheduleThreadSearch(String query, boolean resetIndex) {
        if (threadSearchTask != null) {
            mainHandler.removeCallbacks(threadSearchTask);
        }
        CuspTab tab = currentTab();
        if (tab == null) {
            return;
        }
        int generation = ++tab.threadSearchGeneration;
        threadSearchTask = () -> {
            if (tab == currentTab() && tab.threadSearchGeneration == generation) {
                updateThreadSearch(query, resetIndex);
            }
        };
        mainHandler.postDelayed(threadSearchTask, 90);
    }

    private void updateThreadSearch(String query, boolean resetIndex) {
        CuspTab tab = currentTab();
        if (tab == null || tab.threadPage == null) {
            return;
        }
        tab.threadSearchQuery = query == null ? "" : query;
        Set<Integer> previousHighlights = new LinkedHashSet<>(tab.threadSearchHighlightedPosts);
        tab.threadSearchMatches.clear();
        String needle = tab.threadSearchQuery.trim().toLowerCase(Locale.ROOT);
        if (needle.isEmpty()) {
            tab.threadSearchIndex = -1;
            tab.threadSearchLastQuery = "";
            tab.threadSearchLastCandidates = new ArrayList<>();
            tab.threadSearchHighlightedPosts.clear();
            scheduleThreadHighlightRender(tab, previousHighlights);
            updateThreadSearchCount(tab);
            return;
        }
        List<Post> candidates = tab.threadSearchLastQuery != null
                && !tab.threadSearchLastQuery.isEmpty()
                && needle.startsWith(tab.threadSearchLastQuery)
                ? tab.threadSearchLastCandidates : tab.threadPage.posts;
        tab.threadSearchLastCandidates = new ArrayList<>();
        for (Post post : candidates) {
            String haystack = post.searchBody();
            if (fastContains(haystack, needle)) {
                tab.threadSearchMatches.add(post.number);
                tab.threadSearchLastCandidates.add(post);
            }
        }
        tab.threadSearchLastQuery = needle;
        tab.threadSearchHighlightedPosts = new LinkedHashSet<>(tab.threadSearchMatches);
        if (tab.threadSearchMatches.isEmpty()) {
            tab.threadSearchIndex = -1;
        } else if (resetIndex || tab.threadSearchIndex < 0 || tab.threadSearchIndex >= tab.threadSearchMatches.size()) {
            tab.threadSearchIndex = 0;
        }
        Set<Integer> rerenderTargets = new LinkedHashSet<>(previousHighlights);
        rerenderTargets.addAll(tab.threadSearchHighlightedPosts);
        scheduleThreadHighlightRender(tab, rerenderTargets);
        updateThreadSearchCount(tab);
        if (resetIndex && tab.threadSearchIndex >= 0) {
            jumpToPost(tab.threadSearchMatches.get(tab.threadSearchIndex));
        }
    }

    private void moveThreadSearch(int direction) {
        CuspTab tab = currentTab();
        if (tab == null || tab.threadSearchMatches.isEmpty()) {
            return;
        }
        int size = tab.threadSearchMatches.size();
        tab.threadSearchIndex = (tab.threadSearchIndex + direction + size) % size;
        updateThreadSearchCount(tab);
        jumpToPost(tab.threadSearchMatches.get(tab.threadSearchIndex));
    }

    private void moveActivePageSearch(int direction) {
        if (inlineWebViewMode && inlineWebView != null) {
            inlineWebView.findNext(direction >= 0);
        } else if (isThreadPageSearchActive()) {
            moveThreadSearch(direction);
        } else {
            movePageSearch(direction);
        }
    }

    private void closeThreadSearch() {
        CuspTab tab = currentTab();
        if (tab != null) {
            Set<Integer> previousHighlights = new LinkedHashSet<>(tab.threadSearchHighlightedPosts);
            tab.threadSearchOpen = false;
            tab.threadSearchQuery = "";
            tab.threadSearchMatches.clear();
            tab.threadSearchLastQuery = "";
            tab.threadSearchLastCandidates = new ArrayList<>();
            tab.threadSearchHighlightedPosts.clear();
            tab.threadSearchGeneration++;
            if (threadSearchTask != null) {
                mainHandler.removeCallbacks(threadSearchTask);
                threadSearchTask = null;
            }
            tab.threadSearchIndex = -1;
            if (threadSearchHighlightTask != null) {
                mainHandler.removeCallbacks(threadSearchHighlightTask);
                threadSearchHighlightTask = null;
            }
            rerenderThreadHighlightsChunked(tab, previousHighlights, tab.threadSearchGeneration);
        }
        if (threadSearchInput != null) {
            InputMethodManager imm = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
            if (imm != null) {
                imm.hideSoftInputFromWindow(threadSearchInput.getWindowToken(), 0);
            }
            threadSearchInput.clearFocus();
        }
        if (threadSearchBar != null) {
            threadSearchBar.setVisibility(View.GONE);
        }
        if (inlineWebView != null) {
            inlineWebView.clearMatches();
        }
        syncChromeBarSlots(false);
        int pageGeneration = ++pageSearchGeneration;
        clearPageSearchHighlightsChunked(pageGeneration);
        pageSearchOpen = false;
        pageSearchQuery = "";
        pageSearchMatches.clear();
        pageSearchIndex = -1;
    }

    private void updateThreadSearchBar(CuspTab tab) {
        if (threadSearchBar == null || threadSearchInput == null || threadSearchCount == null) {
            return;
        }
        boolean threadShow = tab != null && tab.threadSearchOpen && NATIVE_THREAD.equals(tab.nativeKind);
        boolean show = threadShow || pageSearchOpen;
        threadSearchBar.setVisibility(show ? View.VISIBLE : View.GONE);
        syncChromeBarSlots(false);
        if (!show) {
            return;
        }
        String query = threadShow ? (tab.threadSearchQuery == null ? "" : tab.threadSearchQuery) : pageSearchQuery;
        if (!query.contentEquals(threadSearchInput.getText())) {
            updatingThreadSearchInput = true;
            threadSearchInput.setText(query);
            threadSearchInput.setSelection(threadSearchInput.getText().length());
            updatingThreadSearchInput = false;
        }
        if (threadShow) {
            updateThreadSearchCount(tab);
        } else {
            updatePageSearchCount();
        }
    }

    private void updateThreadSearchCount(CuspTab tab) {
        if (threadSearchCount == null || tab == null) {
            return;
        }
        int total = tab.threadSearchMatches.size();
        if (tab.threadSearchQuery == null || tab.threadSearchQuery.trim().isEmpty()) {
            threadSearchCount.setText("");
        } else if (total == 0) {
            threadSearchCount.setText("0/0");
        } else {
            threadSearchCount.setText((tab.threadSearchIndex + 1) + "/" + total);
        }
    }

    private void updatePageSearch(String query, boolean resetIndex) {
        pageSearchGeneration++;
        pageSearchQuery = query == null ? "" : query;
        clearPageSearchHighlights();
        pageSearchMatches.clear();
        String needle = pageSearchQuery.trim().toLowerCase(Locale.ROOT);
        if (needle.isEmpty()) {
            pageSearchIndex = -1;
            updatePageSearchCount();
            return;
        }
        List<TextView> textViews = new ArrayList<>();
        collectTextViews(contentFrame, textViews);
        for (TextView view : textViews) {
            CharSequence original = view.getText();
            if (original == null) {
                continue;
            }
            String haystack = original.toString().toLowerCase(Locale.ROOT);
            if (!fastContains(haystack, needle)) {
                continue;
            }
            pageSearchOriginalText.put(view, original);
            SpannableString highlighted = new SpannableString(original);
            int start = haystack.indexOf(needle);
            while (start >= 0) {
                int end = start + needle.length();
                highlighted.setSpan(new BackgroundColorSpan(linkHighlightColor()), start, end, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
                highlighted.setSpan(new ForegroundColorSpan(Color.rgb(15, 118, 110)), start, end, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
                start = haystack.indexOf(needle, end);
            }
            view.setText(highlighted);
            pageSearchMatches.add(view);
        }
        if (pageSearchMatches.isEmpty()) {
            pageSearchIndex = -1;
        } else if (resetIndex || pageSearchIndex < 0 || pageSearchIndex >= pageSearchMatches.size()) {
            pageSearchIndex = 0;
            jumpToPageSearchMatch();
        }
        updatePageSearchCount();
    }

    private void collectTextViews(View view, List<TextView> out) {
        if (view instanceof TextView && view != threadSearchInput && view != threadSearchCount) {
            out.add((TextView) view);
        } else if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) {
                collectTextViews(group.getChildAt(i), out);
            }
        }
    }

    private void clearPageSearchHighlights() {
        for (Map.Entry<TextView, CharSequence> entry : pageSearchOriginalText.entrySet()) {
            entry.getKey().setText(entry.getValue());
        }
        pageSearchOriginalText.clear();
    }

    private void clearPageSearchHighlightsChunked(int generation) {
        if (pageSearchOriginalText.isEmpty()) {
            return;
        }
        List<Map.Entry<TextView, CharSequence>> entries = new ArrayList<>(pageSearchOriginalText.entrySet());
        pageSearchOriginalText.clear();
        restorePageSearchHighlightsChunk(entries, 0, generation);
    }

    private void restorePageSearchHighlightsChunk(List<Map.Entry<TextView, CharSequence>> entries, int start, int generation) {
        if (pageSearchGeneration != generation) {
            return;
        }
        int end = Math.min(entries.size(), start + 12);
        for (int i = start; i < end; i++) {
            Map.Entry<TextView, CharSequence> entry = entries.get(i);
            TextView view = entry.getKey();
            if (view != null && view.isAttachedToWindow()) {
                view.setText(entry.getValue());
            }
        }
        if (end < entries.size()) {
            mainHandler.post(() -> restorePageSearchHighlightsChunk(entries, end, generation));
        }
    }

    private void movePageSearch(int direction) {
        if (pageSearchMatches.isEmpty()) {
            return;
        }
        int size = pageSearchMatches.size();
        pageSearchIndex = (pageSearchIndex + direction + size) % size;
        updatePageSearchCount();
        jumpToPageSearchMatch();
    }

    private void updatePageSearchCount() {
        if (threadSearchCount == null) {
            return;
        }
        if (inlineWebViewMode) {
            if (pageSearchQuery == null || pageSearchQuery.trim().isEmpty()) {
                threadSearchCount.setText("");
            } else if (inlineWebViewFindCount <= 0) {
                threadSearchCount.setText("0/0");
            } else {
                threadSearchCount.setText((inlineWebViewFindIndex + 1) + "/" + inlineWebViewFindCount);
            }
            return;
        }
        if (pageSearchQuery == null || pageSearchQuery.trim().isEmpty()) {
            threadSearchCount.setText("");
        } else if (pageSearchMatches.isEmpty()) {
            threadSearchCount.setText("0/0");
        } else {
            threadSearchCount.setText((pageSearchIndex + 1) + "/" + pageSearchMatches.size());
        }
    }

    private void jumpToPageSearchMatch() {
        if (pageSearchIndex < 0 || pageSearchIndex >= pageSearchMatches.size()) {
            return;
        }
        TextView target = pageSearchMatches.get(pageSearchIndex);
        ScrollView scroll = findScrollView(contentFrame);
        if (scroll == null || scroll.getChildCount() == 0) {
            return;
        }
        View current = target;
        int y = 0;
        View scrollChild = scroll.getChildAt(0);
        while (current != null && current != scrollChild) {
            y += current.getTop();
            ViewParent parent = current.getParent();
            current = parent instanceof View ? (View) parent : null;
        }
        int maxY = Math.max(0, scrollChild.getHeight() - scroll.getHeight());
        scroll.smoothScrollTo(0, Math.max(0, Math.min(y - dp(8), maxY)));
    }

    private void rerenderThreadHighlights(CuspTab tab) {
        if (tab == null) {
            return;
        }
        rerenderThreadHighlights(tab, new LinkedHashSet<>(tab.threadSearchHighlightedPosts));
    }

    private void rerenderThreadHighlights(CuspTab tab, Set<Integer> targets) {
        if (tab == null || tab.threadPage == null || tab.postViews == null) {
            return;
        }
        if (targets != null && !targets.isEmpty()) {
            for (Integer number : targets) {
                rerenderThreadHighlight(tab, number == null ? -1 : number);
            }
            return;
        }
        for (Post post : tab.threadPage.posts) {
            rerenderThreadHighlight(tab, post.number);
        }
    }

    private void rerenderThreadHighlightsChunked(CuspTab tab, Set<Integer> targets, int generation) {
        if (tab == null || tab.threadPage == null || tab.postViews == null || targets == null || targets.isEmpty()) {
            return;
        }
        List<Integer> numbers = new ArrayList<>(targets);
        rerenderThreadHighlightChunk(tab, numbers, 0, generation);
    }

    private void rerenderThreadHighlightChunk(CuspTab tab, List<Integer> numbers, int start, int generation) {
        if (tab == null || tab != currentTab() || tab.threadSearchGeneration != generation) {
            return;
        }
        int end = Math.min(numbers.size(), start + 8);
        for (int i = start; i < end; i++) {
            Integer number = numbers.get(i);
            rerenderThreadHighlight(tab, number == null ? -1 : number);
        }
        if (end < numbers.size()) {
            mainHandler.post(() -> rerenderThreadHighlightChunk(tab, numbers, end, generation));
        }
    }

    private void rerenderThreadHighlight(CuspTab tab, int postNumber) {
        if (tab == null || tab.threadPage == null || tab.postViews == null) {
            return;
        }
        Post post = tab.threadPage.postsByNumber.get(postNumber);
        if (post == null) {
            return;
        }
        View cardView = tab.postViews.get(post.number);
        if (!(cardView instanceof LinearLayout)) {
            return;
        }
        LinearLayout card = (LinearLayout) cardView;
        if (card.getChildCount() < 2) {
            return;
        }
        card.removeViewAt(1);
        View bodyView = postBodyView(card, tab.threadPage, tab, post);
        card.addView(bodyView, 1, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        View parent = (View) card.getParent();
        if (parent instanceof ViewGroup && ((ViewGroup) parent).getChildCount() >= 3) {
            ViewGroup shell = (ViewGroup) parent;
            attachPostSwipeDeep(bodyView, card, shell.getChildAt(0), shell.getChildAt(1), tab, post);
        }
    }

    private void scheduleThreadHighlightRender(CuspTab tab, Set<Integer> targets) {
        if (threadSearchHighlightTask != null) {
            mainHandler.removeCallbacks(threadSearchHighlightTask);
        }
        int generation = ++tab.threadSearchGeneration;
        Set<Integer> renderTargets = targets == null ? new LinkedHashSet<>() : new LinkedHashSet<>(targets);
        threadSearchHighlightTask = () -> {
            if (tab == currentTab() && tab.threadSearchGeneration == generation) {
                rerenderThreadHighlights(tab, renderTargets);
            }
        };
        mainHandler.postDelayed(threadSearchHighlightTask, 180);
    }

    private void searchNextThread() {
        CuspTab tab = currentTab();
        if (tab == null || tab.threadPage == null || tab.threadPage.title == null) {
            Toast.makeText(this, text("\u691c\u7d22\u3067\u304d\u308b\u30b9\u30ec\u540d\u304c\u3042\u308a\u307e\u305b\u3093", "No thread title to search."), Toast.LENGTH_SHORT).show();
            return;
        }
        String boardUrl = currentThreadBoardUrl(tab);
        if (boardUrl == null) {
            Toast.makeText(this, text("\u677fURL\u304c\u898b\u3064\u304b\u308a\u307e\u305b\u3093", "No board URL found."), Toast.LENGTH_SHORT).show();
            return;
        }
        String query = nextThreadSearchQuery(tab.threadPage.title);
        int sourceNumber = nextThreadNumber(tab.threadPage.title);
        String sourceUrl = tab.url;
        AlertDialog loading = showNextThreadLoadingPopup();
        ioExecutor.execute(() -> {
            List<SearchResult> boardResults;
            List<SearchResult> candidates;
            String errorMessage = null;
            try {
                boardResults = downloadBoard(boardUrl).results;
                candidates = nextThreadCandidates(boardResults, query, sourceUrl, sourceNumber);
            } catch (Exception error) {
                boardResults = new ArrayList<>();
                candidates = new ArrayList<>();
                errorMessage = error.getMessage();
            }
            List<SearchResult> allResults = boardResults;
            List<SearchResult> result = candidates;
            String resultError = errorMessage;
            runOnUiThread(() -> {
                boolean active = tabs.contains(tab) && tab == currentTab();
                if (!active || !loading.isShowing()) {
                    return;
                }
                loading.dismiss();
                if (resultError != null) {
                    Toast.makeText(this, resultError, Toast.LENGTH_LONG).show();
                } else {
                    showNextThreadCandidatesDialog(query, allResults, sourceUrl, sourceNumber, result);
                }
            });
        });
    }

    private AlertDialog showNextThreadLoadingPopup() {
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setPadding(dp(20), dp(16), dp(20), dp(16));
        root.setBackgroundColor(surfaceColor());
        TextView title = new TextView(this);
        title.setText(text("\u6b21\u30b9\u30ec\u5019\u88dc", "Next-thread candidates"));
        title.setTextColor(textColor());
        title.setTextSize(17);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        root.addView(title);
        TextView message = new TextView(this);
        message.setText(text("\u691c\u7d22\u4e2d...", "Searching..."));
        message.setTextColor(mutedColor());
        message.setTextSize(14);
        message.setPadding(0, dp(10), 0, 0);
        root.addView(message);
        AlertDialog popup = createUnifiedPopupDialog(root);
        showUnifiedPopupDialog(popup, dp(260), WindowManager.LayoutParams.WRAP_CONTENT);
        return popup;
    }

    private void showNextThreadCandidatesDialog(String query, List<SearchResult> boardResults,
                                                String sourceUrl, int sourceNumber,
                                                List<SearchResult> candidates) {
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setPadding(dp(12), dp(10), dp(12), dp(10));
        root.setBackgroundColor(surfaceColor());

        PopupEditHeader header = popupEditHeader(
                text("\u6b21\u30b9\u30ec\u5019\u88dc", "Next-thread candidates"),
                candidates == null ? 0 : candidates.size(), query,
                text("\u691c\u7d22\u8a9e", "Search query"), false,
                text("\u691c\u7d22", "Search"));
        root.addView(header.root, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        if (candidates == null || candidates.isEmpty()) {
            TextView empty = new TextView(this);
            empty.setText(text("\u540c\u3058\u677f\u306b\u3001\u5341\u5206\u306b\u4f3c\u3066\u3044\u308b\u6b21\u30b9\u30ec\u5019\u88dc\u306f\u898b\u3064\u304b\u308a\u307e\u305b\u3093\u3067\u3057\u305f\u3002", "No sufficiently similar next-thread candidates were found on this board."));
            empty.setTextColor(mutedColor());
            empty.setTextSize(14);
            empty.setPadding(dp(4), dp(8), dp(4), dp(12));
            root.addView(empty, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        } else {
            ScrollView scroll = new ScrollView(this);
            LinearLayout list = new LinearLayout(this);
            list.setOrientation(LinearLayout.VERTICAL);
            scroll.addView(list, new ScrollView.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
            root.addView(scroll, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, 0, 1));
            Dialog[] popupRef = new Dialog[1];
            for (SearchResult result : candidates) {
                View row = searchResultRow(result, () -> {
                    if (popupRef[0] != null) {
                        popupRef[0].dismiss();
                    }
                });
                list.addView(row, new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
            }
            root.setTag(popupRef);
        }
        int width = Math.max(dp(280), getResources().getDisplayMetrics().widthPixels - dp(40));
        int height = Math.max(dp(180), (int) (getResources().getDisplayMetrics().heightPixels * 0.62f));
        AlertDialog popup = createUnifiedPopupDialog(root);
        if (root.getTag() instanceof Dialog[]) {
            ((Dialog[]) root.getTag())[0] = popup;
        }
        Runnable applyQuery = () -> {
            String value = header.input.getText().toString().trim();
            if (value.isEmpty()) {
                return;
            }
            popup.dismiss();
            showNextThreadCandidatesDialog(value, boardResults, sourceUrl, sourceNumber,
                    nextThreadCandidates(boardResults, value, sourceUrl, sourceNumber));
        };
        header.apply.setContentDescription(text("\u6b21\u30b9\u30ec\u306e\u691c\u7d22\u8a9e\u3092\u9069\u7528", "Apply next-thread search query"));
        header.apply.setOnClickListener(v -> applyQuery.run());
        header.input.setOnEditorActionListener((v, actionId, event) -> {
            applyQuery.run();
            return true;
        });
        showUnifiedPopupDialog(popup, width, height);
    }

    private List<SearchResult> nextThreadCandidates(List<SearchResult> boardResults, String sourceTitle,
                                                    String sourceUrl, int sourceNumber) {
        List<SearchResult> candidates = new ArrayList<>();
        String source = nextThreadTitleKey(sourceTitle);
        if (source.isEmpty() || boardResults == null) {
            return candidates;
        }
        for (SearchResult result : boardResults) {
            if (result == null || result.title == null || sameSavedUrl(sourceUrl, result.url)) {
                continue;
            }
            String candidate = nextThreadTitleKey(result.title);
            double similarity = nextThreadSimilarity(source, candidate);
            boolean containsQuery = nextThreadContainsQuery(candidate, source);
            if (similarity < 0.48d && !containsQuery) {
                continue;
            }
            int candidateNumber = nextThreadNumber(result.title);
            double score = similarity * 100d;
            if (containsQuery) {
                score += 20d;
            }
            if (sourceNumber > 0 && candidateNumber == sourceNumber + 1) {
                score += 25d;
            } else if (sourceNumber > 0 && candidateNumber > sourceNumber) {
                score += 10d;
            }
            result.nextThreadScore = score;
            result.nextThreadSimilarity = similarity;
            candidates.add(result);
        }
        Collections.sort(candidates, (left, right) -> Double.compare(right.nextThreadScore, left.nextThreadScore));
        if (candidates.size() > 8) {
            return new ArrayList<>(candidates.subList(0, 8));
        }
        return candidates;
    }

    private boolean nextThreadContainsQuery(String candidate, String query) {
        if (candidate == null || query == null || candidate.isEmpty() || query.isEmpty()) {
            return false;
        }
        for (String token : query.split("\\s+")) {
            if (!token.isEmpty() && !candidate.contains(token)) {
                return false;
            }
        }
        return true;
    }

    private String nextThreadSearchQuery(String title) {
        String value = Normalizer.normalize(stripThreadResponseCount(title), Normalizer.Form.NFKC);
        return value.replaceAll("(?i)\\s*(?:part|pt|vol(?:ume)?|#|\u7b2c|\u305d\u306e)?\\s*\\d+\\s*(?:\u30b9\u30ec|\u8a71|\u5dfb|\u518a|\u672c|th|st|nd|rd)?\\s*$", "").trim();
    }

    private String nextThreadTitleKey(String title) {
        String value = stripThreadResponseCount(title);
        value = Normalizer.normalize(value == null ? "" : value, Normalizer.Form.NFKC)
                .toLowerCase(Locale.ROOT)
                .replaceAll("(?i)\\s*(?:part|pt|vol(?:ume)?|#|\u7b2c|\u305d\u306e)?\\s*\\d+\\s*(?:\u30b9\u30ec|\u8a71|\u5dfb|\u518a|\u672c|th|st|nd|rd)?\\s*$", "")
                .replaceAll("[^\\p{L}\\p{N}]+", " ").trim();
        return value.replaceAll("\\s+", " ");
    }

    private int nextThreadNumber(String title) {
        String value = Normalizer.normalize(stripThreadResponseCount(title), Normalizer.Form.NFKC);
        Matcher matcher = Pattern.compile("(?i)(?:part|pt|vol(?:ume)?|#|\u7b2c|\u305d\u306e)?\\s*(\\d+)\\s*(?:\u30b9\u30ec|\u8a71|\u5dfb|\u518a|\u672c|th|st|nd|rd)?\\s*$").matcher(value);
        return matcher.find() ? parsePositiveInt(matcher.group(1), 0) : 0;
    }

    private double nextThreadSimilarity(String left, String right) {
        if (left.isEmpty() || right.isEmpty()) return 0d;
        if (left.equals(right)) return 1d;
        Set<String> leftTokens = new HashSet<>();
        Set<String> rightTokens = new HashSet<>();
        Collections.addAll(leftTokens, left.split("\\s+"));
        Collections.addAll(rightTokens, right.split("\\s+"));
        Set<String> union = new HashSet<>(leftTokens);
        union.addAll(rightTokens);
        Set<String> intersection = new HashSet<>(leftTokens);
        intersection.retainAll(rightTokens);
        double tokenScore = union.isEmpty() ? 0d : (double) intersection.size() / union.size();
        int distance = levenshteinDistance(left, right);
        double textScore = 1d - (double) distance / Math.max(left.length(), right.length());
        return textScore * 0.65d + tokenScore * 0.35d;
    }

    private int levenshteinDistance(String left, String right) {
        int[] row = new int[right.length() + 1];
        for (int j = 0; j <= right.length(); j++) row[j] = j;
        for (int i = 1; i <= left.length(); i++) {
            int previous = row[0];
            row[0] = i;
            for (int j = 1; j <= right.length(); j++) {
                int saved = row[j];
                row[j] = Math.min(Math.min(row[j] + 1, row[j - 1] + 1),
                        previous + (left.charAt(i - 1) == right.charAt(j - 1) ? 0 : 1));
                previous = saved;
            }
        }
        return row[right.length()];
    }

    private void shareCurrentThread() {
        CuspTab tab = currentTab();
        if (tab == null || tab.url == null || tab.url.trim().isEmpty()) {
            Toast.makeText(this, text("\u5171\u6709\u3059\u308bURL\u304c\u3042\u308a\u307e\u305b\u3093", "No thread URL to share."), Toast.LENGTH_SHORT).show();
            return;
        }
        shareUrl(tab.url, text("\u30b9\u30ec\u3092\u5171\u6709", "Share thread"));
    }

    private void shareUrl(String url) {
        shareUrl(url, text("\u30ea\u30f3\u30af\u3092\u5171\u6709", "Share link"));
    }

    private void shareUrl(String url, String title) {
        if (url == null || url.trim().isEmpty()) {
            return;
        }
        Intent intent = new Intent(Intent.ACTION_SEND);
        intent.setType("text/plain");
        intent.putExtra(Intent.EXTRA_TEXT, url);
        startActivity(Intent.createChooser(intent, title));
    }

    private void goBack() {
        CuspTab tab = currentTab();
        rememberBoardHistoryScroll(tab);
        if (tab == null || tab.navigationIndex <= 0 || tab.navigationIndex > tab.navigationHistory.size() - 1) {
            clearAddressFocus();
            if (tab != null && tab.backToNewTab) {
                boolean privateBrowsing = isPrivateTab(tab);
                rememberTabScroll(tab);
                closeCurrentTabWithoutSwitch();
                showPendingNewTab(privateBrowsing, false);
            } else if (tab != null && tab.returnToIndex >= 0) {
                int returnIndex = Math.max(0, Math.min(tab.returnToIndex, tabs.size() - 1));
                CuspTab returnTab = returnIndex >= 0 && returnIndex < tabs.size()
                        ? tabs.get(returnIndex) : null;
                closeCurrentTab();
                if (!pendingNewTab && returnTab != null) {
                    int liveReturnIndex = tabs.indexOf(returnTab);
                    if (liveReturnIndex >= 0 && liveReturnIndex != currentIndex) {
                        switchToTab(liveReturnIndex);
                    }
                }
            }
            return;
        }
        clearAddressFocus();
        tab.navigationIndex--;
        requestSaveTabsSoon();
        navigateHistory(tab);
    }

    private void goForward() {
        if (pendingNewTab) {
            if (canGoForwardInNewTab()) {
                navigateNewTabHistory(1);
            }
            clearAddressFocus();
            return;
        }
        CuspTab tab = currentTab();
        rememberBoardHistoryScroll(tab);
        if (!canGoForwardInCurrentTab(tab)) {
            clearAddressFocus();
            return;
        }
        clearAddressFocus();
        int nextIndex = tab.navigationIndex + 1;
        tab.navigationIndex = nextIndex;
        requestSaveTabsSoon();
        navigateHistory(tab);
    }

    private void navigateHistory(CuspTab tab) {
        if (tab == null || tab.navigationIndex < 0 || tab.navigationIndex >= tab.navigationHistory.size()) {
            return;
        }
        int tabIndex = tabs.indexOf(tab);
        if (tabIndex >= 0 && tabIndex != currentIndex) {
            switchToTab(tabIndex);
        }
        String url = tab.navigationHistory.get(tab.navigationIndex);
        if (restorePendingNewTabFromInternalUrl(tab, url)) {
            return;
        }
        if (restoreBoardHistoryPage(tab, url)) {
            return;
        }
        if (NATIVE_THREAD.equals(tab.nativeKind) && isBoardUrl(url)) {
            showImmediateBoardHistoryLoading(tab, url);
            openInCurrentTab(url, false, tab.tabScope, bookmarkTabFolder(tab), true);
            return;
        }
        openInCurrentTab(url, false);
    }

    private void showImmediateBoardHistoryLoading(CuspTab tab, String url) {
        if (tab == null || url == null || url.trim().isEmpty()) {
            return;
        }
        tab.readerMode = true;
        tab.nativeKind = NATIVE_BOARD;
        tab.url = normalizeUrl(url);
        tab.title = boardTitle(tab.url);
        showImmediateNavigationLoading(tab);
        updateAddressBarDisplay(false);
        updateBottomThreadBar(tab);
    }

    private void rememberBoardHistoryScroll(CuspTab tab) {
        if (tab == null || !NATIVE_BOARD.equals(tab.nativeKind) || tab.searchPage == null || tab.readerView == null) {
            return;
        }
        rememberContentScroll(tab);
        boolean updated = false;
        for (String key : boardHistoryKeys(tab, tab.searchPage.url)) {
            BoardHistoryPage cached = tab.boardHistoryPages.get(key);
            if (cached != null) {
                cached.rememberScroll(tab.contentScrollRatio, tab.contentScrollY,
                        tab.contentScrollUrl, tab.hasSavedContentScroll);
                updated = true;
            }
        }
        if (!updated) {
            cacheBoardHistoryPage(tab, tab.searchPage, tab.readerView);
        }
    }

    private void cacheBoardHistoryPage(CuspTab tab, SearchPage page, View view) {
        if (tab == null || page == null || view == null || page.error != null
                || !NATIVE_BOARD.equals(tab.nativeKind) || page.url == null || page.url.trim().isEmpty()) {
            return;
        }
        rememberContentScroll(tab);
        BoardHistoryPage cached = new BoardHistoryPage(page, view, tab.title,
                tab.contentScrollRatio, tab.contentScrollY, tab.contentScrollUrl, tab.hasSavedContentScroll);
        for (String key : boardHistoryKeys(tab, page.url)) {
            tab.boardHistoryPages.remove(key);
            tab.boardHistoryPages.put(key, cached);
        }
        while (tab.boardHistoryPages.size() > MAX_BOARD_HISTORY_PAGES) {
            String oldest = tab.boardHistoryPages.keySet().iterator().next();
            tab.boardHistoryPages.remove(oldest);
        }
    }

    private boolean restoreBoardHistoryPage(CuspTab tab, String url) {
        if (tab == null || url == null
                || (!isBoardUrl(url) && !isBbsDirectoryUrl(url) && !isBbsInternalPageUrl(url))) {
            return false;
        }
        BoardHistoryPage cached = null;
        String restoredKey = null;
        for (String key : boardHistoryRestoreKeys(tab, url)) {
            cached = tab.boardHistoryPages.remove(key);
            if (cached != null) {
                restoredKey = key;
                break;
            }
        }
        if (cached == null || cached.page == null || cached.view == null) {
            return false;
        }
        tab.boardHistoryPages.put(restoredKey == null ? boardHistoryKey(url) : restoredKey, cached);
        tab.readerMode = true;
        tab.nativeKind = NATIVE_BOARD;
        tab.url = isBbsInternalPageUrl(url) ? url : cached.page.url;
        tab.title = cached.title;
        tab.searchPage = cached.page;
        tab.threadPage = null;
        tab.threadScroll = null;
        tab.postViews = null;
        tab.readerView = cached.view;
        tab.contentScrollRatio = cached.scrollRatio;
        tab.contentScrollY = cached.scrollY;
        tab.contentScrollUrl = cached.scrollUrl;
        tab.hasSavedContentScroll = cached.hasSavedScroll;
        int index = tabs.indexOf(tab);
        if (index >= 0) {
            switchToTab(index);
        }
        renderTabs();
        return true;
    }

    private String boardHistoryKey(String url) {
        return trimSlash(normalizeUrl(url));
    }

    private List<String> boardHistoryKeys(CuspTab tab, String url) {
        List<String> keys = new ArrayList<>();
        addUnique(keys, boardHistoryKey(url));
        if (tab != null) {
            if (tab.url != null && !tab.url.trim().isEmpty()) {
                addUnique(keys, boardHistoryKey(tab.url));
            }
            if (tab.navigationIndex >= 0 && tab.navigationIndex < tab.navigationHistory.size()) {
                addUnique(keys, boardHistoryKey(tab.navigationHistory.get(tab.navigationIndex)));
            }
        }
        return keys;
    }

    private List<String> boardHistoryRestoreKeys(CuspTab tab, String url) {
        List<String> keys = new ArrayList<>();
        addUnique(keys, boardHistoryKey(url));
        if (tab != null && tab.navigationIndex >= 0 && tab.navigationIndex < tab.navigationHistory.size()) {
            addUnique(keys, boardHistoryKey(tab.navigationHistory.get(tab.navigationIndex)));
        }
        return keys;
    }

    private boolean restorePendingNewTabFromInternalUrl(CuspTab tab, String url) {
        if (url == null || !url.startsWith(INTERNAL_URL_PREFIX + "newtab-history/")) {
            return false;
        }
        List<String> pages = decodeNewTabHistoryPages(url);
        int restoredIndex = decodeNewTabHistoryIndex(url, pages);
        int removeIndex = tabs.indexOf(tab);
        if (removeIndex >= 0) {
            tabs.remove(removeIndex);
            if (currentIndex > removeIndex) {
                currentIndex--;
            } else if (currentIndex >= tabs.size()) {
                currentIndex = tabs.size() - 1;
            }
        }
        pendingNewTab = true;
        pendingPrivateNewTab = isPrivateTab(tab);
        tabOverviewVisible = false;
        newTabNavigationHistory.clear();
        newTabNavigationHistory.addAll(pages);
        newTabNavigationIndex = Math.max(0, Math.min(restoredIndex, newTabNavigationHistory.size() - 1));
        String currentPage = newTabNavigationHistory.get(newTabNavigationIndex);
        pendingHistoryAll = "history".equals(currentPage);
        contentFrame.removeAllViews();
        renderNewTabPage(currentPage, false);
        requestSaveTabsSoon();
        return true;
    }

    private List<String> decodeNewTabHistoryPages(String url) {
        List<String> pages = new ArrayList<>();
        try {
            String json = decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "newtab-history/").length()));
            JSONObject root = new JSONObject(json);
            JSONArray array = root.optJSONArray("pages");
            if (array != null) {
                for (int i = 0; i < array.length(); i++) {
                    String page = array.optString(i, "");
                    if (!page.isEmpty()) {
                        pages.add(page);
                    }
                }
            }
        } catch (Exception ignored) {
        }
        if (pages.isEmpty()) {
            pages.add("home");
        } else if (!"home".equals(pages.get(0))) {
            pages.add(0, "home");
        }
        return pages;
    }

    private int decodeNewTabHistoryIndex(String url, List<String> pages) {
        try {
            String json = decodeNewTabToken(url.substring((INTERNAL_URL_PREFIX + "newtab-history/").length()));
            JSONObject root = new JSONObject(json);
            return Math.max(0, Math.min(root.optInt("index", pages.size() - 1), pages.size() - 1));
        } catch (Exception ignored) {
            return Math.max(0, pages.size() - 1);
        }
    }

    private boolean canGoBackInCurrentTab(CuspTab tab) {
        return tab != null
                && (tab.navigationIndex > 0 || tab.backToNewTab || tab.returnToIndex >= 0);
    }

    private boolean canGoForwardInCurrentTab(CuspTab tab) {
        return tab != null
                && tab.navigationIndex >= 0
                && tab.navigationIndex < tab.navigationHistory.size() - 1;
    }

    private boolean canGoForwardInNewTab() {
        return pendingNewTab
                && newTabNavigationIndex >= 0
                && newTabNavigationIndex < newTabNavigationHistory.size() - 1;
    }

    private void reload() {
        CuspTab tab = currentTab();
        if (tab == null) {
            return;
        }
        if (tab.readerMode && NATIVE_THREAD.equals(tab.nativeKind)) {
            clearAddressFocus();
            loadThread(tab, tab.url);
        } else if (tab.readerMode && NATIVE_HISSI.equals(tab.nativeKind)) {
            clearAddressFocus();
            loadHissiChecker(tab, tab.url);
        } else if (tab.readerMode && NATIVE_SEARCH.equals(tab.nativeKind)) {
            clearAddressFocus();
            loadSearchResults(tab, tab.url);
        } else if (tab.readerMode && NATIVE_BOARD.equals(tab.nativeKind)) {
            clearAddressFocus();
            loadBoard(tab, tab.url);
        } else if (tab.readerMode && NATIVE_SEARCH_HOME.equals(tab.nativeKind)) {
            clearAddressFocus();
            loadSearchHome(tab, tab.url);
        }
    }

    private void reloadFromMenu() {
        if (pendingNewTab) {
            reloadPendingNewTab();
            return;
        }
        CuspTab tab = currentTab();
        if (tab == null) {
            return;
        }
        if (tab.readerMode && NATIVE_THREAD.equals(tab.nativeKind)) {
            clearAddressFocus();
            refreshThreadFromBottom(tab, false, true);
        } else {
            reload();
        }
    }

    private void reloadAllTabs() {
        reloadAllTabs(false);
    }

    private void reloadAllTabs(boolean centerSpinner) {
        reloadAllTabs(centerSpinner, null);
    }

    private void reloadAllTabs(boolean centerSpinner, Runnable onComplete) {
        boolean wasOverview = tabOverviewVisible;
        List<CuspTab> targets = new ArrayList<>();
        for (CuspTab tab : new ArrayList<>(tabs)) {
            if (tab == null || tab.url == null || tab.url.isEmpty()
                    || !tab.readerMode || !NATIVE_THREAD.equals(tab.nativeKind)
                    || (wasOverview && tab.privateBrowsing != tabOverviewPrivateMode)) {
                continue;
            }
            targets.add(tab);
        }
        List<SavedItem> bookmarkTargets = wasOverview && !tabOverviewPrivateMode && showBookmarksInTabOverview()
                ? readSavedItems(PREF_THREAD_BOOKMARKS)
                : new ArrayList<>();
        int totalTargets = targets.size() + bookmarkTargets.size();
        if (wasOverview && centerSpinner && totalTargets > 0) {
            showCenterSpinner();
        }
        AtomicInteger remaining = new AtomicInteger(totalTargets);
        Runnable done = () -> {
            if (remaining.decrementAndGet() <= 0) {
                if (wasOverview && centerSpinner) {
                    hideCenterSpinner();
                }
                trimBackgroundTabViews();
                trimBackgroundPageData();
                requestSaveTabsSoon();
                if (wasOverview && tabOverviewVisible && contentFrame != null) {
                    if (!tabOverviewPrivateMode && showBookmarksInTabOverview()
                            && !bookmarkTargets.isEmpty()) {
                        refreshTabOverviewBookmarkSectionOnly();
                    } else {
                        syncClosedTabUndoBar();
                    }
                }
                if (onComplete != null) {
                    onComplete.run();
                }
            }
        };
        for (CuspTab tab : targets) {
            reloadThreadTabForOverview(tab, done);
        }
        for (SavedItem bookmark : bookmarkTargets) {
            reloadBookmarkForOverview(bookmark, done);
        }
        if (totalTargets == 0) {
            if (wasOverview) {
                tabOverviewVisible = true;
            }
            if (onComplete != null) {
                onComplete.run();
            }
        }
    }

    private void reloadPendingNewTab() {
        if (!pendingNewTab) {
            return;
        }
        clearAddressFocus();
        progressBar.setVisibility(View.VISIBLE);
        List<SavedItem> bookmarks = readSavedItems(PREF_THREAD_BOOKMARKS);
        if (bookmarks.isEmpty()) {
            progressBar.setVisibility(View.GONE);
            renderCurrentNewTabPage();
            return;
        }
        AtomicInteger remaining = new AtomicInteger(bookmarks.size());
        for (SavedItem bookmark : bookmarks) {
            reloadBookmarkForOverview(bookmark, () -> {
                if (remaining.decrementAndGet() == 0) {
                    progressBar.setVisibility(View.GONE);
                    renderCurrentNewTabPage();
                }
            });
        }
    }

    private void renderCurrentNewTabPage() {
        if (!pendingNewTab || newTabNavigationIndex < 0 || newTabNavigationIndex >= newTabNavigationHistory.size()) {
            refreshCurrentHomeOrHistoryView();
            return;
        }
        renderNewTabPage(newTabNavigationHistory.get(newTabNavigationIndex), false);
    }

    private void reloadThreadTabForOverview(CuspTab tab, Runnable onComplete) {
        if (tab == null || tab.url == null || tab.url.isEmpty()) {
            if (onComplete != null) {
                onComplete.run();
            }
            return;
        }
        final String url = tab.url;
        tabReloadExecutor.execute(() -> {
            ThreadOverviewStatus status = null;
            try {
                status = downloadThreadOverviewStatus(url);
            } catch (Exception ignored) {
            }
            ThreadOverviewStatus result = status;
            mainHandler.post(() -> {
                if (result != null && url.equals(tab.url)) {
                    applyOverviewReloadStatus(tab, result);
                    refreshTabOverviewSlotForTab(tab);
                }
                if (onComplete != null) {
                    onComplete.run();
                }
            });
        });
    }

    private void reloadBookmarkForOverview(SavedItem bookmark, Runnable onComplete) {
        if (bookmark == null || bookmark.url == null || bookmark.url.isEmpty()) {
            if (onComplete != null) {
                onComplete.run();
            }
            return;
        }
        final String url = bookmark.url;
        tabReloadExecutor.execute(() -> {
            ThreadOverviewStatus status = null;
            try {
                status = downloadThreadOverviewStatus(url);
            } catch (Exception ignored) {
            }
            ThreadOverviewStatus result = status;
            mainHandler.post(() -> {
                if (result != null) {
                    saveBookmarkOverviewStatus(url, result);
                }
                if (onComplete != null) {
                    onComplete.run();
                }
            });
        });
    }

    private ThreadOverviewStatus downloadThreadOverviewStatus(String url) throws Exception {
        DatAddress address = datAddress(url);
        if (address == null) {
            HttpURLConnection canonical = openConnectionFollowingRedirects(
                    url,
                    "Mozilla/5.0 (Linux; Android) CuspiDroid/0.1");
            try {
                address = datAddress(canonical.getURL().toString());
            } finally {
                canonical.disconnect();
            }
        }
        if (address == null) {
            throw new IllegalStateException("Unsupported thread URL.");
        }
        Exception lastError = null;
        for (String host : threadSubjectHosts(address)) {
            try {
                String scheme = address.scheme == null || address.scheme.isEmpty() ? "https" : address.scheme;
                String boardUrl = scheme + "://" + host + "/" + address.board + "/";
                BoardSubject subject = downloadBoardSubject(boardUrl, host, address.board);
                return threadOverviewStatusFromSubject(url, address.key, subject.body);
            } catch (Exception error) {
                lastError = error;
            }
        }
        throw lastError == null ? new IllegalStateException("subject.txt not found.") : lastError;
    }

    private List<String> threadSubjectHosts(DatAddress address) {
        List<String> hosts = new ArrayList<>();
        if (address == null) {
            return hosts;
        }
        addUnique(hosts, address.host);
        if (address.server != null && !address.server.trim().isEmpty()) {
            addUnique(hosts, address.server + ".5ch.net");
            addUnique(hosts, address.server + ".5ch.io");
        }
        return hosts;
    }

    private ThreadOverviewStatus threadOverviewStatusFromSubject(String url, String key, String body) {
        ThreadOverviewStatus status = new ThreadOverviewStatus();
        status.url = url;
        int order = 1;
        for (String line : (body == null ? "" : body).split("\\r?\\n")) {
            int sep = line.indexOf("<>");
            int sepLength = 2;
            if (sep <= 0) {
                sep = line.indexOf(",");
                sepLength = 1;
            }
            if (sep <= 0) {
                continue;
            }
            String dat = line.substring(0, sep);
            if (!dat.endsWith(".dat") && !dat.endsWith(".cgi")) {
                continue;
            }
            String lineKey = dat.substring(0, dat.length() - 4);
            if (!key.equals(lineKey)) {
                order++;
                continue;
            }
            String subjectTitle = cleanText(line.substring(sep + sepLength));
            status.title = stripThreadResponseCount(subjectTitle);
            status.responseCount = threadResponseCount(subjectTitle);
            status.boardOrder = order;
            status.archived = false;
            return status;
        }
        status.archived = true;
        return status;
    }

    private void applyOverviewReloadStatus(CuspTab tab, ThreadOverviewStatus status) {
        if (tab == null || status == null) {
            return;
        }
        boolean archived = status.archived || tab.knownThreadArchived
                || (tab.threadPage != null && tab.threadPage.archived);
        String title = status.title == null || status.title.trim().isEmpty()
                ? (tab.threadPage != null && tab.threadPage.title != null && !tab.threadPage.title.trim().isEmpty()
                ? tab.threadPage.title : tab.title)
                : status.title.trim();
        if (title == null || title.trim().isEmpty()) {
            title = hostTitle(status.url);
        }
        tab.title = title;
        tab.knownThreadArchived = archived;
        tab.knownBoardOrder = Math.max(0, status.boardOrder);
        tab.readPostNumber = Math.max(tab.readPostNumber, readPostNumberForTab(tab, status.url));
        int loadedPostNumber = maxPostNumber(tab.threadPage);
        if (loadedPostNumber <= 0) {
            loadedPostNumber = Math.max(tab.knownMaxPostNumber, tab.knownPostCount);
        }
        if (status.responseCount > loadedPostNumber) {
            tab.deferredThreadUpdatePostNumber = Math.max(
                    tab.deferredThreadUpdatePostNumber, status.responseCount);
        }
        if (tab.threadPage != null) {
            tab.threadPage.title = title;
            tab.threadPage.archived = archived;
            updateThreadTitleHeader(tab, tab.threadPage);
        }
        if (status.responseCount > 0) {
            tab.knownMaxPostNumber = status.responseCount;
            tab.knownPostCount = status.responseCount;
            tab.cachedUnreadCount = Math.max(0, status.responseCount - tab.readPostNumber);
            tab.hasThreadStats = true;
        } else if (tab.threadPage != null) {
            updateTabThreadStats(tab, tab.threadPage);
        } else if (tab.hasThreadStats) {
            tab.cachedUnreadCount = Math.max(0, tab.knownMaxPostNumber - tab.readPostNumber);
        }
    }

    private void saveBookmarkOverviewStatus(String url, ThreadOverviewStatus status) {
        if (url == null || status == null) {
            return;
        }
        try {
            JSONObject root = new JSONObject(preferences.getString(PREF_BOOKMARK_OVERVIEW_STATUS, "{}"));
            JSONObject item = new JSONObject();
            item.put("title", status.title == null ? "" : status.title);
            item.put("responseCount", status.responseCount);
            item.put("boardOrder", status.boardOrder);
            item.put("archived", status.archived);
            item.put("updatedAt", System.currentTimeMillis());
            root.put(bookmarkOverviewStatusKey(url), item);
            preferences.edit().putString(PREF_BOOKMARK_OVERVIEW_STATUS, root.toString()).apply();
            markBookmarkOverviewDirty();
        } catch (Exception ignored) {
        }
    }

    private void finishDeferredThreadUpdate(CuspTab tab, ThreadPage result) {
        if (tab == null || !tab.deferredThreadUpdateLoading) {
            return;
        }
        tab.deferredThreadUpdateLoading = false;
        if (result != null && result.error == null
                && maxPostNumber(result) >= tab.deferredThreadUpdatePostNumber) {
            tab.deferredThreadUpdatePostNumber = 0;
        }
    }

    private BookmarkOverviewStatus bookmarkOverviewStatus(String url) {
        return bookmarkOverviewStatus(url, preferenceJsonObject(PREF_BOOKMARK_OVERVIEW_STATUS));
    }

    private BookmarkOverviewStatus bookmarkOverviewStatus(String url, JSONObject root) {
        try {
            JSONObject item = root.optJSONObject(bookmarkOverviewStatusKey(url));
            if (item == null) {
                item = root.optJSONObject(url);
            }
            if (item == null) {
                return null;
            }
            BookmarkOverviewStatus status = new BookmarkOverviewStatus();
            status.title = item.optString("title", "");
            status.responseCount = item.optInt("responseCount", 0);
            status.boardOrder = item.optInt("boardOrder", 0);
            status.archived = item.optBoolean("archived", false);
            return status;
        } catch (Exception ignored) {
            return null;
        }
    }

    private String bookmarkOverviewStatusKey(String url) {
        return trimSlash(normalizeUrl(url));
    }

    private int bookmarkOverviewUnread(SavedItem item) {
        if (!bookmarkSupportsUnread(item)) {
            return 0;
        }
        BookmarkOverviewStatus status = bookmarkOverviewStatus(item.url);
        if (status == null || status.responseCount <= 0) {
            CuspTab openTab = matchingThreadTab(item.url);
            int responseCount = openTab != null && openTab.hasThreadStats
                    ? Math.max(openTab.knownMaxPostNumber, openTab.knownPostCount) : 0;
            return Math.max(0, responseCount - (openTab == null ? visibleReadPostNumber(item.url) : openTab.readPostNumber));
        }
        int responseCount = status.responseCount;
        CuspTab openTab = matchingThreadTab(item.url);
        if (openTab != null && openTab.hasThreadStats) {
            responseCount = Math.max(responseCount, Math.max(openTab.knownMaxPostNumber, openTab.knownPostCount));
        }
        int read = visibleReadPostNumber(item.url);
        if (openTab != null) {
            read = Math.max(read, openTab.readPostNumber);
        }
        return Math.max(0, responseCount - read);
    }

    private int bookmarkOverviewUnread(SavedItem item, BookmarkOverviewSnapshot snapshot) {
        if (!bookmarkSupportsUnread(item)) {
            return 0;
        }
        BookmarkOverviewStatus status = snapshot == null
                ? bookmarkOverviewStatus(item.url)
                : bookmarkOverviewStatus(item.url, snapshot.statusRoot);
        if (status == null || status.responseCount <= 0) {
            CuspTab openTab = matchingBookmarkOverviewOpenTab(item.url, snapshot);
            int responseCount = openTab != null && openTab.hasThreadStats
                    ? Math.max(openTab.knownMaxPostNumber, openTab.knownPostCount) : 0;
            int read = snapshot == null ? visibleReadPostNumber(item.url) : snapshot.readPosts.optInt(item.url, 0);
            if (openTab != null) {
                read = Math.max(read, openTab.readPostNumber);
            }
            return Math.max(0, responseCount - read);
        }
        int responseCount = status.responseCount;
        CuspTab openTab = matchingBookmarkOverviewOpenTab(item.url, snapshot);
        if (openTab != null && openTab.hasThreadStats) {
            responseCount = Math.max(responseCount, Math.max(openTab.knownMaxPostNumber, openTab.knownPostCount));
        }
        int read = snapshot == null ? visibleReadPostNumber(item.url) : snapshot.readPosts.optInt(item.url, 0);
        if (openTab != null) {
            read = Math.max(read, openTab.readPostNumber);
        }
        return Math.max(0, responseCount - read);
    }

    private boolean bookmarkSupportsUnread(SavedItem item) {
        return item != null && item.url != null && isThreadUrl(item.url);
    }

    private boolean showHomeBookmarkUnreadBadges() {
        return preferences == null || preferences.getBoolean(PREF_HOME_BOOKMARK_UNREAD_BADGES, true);
    }

    private boolean bookmarkSortEnabled() {
        return preferences != null && preferences.getBoolean(PREF_BOOKMARK_SORT_ENABLED, false);
    }

    private int bookmarkOverviewUnreadSum(List<SavedItem> bookmarks, String folder) {
        int total = 0;
        String normalizedFolder = folder == null ? null : normalizeSavedFolder(folder);
        for (SavedItem bookmark : bookmarks) {
            if (normalizedFolder != null
                    && !savedFolderDescendantOrSelf(normalizedFolder, normalizeSavedFolder(bookmark.folder))) {
                continue;
            }
            total += bookmarkOverviewUnread(bookmark);
        }
        return total;
    }

    private void closeCurrentTab() {
        if (tabs.isEmpty()) {
            return;
        }
        closeTab(currentIndex);
    }

    private void closeCurrentTabWithoutSwitch() {
        if (tabs.isEmpty() || currentIndex < 0 || currentIndex >= tabs.size()) {
            return;
        }
        removeTabWithoutSwitch(currentIndex);
        requestSaveTabsSoon();
    }

    private void switchRelativeTab(int delta) {
        if (tabs.isEmpty() || pendingNewTab) {
            return;
        }
        int target = currentIndex + delta;
        if (target < 0 || target >= tabs.size()) {
            return;
        }
        switchToTab(target);
    }

    private void closeTab(int index) {
        if (tabs.isEmpty() || index < 0 || index >= tabs.size()) {
            return;
        }
        CuspTab closing = tabs.get(index);
        boolean closingCurrent = index == currentIndex;
        clearLoadingUiForClosedTab(closing, closingCurrent);
        int returnToIndex = closing.returnToIndex;
        tabs.remove(index);
        for (CuspTab tab : tabs) {
            if (tab.returnToIndex == index) {
                tab.returnToIndex = -1;
            } else if (tab.returnToIndex > index) {
                tab.returnToIndex--;
            }
        }
        requestSaveTabsSoon();
        if (tabs.isEmpty()) {
            createBlankTab();
            return;
        }
        if (index == currentIndex && returnToIndex >= 0) {
            if (returnToIndex > index) {
                returnToIndex--;
            }
            currentIndex = Math.max(0, Math.min(returnToIndex, tabs.size() - 1));
        } else if (index < currentIndex) {
            currentIndex--;
        } else if (index == currentIndex) {
            currentIndex = Math.max(0, Math.min(index, tabs.size() - 1));
        } else {
            currentIndex = Math.max(0, Math.min(currentIndex, tabs.size() - 1));
        }
        switchToTab(currentIndex);
    }

    private void removeTabWithoutSwitch(int index) {
        if (tabs.isEmpty() || index < 0 || index >= tabs.size()) {
            return;
        }
        CuspTab closing = tabs.get(index);
        clearLoadingUiForClosedTab(closing, index == currentIndex);
        tabs.remove(index);
        for (CuspTab tab : tabs) {
            if (tab.returnToIndex == index) {
                tab.returnToIndex = -1;
            } else if (tab.returnToIndex > index) {
                tab.returnToIndex--;
            }
        }
        if (tabs.isEmpty()) {
            currentIndex = -1;
            return;
        }
        if (index < currentIndex) {
            currentIndex--;
        } else if (index == currentIndex) {
            currentIndex = Math.max(0, Math.min(index, tabs.size() - 1));
        } else {
            currentIndex = Math.max(0, Math.min(currentIndex, tabs.size() - 1));
        }
        syncLoadingUiWithCurrentSurface();
    }

    private void clearLoadingUiForClosedTab(CuspTab closing, boolean closingCurrent) {
        if (closing == null) {
            return;
        }
        CuspTab current = currentTab();
        if (!closingCurrent && (current != null && isLoadingReaderView(current.readerView))) {
            return;
        }
        if (!closingCurrent && !isLoadingReaderView(closing.readerView)) {
            return;
        }
        progressBar.setVisibility(View.GONE);
        hideCenterSpinner();
    }

    private CuspTab currentTab() {
        if (pendingNewTab) {
            return null;
        }
        if (currentIndex < 0 || currentIndex >= tabs.size()) {
            return null;
        }
        return tabs.get(currentIndex);
    }

    private boolean currentTabIsPrivate() {
        return pendingNewTab ? pendingPrivateNewTab : isPrivateTab(currentTab());
    }

    private boolean privateUiActive() {
        return tabOverviewVisible ? tabOverviewPrivateMode : currentTabIsPrivate();
    }

    private boolean isPrivateTab(CuspTab tab) {
        return tab != null && tab.privateBrowsing;
    }

    private String download(String urlText) throws Exception {
        return download(urlText, "Mozilla/5.0 (Linux; Android) CuspiDroid/0.1");
    }

    private String download(String urlText, String userAgent) throws Exception {
        Map<String, String> headers = new LinkedHashMap<>();
        headers.put("Accept-Encoding", "gzip");
        HttpURLConnection connection = openConnectionFollowingRedirects(urlText, userAgent, headers);
        try {
            int code = connection.getResponseCode();
            InputStream stream = responseInputStream(connection, code);
            if (stream == null) {
                throw new HttpStatusException(code, "");
            }
            byte[] bytes = readBytes(stream);
            Charset charset = responseCharset(connection, Charset.forName("UTF-8"));
            String body = new String(bytes, charset);
            Charset metaCharset = htmlMetaCharset(body);
            if (metaCharset != null && !metaCharset.equals(charset)) {
                body = new String(bytes, metaCharset);
            }
            if (code >= 400) {
                throw new HttpStatusException(code, stripTags(body));
            }
            return body;
        } finally {
            connection.disconnect();
        }
    }

    private InputStream responseInputStream(HttpURLConnection connection, int code) throws Exception {
        InputStream stream = code >= 400 ? connection.getErrorStream() : connection.getInputStream();
        if (stream == null) {
            return null;
        }
        String encoding = connection.getContentEncoding();
        if (encoding != null && encoding.toLowerCase(Locale.ROOT).contains("gzip")) {
            return new GZIPInputStream(stream);
        }
        return stream;
    }

    private String resolveRedirectedUrl(String urlText, String userAgent) throws Exception {
        HttpURLConnection connection = openConnectionFollowingRedirects(urlText, userAgent);
        try {
            return connection.getURL().toString();
        } finally {
            connection.disconnect();
        }
    }

    private Charset responseCharset(HttpURLConnection connection, Charset fallback) {
        Charset charset = fallback;
        String contentType = connection.getContentType();
        if (contentType != null) {
            Matcher matcher = Pattern.compile("charset=([^;]+)", Pattern.CASE_INSENSITIVE).matcher(contentType);
            if (matcher.find()) {
                try {
                    charset = Charset.forName(matcher.group(1).trim());
                } catch (Exception ignored) {
                }
            }
        }
        return charset;
    }

    private Charset htmlMetaCharset(String body) {
        if (body == null) {
            return null;
        }
        Matcher matcher = Pattern.compile("<meta[^>]+charset=[\"']?([^\"'\\s>/;]+)", Pattern.CASE_INSENSITIVE)
                .matcher(body);
        if (!matcher.find()) {
            return null;
        }
        try {
            return Charset.forName(matcher.group(1).trim());
        } catch (Exception error) {
            return null;
        }
    }

    private HttpURLConnection openConnectionFollowingRedirects(String urlText, String userAgent) throws Exception {
        return openConnectionFollowingRedirects(urlText, userAgent, null);
    }

    private HttpURLConnection openConnectionFollowingRedirects(String urlText, String userAgent, Map<String, String> headers) throws Exception {
        String current = urlText;
        for (int i = 0; i < 8; i++) {
            HttpURLConnection connection = (HttpURLConnection) new URL(current).openConnection();
            connection.setInstanceFollowRedirects(false);
            connection.setConnectTimeout(12000);
            connection.setReadTimeout(16000);
            connection.setRequestProperty("User-Agent", userAgent);
            connection.setRequestProperty("Accept", "*/*");
            if (headers != null) {
                for (Map.Entry<String, String> header : headers.entrySet()) {
                    connection.setRequestProperty(header.getKey(), header.getValue());
                }
            }
            applyCookies(connection, current, null);
            int code = connection.getResponseCode();
            storeCookies(current, connection.getHeaderFields().get("Set-Cookie"));
            if (code == HttpURLConnection.HTTP_MOVED_PERM
                    || code == HttpURLConnection.HTTP_MOVED_TEMP
                    || code == HttpURLConnection.HTTP_SEE_OTHER
                    || code == 307
                    || code == 308) {
                String location = connection.getHeaderField("Location");
                connection.disconnect();
                if (location == null || location.trim().isEmpty()) {
                    throw new IllegalStateException("Redirect without Location");
                }
                current = new URL(new URL(current), location).toString();
                continue;
            }
            return connection;
        }
        throw new IllegalStateException("Too many redirects");
    }

    private String readText(InputStream stream, Charset charset) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(stream, charset));
        StringBuilder builder = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            builder.append(line).append('\n');
        }
        reader.close();
        return builder.toString();
    }

    private byte[] readBytes(InputStream stream) throws Exception {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        byte[] buffer = new byte[8192];
        int read;
        while ((read = stream.read(buffer)) != -1) {
            out.write(buffer, 0, read);
        }
        stream.close();
        return out.toByteArray();
    }

    private ThreadPage downloadDatThread(String threadUrl) throws Exception {
        String pageUrl = threadUrl;
        DatAddress address = datAddress(threadUrl);
        if (address == null) {
            HttpURLConnection canonical = openConnectionFollowingRedirects(
                    threadUrl,
                    "Mozilla/5.0 (Linux; Android) CuspiDroid/0.1");
            String canonicalUrl = canonical.getURL().toString();
            canonical.disconnect();
            address = datAddress(canonicalUrl);
            if (address != null) {
                pageUrl = canonicalUrl;
            }
        }
        if (address == null) {
            return null;
        }
        List<String> candidates = datCandidates(address);
        for (String candidate : candidates) {
            try {
                DatDownload download = downloadDatBytes(candidate, 0);
                ThreadPage page = parseDatThread(pageUrl, download.body);
                page.datUrl = download.url;
                page.datByteLength = download.totalByteLength;
                page.archived = isArchiveDatUrl(download.url);
                return page;
            } catch (Exception error) {
            }
        }
        return null;
    }

    private ThreadPage downloadNewDatPosts(CuspTab tab) throws Exception {
        if (tab == null || tab.threadPage == null || tab.threadPage.posts.isEmpty()
                || tab.threadPage.datUrl == null || tab.threadPage.datUrl.isEmpty()
                || tab.threadPage.datByteLength <= 0) {
            return null;
        }
        return downloadNewDatPosts(tab.url, tab.threadPage);
    }

    private ThreadPage downloadNewDatPosts(String threadUrl, ThreadPage existing) throws Exception {
        if (existing == null || existing.posts == null || existing.posts.isEmpty()
                || existing.datUrl == null || existing.datUrl.isEmpty()
                || existing.datByteLength <= 0) {
            return null;
        }
        DatDownload download = downloadDatBytes(existing.datUrl, existing.datByteLength);
        if (download.unchanged || (download.partial && download.body.trim().isEmpty())) {
            ThreadPage unchanged = cloneThreadPage(existing);
            unchanged.url = threadUrl;
            unchanged.datUrl = download.url;
            unchanged.datByteLength = Math.max(existing.datByteLength, download.totalByteLength);
            unchanged.archived = existing.archived || isArchiveDatUrl(download.url);
            unchanged.newPostCount = 0;
            return unchanged;
        }
        if (!download.partial) {
            ThreadPage full = parseDatThread(threadUrl, download.body);
            full.datUrl = download.url;
            full.datByteLength = download.totalByteLength;
            full.archived = existing.archived || isArchiveDatUrl(download.url);
            full.newPostCount = Math.max(0, full.posts.size() - existing.posts.size());
            return full;
        }
        ThreadPage additional = parseDatThread(threadUrl, download.body,
                existing.posts.get(existing.posts.size() - 1).number + 1);
        if (additional.posts.isEmpty()) {
            return null;
        }
        ThreadPage merged = cloneThreadPage(existing);
        merged.datUrl = download.url;
        merged.datByteLength = download.totalByteLength;
        merged.archived = existing.archived || isArchiveDatUrl(download.url);
        for (Post post : additional.posts) {
            merged.posts.add(post);
            merged.postsByNumber.put(post.number, post);
        }
        merged.newPostCount = additional.posts.size();
        return merged;
    }

    private DatDownload downloadDatBytes(String url, long rangeStart) throws Exception {
        Map<String, String> headers = new LinkedHashMap<>();
        if (rangeStart > 0) {
            headers.put("Range", "bytes=" + rangeStart + "-");
        }
        HttpURLConnection connection = openConnectionFollowingRedirects(
                url,
                "Monazilla/1.00 CuspiDroid/0.1",
                headers);
        int code = connection.getResponseCode();
        if (rangeStart > 0 && code == 416) {
            long totalLength = totalLengthFromContentRange(connection.getHeaderField("Content-Range"));
            if (totalLength <= 0) {
                totalLength = rangeStart;
            }
            return new DatDownload(connection.getURL().toString(), "", totalLength, true, true);
        }
        InputStream stream = code >= 400 ? connection.getErrorStream() : connection.getInputStream();
        if (stream == null) {
            throw new IllegalStateException("HTTP " + code);
        }
        byte[] bytes = readBytes(stream);
        String host = Uri.parse(url).getHost();
        Charset charset = isShitarabaHost(host) ? Charset.forName("EUC-JP") : Charset.forName("MS932");
        String body = new String(bytes, charset);
        if (code >= 400) {
            throw new IllegalStateException("DAT HTTP " + code + "\n" + body.trim());
        }
        boolean partial = rangeStart > 0 && code == HttpURLConnection.HTTP_PARTIAL;
        long totalLength = partial ? totalLengthFromContentRange(connection.getHeaderField("Content-Range")) : bytes.length;
        if (totalLength <= 0) {
            totalLength = rangeStart + bytes.length;
        }
        return new DatDownload(connection.getURL().toString(), body, totalLength, partial, false);
    }

    private long totalLengthFromContentRange(String value) {
        if (value == null) {
            return 0;
        }
        Matcher matcher = Pattern.compile("/(\\d+)\\s*$").matcher(value);
        if (!matcher.find()) {
            return 0;
        }
        try {
            return Long.parseLong(matcher.group(1));
        } catch (Exception error) {
            return 0;
        }
    }

    private boolean isArchiveDatUrl(String url) {
        String lower = url == null ? "" : url.toLowerCase(Locale.ROOT);
        return lower.contains("/kako/") || lower.contains("/oyster/");
    }

    private ThreadPage cloneThreadPage(ThreadPage source) {
        ThreadPage copy = new ThreadPage();
        copy.url = source.url;
        copy.title = source.title;
        copy.error = source.error;
        copy.archived = source.archived;
        copy.datUrl = source.datUrl;
        copy.datByteLength = source.datByteLength;
        for (Post post : source.posts) {
            copy.posts.add(post);
            copy.postsByNumber.put(post.number, post);
        }
        return copy;
    }

    private List<String> datCandidates(DatAddress address) {
        List<String> candidates = new ArrayList<>();
        String realHost = address.server == null || address.server.trim().isEmpty()
                ? ""
                : address.server + ".5ch.io";
        if (address.host != null && !address.host.isEmpty()
                && !"itest.5ch.io".equalsIgnoreCase(address.host)) {
            String base = (address.scheme == null ? "https" : address.scheme) + "://" + address.host + "/" + address.board;
            if (isShitarabaHost(address.host)) {
                addUnique(candidates, (address.scheme == null ? "https" : address.scheme)
                        + "://" + address.host + "/bbs/rawmode.cgi/" + address.board + "/" + address.key + "/");
                return candidates;
            }
            addUnique(candidates, base + "/dat/" + address.key + ".dat");
            if (address.key.length() >= 4) {
                String bucket = address.key.substring(0, 4);
                addUnique(candidates, base + "/kako/" + bucket + "/" + address.key + ".dat");
            }
            if (address.key.length() >= 5) {
                String bucket4 = address.key.substring(0, 4);
                String bucket5 = address.key.substring(0, 5);
                addUnique(candidates, base + "/kako/" + bucket4 + "/" + bucket5 + "/" + address.key + ".dat");
            }
        }
        if (!realHost.isEmpty()) {
            String base = "https://" + realHost + "/" + address.board;
            addUnique(candidates, base + "/dat/" + address.key + ".dat");
            if (address.key.length() >= 4) {
                String bucket = address.key.substring(0, 4);
                addUnique(candidates, base + "/oyster/" + bucket + "/" + address.key + ".dat");
                addUnique(candidates, base + "/kako/" + bucket + "/" + address.key + ".dat");
            }
            if (address.key.length() >= 5) {
                String bucket4 = address.key.substring(0, 4);
                String bucket5 = address.key.substring(0, 5);
                addUnique(candidates, base + "/kako/" + bucket4 + "/" + bucket5 + "/" + address.key + ".dat");
            }
        }
        addUnique(candidates, "https://" + address.server + ".5ch.io/" + address.board + "/dat/" + address.key + ".dat");
        addUnique(candidates, "https://" + address.server + ".5ch.net/" + address.board + "/dat/" + address.key + ".dat");
        if (address.key.length() >= 4) {
            String bucket = address.key.substring(0, 4);
            addUnique(candidates, "https://" + address.server + ".5ch.io/" + address.board + "/oyster/" + bucket + "/" + address.key + ".dat");
            addUnique(candidates, "https://" + address.server + ".5ch.net/" + address.board + "/oyster/" + bucket + "/" + address.key + ".dat");
            addUnique(candidates, "https://" + address.server + ".5ch.io/" + address.board + "/kako/" + bucket + "/" + address.key + ".dat");
            addUnique(candidates, "https://" + address.server + ".5ch.net/" + address.board + "/kako/" + bucket + "/" + address.key + ".dat");
        }
        if (address.key.length() >= 5) {
            String bucket4 = address.key.substring(0, 4);
            String bucket5 = address.key.substring(0, 5);
            addUnique(candidates, "https://" + address.server + ".5ch.io/" + address.board + "/kako/" + bucket4 + "/" + bucket5 + "/" + address.key + ".dat");
            addUnique(candidates, "https://" + address.server + ".5ch.net/" + address.board + "/kako/" + bucket4 + "/" + bucket5 + "/" + address.key + ".dat");
        }
        return candidates;
    }

    private String threadHtmlUrl(String threadUrl) {
        DatAddress address = datAddress(threadUrl);
        if (address == null || address.shortThread || !is5chUrl(threadUrl)
                || address.server == null || address.server.trim().isEmpty()) {
            return threadUrl;
        }
        return "https://" + address.server + ".5ch.io/test/read.cgi/"
                + address.board + "/" + address.key + "/";
    }

    private DatAddress datAddress(String threadUrl) {
        Uri uri = Uri.parse(threadUrl);
        String host = uri.getHost();
        if (host == null) {
            return null;
        }
        String[] segments = uri.getPath() == null ? new String[0] : uri.getPath().split("/");
        List<String> parts = new ArrayList<>();
        for (String segment : segments) {
            if (!segment.isEmpty()) {
                parts.add(segment);
            }
        }

        int testIndex = parts.indexOf("test");
        if (testIndex < 0) {
            testIndex = parts.indexOf("bbs");
        }
        if (testIndex >= 0 && testIndex + 3 < parts.size()
                && "read.cgi".equals(parts.get(testIndex + 1))) {
            if (isShitarabaHost(host) && testIndex + 4 < parts.size()) {
                String board = parts.get(testIndex + 2) + "/" + parts.get(testIndex + 3);
                String key = parts.get(testIndex + 4);
                return datAddress(uri, host, host.split("\\.")[0], board, key, false);
            }
            String board = parts.get(testIndex + 2);
            String key = parts.get(testIndex + 3);
            String server = host.split("\\.")[0];
            if ("itest".equals(server) && testIndex > 0) {
                server = parts.get(testIndex - 1);
            }
            if ("itest".equals(server) || server.trim().isEmpty()) {
                return null;
            }
            return datAddress(uri, host, server, board, key, false);
        }
        if (isRegisteredShortThreadPath(threadUrl, parts)) {
            return datAddress(uri, host, host.split("\\.")[0], parts.get(0), parts.get(1), true);
        }
        return null;
    }

    private DatAddress boardWriteAddress(CuspTab tab) {
        if (tab == null || tab.url == null || !NATIVE_BOARD.equals(tab.nativeKind)
                || !isBoardUrl(tab.url) || isBbsDirectoryUrl(tab.url)) {
            return null;
        }
        Uri uri = Uri.parse(normalizeUrl(tab.url));
        String host = uri.getHost();
        String board = boardNameFromUrl(tab.url);
        if (host == null || host.trim().isEmpty() || board == null || board.trim().isEmpty()
                || isFutabaHost(host)) {
            return null;
        }
        String server = host.split("\\.")[0];
        if (("itest".equalsIgnoreCase(server)) && tab.searchPage != null
                && tab.searchPage.url != null && !tab.searchPage.url.equals(tab.url)) {
            Uri pageUri = Uri.parse(normalizeUrl(tab.searchPage.url));
            if (pageUri.getHost() != null && !"itest".equalsIgnoreCase(pageUri.getHost().split("\\.")[0])) {
                host = pageUri.getHost();
                server = host.split("\\.")[0];
            }
        }
        return datAddress(uri, host, server, board, "", usesShortThreadUrls(tab.url, host));
    }

    private DatAddress datAddress(Uri uri, String host, String server, String board, String key, boolean shortThread) {
        DatAddress address = new DatAddress();
        address.scheme = uri.getScheme() == null ? "https" : uri.getScheme();
        address.host = host;
        address.server = server;
        address.board = board;
        address.key = key;
        address.shortThread = shortThread;
        return address;
    }

    private boolean isRegisteredShortThreadPath(String url, List<String> parts) {
        if (parts == null || parts.size() < 2 || is5chUrl(url) || !isRegisteredBbsUrl(url)) {
            return false;
        }
        String board = parts.get(0);
        String key = parts.get(1);
        String lowerBoard = board == null ? "" : board.toLowerCase(Locale.ROOT);
        if (board == null || board.trim().isEmpty()
                || "test".equals(lowerBoard) || "bbs".equals(lowerBoard) || "dat".equals(lowerBoard)) {
            return false;
        }
        return key != null && key.matches("\\d{9,13}");
    }

    private ThreadPage parseDatThread(String threadUrl, String dat) {
        return parseDatThread(threadUrl, dat, 1);
    }

    private ThreadPage parseDatThread(String threadUrl, String dat, int firstNumber) {
        ThreadPage page = new ThreadPage();
        page.url = threadUrl;
        page.title = hostTitle(threadUrl);
        int number = Math.max(1, firstNumber);
        int start = 0;
        int length = dat == null ? 0 : dat.length();
        while (start < length) {
            int end = start;
            while (end < length && dat.charAt(end) != '\n' && dat.charAt(end) != '\r') {
                end++;
            }
            String line = dat.substring(start, end);
            if (end < length && dat.charAt(end) == '\r' && end + 1 < length && dat.charAt(end + 1) == '\n') {
                end++;
            }
            start = end + 1;
            if (line.trim().isEmpty()) {
                continue;
            }
            String[] fields = splitDatFields(line);
            if (fields.length < 4) {
                continue;
            }
            Post post = new Post();
            boolean machiDat = isMachiDatFields(threadUrl, fields);
            if (machiDat) {
                post.number = parsePositiveInt(fields[0], number);
                post.name = cleanText(fields[1]);
                post.date = cleanText(fields[3]);
                post.body = cleanText(fields[4]);
            } else {
                post.number = number;
                post.name = cleanText(fields[0]);
                post.date = cleanText(fields[2]);
                post.body = cleanText(fields[3]);
            }
            post.cachedLikelyAa = likelyAaPost(post.body);
            page.posts.add(post);
            page.postsByNumber.put(post.number, post);
            if (number == 1) {
                String title = machiDat && fields.length >= 6
                        ? cleanText(fields[5])
                        : fields.length >= 5 ? cleanText(fields[4]) : "";
                if (!title.isEmpty()) {
                    page.title = title;
                }
            }
            number = Math.max(number + 1, post.number + 1);
        }
        return page;
    }

    private String[] splitDatFields(String line) {
        List<String> fields = new ArrayList<>(6);
        int start = 0;
        while (true) {
            int sep = line.indexOf("<>", start);
            if (sep < 0) {
                fields.add(line.substring(start));
                break;
            }
            fields.add(line.substring(start, sep));
            start = sep + 2;
        }
        return fields.toArray(new String[0]);
    }

    private boolean isMachiDatFields(String threadUrl, String[] fields) {
        if (fields == null || fields.length < 5) {
            return false;
        }
        try {
            String host = Uri.parse(threadUrl).getHost();
            String lowerHost = host == null ? "" : host.toLowerCase(Locale.ROOT);
            if (!lowerHost.equals("machi.to") && !lowerHost.endsWith(".machi.to")
                    && !isShitarabaHost(lowerHost)) {
                return false;
            }
        } catch (Exception ignored) {
            return false;
        }
        String number = fields[0] == null ? "" : fields[0].trim();
        if (!number.matches("\\d+")) {
            return false;
        }
        String date = fields[3] == null ? "" : cleanText(fields[3]);
        String body = fields[4] == null ? "" : cleanText(fields[4]);
        return !date.isEmpty() && !body.isEmpty();
    }

    private SearchPage downloadBoard(String boardUrl) throws Exception {
        BoardSubject subject = null;
        Uri originalUri = Uri.parse(normalizeUrl(boardUrl));
        String originalHost = originalUri.getHost();
        String originalBoard = boardNameFromUrl(boardUrl);
        if (originalHost != null && originalBoard != null && !isFutabaBoardUrl(boardUrl)) {
            try {
                subject = downloadBoardSubject(boardUrl, originalHost, originalBoard);
            } catch (Exception ignored) {
                subject = null;
            }
        }
        String redirectedUrl = subject == null
                ? resolveRedirectedUrl(boardUrl, "Mozilla/5.0 (Linux; Android) CuspiDroid/0.1")
                : boardUrl;
        Uri uri = Uri.parse(redirectedUrl);
        String host = uri.getHost();
        String board = boardNameFromUrl(redirectedUrl);
        if (host == null || board == null) {
            throw new IllegalStateException("Unsupported board URL.");
        }
        if (isFutabaBoardUrl(redirectedUrl)) {
            return parseFutabaBoard(redirectedUrl, download(redirectedUrl));
        }
        if (subject == null && originalHost != null && originalBoard != null
                && !sameSavedUrl(boardUrl, redirectedUrl)) {
            try {
                subject = downloadBoardSubject(boardUrl, originalHost, originalBoard);
            } catch (Exception error) {
                subject = null;
            }
        }
        try {
            if (subject == null) {
                subject = downloadBoardSubject(redirectedUrl, host, board);
            }
        } catch (Exception directError) {
            String dataUrl = boardDataUrlFromHtml(redirectedUrl, board);
            if (dataUrl == null || dataUrl.equals(redirectedUrl)) {
                throw directError;
            }
            Uri dataUri = Uri.parse(dataUrl);
            String dataHost = dataUri.getHost();
            String dataBoard = boardNameFromUrl(dataUrl);
            if (dataHost == null || dataBoard == null) {
                throw directError;
            }
            subject = downloadBoardSubject(dataUrl, dataHost, dataBoard);
        }
        String body = subject.body;
        String pageUrl = subject.boardUrl == null || subject.boardUrl.trim().isEmpty()
                ? redirectedUrl
                : subject.boardUrl;

        SearchPage page = new SearchPage();
        page.url = pageUrl;
        page.title = boardTitle(pageUrl);
        JSONObject readPosts = readHistoryEnabled() ? preferenceJsonObject(PREF_READ_POSTS) : new JSONObject();
        List<ThreadHistoryItem> historyItems = threadHistory();
        Set<String> historyUrls = threadHistoryUrlSnapshot(historyItems);
        List<BoardPriorityRule> priorityRules = readBoardPriorityRules(preferences);
        String boardDisplay = displayBoardTitle(pageUrl);
        int order = 1;
        for (String line : body.split("\\r?\\n")) {
            int sep = line.indexOf("<>");
            int sepLength = 2;
            if (sep <= 0) {
                sep = line.indexOf(",");
                sepLength = 1;
            }
            if (sep <= 0) {
                continue;
            }
            String dat = line.substring(0, sep);
            String title = cleanText(line.substring(sep + sepLength));
            if (!dat.endsWith(".dat") && !dat.endsWith(".cgi")) {
                continue;
            }
            String key = dat.substring(0, dat.length() - 4);
            int responses = threadResponseCount(title);
            SearchResult result = new SearchResult();
            result.title = title;
            result.url = subject.threadBase + key + "/";
            result.responses = responses;
            result.velocity = threadVelocity(key, responses);
            result.boardOrder = order;
            result.createdAt = threadCreatedAtMillis(key);
            result.hasReadHistory = threadHistoryContains(historyUrls, historyItems, result.url);
            int readNumber = result.hasReadHistory ? boardThreadReadNumber(readPosts, result.url) : 0;
            result.unread = result.hasReadHistory ? Math.max(0, responses - readNumber) : 0;
            result.boardName = boardDisplay;
            result.priorityMatch = matchingBoardPriorityWord(title, pageUrl, priorityRules);
            result.meta = boardThreadMeta(result);
            page.results.add(result);
            order++;
        }
        sortBoardResults(page.results);
        return page;
    }

    private int boardThreadReadNumber(JSONObject readPosts, String url) {
        int read = readPostNumberFromObject(readPosts, url);
        CuspTab openTab = matchingThreadTab(url);
        if (openTab != null) {
            read = Math.max(read, openTab.readPostNumber);
        }
        return read;
    }

    private int readPostNumberFromObject(JSONObject object, String url) {
        if (object == null || url == null || url.trim().isEmpty()) {
            return 0;
        }
        int read = 0;
        for (String key : threadHistoryKeys(url)) {
            read = Math.max(read, object.optInt(key, 0));
        }
        try {
            Iterator<String> keys = object.keys();
            while (keys.hasNext()) {
                String key = keys.next();
                if (sameThreadIdentity(key, url)) {
                    read = Math.max(read, object.optInt(key, 0));
                }
            }
        } catch (Exception ignored) {
        }
        return read;
    }

    private String boardDataUrlFromHtml(String boardUrl, String board) {
        try {
            String html = download(boardUrl, "Mozilla/5.0 (Linux; Android) CuspiDroid/0.1");
            Matcher ref = Pattern.compile(
                    "\\bref\\s*=\\s*['\"](https?://[^'\"]+)['\"]",
                    Pattern.CASE_INSENSITIVE).matcher(html);
            if (ref.find()) {
                return normalizeUrl(ref.group(1));
            }
            Matcher domain = Pattern.compile(
                    "id\\s*=\\s*['\"]board_domain['\"][^>]*value\\s*=\\s*['\"]([^'\"]+)['\"]",
                    Pattern.CASE_INSENSITIVE).matcher(html);
            boolean foundDomain = domain.find();
            if (!foundDomain) {
                domain = Pattern.compile(
                        "value\\s*=\\s*['\"]([^'\"]+)['\"][^>]*id\\s*=\\s*['\"]board_domain['\"]",
                        Pattern.CASE_INSENSITIVE).matcher(html);
                foundDomain = domain.find();
            }
            if (foundDomain) {
                String scheme = Uri.parse(boardUrl).getScheme();
                return (scheme == null ? "https" : scheme) + "://" + domain.group(1) + "/" + board + "/";
            }
        } catch (Exception ignored) {
        }
        return null;
    }

    private SearchPage downloadBbsDirectory(String directoryUrl) throws Exception {
        String redirectedUrl = resolveRedirectedUrl(
                directoryUrl,
                "Mozilla/5.0 (Linux; Android) CuspiDroid/0.1");
        String html = download(redirectedUrl);
        if (isShitarabaBbsMenuJsonUrl(redirectedUrl)) {
            return parseShitarabaBbsMenuJson(redirectedUrl, html);
        }
        Uri base = Uri.parse(normalizeUrl(redirectedUrl));
        String baseHost = base.getHost();
        SearchPage page = new SearchPage();
        page.url = redirectedUrl;
        page.title = hostTitle(redirectedUrl);
        Set<String> seen = new LinkedHashSet<>();
        Map<String, Integer> categoryCounts = new LinkedHashMap<>();
        Pattern anchorPattern = Pattern.compile(
                "<a\\s+[^>]*href\\s*=\\s*(?:\"([^\"]+)\"|'([^']+)'|([^\\s>]+))[^>]*>(.*?)</a>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = anchorPattern.matcher(html);
        int lastEnd = 0;
        String currentCategory = "";
        Map<String, String> boardNames = new LinkedHashMap<>();
        while (matcher.find()) {
            currentCategory = lastBbsMenuCategory(html.substring(lastEnd, matcher.start()), currentCategory);
            lastEnd = matcher.end();
            String href = firstNonEmpty(matcher.group(1), matcher.group(2), matcher.group(3));
            String label = cleanText(matcher.group(4));
            if (href == null || href.trim().isEmpty()) {
                continue;
            }
            String absolute = absoluteUrl(redirectedUrl, href);
            Uri target = Uri.parse(absolute);
            String host = target.getHost();
            if (!isSameDirectoryFamily(redirectedUrl, absolute, baseHost, host)) {
                continue;
            }
            if (!isDirectoryBoardLink(absolute)) {
                continue;
            }
            String board = boardNameFromUrl(absolute);
            if (board == null || board.trim().isEmpty()) {
                continue;
            }
            String boardUrl = boardUrlFromDirectoryLink(absolute, board);
            if (!seen.add(boardUrl)) {
                continue;
            }
            boardNames.put(boardUrl, label);
            SearchResult result = new SearchResult();
            result.title = label == null || label.isEmpty() ? board : label;
            result.url = boardUrl;
            result.meta = host;
            result.category = currentCategory;
            page.results.add(result);
            String category = currentCategory == null ? "" : currentCategory.trim();
            categoryCounts.put(category, categoryCounts.containsKey(category) ? categoryCounts.get(category) + 1 : 1);
        }
        page.categoryCounts = categoryCounts;
        saveBoardDisplayNames(boardNames);
        if (page.results.isEmpty()) {
            throw new IllegalStateException(text("\u677f\u30ea\u30f3\u30af\u304c\u898b\u3064\u304b\u308a\u307e\u305b\u3093", "No board links found."));
        }
        return page;
    }

    private String lastBbsMenuCategory(String htmlFragment, String fallback) {
        if (htmlFragment == null || htmlFragment.isEmpty()) {
            return fallback == null ? "" : fallback;
        }
        String category = fallback == null ? "" : fallback;
        Pattern pattern = Pattern.compile(
                "<(?:b|strong)\\b[^>]*>(.*?)</(?:b|strong)>|<h[1-6]\\b[^>]*>(.*?)</h[1-6]>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = pattern.matcher(htmlFragment);
        while (matcher.find()) {
            String value = cleanText(firstNonEmpty(matcher.group(1), matcher.group(2)));
            if (looksLikeBbsCategory(value)) {
                category = value;
            }
        }
        return category;
    }

    private boolean looksLikeBbsCategory(String value) {
        if (value == null) {
            return false;
        }
        String trimmed = value.trim();
        return !trimmed.isEmpty() && trimmed.length() <= 40 && !trimmed.contains("http");
    }

    private boolean isSameDirectoryFamily(String directoryUrl, String targetUrl, String baseHost, String targetHost) {
        if (baseHost == null || targetHost == null) {
            return false;
        }
        if (targetHost.equalsIgnoreCase(baseHost)) {
            return true;
        }
        if (isBbsMenuUrl(directoryUrl) && is5chUrl(directoryUrl) && is5chUrl(targetUrl)) {
            return true;
        }
        if (isBbsMenuUrl(directoryUrl) && isSameBbsHostFamily(baseHost, targetHost)) {
            return true;
        }
        return false;
    }

    private boolean isDirectoryBoardLink(String url) {
        try {
            Uri uri = Uri.parse(normalizeUrl(url));
            String path = uri.getPath();
            if (path == null || path.isEmpty()) {
                return false;
            }
            String[] parts = path.split("/");
            List<String> nonEmpty = new ArrayList<>();
            for (String part : parts) {
                if (part != null && !part.isEmpty()) {
                    nonEmpty.add(part);
                }
            }
            if (nonEmpty.isEmpty()) {
                return false;
            }
            String first = nonEmpty.get(0).toLowerCase(Locale.ROOT);
            if ("cdn-cgi".equals(first) || "image".equals(first) || "sp".equals(first)) {
                return false;
            }
            if ("bbs".equals(first) && nonEmpty.size() >= 3
                    && "read.cgi".equalsIgnoreCase(nonEmpty.get(1))) {
                return true;
            }
            if (isShitarabaBoardUrl(url) || isFutabaBoardUrl(url)) {
                return true;
            }
            if (isRegisteredBbsMenuChild(url, nonEmpty)) {
                return true;
            }
            if (nonEmpty.size() == 1) {
                return !nonEmpty.get(0).contains(".");
            }
            return false;
        } catch (Exception error) {
            return false;
        }
    }

    private boolean isRegisteredBbsMenuChild(String url, List<String> pathParts) {
        if (url == null || pathParts == null || pathParts.size() < 2) {
            return false;
        }
        try {
            Uri target = Uri.parse(normalizeUrl(url));
            String targetHost = target.getHost();
            if (targetHost == null) {
                return false;
            }
            for (BbsLink link : readBbsLinks(preferences)) {
                Uri base = Uri.parse(normalizeUrl(link.url));
                String baseHost = base.getHost();
                if (baseHost == null || !isSameBbsHostFamily(baseHost, targetHost) || !isBbsMenuUrl(link.url)) {
                    continue;
                }
                List<String> baseParts = pathParts(base.getPath());
                if (baseParts.isEmpty()) {
                    continue;
                }
                String menuFile = baseParts.get(baseParts.size() - 1).toLowerCase(Locale.ROOT);
                if (!menuFile.endsWith(".html") && !menuFile.endsWith(".htm")) {
                    continue;
                }
                List<String> prefix = baseParts.subList(0, baseParts.size() - 1);
                if (pathParts.size() == prefix.size() + 1 && pathStartsWith(pathParts, prefix)
                        && !pathParts.get(pathParts.size() - 1).contains(".")) {
                    return true;
                }
            }
        } catch (Exception ignored) {
        }
        return false;
    }

    private String boardUrlFromDirectoryLink(String url, String board) {
        if (isShitarabaBoardUrl(url) || isFutabaBoardUrl(url)) {
            return normalizeUrl(url);
        }
        Uri uri = Uri.parse(url);
        String scheme = uri.getScheme() == null ? "https" : uri.getScheme();
        String host = uri.getHost();
        if (host == null) {
            return url;
        }
        return scheme + "://" + host + "/" + board + "/";
    }

    private String absoluteUrl(String baseUrl, String href) {
        try {
            return new URL(new URL(normalizeUrl(baseUrl)), href).toString();
        } catch (Exception error) {
            return normalizeUrl(href);
        }
    }

    private BoardSubject downloadBoardSubject(String boardUrl, String host, String board) throws Exception {
        Exception lastError = null;
        for (String subjectUrl : boardSubjectCandidates(boardUrl, host, board)) {
            HttpURLConnection connection = null;
            try {
                connection = openConnectionFollowingRedirects(
                        subjectUrl,
                        "Monazilla/1.00 CuspiDroid/0.1");
                int code = connection.getResponseCode();
                InputStream stream = code >= 400 ? connection.getErrorStream() : connection.getInputStream();
                if (stream == null) {
                    throw new IllegalStateException("HTTP " + code);
                }
                String body = readText(stream, responseCharset(connection, boardSubjectFallbackCharset(subjectUrl)));
                if (code >= 400) {
                    throw new IllegalStateException("HTTP " + code + "\n" + cleanText(body));
                }
                if (!isBoardSubjectBody(body)) {
                    throw new IllegalStateException("Invalid subject.txt response.");
                }
                String loadedSubjectUrl = connection.getURL().toString();
                return new BoardSubject(body, threadBaseFromSubjectUrl(loadedSubjectUrl, board),
                        boardUrlFromSubjectUrl(loadedSubjectUrl));
            } catch (Exception error) {
                lastError = error;
            } finally {
                if (connection != null) {
                    connection.disconnect();
                }
            }
        }
        throw lastError == null ? new IllegalStateException("subject.txt not found.") : lastError;
    }

    private Charset boardSubjectFallbackCharset(String subjectUrl) {
        try {
            return isShitarabaHost(Uri.parse(subjectUrl).getHost())
                    ? Charset.forName("EUC-JP")
                    : Charset.forName("MS932");
        } catch (Exception ignored) {
            return Charset.forName("MS932");
        }
    }

    private boolean isBoardSubjectBody(String body) {
        if (body == null || body.trim().isEmpty()) {
            return true;
        }
        for (String line : body.split("\\r?\\n")) {
            int separator = line.indexOf("<>");
            if (separator <= 0) {
                separator = line.indexOf(",");
            }
            if (separator <= 0) {
                continue;
            }
            String file = line.substring(0, separator).trim().toLowerCase(Locale.ROOT);
            if (file.endsWith(".dat") || file.endsWith(".cgi")) {
                return true;
            }
        }
        return false;
    }

    private List<String> boardSubjectCandidates(String boardUrl, String host, String board) {
        List<String> urls = new ArrayList<>();
        String normalized = normalizeUrl(boardUrl);
        addUnique(urls, trimSlash(normalized) + "/subject.txt");
        String scheme = Uri.parse(normalized).getScheme();
        if (scheme == null || scheme.isEmpty()) {
            scheme = "https";
        }
        if (host.toLowerCase(Locale.ROOT).endsWith("machi.to")) {
            addUnique(urls, scheme + "://" + host + "/bbs/" + board + "/subject.txt");
            addUnique(urls, "https://" + host + "/bbs/" + board + "/subject.txt");
            addUnique(urls, "http://" + host + "/bbs/" + board + "/subject.txt");
        }
        addUnique(urls, scheme + "://" + host + "/" + board + "/subject.txt");
        addUnique(urls, "https://" + host + "/" + board + "/subject.txt");
        addUnique(urls, "http://" + host + "/" + board + "/subject.txt");
        for (BbsLink link : readBbsLinks(preferences)) {
            try {
                Uri base = Uri.parse(normalizeUrl(link.url));
                if (base.getHost() != null && base.getHost().equalsIgnoreCase(host)) {
                    addUnique(urls, trimSlash(normalizeUrl(link.url)) + "/subject.txt");
                }
            } catch (Exception ignored) {
            }
        }
        return urls;
    }

    private void addUnique(List<String> values, String value) {
        if (value != null && !values.contains(value)) {
            values.add(value);
        }
    }

    private String trimSlash(String value) {
        String result = value == null ? "" : value.trim();
        while (result.endsWith("/")) {
            result = result.substring(0, result.length() - 1);
        }
        return result;
    }

    private String threadBaseFromSubjectUrl(String subjectUrl, String board) {
        Uri uri = Uri.parse(subjectUrl);
        String scheme = uri.getScheme() == null ? "https" : uri.getScheme();
        String host = uri.getHost();
        if (host == null) {
            return "";
        }
        if (isShitarabaHost(host)) {
            return scheme + "://" + host + "/bbs/read.cgi/" + board + "/";
        }
        if (usesShortThreadUrls(subjectUrl, host)) {
            return scheme + "://" + host + "/" + board + "/";
        }
        String reader = host.toLowerCase(Locale.ROOT).endsWith("machi.to")
                ? "/bbs/read.cgi/"
                : "/test/read.cgi/";
        return scheme + "://" + host + reader + board + "/";
    }

    private String boardUrlFromSubjectUrl(String subjectUrl) {
        String value = trimSlash(normalizeUrl(subjectUrl));
        String lower = value.toLowerCase(Locale.ROOT);
        if (lower.endsWith("/subject.txt")) {
            return value.substring(0, value.length() - "/subject.txt".length()) + "/";
        }
        return value;
    }

    private boolean usesShortThreadUrls(String url, String host) {
        if (host == null) {
            return false;
        }
        String lowerHost = host.toLowerCase(Locale.ROOT);
        return isRegisteredBbsUrl(url)
                && !is5chUrl(url)
                && !lowerHost.endsWith(".open2ch.net")
                && !lowerHost.equals("open2ch.net")
                && !lowerHost.endsWith(".machi.to")
                && !lowerHost.equals("machi.to")
                && !lowerHost.endsWith(".2ch.sc")
                && !lowerHost.equals("2ch.sc")
                && !lowerHost.endsWith(".bbspink.org")
                && !lowerHost.equals("bbspink.org")
                && !isShitarabaHost(lowerHost);
    }

    private int threadResponseCount(String title) {
        Matcher matcher = Pattern.compile("\\((\\d{1,6})\\)\\s*$").matcher(title == null ? "" : title);
        return matcher.find() ? parsePositiveInt(matcher.group(1), 0) : 0;
    }

    private String stripThreadResponseCount(String title) {
        return Pattern.compile("\\s*\\(\\d{1,6}\\)\\s*$")
                .matcher(title == null ? "" : title)
                .replaceFirst("")
                .trim();
    }

    private double threadVelocity(String key, int responses) {
        int created = parsePositiveInt(key, 0);
        if (created <= 0 || responses <= 0) {
            return 0d;
        }
        double days = Math.max(1d / 24d, (System.currentTimeMillis() / 1000d - created) / 86400d);
        return responses / days;
    }

    private long threadCreatedAtMillis(String key) {
        int created = parsePositiveInt(key, 0);
        return created <= 0 ? 0L : created * 1000L;
    }

    private void sortBoardResults(List<SearchResult> results) {
        if (results == null || results.isEmpty()) {
            return;
        }
        final String sortKey = boardThreadSortKey();
        final boolean desc = boardThreadSortDesc();
        for (int i = 0; i < results.size(); i++) {
            if (results.get(i).boardOrder <= 0) {
                results.get(i).boardOrder = i + 1;
            }
        }
        Collections.sort(results, (left, right) -> {
            int leftPriority = left.priorityMatch == null ? 0 : 1;
            int rightPriority = right.priorityMatch == null ? 0 : 1;
            if (leftPriority != rightPriority) {
                return Integer.compare(rightPriority, leftPriority);
            }
            int compared = compareBoardSortValue(left, right, sortKey);
            if (compared != 0) {
                return desc ? -compared : compared;
            }
            return Integer.compare(left.boardOrder, right.boardOrder);
        });
    }

    private int compareBoardSortValue(SearchResult left, SearchResult right, String sortKey) {
        if (BOARD_SORT_BOARD_NAME.equals(sortKey)) {
            return String.CASE_INSENSITIVE_ORDER.compare(
                    left.boardName == null ? "" : left.boardName,
                    right.boardName == null ? "" : right.boardName);
        }
        if (BOARD_SORT_RESPONSES.equals(sortKey)) {
            return Integer.compare(left.responses, right.responses);
        }
        if (BOARD_SORT_VELOCITY.equals(sortKey)) {
            return Double.compare(left.velocity, right.velocity);
        }
        if (BOARD_SORT_CREATED.equals(sortKey)) {
            return Long.compare(left.createdAt, right.createdAt);
        }
        if (BOARD_SORT_UNREAD.equals(sortKey)) {
            return Integer.compare(left.unread, right.unread);
        }
        return Integer.compare(left.boardOrder, right.boardOrder);
    }

    private String boardThreadSortKey() {
        String key = preferences.getString(PREF_BOARD_THREAD_SORT_KEY, "");
        if (key == null || key.isEmpty()) {
            return preferences.getBoolean(PREF_BOARD_SORT_BY_SPEED, true)
                    ? BOARD_SORT_VELOCITY : BOARD_SORT_ORDER;
        }
        return key;
    }

    private boolean boardThreadSortDesc() {
        return preferences.getBoolean(PREF_BOARD_THREAD_SORT_DESC, true);
    }

    private BoardPriorityMatch matchingBoardPriorityWord(String title, String boardUrl) {
        return matchingBoardPriorityWord(title, boardUrl, readBoardPriorityRules(preferences));
    }

    private BoardPriorityMatch matchingBoardPriorityWord(String title, String boardUrl,
                                                          List<BoardPriorityRule> rules) {
        if (title == null || title.isEmpty()) {
            return null;
        }
        String lowerTitle = title.toLowerCase(Locale.ROOT);
        if (rules == null) {
            return null;
        }
        for (BoardPriorityRule rule : rules) {
            if (!boardPriorityRuleApplies(rule, boardUrl)) {
                continue;
            }
            String value = rule.value == null ? "" : rule.value.trim();
            if (value.isEmpty()) {
                continue;
            }
            if (rule.regex) {
                try {
                    Matcher matcher = Pattern.compile(value, Pattern.CASE_INSENSITIVE).matcher(title);
                    if (matcher.find()) {
                        return new BoardPriorityMatch(value, true);
                    }
                } catch (Exception ignored) {
                }
            } else if (lowerTitle.contains(value.toLowerCase(Locale.ROOT))) {
                return new BoardPriorityMatch(value, false);
            }
        }
        return null;
    }

    private String boardThreadMeta(SearchResult result) {
        List<String> parts = new ArrayList<>();
        String board = result == null || result.boardName == null ? "" : result.boardName;
        if (!board.isEmpty() && preferences.getBoolean(PREF_BOARD_SHOW_BOARD_NAME, false)) {
            parts.add(board);
        }
        if (preferences.getBoolean(PREF_BOARD_SHOW_RESPONSES, true)) {
            parts.add(result.responses > 0
                    ? text("\u30ec\u30b9: ", "Posts: ") + result.responses
                    : text("\u30ec\u30b9: -", "Posts: -"));
        }
        if (preferences.getBoolean(PREF_BOARD_SHOW_VELOCITY, true)) {
            parts.add(result.velocity > 0
                    ? text("\u52e2\u3044: ", "Speed: ") + String.format(Locale.ROOT, "%.1f", result.velocity)
                    : text("\u52e2\u3044: -", "Speed: -"));
        }
        if (preferences.getBoolean(PREF_BOARD_SHOW_ORDER, true)) {
            parts.add(text("\u9806\u4f4d: ", "Rank: ") + (result.boardOrder > 0 ? result.boardOrder : "-"));
        }
        if (preferences.getBoolean(PREF_BOARD_SHOW_CREATED, true)) {
            parts.add(text("\u4f5c\u6210: ", "Created: ") + boardCreatedText(result.createdAt));
        }
        return TextUtils.join("  ", parts);
    }

    private String boardCreatedText(long createdAt) {
        if (createdAt <= 0) {
            return "-";
        }
        return DateFormat.getDateTimeInstance(DateFormat.SHORT, DateFormat.SHORT).format(new Date(createdAt));
    }

    private ThreadPage parseThread(String url, String html) {
        ThreadPage page = new ThreadPage();
        page.url = url;
        page.title = firstMatch(html, "<title[^>]*>(.*?)</title>");
        if (page.title == null || page.title.trim().isEmpty()) {
            page.title = hostTitle(url);
        }
        page.title = cleanText(page.title);

        parseFutabaPosts(html, page.posts);
        parseMachiPosts(html, page.posts);
        if (page.posts.isEmpty()) {
            parseKakoPosts(html, page.posts);
        }
        if (page.posts.isEmpty()) {
            parseModernPosts(html, page.posts);
        }
        if (page.posts.isEmpty()) {
            parseClassicPosts(html, page.posts);
        }
        indexPosts(page);
        return page;
    }

    private void parseFutabaPosts(String html, List<Post> posts) {
        if (html == null || !html.contains("2chan.net") && !html.contains("GazouBBS")) {
            return;
        }
        Pattern pattern = Pattern.compile(
                "<span[^>]+class=[\"']cno[\"'][^>]*>\\s*No\\.(\\d+)\\s*</span>(.*?)(?=<span[^>]+class=[\"']cno[\"']|<div[^>]+style=[\"']clear:left|</div><!--\\s*\\u30b9\\u30ec\\u30c3\\u30c9\\u7d42\\u4e86|<hr)",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = pattern.matcher(html);
        while (matcher.find()) {
            String block = matcher.group(2);
            String body = firstMatch(block, "<blockquote[^>]*>(.*?)</blockquote>");
            if (body == null || cleanText(body).isEmpty()) {
                continue;
            }
            Post post = new Post();
            post.number = parsePositiveInt(matcher.group(1), posts.size() + 1);
            post.name = valueOr(firstMatch(block, "<span[^>]+class=[\"']cnm[\"'][^>]*>(.*?)</span>"), "anonymous");
            post.date = valueOr(firstMatch(block, "<span[^>]+class=[\"']cnw[\"'][^>]*>(.*?)</span>"), "");
            post.body = cleanText(body);
            post.cachedLikelyAa = likelyAaPost(post.body);
            posts.add(post);
        }
    }

    private void indexPosts(ThreadPage page) {
        page.postsByNumber.clear();
        for (Post post : page.posts) {
            if (post.cachedLikelyAa == null) {
                post.cachedLikelyAa = likelyAaPost(post.body);
            }
            page.postsByNumber.put(post.number, post);
        }
    }

    private void parseKakoPosts(String html, List<Post> posts) {
        Pattern pattern = Pattern.compile(
                "<div\\s+id=[\"'](\\d+)[\"'][^>]+class=[\"'][^\"']*(?<![A-Za-z0-9_-])post(?![A-Za-z0-9_-])[^\"']*[\"'][^>]*>(.*?)(?=<div\\s+id=[\"']\\d+[\"'][^>]+class=[\"'][^\"']*(?<![A-Za-z0-9_-])post(?![A-Za-z0-9_-])|<div[^>]+class=[\"'][^\"']*ads_container|<div[^>]+class=[\"'][^\"']*navmenu|</div>\\s*<footer|</body>)",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = pattern.matcher(html);
        while (matcher.find()) {
            String block = matcher.group(2);
            String body = firstMatch(block,
                    "<section[^>]+class=[\"'][^\"']*post-content[^\"']*[\"'][^>]*>(.*?)</section>");
            if (body == null) {
                continue;
            }
            Post post = new Post();
            post.number = parsePositiveInt(matcher.group(1), posts.size() + 1);
            post.name = valueOr(firstMatch(block,
                    "<span[^>]+class=[\"'][^\"']*postusername[^\"']*[\"'][^>]*>\\s*<b[^>]*>(.*?)</b>"), "anonymous");
            post.date = valueOr(firstMatch(block,
                    "<span[^>]+class=[\"'][^\"']*date[^\"']*[\"'][^>]*>(.*?)</span>"), "");
            String id = firstMatch(block,
                    "<span[^>]+class=[\"'][^\"']*uid[^\"']*[\"'][^>]*>(.*?)</span>");
            if (id != null && !cleanText(id).isEmpty()) {
                String plainId = cleanText(id);
                post.date = post.date == null || post.date.trim().isEmpty()
                        ? plainId
                        : post.date + " " + plainId;
            }
            post.body = cleanText(body);
            if (post.body.isEmpty()) {
                continue;
            }
            posts.add(post);
        }
    }

    private void parseModernPosts(String html, List<Post> posts) {
        Pattern pattern = Pattern.compile(
                "<div[^>]+class=[\"'][^\"']*post[^\"']*[\"'][^>]*>(.*?)</div>\\s*</div>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = pattern.matcher(html);
        int fallbackNumber = 1;
        while (matcher.find()) {
            String block = matcher.group(1);
            String body = firstMatch(block, "<div[^>]+class=[\"'][^\"']*(?:message|escaped)[^\"']*[\"'][^>]*>(.*?)</div>");
            if (body == null) {
                continue;
            }
            Post post = new Post();
            post.number = parsePositiveInt(valueOr(firstMatch(block, "class=[\"'][^\"']*(?:number|no)[^\"']*[\"'][^>]*>(.*?)<"), String.valueOf(fallbackNumber)), fallbackNumber);
            post.name = valueOr(firstMatch(block, "class=[\"'][^\"']*name[^\"']*[\"'][^>]*>(.*?)<"), "anonymous");
            post.date = valueOr(firstMatch(block, "class=[\"'][^\"']*(?:date|time)[^\"']*[\"'][^>]*>(.*?)<"), "");
            post.body = cleanText(body);
            posts.add(post);
            fallbackNumber++;
        }
    }

    private void parseMachiPosts(String html, List<Post> posts) {
        Pattern pattern = Pattern.compile(
                "<div[^>]+class=[\"'][^\"']*(?<![A-Za-z0-9_-])res(?![A-Za-z0-9_-])[^\"']*[\"'][^>]*>(.*?)</div>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = pattern.matcher(html);
        while (matcher.find()) {
            String block = matcher.group(1);
            Matcher separator = Pattern.compile("<hr[^>]+class=[\"'][^\"']*reshr[^\"']*[\"'][^>]*>",
                    Pattern.CASE_INSENSITIVE | Pattern.DOTALL).matcher(block);
            if (!separator.find()) {
                continue;
            }
            String meta = block.substring(0, separator.start());
            String body = block.substring(separator.end());
            Post post = new Post();
            post.number = parsePositiveInt(valueOr(firstMatch(meta, "^\\s*(\\d+)\\s*:"), String.valueOf(posts.size() + 1)),
                    posts.size() + 1);
            post.name = valueOr(firstMatch(meta, "<b[^>]*>(.*?)</b>"), "anonymous");
            post.date = valueOr(firstMatch(meta, "<font[^>]+size=[\"']?1[\"']?[^>]*>(.*?)</font>"), "");
            post.body = cleanText(body);
            if (post.body.isEmpty()) {
                continue;
            }
            posts.add(post);
        }
    }

    private void parseClassicPosts(String html, List<Post> posts) {
        Pattern pattern = Pattern.compile("<dt[^>]*>(.*?)</dt>\\s*<dd[^>]*>(.*?)</dd>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = pattern.matcher(html);
        while (matcher.find()) {
            String meta = matcher.group(1);
            String body = matcher.group(2);
            Post post = new Post();
            post.number = parsePositiveInt(valueOr(firstMatch(meta, "^(\\s*\\d+)"), String.valueOf(posts.size() + 1)).trim(), posts.size() + 1);
            post.name = valueOr(firstMatch(meta, "<b[^>]*>(.*?)</b>"), "anonymous");
            post.date = cleanText(stripTags(meta)).replace(String.valueOf(post.number), "").replace(post.name, "").trim();
            post.body = cleanText(body);
            posts.add(post);
        }
    }

    private SearchPage parseSearchPage(String url, String html) {
        SearchPage page = new SearchPage();
        page.url = url;
        page.title = searchTitle(url);
        Pattern rowPattern = Pattern.compile(
                "<div[^>]+class=[\"'][^\"']*(?<![A-Za-z0-9_-])list_line(?![A-Za-z0-9_-])[^\"']*[\"'][^>]*>(.*?)(?=<div[^>]+class=[\"'][^\"']*(?<![A-Za-z0-9_-])list_line(?![A-Za-z0-9_-])[^\"']*[\"']|</div>\\s*</div>\\s*<div[^>]+class=[\"'][^\"']*col-lg-5|<script|</body>)",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher rowMatcher = rowPattern.matcher(html);
        while (rowMatcher.find()) {
            String block = rowMatcher.group(1);
            String href = firstMatch(block, "<a[^>]+class=[\"'][^\"']*list_line_link[^\"']*[\"'][^>]+href=[\"']([^\"']+)[\"']");
            String title = firstMatch(block, "<div[^>]+class=[\"'][^\"']*list_line_link_title[^\"']*[\"'][^>]*>(.*?)</div>");
            if (href == null || title == null) {
                continue;
            }
            SearchResult result = new SearchResult();
            result.url = absolutizeFindUrl(href);
            result.title = cleanText(title);
            result.meta = cleanSearchMeta(block);
            page.results.add(result);
        }
        return page;
    }

    private String cleanSearchMeta(String block) {
        StringBuilder meta = new StringBuilder();
        Pattern infoPattern = Pattern.compile(
                "<div[^>]+class=[\"'][^\"']*list_line_info_container[^\"']*[\"'][^>]*>(.*?)</div>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = infoPattern.matcher(block);
        while (matcher.find()) {
            String value = cleanText(matcher.group(1));
            if (!value.isEmpty()) {
                if (meta.length() > 0) {
                    meta.append("  ");
                }
                meta.append(value);
            }
        }
        return meta.toString();
    }

    private String absolutizeFindUrl(String href) {
        if (href.startsWith("//")) {
            return "https:" + href;
        }
        if (href.startsWith("http://") || href.startsWith("https://")) {
            return href;
        }
        if (href.startsWith("/")) {
            return "https://find.5ch.io" + href;
        }
        return "https://find.5ch.io/" + href;
    }

    private int parsePositiveInt(String value, int fallback) {
        if (value == null) {
            return fallback;
        }
        Matcher matcher = Pattern.compile("\\d+").matcher(value);
        if (!matcher.find()) {
            return fallback;
        }
        try {
            int parsed = Integer.parseInt(matcher.group());
            return parsed > 0 ? parsed : fallback;
        } catch (NumberFormatException error) {
            return fallback;
        }
    }

    private String firstMatch(String text, String regex) {
        Matcher matcher = Pattern.compile(regex, Pattern.CASE_INSENSITIVE | Pattern.DOTALL).matcher(text);
        return matcher.find() ? matcher.group(1) : null;
    }

    private String firstNonEmpty(String... values) {
        if (values == null) {
            return null;
        }
        for (String value : values) {
            if (value != null && !value.trim().isEmpty()) {
                return value.trim();
            }
        }
        return null;
    }

    private String cleanText(String html) {
        String marker = "\uE000";
        String normalized = html
                .replaceAll("(?i)<br\\s*/?>", marker)
                .replaceAll("(?i)</p\\s*>", marker)
                .replaceAll("(?i)</div\\s*>", marker);
        Spanned spanned;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
            spanned = Html.fromHtml(normalized, Html.FROM_HTML_MODE_LEGACY);
        } else {
            spanned = Html.fromHtml(normalized);
        }
        return spanned.toString()
                .replace(marker, "\n")
                .replace('\u00a0', ' ')
                .replaceAll("[ \\t]+\\n", "\n")
                .replaceAll("\\n[ \\t]+", "\n")
                .trim();
    }

    private String stripTags(String html) {
        return cleanText(html.replaceAll("<script[\\s\\S]*?</script>", "")
                .replaceAll("<style[\\s\\S]*?</style>", "")
                .replaceAll("<[^>]+>", " "));
    }

    private String valueOr(String value, String fallback) {
        if (value == null || cleanText(value).isEmpty()) {
            return fallback;
        }
        return cleanText(value);
    }

    private void addThreadHistory(String url, String title, int responseCount) {
        if (url == null || url.trim().isEmpty() || title == null || title.trim().isEmpty()) {
            return;
        }
        List<ThreadHistoryItem> history = threadHistory();
        for (int i = history.size() - 1; i >= 0; i--) {
            if (url.equals(history.get(i).url)) {
                history.remove(i);
            }
        }
        history.add(0, new ThreadHistoryItem(title, url, System.currentTimeMillis(), responseCount));
        while (history.size() > 100) {
            history.remove(history.size() - 1);
        }
        JSONArray array = new JSONArray();
        try {
            for (ThreadHistoryItem item : history) {
                JSONObject object = new JSONObject();
                object.put("title", item.title);
                object.put("url", item.url);
                object.put("lastViewedAt", item.lastViewedAt);
                object.put("responseCount", item.responseCount);
                array.put(object);
            }
        } catch (Exception ignored) {
        }
        preferences.edit().putString(PREF_HISTORY, array.toString()).apply();
    }

    private void addThreadHistory(CuspTab tab, String url, String title) {
        if (isPrivateTab(tab) || !browsingHistoryEnabled()) {
            return;
        }
        int responseCount = tab == null ? 0 : Math.max(tab.knownMaxPostNumber, tab.knownPostCount);
        addThreadHistory(url, title, responseCount);
    }

    static List<ThreadHistoryItem> readThreadHistory(SharedPreferences preferences) {
        List<ThreadHistoryItem> history = readThreadItems(preferences, PREF_HISTORY);
        Collections.sort(history, (left, right) -> Long.compare(right.lastViewedAt, left.lastViewedAt));
        return history;
    }

    static List<WritePostHistoryItem> readWritePostHistory(SharedPreferences preferences) {
        List<WritePostHistoryItem> history = new ArrayList<>();
        Map<String, String> titles = new LinkedHashMap<>();
        for (ThreadHistoryItem item : readThreadHistory(preferences)) {
            titles.put(item.url, item.title);
        }
        try {
            JSONObject root = new JSONObject(preferences.getString(PREF_MY_POSTS, "{}"));
            Iterator<String> urls = root.keys();
            while (urls.hasNext()) {
                String url = urls.next();
                JSONArray items = root.optJSONArray(url);
                if (items == null) {
                    continue;
                }
                for (int i = 0; i < items.length(); i++) {
                    Object value = items.opt(i);
                    String hash = myPostHash(value);
                    if (hash.isEmpty()) {
                        continue;
                    }
                    String title = myPostTitle(value);
                    if (title.isEmpty()) {
                        title = titles.containsKey(url) ? titles.get(url) : url;
                    }
                    history.add(new WritePostHistoryItem(
                            title,
                            url,
                            myPostNumber(value),
                            myPostBody(value),
                            hash,
                            myPostPostedAt(value)));
                }
            }
        } catch (Exception ignored) {
        }
        Collections.sort(history, (left, right) -> Long.compare(right.postedAt, left.postedAt));
        return history;
    }

    static void clearWritePostHistory(SharedPreferences preferences) {
        preferences.edit().remove(PREF_MY_POSTS).apply();
    }

    static void removeWritePostHistory(SharedPreferences preferences, WritePostHistoryItem target) {
        if (target == null || target.url == null || target.url.isEmpty() || target.hash == null || target.hash.isEmpty()) {
            return;
        }
        try {
            JSONObject root = new JSONObject(preferences.getString(PREF_MY_POSTS, "{}"));
            JSONArray old = root.optJSONArray(target.url);
            if (old == null) {
                return;
            }
            JSONArray next = new JSONArray();
            for (int i = 0; i < old.length(); i++) {
                Object value = old.opt(i);
                if (matchesWritePostHistory(value, target)) {
                    continue;
                }
                next.put(value);
            }
            if (next.length() == 0) {
                root.remove(target.url);
            } else {
                root.put(target.url, next);
            }
            preferences.edit().putString(PREF_MY_POSTS, root.toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private static boolean matchesWritePostHistory(Object value, WritePostHistoryItem target) {
        if (target == null || !target.hash.equals(myPostHash(value))) {
            return false;
        }
        int number = myPostNumber(value);
        long postedAt = myPostPostedAt(value);
        return (target.number <= 0 || number == target.number)
                && (target.postedAt <= 0 || postedAt == target.postedAt);
    }

    private static List<ThreadHistoryItem> readThreadItems(SharedPreferences preferences, String key) {
        List<ThreadHistoryItem> history = new ArrayList<>();
        try {
            JSONArray array = new JSONArray(preferences.getString(key, "[]"));
            for (int i = 0; i < array.length(); i++) {
                JSONObject object = array.optJSONObject(i);
                if (object == null) {
                    continue;
                }
                String title = object.optString("title", "").trim();
                String url = object.optString("url", "").trim();
                long fallbackViewedAt = System.currentTimeMillis() - i;
                long lastViewedAt = object.optLong("lastViewedAt", fallbackViewedAt);
                int responseCount = Math.max(0, object.optInt("responseCount", 0));
                if (!title.isEmpty() && !url.isEmpty()) {
                    history.add(new ThreadHistoryItem(title, url, lastViewedAt, responseCount));
                }
            }
        } catch (Exception ignored) {
        }
        return history;
    }

    private List<ThreadHistoryItem> threadHistory() {
        return readThreadHistory(preferences);
    }

    static int historyUnreadCount(SharedPreferences preferences, ThreadHistoryItem item) {
        if (preferences == null || item == null || item.responseCount <= 0) {
            return 0;
        }
        return Math.max(0, item.responseCount - readPostNumber(preferences, item.url));
    }

    private boolean threadHistoryContains(String url) {
        return threadHistoryContains(threadHistoryUrlSnapshot(), url);
    }

    private boolean threadHistoryContains(Set<String> historyUrls, String url) {
        return threadHistoryContains(historyUrls, null, url);
    }

    private boolean threadHistoryContains(Set<String> historyUrls, List<ThreadHistoryItem> historyItems, String url) {
        if (historyUrls == null || historyUrls.isEmpty()) {
            return threadHistoryContainsByIdentity(historyItems, url);
        }
        for (String key : threadHistoryKeys(url)) {
            if (!key.isEmpty() && historyUrls.contains(key)) {
                return true;
            }
        }
        return threadHistoryContainsByIdentity(historyItems, url);
    }

    private boolean threadHistoryContainsByIdentity(List<ThreadHistoryItem> historyItems, String url) {
        if (historyItems == null || historyItems.isEmpty() || url == null || url.trim().isEmpty()) {
            return false;
        }
        for (ThreadHistoryItem item : historyItems) {
            if (item != null && sameThreadIdentity(item.url, url)) {
                return true;
            }
        }
        return false;
    }

    private Set<String> threadHistoryUrlSnapshot() {
        return threadHistoryUrlSnapshot(threadHistory());
    }

    private Set<String> threadHistoryUrlSnapshot(List<ThreadHistoryItem> historyItems) {
        Set<String> urls = new LinkedHashSet<>();
        if (historyItems == null) {
            return urls;
        }
        for (ThreadHistoryItem item : historyItems) {
            if (item != null) {
                urls.addAll(threadHistoryKeys(item.url));
            }
        }
        return urls;
    }

    private Set<String> threadHistoryKeys(String url) {
        Set<String> keys = new LinkedHashSet<>();
        String normalized = normalizeHistoryUrl(url);
        if (!normalized.isEmpty()) {
            keys.add(normalized);
        }
        DatAddress address = datAddress(url);
        if (address != null && address.board != null && address.key != null) {
            String board = address.board.toLowerCase(Locale.ROOT);
            String key = address.key.toLowerCase(Locale.ROOT);
            if (address.host != null && !address.host.isEmpty()) {
                keys.add("dat:" + address.host.toLowerCase(Locale.ROOT) + "/" + board + "/" + key);
            }
            if (address.server != null && !address.server.isEmpty()) {
                keys.add("dat-server:" + address.server.toLowerCase(Locale.ROOT) + "/" + board + "/" + key);
            }
        }
        return keys;
    }

    private String normalizeHistoryUrl(String url) {
        String value = normalizeUrl(url == null ? "" : url.trim());
        while (value.endsWith("/") && value.length() > "https://x".length()) {
            value = value.substring(0, value.length() - 1);
        }
        return value;
    }

    private List<SavedItem> readSavedItems(String key) {
        List<SavedItem> items = new ArrayList<>();
        Set<String> seen = new LinkedHashSet<>();
        try {
            JSONArray array = new JSONArray(preferences.getString(key, "[]"));
            for (int i = 0; i < array.length(); i++) {
                JSONObject object = array.optJSONObject(i);
                if (object == null) {
                    continue;
                }
                String title = object.optString("title", "").trim();
                String url = object.optString("url", "").trim();
                String folder = normalizeSavedFolder(object.optString("folder", ""));
                String identity = savedItemIdentity(url, folder);
                if (!title.isEmpty() && !url.isEmpty() && !seen.contains(identity)) {
                    items.add(new SavedItem(title, url, folder));
                    seen.add(identity);
                }
            }
        } catch (Exception ignored) {
        }
        return items;
    }

    private void migrateFavoriteBoardsToBookmarks() {
        if (preferences == null || preferences.getBoolean("favorite_boards_migrated_to_bookmarks", false)) {
            return;
        }
        List<SavedItem> bookmarks = readSavedItems(PREF_THREAD_BOOKMARKS);
        boolean changed = false;
        for (SavedItem favorite : readSavedItems(PREF_BOARD_FAVORITES)) {
            boolean exists = false;
            for (SavedItem bookmark : bookmarks) {
                if (sameSavedUrl(bookmark.url, favorite.url)) {
                    exists = true;
                    break;
                }
            }
            if (!exists) {
                bookmarks.add(new SavedItem(favorite.title, favorite.url, favorite.folder));
                changed = true;
            }
        }
        SharedPreferences.Editor editor = preferences.edit()
                .putBoolean("favorite_boards_migrated_to_bookmarks", true)
                .putString(PREF_BOARD_FAVORITES, "[]");
        if (changed) {
            JSONArray array = new JSONArray();
            try {
                for (SavedItem item : bookmarks) {
                    JSONObject object = new JSONObject();
                    object.put("title", item.title);
                    object.put("url", item.url);
                    object.put("folder", normalizeSavedFolder(item.folder));
                    array.put(object);
                }
            } catch (Exception ignored) {
            }
            editor.putString(PREF_THREAD_BOOKMARKS, array.toString());
        }
        editor.apply();
    }

    private void writeSavedItems(String key, List<SavedItem> items) {
        JSONArray array = new JSONArray();
        Set<String> seen = new LinkedHashSet<>();
        try {
            for (SavedItem item : items) {
                if (item == null || item.url == null || item.url.trim().isEmpty()) {
                    continue;
                }
                String folder = normalizeSavedFolder(item.folder);
                String identity = savedItemIdentity(item.url, folder);
                if (seen.contains(identity)) {
                    continue;
                }
                JSONObject object = new JSONObject();
                object.put("title", item.title);
                object.put("url", item.url.trim());
                object.put("folder", folder);
                array.put(object);
                seen.add(identity);
            }
        } catch (Exception ignored) {
        }
        preferences.edit().putString(key, array.toString()).apply();
        if (PREF_THREAD_BOOKMARKS.equals(key)) {
            markBookmarkOverviewDirty();
        }
    }

    private String savedItemIdentity(String url, String folder) {
        return normalizeSavedFolder(folder) + "\n" + (url == null ? "" : url.trim());
    }

    private List<String> readSavedFolders(String key) {
        return readSavedFolders(key, readSavedItems(key));
    }

    private List<String> readSavedFolders(String key, List<SavedItem> items) {
        List<String> folders = new ArrayList<>();
        try {
            JSONArray array = new JSONArray(preferences.getString(savedFoldersKey(key), "[]"));
            for (int i = 0; i < array.length(); i++) {
                String folder = normalizeSavedFolder(array.optString(i, ""));
                if (!folder.isEmpty() && !folders.contains(folder)) {
                    folders.add(folder);
                }
            }
        } catch (Exception ignored) {
        }
        for (SavedItem item : items) {
            String folder = normalizeSavedFolder(item.folder);
            if (!folder.isEmpty() && !folders.contains(folder)) {
                folders.add(folder);
            }
        }
        return folders;
    }

    private void writeSavedFolders(String key, List<String> folders) {
        JSONArray array = new JSONArray();
        try {
            for (String folder : folders) {
                folder = normalizeSavedFolder(folder);
                if (!folder.isEmpty() && !containsString(array, folder)) {
                    array.put(folder);
                }
            }
        } catch (Exception ignored) {
        }
        preferences.edit().putString(savedFoldersKey(key), array.toString()).apply();
        if (PREF_THREAD_BOOKMARKS.equals(key)) {
            markBookmarkOverviewDirty();
        }
    }

    private void persistCurrentSavedFolders(String key) {
        writeSavedFolders(key, savedFoldersWithAncestors(readSavedFolders(key)));
    }

    private List<String> savedFoldersWithAncestors(List<String> folders) {
        List<String> result = new ArrayList<>();
        if (folders == null) {
            return result;
        }
        for (String folder : folders) {
            folder = normalizeSavedFolder(folder);
            if (folder.isEmpty()) {
                continue;
            }
            String[] parts = folder.split("/");
            StringBuilder path = new StringBuilder();
            for (String part : parts) {
                part = normalizeSavedFolder(part);
                if (part.isEmpty()) {
                    continue;
                }
                if (path.length() > 0) {
                    path.append('/');
                }
                path.append(part);
                String value = path.toString();
                if (!result.contains(value)) {
                    result.add(value);
                }
            }
        }
        return result;
    }

    private boolean containsString(JSONArray array, String value) {
        for (int i = 0; i < array.length(); i++) {
            if (value.equals(array.optString(i, ""))) {
                return true;
            }
        }
        return false;
    }

    private String savedFoldersKey(String key) {
        return key + "_folders";
    }

    private String normalizeSavedFolder(String folder) {
        if (folder == null) {
            return "";
        }
        String value = folder.trim().replace('\\', '/');
        while (value.contains("//")) {
            value = value.replace("//", "/");
        }
        while (value.startsWith("/")) {
            value = value.substring(1);
        }
        while (value.endsWith("/")) {
            value = value.substring(0, value.length() - 1);
        }
        return value.trim();
    }

    private String parentSavedFolder(String folder) {
        folder = normalizeSavedFolder(folder);
        int sep = folder.lastIndexOf('/');
        return sep < 0 ? "" : folder.substring(0, sep);
    }

    private String savedFolderDisplayName(String folder) {
        folder = normalizeSavedFolder(folder);
        int sep = folder.lastIndexOf('/');
        return sep < 0 ? folder : folder.substring(sep + 1);
    }

    private String topSavedFolder(String folder) {
        folder = normalizeSavedFolder(folder);
        int sep = folder.indexOf('/');
        return sep < 0 ? folder : folder.substring(0, sep);
    }

    private String childSavedFolderPath(String parent, String childName) {
        parent = normalizeSavedFolder(parent);
        childName = normalizeSavedFolder(childName);
        if (childName.isEmpty()) {
            return parent;
        }
        return parent.isEmpty() ? childName : parent + "/" + childName;
    }

    private boolean savedFolderDescendantOrSelf(String folder, String target) {
        folder = normalizeSavedFolder(folder);
        target = normalizeSavedFolder(target);
        return !folder.isEmpty() && (target.equals(folder) || target.startsWith(folder + "/"));
    }

    private List<String> childSavedFolders(String key, String parent) {
        return childSavedFolders(parent, readSavedFolders(key));
    }

    private List<String> childSavedFolders(String parent, List<String> folders) {
        parent = normalizeSavedFolder(parent);
        List<String> children = new ArrayList<>();
        if (folders == null) {
            return children;
        }
        for (String folder : folders) {
            if (parent.equals(parentSavedFolder(folder)) && !children.contains(folder)) {
                children.add(folder);
            }
        }
        return children;
    }

    private List<BookmarkNode> bookmarkChildren(String parent) {
        parent = normalizeSavedFolder(parent);
        List<BookmarkNode> nodes = new ArrayList<>();
        for (String folder : childSavedFolders(PREF_THREAD_BOOKMARKS, parent)) {
            nodes.add(BookmarkNode.folder(folder));
        }
        for (SavedItem item : readSavedItems(PREF_THREAD_BOOKMARKS)) {
            if (parent.equals(normalizeSavedFolder(item.folder))) {
                nodes.add(BookmarkNode.item(item));
            }
        }
        List<String> order = bookmarkOrder(parent);
        Collections.sort(nodes, (left, right) -> {
            int li = bookmarkOrderIndex(order, left);
            int ri = bookmarkOrderIndex(order, right);
            if (li < 0) {
                li = Integer.MAX_VALUE;
            }
            if (ri < 0) {
                ri = Integer.MAX_VALUE;
            }
            if (li != ri) {
                return Integer.compare(li, ri);
            }
            return left.label().compareToIgnoreCase(right.label());
        });
        return nodes;
    }

    private List<BookmarkNode> bookmarkChildren(String parent, BookmarkOverviewSnapshot snapshot) {
        parent = normalizeSavedFolder(parent);
        if (snapshot.childrenByParent.containsKey(parent)) {
            return snapshot.childrenByParent.get(parent);
        }
        List<BookmarkNode> nodes = new ArrayList<>();
        for (String folder : snapshot.folders) {
            if (parent.equals(parentSavedFolder(folder))) {
                nodes.add(BookmarkNode.folder(folder));
            }
        }
        for (SavedItem item : snapshot.bookmarks) {
            if (parent.equals(normalizeSavedFolder(item.folder))) {
                nodes.add(BookmarkNode.item(item));
            }
        }
        if (bookmarkSortEnabled()) {
            sortBookmarkNodesLikeTabs(nodes, snapshot);
            snapshot.childrenByParent.put(parent, nodes);
            return nodes;
        }
        List<String> order = bookmarkOrder(parent, snapshot.orderRoot);
        Collections.sort(nodes, (left, right) -> {
            int li = bookmarkOrderIndex(order, left);
            int ri = bookmarkOrderIndex(order, right);
            if (li < 0) {
                li = Integer.MAX_VALUE;
            }
            if (ri < 0) {
                ri = Integer.MAX_VALUE;
            }
            if (li != ri) {
                return Integer.compare(li, ri);
            }
            return left.label().compareToIgnoreCase(right.label());
        });
        snapshot.childrenByParent.put(parent, nodes);
        return nodes;
    }

    private void sortBookmarkNodesLikeTabs(List<BookmarkNode> nodes, BookmarkOverviewSnapshot snapshot) {
        final String key = preferences.getString(PREF_TAB_SORT_KEY, BOARD_SORT_VELOCITY);
        final boolean desc = preferences.getBoolean(PREF_TAB_SORT_DESC, true);
        Collections.sort(nodes, (left, right) -> {
            if (left.folderNode != right.folderNode) {
                return left.folderNode ? -1 : 1;
            }
            if (left.folderNode) {
                return left.label().compareToIgnoreCase(right.label());
            }
            CuspTab leftTab = bookmarkOverviewTab(left.item, snapshot);
            CuspTab rightTab = bookmarkOverviewTab(right.item, snapshot);
            SearchResult leftResult = searchResultForTabOverview(leftTab);
            SearchResult rightResult = searchResultForTabOverview(rightTab);
            boolean leftThread = leftResult != null;
            boolean rightThread = rightResult != null;
            if (leftThread != rightThread) {
                boolean nonThreadTop = preferences.getBoolean(PREF_TAB_NON_THREAD_TOP, true);
                return leftThread ? (nonThreadTop ? 1 : -1) : (nonThreadTop ? -1 : 1);
            }
            if (!leftThread) {
                return left.label().compareToIgnoreCase(right.label());
            }
            int compared = compareBoardSortValue(leftResult, rightResult, key);
            if (compared != 0) {
                return desc ? -compared : compared;
            }
            return left.label().compareToIgnoreCase(right.label());
        });
    }

    private int bookmarkOrderIndex(List<String> order, BookmarkNode node) {
        int index = order.indexOf(node.orderKey());
        if (index < 0 && node != null && !node.folderNode && node.item != null) {
            index = order.indexOf(legacyBookmarkItemKey(node.item.url));
        }
        return index;
    }

    private List<String> bookmarkOrder(String parent) {
        return bookmarkOrder(parent, preferenceJsonObject(PREF_BOOKMARK_ORDER));
    }

    private List<String> bookmarkOrder(String parent, JSONObject root) {
        parent = normalizeSavedFolder(parent);
        List<String> order = new ArrayList<>();
        try {
            JSONArray array = root.optJSONArray(parent);
            if (array != null) {
                for (int i = 0; i < array.length(); i++) {
                    String value = array.optString(i, "");
                    if (!value.isEmpty() && !order.contains(value)) {
                        order.add(value);
                    }
                }
            }
        } catch (Exception ignored) {
        }
        return order;
    }

    private void writeBookmarkOrder(String parent, List<BookmarkNode> nodes) {
        parent = normalizeSavedFolder(parent);
        try {
            JSONObject root = new JSONObject(preferences.getString(PREF_BOOKMARK_ORDER, "{}"));
            JSONArray array = new JSONArray();
            for (BookmarkNode node : nodes) {
                array.put(node.orderKey());
            }
            root.put(parent, array);
            preferences.edit().putString(PREF_BOOKMARK_ORDER, root.toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private void moveBookmarkNodeIntoFolder(String movingKey, String targetFolder) {
        targetFolder = normalizeSavedFolder(targetFolder);
        if (movingKey == null || movingKey.length() < 3) {
            return;
        }
        if (movingKey.startsWith("I:")) {
            SavedItem item = savedItemByBookmarkKey(movingKey);
            if (item == null) {
                return;
            }
            String url = item.url;
            String oldKey = itemBookmarkOrderKey(item);
            String oldParent = normalizeSavedFolder(item.folder);
            if (oldParent.equals(targetFolder)) {
                return;
            }
            moveSavedItemToFolder(PREF_THREAD_BOOKMARKS, url, oldParent, targetFolder);
            appendBookmarkOrder(targetFolder, itemBookmarkOrderKey(url, targetFolder));
            removeBookmarkOrderEntry(oldParent, oldKey);
            removeBookmarkOrderEntry(oldParent, legacyBookmarkItemKey(url));
            return;
        }
        if (movingKey.startsWith("F:")) {
            String folder = normalizeSavedFolder(movingKey.substring(2));
            if (folder.isEmpty() || folder.equals(targetFolder) || savedFolderDescendantOrSelf(folder, targetFolder)) {
                return;
            }
            String oldParent = parentSavedFolder(folder);
            if (oldParent.equals(targetFolder)) {
                return;
            }
            String newFolder = childSavedFolderPath(targetFolder, savedFolderDisplayName(folder));
            renameSavedFolder(PREF_THREAD_BOOKMARKS, folder, newFolder);
            appendBookmarkOrder(targetFolder, "F:" + newFolder);
            removeBookmarkOrderEntry(oldParent, "F:" + folder);
        }
    }

    private void renameBookmarkFolder(String oldFolder, String newName) {
        oldFolder = normalizeSavedFolder(oldFolder);
        String newFolder = childSavedFolderPath(parentSavedFolder(oldFolder), newName);
        if (oldFolder.isEmpty() || newFolder.isEmpty() || oldFolder.equals(newFolder)) {
            return;
        }
        renameSavedFolder(PREF_THREAD_BOOKMARKS, oldFolder, newName);
        renameBookmarkOrderFolders(oldFolder, newFolder);
    }

    private void renameBookmarkOrderFolders(String oldFolder, String newFolder) {
        try {
            JSONObject root = new JSONObject(preferences.getString(PREF_BOOKMARK_ORDER, "{}"));
            JSONObject next = new JSONObject();
            java.util.Iterator<String> keys = root.keys();
            while (keys.hasNext()) {
                String parent = keys.next();
                JSONArray source = root.optJSONArray(parent);
                if (source == null) {
                    continue;
                }
                JSONArray array = new JSONArray();
                for (int i = 0; i < source.length(); i++) {
                    String value = source.optString(i, "");
                    if (value.startsWith("F:")) {
                        value = "F:" + renamedBookmarkFolderPath(value.substring(2), oldFolder, newFolder);
                    }
                    if (!value.isEmpty() && !containsString(array, value)) {
                        array.put(value);
                    }
                }
                next.put(renamedBookmarkFolderPath(parent, oldFolder, newFolder), array);
            }
            preferences.edit().putString(PREF_BOOKMARK_ORDER, next.toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private String renamedBookmarkFolderPath(String folder, String oldFolder, String newFolder) {
        folder = normalizeSavedFolder(folder);
        oldFolder = normalizeSavedFolder(oldFolder);
        newFolder = normalizeSavedFolder(newFolder);
        if (folder.equals(oldFolder)) {
            return newFolder;
        }
        if (!oldFolder.isEmpty() && folder.startsWith(oldFolder + "/")) {
            return newFolder + folder.substring(oldFolder.length());
        }
        return folder;
    }

    private void moveBookmarkNodeToParentNear(String movingKey, String targetParent, String targetKey, boolean after) {
        targetParent = normalizeSavedFolder(targetParent);
        if (movingKey == null || movingKey.isEmpty() || targetKey == null || targetKey.isEmpty()) {
            return;
        }
        String oldParent = bookmarkNodeParent(movingKey);
        if (!oldParent.equals(targetParent)) {
            moveBookmarkNodeIntoFolder(movingKey, targetParent);
            movingKey = movedBookmarkNodeKey(movingKey, targetParent);
            if (movingKey.isEmpty()) {
                return;
            }
        }
        List<BookmarkNode> nodes = bookmarkChildren(targetParent);
        BookmarkNode moved = null;
        for (int i = nodes.size() - 1; i >= 0; i--) {
            if (nodes.get(i).orderKey().equals(movingKey)) {
                moved = nodes.remove(i);
                break;
            }
        }
        if (moved == null) {
            return;
        }
        int target = -1;
        for (int i = 0; i < nodes.size(); i++) {
            if (nodes.get(i).orderKey().equals(targetKey)) {
                target = i;
                break;
            }
        }
        if (target < 0) {
            nodes.add(moved);
        } else {
            nodes.add(Math.max(0, Math.min(after ? target + 1 : target, nodes.size())), moved);
        }
        writeBookmarkOrder(targetParent, nodes);
    }

    private int bookmarkDropZone(android.view.DragEvent event, View target, boolean hasCenter) {
        if (event == null || target == null || target.getHeight() <= 0) {
            return 0;
        }
        float ratio = event.getY() / Math.max(1f, target.getHeight());
        if (hasCenter) {
            if (ratio < 0.32f) {
                return -1;
            }
            if (ratio > 0.68f) {
                return 1;
            }
            return 0;
        }
        return ratio < 0.5f ? -1 : 1;
    }

    private String bookmarkNodeParent(String key) {
        if (key == null || key.length() < 3) {
            return "";
        }
        if (key.startsWith("I:")) {
            SavedItem item = savedItemByBookmarkKey(key);
            return item == null ? "" : normalizeSavedFolder(item.folder);
        }
        if (key.startsWith("F:")) {
            return parentSavedFolder(key.substring(2));
        }
        return "";
    }

    private String movedBookmarkNodeKey(String originalKey, String targetParent) {
        if (originalKey == null || originalKey.length() < 3) {
            return "";
        }
        if (originalKey.startsWith("I:")) {
            SavedItem item = savedItemByBookmarkKey(originalKey);
            return item == null ? "" : itemBookmarkOrderKey(item.url, targetParent);
        }
        if (originalKey.startsWith("F:")) {
            return "F:" + childSavedFolderPath(targetParent, savedFolderDisplayName(originalKey.substring(2)));
        }
        return "";
    }

    private SavedItem savedItemByUrl(String key, String url) {
        for (SavedItem item : readSavedItems(key)) {
            if (sameSavedUrl(item.url, url)) {
                return item;
            }
        }
        return null;
    }

    private boolean boardPriorityRuleApplies(BoardPriorityRule rule, String boardUrl) {
        if (rule == null || rule.targetUrl == null || rule.targetUrl.trim().isEmpty()) {
            return true;
        }
        String target = normalizePriorityTargetUrl(rule.targetUrl);
        if (target.isEmpty()) {
            return true;
        }
        return target.equals(normalizePriorityTargetUrl(boardUrl));
    }

    private SavedItem savedItemByBookmarkKey(String bookmarkKey) {
        if (bookmarkKey == null || !bookmarkKey.startsWith("I:")) {
            return null;
        }
        String value = bookmarkKey.substring(2);
        int sep = value.indexOf('\n');
        if (sep >= 0) {
            String folder = normalizeSavedFolder(value.substring(0, sep));
            String url = value.substring(sep + 1);
            for (SavedItem item : readSavedItems(PREF_THREAD_BOOKMARKS)) {
                if (folder.equals(normalizeSavedFolder(item.folder)) && sameSavedUrl(item.url, url)) {
                    return item;
                }
            }
            return null;
        }
        return savedItemByUrl(PREF_THREAD_BOOKMARKS, value);
    }

    private boolean savedItemExists(String key, String url) {
        return savedItemByUrl(key, url) != null;
    }

    private void appendBookmarkOrder(String parent, String key) {
        parent = normalizeSavedFolder(parent);
        List<BookmarkNode> nodes = bookmarkChildren(parent);
        List<String> keys = new ArrayList<>();
        for (BookmarkNode node : nodes) {
            String nodeKey = node.orderKey();
            if (!nodeKey.equals(key)) {
                keys.add(nodeKey);
            }
        }
        keys.add(key);
        writeBookmarkOrderKeys(parent, keys);
    }

    private void removeBookmarkOrderEntry(String parent, String key) {
        parent = normalizeSavedFolder(parent);
        List<String> keys = bookmarkOrder(parent);
        if (keys.remove(key)) {
            writeBookmarkOrderKeys(parent, keys);
        }
    }

    private void writeBookmarkOrderKeys(String parent, List<String> keys) {
        parent = normalizeSavedFolder(parent);
        try {
            JSONObject root = new JSONObject(preferences.getString(PREF_BOOKMARK_ORDER, "{}"));
            JSONArray array = new JSONArray();
            for (String key : keys) {
                if (key != null && !key.isEmpty() && !containsString(array, key)) {
                    array.put(key);
                }
            }
            root.put(parent, array);
            preferences.edit().putString(PREF_BOOKMARK_ORDER, root.toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private String bookmarkNodeDragKey(BookmarkNode node) {
        return "bookmark-node:" + node.orderKey();
    }

    private String bookmarkNodeDragValue(String dragKey) {
        return dragKey != null && dragKey.startsWith("bookmark-node:")
                ? dragKey.substring("bookmark-node:".length()) : "";
    }

    private String itemBookmarkOrderKey(SavedItem item) {
        return item == null ? "I:" : itemBookmarkOrderKey(item.url, item.folder);
    }

    private String itemBookmarkOrderKey(String url, String folder) {
        return "I:" + normalizeSavedFolder(folder) + "\n" + (url == null ? "" : url.trim());
    }

    private String legacyBookmarkItemKey(String url) {
        return "I:" + (url == null ? "" : url.trim());
    }

    private String savedPageToken(String key, String folder) {
        folder = normalizeSavedFolder(folder);
        return folder.isEmpty() ? key : key + "|" + folder;
    }

    private SavedPage savedPageFromToken(String token) {
        String value = token == null ? "" : token;
        int sep = value.indexOf('|');
        if (sep < 0) {
            return new SavedPage(value, "");
        }
        return new SavedPage(value.substring(0, sep), value.substring(sep + 1));
    }

    private int savedFolderItemCount(String key, String folder) {
        return savedFolderItemCount(key, folder, null);
    }

    private int savedFolderItemCount(String key, String folder, List<SavedItem> savedItems) {
        int count = 0;
        folder = normalizeSavedFolder(folder);
        List<SavedItem> items = savedItems == null ? readSavedItems(key) : savedItems;
        for (SavedItem item : items) {
            if (savedFolderDescendantOrSelf(folder, normalizeSavedFolder(item.folder))) {
                count++;
            }
        }
        return count;
    }

    private boolean isSavedItem(String key, String url) {
        if (url == null) {
            return false;
        }
        for (SavedItem item : readSavedItems(key)) {
            if (url.equals(item.url)) {
                return true;
            }
        }
        return false;
    }

    private void toggleSavedItem(String key, String title, String url) {
        if (url == null || url.trim().isEmpty()) {
            return;
        }
        List<SavedItem> items = readSavedItems(key);
        for (int i = 0; i < items.size(); i++) {
            if (url.equals(items.get(i).url)) {
                persistCurrentSavedFolders(key);
                items.remove(i);
                writeSavedItems(key, items);
                return;
            }
        }
        items.add(0, new SavedItem(cleanTitle(title, url), url, ""));
        writeSavedItems(key, items);
    }

    private void removeSavedItem(String key, String url) {
        List<SavedItem> items = readSavedItems(key);
        boolean removed = false;
        for (int i = items.size() - 1; i >= 0; i--) {
            if (url.equals(items.get(i).url)) {
                items.remove(i);
                removed = true;
            }
        }
        if (removed) {
            persistCurrentSavedFolders(key);
        }
        writeSavedItems(key, items);
    }

    private void removeSavedItem(String key, SavedItem target) {
        if (target == null) {
            return;
        }
        List<SavedItem> items = readSavedItems(key);
        boolean removed = false;
        for (int i = items.size() - 1; i >= 0; i--) {
            if (sameSavedItem(items.get(i), target)) {
                items.remove(i);
                removed = true;
                break;
            }
        }
        if (removed) {
            persistCurrentSavedFolders(key);
        }
        writeSavedItems(key, items);
    }

    private void moveSavedItemToFolder(String key, String url, String folder) {
        moveSavedItemToFolder(key, url, null, folder);
    }

    private void moveSavedItemToFolder(String key, String url, String oldFolder, String folder) {
        List<SavedItem> items = readSavedItems(key);
        oldFolder = oldFolder == null ? null : normalizeSavedFolder(oldFolder);
        folder = normalizeSavedFolder(folder);
        for (int i = 0; i < items.size(); i++) {
            SavedItem item = items.get(i);
            if (url.equals(item.url) && (oldFolder == null || oldFolder.equals(normalizeSavedFolder(item.folder)))) {
                String currentFolder = normalizeSavedFolder(item.folder);
                if (!currentFolder.equals(folder)) {
                    persistCurrentSavedFolders(key);
                }
                items.set(i, new SavedItem(item.title, item.url, folder));
                break;
            }
        }
        if (!folder.isEmpty()) {
            List<String> folders = readSavedFolders(key);
            if (!folders.contains(folder)) {
                folders.add(folder);
                writeSavedFolders(key, folders);
            }
        }
        writeSavedItems(key, items);
    }

    private void createSavedFolder(String key, String folder) {
        createSavedFolder(key, "", folder);
    }

    private void createSavedFolder(String key, String parent, String folder) {
        folder = childSavedFolderPath(parent, folder);
        if (folder.isEmpty()) {
            return;
        }
        List<String> folders = readSavedFolders(key);
        if (!folders.contains(folder)) {
            folders.add(folder);
            writeSavedFolders(key, folders);
        }
    }

    private void renameSavedFolder(String key, String oldFolder, String newFolder) {
        oldFolder = normalizeSavedFolder(oldFolder);
        newFolder = childSavedFolderPath(parentSavedFolder(oldFolder), newFolder);
        if (oldFolder.isEmpty() || newFolder.isEmpty() || oldFolder.equals(newFolder)) {
            return;
        }
        List<String> folders = readSavedFolders(key);
        for (int i = 0; i < folders.size(); i++) {
            String folder = folders.get(i);
            if (savedFolderDescendantOrSelf(oldFolder, folder)) {
                folders.set(i, newFolder + folder.substring(oldFolder.length()));
            }
        }
        if (!folders.contains(newFolder)) {
            folders.add(newFolder);
        }
        List<SavedItem> items = readSavedItems(key);
        for (int i = 0; i < items.size(); i++) {
            SavedItem item = items.get(i);
            String folder = normalizeSavedFolder(item.folder);
            if (savedFolderDescendantOrSelf(oldFolder, folder)) {
                items.set(i, new SavedItem(item.title, item.url, newFolder + folder.substring(oldFolder.length())));
            }
        }
        writeSavedFolders(key, folders);
        writeSavedItems(key, items);
    }

    private void deleteSavedFolder(String key, String folder) {
        folder = normalizeSavedFolder(folder);
        List<String> folders = readSavedFolders(key);
        for (int i = folders.size() - 1; i >= 0; i--) {
            if (savedFolderDescendantOrSelf(folder, folders.get(i))) {
                folders.remove(i);
            }
        }
        List<SavedItem> items = readSavedItems(key);
        for (int i = 0; i < items.size(); i++) {
            SavedItem item = items.get(i);
            if (savedFolderDescendantOrSelf(folder, normalizeSavedFolder(item.folder))) {
                items.set(i, new SavedItem(item.title, item.url, ""));
            }
        }
        writeSavedFolders(key, folders);
        writeSavedItems(key, items);
    }

    private void moveSavedItem(String key, int from, int to) {
        List<SavedItem> items = readSavedItems(key);
        if (from < 0 || from >= items.size() || to < 0 || to >= items.size() || from == to) {
            return;
        }
        SavedItem item = items.remove(from);
        items.add(to, item);
        writeSavedItems(key, items);
    }

